CREATE FUNCTION public.abastecimento_codigo_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN
	IF TG_OP = 'INSERT' THEN
		IF NEW.codigo IS NULL THEN
			NEW.codigo = NEXTVAL('abastecimento_seq');
		END IF;
		RETURN NEW;
	END IF;
END;	
  
$$;


