--
-- Name: aplica_regra_transitoria_ad_rem_f(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.aplica_regra_transitoria_ad_rem_f(text, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$


  DECLARE
      v_ad_rem FLOAT;
      v_data_ini DATE;
      v_mes_transicao DATE;
      v_dia INT;
      v_mes_anterior DATE;
      v_segundo_mes_anterior DATE;
  BEGIN
      -- Busca a vigencia correspondente a data
      SELECT ad_rem, data_ini
      INTO v_ad_rem, v_data_ini
      FROM combustivel_ad_rem
      WHERE codigo_anp = $1
        AND data_ini <= $2
      ORDER BY data_ini DESC
      LIMIT 1;

      IF v_data_ini IS NULL THEN
          RETURN NULL;
      END IF;

      -- Primeiro mes da vigencia
      v_mes_transicao := date_trunc('month', v_data_ini);

      -- Se NAO eh mes de transiÁ„o, retorna direto a aliquota
      IF date_trunc('month', $2) != v_mes_transicao THEN
          RETURN v_ad_rem;
      END IF;

      -- Se eh mes de transiÁ„o, aplica regra
      v_dia := EXTRACT(DAY FROM $2);

      v_mes_anterior := date_trunc('month', $2) - INTERVAL '1 month';
      v_segundo_mes_anterior := date_trunc('month', $2) - INTERVAL '2 month';

      IF v_dia BETWEEN 1 AND 5 THEN
          -- Media ponderada do segundo mes anterior
          SELECT AVG(ad_rem)
          INTO v_ad_rem
          FROM combustivel_ad_rem
          WHERE codigo_anp = $1
            AND data_ini = v_segundo_mes_anterior
        AND data_ini < v_segundo_mes_anterior + INTERVAL '1 month';

          -- Se nao houver dados para o segundo mes anterior, utiliza o valor mais recente antes do segundo mes anterior
        IF v_ad_rem IS NULL THEN
          SELECT ad_rem
          INTO v_ad_rem
          FROM combustivel_ad_rem
          WHERE codigo_anp = $1
            AND data_ini <= v_segundo_mes_anterior
          ORDER BY data_ini DESC
          LIMIT 1;
        END IF;
      ELSE
          -- Media ponderada do mes anterior
          SELECT AVG(ad_rem)
          INTO v_ad_rem
          FROM combustivel_ad_rem
          WHERE codigo_anp = $1
            AND data_ini >= v_mes_anterior
        AND data_ini < v_mes_anterior + INTERVAL '1 month';

        -- Se nao houver dados para o mes anterior, utiliza o valor mais recente antes do mes anterior
        IF v_ad_rem IS NULL THEN
          SELECT ad_rem
          INTO v_ad_rem
          FROM combustivel_ad_rem
          WHERE codigo_anp = $1
            AND data_ini <= v_mes_anterior
          ORDER BY data_ini DESC
          LIMIT 1;
        END IF;
      END IF;

      RETURN v_ad_rem;
  END;
  
$_$;


ALTER FUNCTION public.aplica_regra_transitoria_ad_rem_f(text, date) OWNER TO postgres;

