--
-- Name: bico_set_preco_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.bico_set_preco_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
	emp RECORD;
 	rec RECORD;
 	
	json TEXT;
	SCS TEXT;

BEGIN
	SELECT e.grid, regexp_replace(e.cpf, '[^0-9]', '', 'g') as cnpj
	  INTO emp
      FROM empresa e
	  JOIN empresa_local el
        ON el.empresa = e.grid;

	--Sair da funcao se nao localizar os dados da empresa.
	IF NOT found THEN
		RETURN NEW;
	END IF;

	--Sair se a atualizacao de preco nao for pelo preco bomba (legado=null; default=0)
	IF (SELECT True 
	      FROM exc_ipp_config 
	     WHERE empresa = emp.grid
	       AND tipo_atualizacao_preco_pro_frotas > 0) THEN
		RETURN NEW;
	END IF;
	
	RAISE NOTICE 'CNPJ da Empresa: %...', emp.cnpj;

	BEGIN
		SELECT tc.codigo_anp
		  FROM produto p
		  JOIN deposito d 
		    ON p.grid = d.produto
		  JOIN bico b 
		    ON d.grid = b.deposito
		  JOIN bico_bomba bb 
		    ON bb.bico = b.nome
		  JOIN empresa_local el 
		    ON el.empresa = b.empresa
		  JOIN bico_set_preco bsp 
		    ON bsp.bico = bb.bomba
		  JOIN tipo_combustivel tc 
		    ON tc.codigo = p.tipo_combustivel
		  JOIN exc_ipp_pro_frotas_anp AS ep
		    ON tc.codigo_anp = ep.codigo_anp
		 WHERE bb.bomba = NEW.bico
		   AND p.tipo = 'C' 
		   AND p.flag = 'A'
		   AND p.codigo not in (SELECT produto 
								  FROM exc_ipp_conecta_produtos 
								 WHERE produto_modulo = 'PRO_FROTAS')
		   AND tc.grupo_combustivel in (SELECT codigo 
										  FROM grupo_combustivel)

		  INTO rec;

		IF NOT FOUND THEN
			RETURN NEW;
		END IF;
		
		RAISE NOTICE 'Codigo ANP do Combustivel: %...', rec.codigo_anp;

		if rec.codigo_anp = Null THEN
			RETURN NEW;
		END IF;

		json := '{
			"cnpj": "' || emp.cnpj || '",
			"codigoProduto": "' || rec.codigo_anp || '",
			"valorUnitario": ' || NEW.preco_unit || '
		}';

		--raise info 'JSON: %', json;
		SHOW standard_conforming_strings INTO SCS;

		IF SCS = 'off' THEN
			set standard_conforming_strings = on;
		END IF;

		json := regexp_replace(json, E'[\n\r\t]+', '', 'g');

		IF NOT EXISTS (SELECT codigo_anp from exc_ipp_pro_frotas_atualiza_preco_pendencia where codigo_anp = rec.codigo_anp ) THEN
			INSERT INTO exc_ipp_pro_frotas_atualiza_preco_pendencia (ts, payload, status, codigo_anp) VALUES (now(), json, 0, rec.codigo_anp);
		ELSE
			UPDATE exc_ipp_pro_frotas_atualiza_preco_pendencia SET ts = now(), payload = json, status = 0 where codigo_anp = rec.codigo_anp;
		END IF;

		IF SCS = 'off' THEN
			set standard_conforming_strings = off;
		END IF;
	EXCEPTION
		WHEN OTHERS THEN
			RETURN NEW;
	END;

	RETURN NEW;
END;
  
$$;


ALTER FUNCTION public.bico_set_preco_pendencia_tgf() OWNER TO postgres;

--
-- Name: caixa_bico_encerrante_f(bigint, text, date, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.caixa_bico_encerrante_f(bigint, text, date, integer, text) RETURNS double precision[]
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	enc_ini float := NULL;
	enc_fim float := NULL;
	pendente float := 0;
	volume float := 0;
	caixa_fechado bool := FALSE;
	sem_movto bool := FALSE;
	conta_caixa text := $2;

BEGIN
	
	if not conta_caixa is null then
		select into r fechamento from caixa where empresa=$1 and conta=conta_caixa and data=$3 and turno=$4 limit 1;
		
		if not found then
			return '{0,0,0}';
		end if;

		if not r.fechamento is null then
			caixa_fechado := TRUE;
		end if;
	else
		select into r grid from caixa_enc where empresa=$1 and data=$3 and turno=$4 limit 1;
		
		if found then
			caixa_fechado := TRUE;
			
		else
			select into r 1 from lancto where empresa = $1 and data=$3 and turno =$4 and bico=$5 limit 1;
			
			if not found then
				sem_movto := True;	
			end if;
		end if;
	end if;

	if caixa_fechado then
		select into r * from caixa_enc where empresa=$1 and 
			bico=$5 and data=$3 and turno=$4 limit 1;

		if found then
			if not r.encerrante is null then
				enc_fim := r.encerrante;
			end if;

			if not r.pendente is null then
				pendente := r.pendente;
			end if;

			if not r.enc_ini is null then
				enc_ini := r.enc_ini;
			end if;
		end if;
	else
		if not sem_movto then
			select into r encerrante from bico_encerrante_view where bico=$5 and 
				not encerrante is null limit 1;

			if found then
				enc_fim := r.encerrante;
			end if;

			select into r sum(a.quantidade) as qtde from abastecimento a join bico_bomba b on
				(a.bico=b.bomba) where b.bico=$5 limit 1;

			if found then
				if not r.qtde is null then
					pendente := r.qtde;

					if not enc_fim is null and pendente >= 0 then
						enc_fim := enc_fim - pendente;

						if enc_fim < 0 then
							enc_fim := 0;
						end if;
					end if;
				end if;
			end if;

			if not enc_fim is null then
				-- Busca se houve lancamento em turno superior e deduz do encerrante final para bater o fechamento
				-- NAO MECHER NESTE SQL, PORQUE TRAVA TUDO SE NAO FOR DESTA FORMA
				select into r sum(qtde) as qtde from 
				(select sum(ba.quantidade) as qtde from lancto l join bico_abastecimento ba on (ba.codigo = l.abastecimento)
				where l.empresa=$1 and ((l.data=$3 and l.turno > $4) or (l.data between $3+1 and (select max(data)+1 from caixa c 
				where c.empresa = $1))) and l.bico=$5
				union all
				select sum(ba.quantidade) as qtde from lancto_caixa lc join bico_abastecimento ba on (ba.codigo=lc.abastecimento) 
				join caixa c on (c.conta=lc.conta and c.empresa=$1) 
				where lc.bico=$5 and c.fechamento is null and ((c.data=$3 and c.turno >= $4) or (c.data > $3))) t;

				if found then
					if r.qtde is not null then
						enc_fim := enc_fim - r.qtde;

						if enc_fim < 0 then
							enc_fim := 0;
						end if;
					end if;
				end if;
			end if;
		end if;
	end if;
	
	if enc_ini is null then
		select into r encerrante from caixa_enc where empresa=$1 and bico=$5 and
			(data < $3 or (data=$3 and turno < $4)) and not encerrante is null 
			order by data desc, turno desc limit 1;
	
		if found then
			enc_ini := r.encerrante;
		else
			select into r * from bico where empresa=$1 and nome=$5 limit 1;

			if found then
				if not r.enc_ini is null then
					enc_ini := r.enc_ini;
				end if;
			end if;
		end if;
	end if;
	
	if (enc_ini is null or enc_fim is null) then
		if not sem_movto then
			select into r sum(quantidade) as qtde from lancto where empresa=$1 and bico=$5 and
				data=$3 and turno=$4 and operacao not in ('N', 'AE');
	
			if found then
				if not r.qtde is null then
					volume := r.qtde;
				end if;
			end if;
		end if;

		if enc_ini is null and enc_fim is null then
			enc_ini := 0;
			enc_fim := volume;
		elsif enc_ini is null then
			enc_ini := enc_fim - volume;
		elsif enc_fim is null then
			enc_fim = enc_ini + volume;
		end if;
	end if;

	enc_ini := round(enc_ini::numeric, 3)::float;
	enc_fim := round(enc_fim::numeric, 3)::float;
	pendente := round(pendente::numeric, 3)::float;

	return '{' || enc_ini || ',' || enc_fim || ',' || pendente || '}';
end
$_$;


ALTER FUNCTION public.caixa_bico_encerrante_f(bigint, text, date, integer, text) OWNER TO postgres;

--
-- Name: caixa_bico_preco_f(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.caixa_bico_preco_f(bigint, text) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	DECLARE
		rc record;
		r record;
	BEGIN
		IF (($1 is null) or ($1 = 0::bigint)) THEN
			RETURN null;
		END IF;
		SELECT preco INTO r FROM caixa_bico_preco WHERE caixa=$1 AND bico=$2;
		IF FOUND THEN -- if princical
			RETURN r.preco;
		ELSE
			SELECT c.empresa,c.data,c.turno,c.conta INTO rc FROM caixa c WHERE c.grid=$1;
			SELECT count(*)
			     , l.preco_unit
			  INTO r
			  FROM lancto l
			 WHERE l.empresa=rc.empresa
			   AND l.data=rc.data
			   AND l.turno=rc.turno
			   AND l.bico=$2
			   AND l.conta=rc.conta
			   AND l.operacao='V'
			 GROUP BY l.preco_unit
			 ORDER BY 1 desc limit 1;
			IF FOUND THEN
				RETURN r.preco_unit;
			ELSE
				SELECT l.preco_unit
				  INTO r
				  FROM lancto l
				 WHERE l.empresa=rc.empresa
				   AND l.data=rc.data
				   AND l.turno<rc.turno
				   AND l.bico=$2
				   AND l.conta=rc.conta
				   AND l.operacao='V'
				   AND l.pessoa is null
				 ORDER BY l.turno desc limit 1;
				IF FOUND THEN
					RETURN r.preco_unit;
				ELSE
					SELECT l.preco_unit
					  INTO r
					  FROM lancto l
					 WHERE l.empresa=rc.empresa
					   AND l.data=rc.data-'1 day'::interval
					   AND l.bico=$2
					   AND l.conta=rc.conta
					   AND l.operacao='V'
					   AND l.pessoa is null
					 ORDER BY l.turno desc limit 1;
					IF FOUND THEN
						RETURN r.preco_unit;
					ELSE
						SELECT l.preco_unit
						  INTO r
						  FROM lancto l
						 WHERE l.empresa=rc.empresa
						   AND l.data<rc.data-'1 day'::interval
						   AND l.bico=$2
						   AND l.conta=rc.conta
						   AND l.operacao='V'
						   AND l.pessoa is null
						 ORDER BY l.data desc, l.turno desc limit 1;
						IF FOUND THEN
							RETURN r.preco_unit;
						ELSE
							SELECT p.preco_unit
							  INTO r
							  FROM produto p
							  JOIN deposito d on (d.produto=p.grid)
							  JOIN bico b on (b.deposito=d.grid)
							 WHERE b.empresa=rc.empresa
							   AND b.nome=$2;
							IF FOUND THEN
								RETURN r.preco_unit;
							END IF;
						END IF;
					END IF;
				END IF;
			END IF;
		END IF;
	RETURN 0.0;
END

$_$;


ALTER FUNCTION public.caixa_bico_preco_f(bigint, text) OWNER TO postgres;

--
-- Name: caixa_movto_lote_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.caixa_movto_lote_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;       
        ex BOOLEAN;
        emp BIGINT;
 
        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;
        ELSE
            rec := NEW;
            rec_old := rec;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM caixa_movto_lote_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE caixa_movto_lote_sync;
                PERFORM setval('caixa_movto_lote_sync', 1);
            END IF;
            RETURN rec;
        END IF;
 
        ex := TG_OP = 'DELETE';
        rel := TG_RELNAME;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        IF TG_OP = 'UPDATE' THEN
            RETURN rec;
        END IF;

        pk := rec.id;
 
        BEGIN
            INSERT INTO caixa_movto_lote_sync (pkey, excluido) VALUES (pk, ex);
 
        EXCEPTION WHEN unique_violation THEN
 
            UPDATE caixa_movto_lote_sync SET seq = NEXTVAL('caixa_movto_lote_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
        END;
 
        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.caixa_movto_lote_sync_tgf() OWNER TO postgres;

--
-- Name: calcula_entrada_bloco_x_f(bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcula_entrada_bloco_x_f(bigint, bigint, date, date) RETURNS TABLE(quantidade_entrada double precision, valor_entrada double precision, valor_base_icmsst double precision, valor_total_icmsst double precision, valor_total_icms_deb_fornec double precision)
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
BEGIN
-- parametros: empresa, produto, data_ini, data_fim
return query select 
	sum(nfp.quantidade) as quantidade_entrada,
	sum(nfp.valor) as valor_entrada,
	sum((case when substr(nfp.cst,2,3) in ('10') then nfp.base_subst else 0.00 end)) as valor_base_icmsst,
	sum((case when substr(nfp.cst,2,3) in ('10') then nfp.valor_subst else 0.00 end)) as valor_total_icmsst,
	sum((case when substr(nfp.cst,2,3) in ('00','10','20') then nfp.valor_icms else 0.00 end)) as valor_total_icms_deb_fornec
from 
	nota_fiscal nf
	join nota_fiscal_produto nfp on (nfp.nota_fiscal=nf.grid)
where	
	nf.empresa = $1
	and (nf.data_emissao::date between $3 and $4)
	and nf.tipo in ('C','E')
	and nfp.produto=$2
	and substr(nfp.cfop, 1,1) in ('1', '2', '3')
	and not (substr(nfp.cfop, 3,1) in ('2') or substr(nfp.cfop, 3,3) in ('660', '661', '662'));
END;
   
$_$;


ALTER FUNCTION public.calcula_entrada_bloco_x_f(bigint, bigint, date, date) OWNER TO postgres;

--
-- Name: calcula_estoque_deposito_f(bigint, bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcula_estoque_deposito_f(bigint, bigint, bigint, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r RECORD;
	c1 REFCURSOR;
	r_aux RECORD;
	b_found BOOLEAN;
	v_data_ant DATE;
	v_data_cur DATE;
	v_estoque FLOAT;

	-- Totalizadores de operacao de estoque
	v_venda 	FLOAT := 0;
	v_compra 	FLOAT := 0;
	v_perda 	FLOAT := 0;
	v_sobra 	FLOAT := 0;
	v_consumo 	FLOAT := 0;
	v_dev_cli 	FLOAT := 0;
	v_dev_for 	FLOAT := 0;
	v_inv_perda 	FLOAT := 0;
	v_inv_sobra 	FLOAT := 0;
	v_transf_ent 	FLOAT := 0;
	v_transf_sai 	FLOAT := 0;
	v_brinde 	FLOAT := 0;
	v_afericao 	FLOAT := 0;
	v_entrada 	FLOAT := 0;
	v_saida 	FLOAT := 0;
	v_bonificacao 	FLOAT := 0;
	v_sai_desagregacao 	FLOAT := 0;
	v_ent_desagregacao  FLOAT := 0;
	v_sai_reclassificacao	FLOAT := 0;
	v_ent_reclassificacao FLOAT := 0;
	v_msg_erro TEXT := '';
	v_degustacao FLOAT := 0;

  BEGIN
	-- Apaga dados invalidos da tabela estoque_deposito
	BEGIN
		DELETE FROM estoque_deposito WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data>=$4;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('1 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		    PERFORM estoque_log_f($1, $3, $4, 'ESTOQUE_DEPOSITO'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_DEPOSITO_F'::TEXT, v_msg_erro);
	END;

	-- Determina a data do ultimo registro conhecido na estoque_deposito
	-- para comecar a partir dele o preenchimento da tabela
	SELECT data INTO r_aux FROM estoque_deposito
		WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data=($4 - '1 day'::interval)
		ORDER BY data DESC LIMIT 1;

	IF NOT found THEN
		SELECT data INTO r_aux FROM estoque_deposito
			WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data<$4 
			ORDER BY data DESC LIMIT 1;
	END IF;

	IF found THEN
		v_data_ant := r_aux.data + '1 day'::interval;
	ELSE
		v_data_ant := $4;
	END IF;
		
	-- Busca o estoque antes da data informada
	SELECT estoque_dep INTO r FROM estoque_lancto
		WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data=(v_data_ant - '1 day'::interval)
		ORDER BY data DESC, ordem DESC LIMIT 1;

	IF NOT found THEN
		SELECT estoque_dep INTO r FROM estoque_lancto
			WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data < v_data_ant 
			ORDER BY data DESC, ordem DESC LIMIT 1;
	END IF;

	IF found THEN
		v_estoque := r.estoque_dep;
	ELSE
		v_estoque := 0;
	END IF;

	OPEN c1 FOR SELECT el.data, el.operacao, el.estoque_dep, el.movimento
		FROM estoque_lancto el 
		WHERE el.empresa=$1 AND el.deposito=$2 AND el.produto=$3 AND el.data BETWEEN v_data_ant AND current_date
		ORDER BY el.data, el.ordem;


	LOOP
		FETCH c1 INTO r;
		b_found := found;

		IF b_found THEN
			v_data_cur := r.data;
		ELSE
			-- Seta a data informada mais 1 dia apenas para inserir o ultimo registro
			v_data_cur := current_date + '1 day'::interval;
		END IF;

		IF (v_data_ant < v_data_cur) THEN
			WHILE v_data_ant < v_data_cur LOOP

				BEGIN
					INSERT INTO estoque_deposito (
							empresa, deposito, produto, data, estoque, entrada, saida,
							venda, compra, perda, sobra, consumo, dev_cli, dev_for, inv_perda, inv_sobra, 
							transf_ent, transf_sai, brinde, afericao, bonificacao, sai_desagregacao, ent_desagregacao,
							sai_reclassificacao, ent_reclassificacao, sai_degustacao, ult_alteracao)
						VALUES (
							$1, $2, $3, v_data_ant, v_estoque, v_entrada, v_saida,
							v_venda, v_compra, v_perda, v_sobra, v_consumo, v_dev_cli, v_dev_for, v_inv_perda, v_inv_sobra, 
							v_transf_ent, v_transf_sai, v_brinde, v_afericao, v_bonificacao, v_sai_desagregacao, v_ent_desagregacao,
							v_sai_reclassificacao, v_ent_reclassificacao, v_degustacao, now());
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('2 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f($1, $3, $4, 'ESTOQUE_DEPOSITO'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_DEPOSITO_F'::TEXT, v_msg_erro);
				END;

				v_data_ant 	:= v_data_ant + '1 day'::interval;
				v_venda 	:= 0;
				v_compra 	:= 0;
				v_perda 	:= 0;
				v_sobra 	:= 0;
				v_consumo 	:= 0;
				v_dev_cli 	:= 0;
				v_dev_for 	:= 0;
				v_inv_perda 	:= 0;
				v_inv_sobra 	:= 0;
				v_transf_ent 	:= 0;
				v_transf_sai 	:= 0;
				v_brinde 	:= 0;
				v_afericao 	:= 0;
				v_entrada 	:= 0;
				v_saida 	:= 0;
				v_bonificacao 	:= 0;
				v_sai_desagregacao 	:= 0;
				v_ent_desagregacao  := 0;
				v_sai_reclassificacao := 0;
				v_ent_reclassificacao := 0;
				v_degustacao :=0;
			END LOOP;
		END IF;

		EXIT WHEN NOT b_found;

		CONTINUE WHEN r.movimento IS NULL OR r.movimento = 0;
		
		--RAISE INFO 'Movimento: %s, Perda: %s', r.movimento, v_inv_perda;
		IF r.operacao = 'V' THEN
			v_venda := v_venda + (r.movimento*-1);
		ELSIF r.operacao = 'E' THEN
			v_compra := v_compra + abs(r.movimento);
		ELSIF r.operacao = 'P' THEN
			v_perda := v_perda + abs(r.movimento);
		ELSIF r.operacao = 'S' THEN
			v_sobra := v_sobra + abs(r.movimento);
		ELSIF r.operacao = 'C' THEN
			v_consumo := v_consumo + abs(r.movimento);
		ELSIF r.operacao = 'DC' THEN
			v_dev_cli := v_dev_cli + abs(r.movimento);
		ELSIF r.operacao = 'DF' THEN
			v_dev_for := v_dev_for + abs(r.movimento);
		ELSIF r.operacao IN ('I','M','F') AND r.movimento < 0 THEN
			v_inv_perda := v_inv_perda + abs(r.movimento);
		ELSIF r.operacao IN ('I','M','F') AND r.movimento > 0 THEN
			v_inv_sobra := v_inv_sobra + abs(r.movimento);
		ELSIF r.operacao = 'TE' THEN
			v_transf_ent := v_transf_ent + abs(r.movimento);
		ELSIF r.operacao = 'TS' THEN
			v_transf_sai := v_transf_sai + abs(r.movimento);
		ELSIF r.operacao = 'B' THEN
			v_brinde := v_brinde + abs(r.movimento);
		ELSIF r.operacao = 'A' THEN
			v_afericao := v_afericao + abs(r.movimento);
		ELSIF r.operacao = 'O' THEN
			v_bonificacao := v_bonificacao + abs(r.movimento);
		ELSIF r.operacao = 'SD' THEN
			v_sai_desagregacao := v_sai_desagregacao + abs(r.movimento);
		ELSIF r.operacao = 'ED' THEN
			v_ent_desagregacao := v_ent_desagregacao + abs(r.movimento);
		ELSIF r.operacao = 'SR' THEN
			v_sai_reclassificacao := v_sai_reclassificacao + abs(r.movimento);
		ELSIF r.operacao = 'ER' THEN
			v_ent_reclassificacao := v_ent_reclassificacao + abs(r.movimento);
		ELSIF r.operacao = 'DG' THEN
			v_degustacao := v_degustacao + abs(r.movimento);
		END IF;
		--RAISE INFO 'Movimento: %s, Perda: %s', r.movimento, v_inv_perda;
		v_entrada := v_compra+v_sobra+v_inv_sobra+v_dev_cli+v_transf_ent+v_bonificacao+v_ent_desagregacao+v_ent_reclassificacao;  
		v_saida := v_venda+v_perda+v_inv_perda+v_consumo+v_dev_for+v_transf_sai+v_brinde+v_sai_desagregacao+v_sai_reclassificacao+v_degustacao;

		v_estoque := r.estoque_dep;
	END LOOP;

	CLOSE c1;

  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, $3, $4, 'PROGRAMACAO'::text, 'GERAL'::text, 'CALCULA_ESTOQUE_DEPOSITO_F'::TEXT, v_msg_erro);
  END;
  
$_$;


ALTER FUNCTION public.calcula_estoque_deposito_f(bigint, bigint, bigint, date) OWNER TO postgres;

--
-- Name: calcula_estoque_lancto_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcula_estoque_lancto_f(bigint, bigint, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r_aux RECORD;
	r_prod RECORD;
	e_aux  RECORD;
	i INTEGER;
	r RECORD;
	estoque_dep_init boolean;
	c1 REFCURSOR;
	op_entrada BOOLEAN;
	v_data_ini DATE;
	v_data_ant DATE;
	v_ordem INTEGER;
	v_custo_medio FLOAT;	-- Ultimo custo medio
	v_ult_custo FLOAT;		-- Ultimo custo
	v_custo_medio_fiscal FLOAT; -- Custo medio sem imposto
	v_ult_custo_fiscal FLOAT;  -- Ultimo custo sem imposto
	v_custo_fiscal FLOAT;  --  custo sem imposto

	v_estoque_emp FLOAT;	-- Acumulam o estoque da empresa
	v_estoque_dep FLOAT;	-- Acumulam o estoque do deposito
	v_movimento FLOAT;

	v_custo_medio_ant FLOAT;	-- Ultimo custo medio
	v_ult_custo_ant FLOAT;		-- Ultimo custo
	v_ult_custo_fiscal_ant FLOAT;		-- Ultimo custo fiscal
	v_custo_medio_fiscal_ant FLOAT;    -- Ultimo custo medio fiscal

	-- Controle do array de estoque por deposito
	v_dep_len INTEGER = 1;
	a_deposito BIGINT[];		-- depositos que movimentam o produto
	a_estoque FLOAT[];		-- estoque de cada deposito
	a_data DATE[];			-- data do ultimo movimento processado de cada deposito
	v_deposito bigint;
	v_data date;
	v_estoque float;
	v_msg_erro TEXT := '';
	v_ascustom boolean := False; --controle de customizacao
	v_empresa_cpf text; --cpf da empresa do custom

  BEGIN

	-- verifica cpf para customizacao
	SELECT e.cpf INTO v_empresa_cpf FROM empresa_local el JOIN empresa e ON (el.empresa=e.grid);

	-- [REDE SIM]
	IF SPLIT_PART(v_empresa_cpf,'/','1') = '07.473.735' THEN
		v_ascustom := True;
	END IF;

	-- FIXME LOCK TABLE lancto?
	BEGIN
		DELETE FROM estoque_lancto  WHERE empresa=$1 AND produto=$2 AND data>=$3;
		DELETE FROM estoque_produto WHERE empresa=$1 AND produto=$2;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('3 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		    PERFORM estoque_log_f($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
    END;

	-- Busca a ultima movimentacao antes da data inicial
	-- FIXME talvez buscar na estoque_deposito -> mais rapido
	SELECT * INTO r FROM estoque_lancto WHERE empresa=$1 AND produto=$2 and data=($3 - '1 day'::interval)
		ORDER BY data DESC, ordem DESC LIMIT 1;

	IF NOT found THEN
		SELECT * INTO r FROM estoque_lancto WHERE empresa=$1 AND produto=$2 and data<$3
			ORDER BY data DESC, ordem DESC LIMIT 1;
	END IF;

	IF found THEN
		v_data_ini := r.data;
		v_estoque_emp := r.estoque_emp;
		v_custo_medio := r.custo_medio;
		v_ult_custo := r.ult_custo;
		v_custo_medio_fiscal := r.custo_medio_fiscal;
		v_ult_custo_fiscal := r.ult_custo_fiscal;
	ELSE
		v_data_ini := '0001-01-01';
		v_estoque_emp := 0;
		v_custo_medio := 0;
		v_ult_custo := 0;
		v_custo_medio_fiscal := 0;
		v_ult_custo_fiscal := 0;
	END IF;

	v_ordem := 1;
	select p.controlar_estoque, p.tipo into r_prod from produto p where p.grid = $2;		

	OPEN c1 FOR SELECT l.grid, l.mlid, l.deposito, l.data, l.operacao, l.quantidade, l.preco_unit, l.preco_unit_fiscal
		FROM lancto l WHERE l.empresa=$1 AND l.produto=$2 AND l.data>v_data_ini
		ORDER BY l.data, l.turno, l.hora, l.grid;

	LOOP
		FETCH c1 INTO r;
		EXIT WHEN NOT found;

		-- Caso nao tenha quantidade, continua
		CONTINUE WHEN r.quantidade IS NULL;	
			
		-- Quebra da ordem
		IF (v_data_ant IS NULL OR v_data_ant != r.data) THEN			
			v_ordem := 1;
			v_data_ant := r.data;			
			
			--zera o gnv no inicio do m√™s
			if date_part('d', r.data) = 1 and not r_prod.controlar_estoque and r_prod.tipo = 'C' then
				v_estoque_emp := 0;
			end if;
		END IF;

		op_entrada := FALSE;

		-- Testa se eh uma entrada que modifica o custo, sendo:
		-- 1) Compra
		-- 2) Devolucao de cliente
		-- 3) Transferencia externa

		IF (NOT r.quantidade IS NULL AND r.quantidade != 0) THEN
			IF (NOT r.preco_unit IS NULL AND r.preco_unit != 0) THEN
				--IF r.operacao IN ('E', 'DC') THEN
				-- comentado por causa do erro na mostragem do valor de custo no relatorio de venda lucro produto
				IF r.operacao = 'E' THEN
					op_entrada := TRUE;
				ELSIF r.operacao = 'TE' THEN
					IF r.mlid IS NULL THEN
						op_entrada := TRUE;
					ELSE
						-- FIXME Quando fizer transferencia entre postos e tirar o relatorio
						-- FIXME no posto esse valor vai falhar, pois o posto tem apenas a movimentacao 
						-- FIXME de estoque dele.

						SELECT grid INTO r_aux FROM lancto 
							WHERE empresa=$1 AND mlid=r.mlid AND produto=$2 AND operacao='TS';

						IF NOT found THEN
							op_entrada := TRUE;
						END IF;
					END IF;
				END IF;
			END IF;
		END IF;

		IF op_entrada THEN
			v_custo_medio_ant := v_custo_medio;
			v_ult_custo_ant := v_ult_custo;
			v_custo_medio_fiscal_ant := v_custo_medio_fiscal;		
			v_ult_custo_fiscal_ant := v_ult_custo_fiscal;
		
			IF (v_estoque_emp <= 0 OR v_custo_medio = 0) THEN
				v_custo_medio := r.preco_unit;
			ELSE
				-- (valor estoque ant + valor entrada) / estoque final
				BEGIN
					v_custo_medio := ((v_estoque_emp * v_custo_medio) + (r.quantidade * r.preco_unit)) / (v_estoque_emp + r.quantidade);
				EXCEPTION 
					WHEN division_by_zero THEN
						v_custo_medio := ((v_estoque_emp * v_custo_medio) + (r.quantidade * r.preco_unit));
				END;
			END IF;

			v_custo_medio := ROUND(v_custo_medio::numeric, 8);
			v_ult_custo := r.preco_unit;

			v_ult_custo_fiscal := r.preco_unit_fiscal;
			
			IF (v_custo_medio_fiscal = 0 or v_custo_medio_fiscal is null) AND v_ascustom THEN
				SELECT l.preco_unit into v_custo_medio_fiscal
				  FROM lancto l
				 WHERE l.empresa = $1
				   AND l.produto = $2
				   AND l.operacao in ('M', 'I')
			  ORDER BY l.data, l.turno, l.hora LIMIT 1;

				BEGIN
					UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal, ult_custo_fiscal = v_custo_medio_fiscal
				WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
					EXCEPTION
						WHEN OTHERS THEN
							v_msg_erro := upper('20 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
							PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;

			END IF;

			IF (v_estoque_emp <= 0 OR v_custo_medio_fiscal = 0) THEN
				v_custo_medio_fiscal := v_ult_custo_fiscal;
			ELSE
				-- (valor estoque ant + valor entrada) / estoque final
				BEGIN
					v_custo_medio_fiscal := ((v_estoque_emp * v_custo_medio_fiscal) + (r.quantidade * v_ult_custo_fiscal)) / (v_estoque_emp + r.quantidade);
				EXCEPTION 
					WHEN division_by_zero THEN
						v_custo_medio_fiscal := ((v_estoque_emp * v_custo_medio_fiscal) + (r.quantidade * v_ult_custo_fiscal));
				END;
			END IF;

			IF (v_custo_medio_fiscal IS NULL) THEN
				v_custo_medio_fiscal := v_ult_custo_fiscal;
			END IF;

			v_custo_medio_fiscal := ROUND(v_custo_medio_fiscal::numeric, 8);

			---------------------------------------------------------------------------------------------------

			--RAISE INFO '%', v_custo_medio;

			IF v_custo_medio_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET custo_medio = v_custo_medio WHERE empresa=$1 AND produto=$2 AND custo_medio=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('4 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;

				BEGIN
					UPDATE estoque_lancto SET ult_custo = v_ult_custo WHERE empresa=$1 AND produto=$2 AND ult_custo=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('5 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;

			IF v_custo_medio_fiscal_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('13 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;
			
			IF v_ult_custo_fiscal_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET ult_custo_fiscal = v_ult_custo_fiscal WHERE empresa=$1 AND produto=$2 AND ult_custo_fiscal=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('19 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;

		END IF;

		v_estoque_dep := NULL;

		FOR i IN 1..v_dep_len LOOP
			IF a_deposito[i] = r.deposito THEN
				v_estoque_dep = a_estoque[i];
				EXIT;
			END IF;
		END LOOP;

		IF v_estoque_dep IS NULL THEN
			SELECT estoque_dep, data INTO r_aux FROM estoque_lancto 
				WHERE empresa=$1 AND produto=$2 AND data=($3 - '1 day'::interval) AND deposito=r.deposito
				ORDER BY data DESC, ordem DESC LIMIT 1;

			IF NOT found THEN
				SELECT estoque_dep, data INTO r_aux FROM estoque_lancto 
					WHERE empresa=$1 AND produto=$2 AND data<$3 AND deposito=r.deposito
					ORDER BY data DESC, ordem DESC LIMIT 1;
			END IF;

			IF found THEN
				v_estoque_dep := r_aux.estoque_dep;
				a_data[v_dep_len] := r_aux.data::DATE;
			ELSE
				v_estoque_dep := 0;
				a_data[v_dep_len] := NULL::DATE;
			END IF;

			a_deposito[v_dep_len] := r.deposito;
			a_estoque[v_dep_len] := v_estoque_dep::FLOAT;
			v_dep_len := v_dep_len + 1;
		END IF;

		-- ZERAR GNV 		
		if date_part('d', r.data) = 1 and not r_prod.controlar_estoque and r_prod.tipo = 'C' then
			IF date_part('d', r.data) = 1 THEN -- Primeiro dia do mes
				FOR i IN 1..v_dep_len LOOP
					IF a_deposito[i] = r.deposito THEN
						IF a_data[i] != r.data THEN
							v_estoque_dep := 0;
						END IF;
						EXIT;
					END IF;
				END LOOP;
			END IF;
		END IF;

		v_movimento := 0;

		-- Calcula o estoque conforme a operacao
		IF r.operacao in ('V','C','P','DF','TS','B', 'SD', 'SR', 'DG') then
			v_movimento := r.quantidade * -1;
		ELSIF r.operacao in ('E','S','TE','DC', 'O', 'ED', 'ER') THEN
			v_movimento := r.quantidade;
		ELSIF r.operacao in ('I','M') THEN
			v_movimento := r.quantidade - v_estoque_dep;
		ELSIF r.operacao = 'F' THEN
			v_movimento := v_estoque_dep * -1;
		END IF;

		v_estoque_dep := v_estoque_dep + v_movimento;
		v_estoque_emp := v_estoque_emp + v_movimento;

		SELECT lancto INTO r_aux FROM estoque_lancto
			WHERE lancto = r.grid;

		IF found THEN
			BEGIN
				DELETE FROM estoque_lancto WHERE lancto = r.grid;
			EXCEPTION
				WHEN OTHERS THEN
					v_msg_erro := upper('6 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
					PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
			END;
		END IF;

		BEGIN

			IF v_custo_medio = 0 and r.operacao = 'I' THEN
				v_custo_medio := r.preco_unit;
			END IF;

			IF v_custo_medio_fiscal = 0 and r.operacao = 'I' THEN
				v_custo_medio_fiscal := r.preco_unit_fiscal;
			END IF;

			INSERT INTO estoque_lancto (
				empresa, deposito, produto, data, operacao, ordem, lancto,
				movimento, estoque_dep, estoque_emp, custo_medio, ult_custo,
				custo_medio_fiscal, ult_custo_fiscal
				)
			VALUES (
				$1, r.deposito, $2, r.data, r.operacao, v_ordem, r.grid,
				v_movimento, v_estoque_dep, v_estoque_emp, v_custo_medio, v_ult_custo,
				v_custo_medio_fiscal, v_ult_custo_fiscal
			);
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('7 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;

		FOR i IN 1..v_dep_len LOOP
			IF a_deposito[i] = r.deposito THEN
				a_estoque[i] := v_estoque_dep;
				a_data[i] := r.data;
				EXIT;
			END IF;
		END LOOP;

		v_ordem := v_ordem + 1;
	END LOOP;

	CLOSE c1;

	IF v_ult_custo = 0 THEN
		v_ult_custo := preco_custo_empresa_f($2, $1);
		BEGIN
			UPDATE estoque_lancto SET ult_custo=v_ult_custo	WHERE empresa=$1 AND produto=$2 AND ult_custo = 0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('8 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	IF v_custo_medio = 0 THEN
		v_custo_medio := v_ult_custo;
		BEGIN
			UPDATE estoque_lancto SET custo_medio=v_custo_medio WHERE empresa=$1 AND produto=$2 AND custo_medio = 0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('9 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;	

	IF v_ult_custo_fiscal = 0 or v_ult_custo_fiscal is null THEN

		-- se for rede sim e o produto nao tiver entrada pegar o primeiro custo de inventario
		IF v_ascustom THEN
				SELECT l.preco_unit into v_ult_custo_fiscal
				  FROM lancto l
				 WHERE l.empresa = $1
				   AND l.produto = $2
				   AND l.operacao in ('M', 'I')
			  ORDER BY l.data, l.turno, l.hora LIMIT 1;

			IF NOT FOUND THEN
				v_ult_custo_fiscal := 0;
			END IF;

		END IF;

		BEGIN
			UPDATE estoque_lancto SET ult_custo_fiscal = v_ult_custo_fiscal WHERE empresa=$1 AND produto=$2 AND ult_custo_fiscal=0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('19 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	IF v_custo_medio_fiscal = 0 or v_custo_medio_fiscal is null THEN

		v_custo_medio_fiscal := v_ult_custo_fiscal;

		BEGIN
			UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('18 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	----------------------------------------------------------------------------
	-- Atualiza a tabela estoque_prodruto
	-- Tabela responsavel por guardar a ultima movimentacao do produto
	FOR e_aux in select max(data) as data, deposito from estoque_lancto where empresa=$1 and produto=$2 group by deposito LOOP
    
		BEGIN
			INSERT INTO estoque_produto (empresa, deposito, produto, data, estoque, custo_medio, ult_custo, ts_atualizacao, custo_medio_fiscal, ult_custo_fiscal)
				SELECT empresa,deposito,produto,data,coalesce(estoque_dep,0)
				      ,coalesce(custo_medio,v_custo_medio,0),coalesce(ult_custo,v_ult_custo,0), now()::timestamp as ts_atualizacao
					  ,coalesce(custo_medio_fiscal,v_custo_medio_fiscal,0), coalesce(ult_custo_fiscal,v_ult_custo_fiscal,0)
				  FROM estoque_lancto
				 WHERE empresa=$1
				   AND deposito=e_aux.deposito
				   AND produto=$2
				   AND data=e_aux.data
			  ORDER BY ordem desc
                 LIMIT 1;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('11 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_PRODUTO'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
		
	END LOOP;
	
	-- manter atualizado o custo para todos os depositos, pois as vezes o produto possui a movimentacao em apenas 1 deposito
	-- com isso o custo acaba ficando diferente de um deposito para o outro
	BEGIN
		UPDATE estoque_produto
		   SET custo_medio=coalesce(v_custo_medio, 0)
			  ,ult_custo=coalesce(v_ult_custo, 0)
			  ,custo_medio_fiscal=coalesce(v_custo_medio_fiscal,0)
			  ,ult_custo_fiscal=coalesce(v_ult_custo_fiscal,0)
		 WHERE empresa=$1
		   AND produto=$2;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('12 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
			PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_PRODUTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
	END;
	---------------------------------------------------------------------------
	
  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f ($1, $2, $3, 'PROGRAMACAO'::text, 'GERAL'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
  END;  
  
$_$;


ALTER FUNCTION public.calcula_estoque_lancto_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: calcula_estoque_lancto_f(bigint, bigint, date, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcula_estoque_lancto_f(bigint, bigint, date, boolean) RETURNS void
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r_aux RECORD;
	r_prod RECORD;
	e_aux  RECORD;
	i INTEGER;
	r RECORD;
	estoque_dep_init boolean;
	c1 REFCURSOR;
	op_entrada BOOLEAN;
	v_data_ini DATE;
	v_data_ant DATE;
	v_ordem INTEGER;
	v_custo_medio FLOAT;	-- Ultimo custo medio
	v_ult_custo FLOAT;		-- Ultimo custo
	v_custo_medio_fiscal FLOAT; -- Custo medio sem imposto
	v_ult_custo_fiscal FLOAT;  -- Ultimo custo sem imposto
	v_custo_fiscal FLOAT;  --  custo sem imposto

	v_estoque_emp FLOAT;	-- Acumulam o estoque da empresa
	v_estoque_dep FLOAT;	-- Acumulam o estoque do deposito
	v_movimento FLOAT;

	v_custo_medio_ant FLOAT;	-- Ultimo custo medio
	v_ult_custo_ant FLOAT;		-- Ultimo custo
	v_ult_custo_fiscal_ant FLOAT;		-- Ultimo custo fiscal
	v_custo_medio_fiscal_ant FLOAT;    -- Ultimo custo medio fiscal

	-- Controle do array de estoque por deposito
	v_dep_len INTEGER = 1;
	a_deposito BIGINT[];		-- depositos que movimentam o produto
	a_estoque FLOAT[];		-- estoque de cada deposito
	a_data DATE[];			-- data do ultimo movimento processado de cada deposito
	v_deposito bigint;
	v_data date;
	v_estoque float;
	v_msg_erro TEXT := '';
	v_ascustom boolean := False; --controle de customizacao
	v_empresa_cpf text; --cpf da empresa do custom

	-- Custo de produtos compostos
	c2 REFCURSOR;
	r_pc RECORD;
	v_custo_medio_comp FLOAT;
	v_ult_custo_comp FLOAT;
	v_custo_medio_fiscal_comp FLOAT;
	v_ult_custo_fiscal_comp	FLOAT;
	v_preco_unit FLOAT;
	v_preco_unit_fiscal FLOAT;
	v_quantidade_comp FLOAT;
	v_quantidade_venda FLOAT;
	achou boolean := False;
	v_fabricado_venda BOOLEAN;

  BEGIN

	-- verifica cpf para customizacao
	SELECT e.cpf INTO v_empresa_cpf FROM empresa_local el JOIN empresa e ON (el.empresa=e.grid);

	-- [REDE SIM]
	IF SPLIT_PART(v_empresa_cpf,'/','1') = '07.473.735' THEN
		v_ascustom := True;
	END IF;

	-- FIXME LOCK TABLE lancto?
	BEGIN
		DELETE FROM estoque_lancto  WHERE empresa=$1 AND produto=$2 AND data>=$3;
		DELETE FROM estoque_produto WHERE empresa=$1 AND produto=$2;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('3 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		    PERFORM estoque_log_f($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
    END;

	-- Busca a ultima movimentacao antes da data inicial
	-- FIXME talvez buscar na estoque_deposito -> mais rapido
	SELECT * INTO r FROM estoque_lancto WHERE empresa=$1 AND produto=$2 and data=($3 - '1 day'::interval)
		ORDER BY data DESC, ordem DESC LIMIT 1;

	IF NOT found THEN
		SELECT * INTO r FROM estoque_lancto WHERE empresa=$1 AND produto=$2 and data<$3
			ORDER BY data DESC, ordem DESC LIMIT 1;
	END IF;

	IF found THEN
		v_data_ini := r.data;
		v_estoque_emp := r.estoque_emp;
		v_custo_medio := r.custo_medio;
		v_ult_custo := r.ult_custo;
		v_custo_medio_fiscal := r.custo_medio_fiscal;
		v_ult_custo_fiscal := r.ult_custo_fiscal;
	ELSE
		v_data_ini := '0001-01-01';
		v_estoque_emp := 0;
		v_custo_medio := 0;
		v_ult_custo := 0;
		v_custo_medio_fiscal := 0;
		v_ult_custo_fiscal := 0;
	END IF;

	SELECT fabricado_venda INTO v_fabricado_venda FROM produto where grid = $2;

	v_ordem := 1;
	select p.controlar_estoque, p.tipo into r_prod from produto p where p.grid = $2;

	OPEN c1 FOR SELECT l.grid, l.mlid, l.deposito, l.data, l.operacao, l.quantidade, l.preco_unit, l.preco_unit_fiscal
		FROM lancto l WHERE l.empresa=$1 AND l.produto=$2 AND l.data>v_data_ini
		ORDER BY l.data, l.turno, l.hora, l.grid;

	LOOP
		FETCH c1 INTO r;
		EXIT WHEN NOT found;

		-- Caso nao tenha quantidade, continua
		CONTINUE WHEN r.quantidade IS NULL;

		-- Quebra da ordem
		IF (v_data_ant IS NULL OR v_data_ant != r.data) THEN
			v_ordem := 1;
			v_data_ant := r.data;

			--zera o gnv no inicio do mÍs
			if date_part('d', r.data) = 1 and not r_prod.controlar_estoque and r_prod.tipo = 'C' then
				v_estoque_emp := 0;
			end if;
		END IF;

		v_preco_unit = r.preco_unit;
		v_preco_unit_fiscal = r.preco_unit_fiscal;

		-- Calcula o custo de produtos compostos
		IF $4 THEN
			v_ult_custo_comp := 0.0;
			v_ult_custo_fiscal_comp := 0.0;
			v_custo_medio_comp := 0.0;
			v_custo_medio_fiscal_comp := 0.0;

			OPEN c2 FOR 
				SELECT l.quantidade as qtd_lancto, l.produto as materia_prima FROM lancto l 
				WHERE l.mlid = r.mlid AND l.operacao = 'SR' AND l.id_er_sr = r.id_er_sr;
			FETCH c2 INTO r_pc;

			IF NOT FOUND THEN
				CLOSE c2;
				achou := False;

				IF v_fabricado_venda THEN
					OPEN c2 FOR SELECT pc.materia_prima, pc.opcional, avg(pc.quantidade) as qtd_mp, avg(l.quantidade) as qtd_lancto FROM produto_composicao pc
						LEFT JOIN lancto l ON (l.produto = pc.materia_prima and l.mlid = r.mlid and l.operacao = 'SR') 
						WHERE pc.produto=$2 AND pc.empresa=$1 GROUP BY pc.materia_prima, pc.opcional;
					FETCH c2 INTO r_pc;
				ELSE
					OPEN c2 FOR SELECT pc.materia_prima, pc.opcional, pc.quantidade as qtd_mp FROM produto_composicao pc
						WHERE pc.produto=$2 AND pc.empresa=$1 
						UNION
						SELECT pc.materia_prima, pc.opcional, pc.quantidade as qtd_mp FROM produto_composicao pc
						WHERE pc.produto=$2 AND empresa IS NULL AND pc.materia_prima NOT IN (
							SELECT materia_prima from produto_composicao WHERE empresa=$1)
						GROUP BY pc.materia_prima, pc.opcional, qtd_mp;
					FETCH c2 INTO r_pc;
				END IF;
			ELSE
				achou := True;
			END IF;
	
			IF NOT FOUND THEN
				CLOSE c2;
				OPEN c2 FOR SELECT pc.materia_prima, pc.opcional, pc.quantidade as qtd_mp, l.quantidade as qtd_lancto FROM produto_composicao pc
					LEFT JOIN lancto l ON (l.produto = pc.materia_prima and l.mlid = r.mlid and l.operacao = 'SR')
					WHERE pc.produto=$2 AND pc.empresa IS NULL GROUP BY pc.materia_prima, pc.opcional, qtd_mp, qtd_lancto;
				FETCH c2 INTO r_pc;
			END IF;

			LOOP
				EXIT WHEN NOT FOUND;

				IF r.quantidade != 0 THEN
					v_quantidade_venda := r.quantidade;
				ELSE
					v_quantidade_venda := 1;
				END IF;

				IF not achou THEN
					IF v_fabricado_venda THEN
						IF r_pc.qtd_lancto IS NULL THEN
							IF r_pc.opcional THEN
								FETCH c2 INTO r_pc;
								CONTINUE;
							END IF;

							v_quantidade_comp := r_pc.qtd_mp;
							v_quantidade_venda := 1;
						ELSE
							v_quantidade_comp := r_pc.qtd_lancto;
						END IF;
					ELSE
						v_quantidade_venda := 1;
						v_quantidade_comp := r_pc.qtd_mp;
					END IF;
				ELSE
					v_quantidade_comp := r_pc.qtd_lancto;
				END IF;

				v_ult_custo_comp := v_ult_custo_comp + (preco_custo_empresa_f(r_pc.materia_prima,$1,r.data) * v_quantidade_comp)/ v_quantidade_venda;
				v_ult_custo_fiscal_comp := v_ult_custo_fiscal_comp + (preco_custo_fiscal_empresa_f(r_pc.materia_prima,$1,r.data) * v_quantidade_comp)/ v_quantidade_venda;
				v_custo_medio_comp := v_custo_medio_comp + (custo_medio_empresa_f($1, r_pc.materia_prima, r.data) * v_quantidade_comp)/ v_quantidade_venda;
				v_custo_medio_fiscal_comp := v_custo_medio_fiscal_comp + (custo_medio_fiscal_empresa_f($1, r_pc.materia_prima, r.data) * v_quantidade_comp)/ v_quantidade_venda;

				FETCH c2 INTO r_pc;
			END LOOP;
			CLOSE c2;

			IF v_ult_custo_comp > 0 THEN
				v_preco_unit := v_ult_custo_comp;
			END IF;

			IF v_ult_custo_fiscal_comp > 0 THEN
				v_preco_unit_fiscal := v_ult_custo_fiscal_comp;
			END IF;

			IF (v_custo_medio = 0 AND v_custo_medio_comp != 0) THEN
				BEGIN
					UPDATE estoque_lancto SET custo_medio = v_custo_medio_comp WHERE empresa=$1 AND produto=$2 AND custo_medio=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('4 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;

				BEGIN
					UPDATE estoque_lancto SET ult_custo = v_ult_custo_comp WHERE empresa=$1 AND produto=$2 AND ult_custo=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('5 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;

			v_custo_medio := v_custo_medio_comp;
			v_custo_medio_fiscal := v_custo_medio_fiscal_comp;
		END IF;

		op_entrada := FALSE;

		-- Testa se eh uma entrada que modifica o custo, sendo:
		-- 1) Compra
		-- 2) Devolucao de cliente
		-- 3) Transferencia externa

		IF (NOT r.quantidade IS NULL AND r.quantidade != 0) THEN
			IF (NOT v_preco_unit IS NULL AND v_preco_unit != 0) THEN
				--IF r.operacao IN ('E', 'DC') THEN
				-- comentado por causa do erro na mostragem do valor de custo no relatorio de venda lucro produto
				IF r.operacao = 'E' THEN
					op_entrada := TRUE;
				ELSIF r.operacao = 'TE' THEN
					IF r.mlid IS NULL THEN
						op_entrada := TRUE;
					ELSE
						-- FIXME Quando fizer transferencia entre postos e tirar o relatorio
						-- FIXME no posto esse valor vai falhar, pois o posto tem apenas a movimentacao 
						-- FIXME de estoque dele.

						SELECT grid INTO r_aux FROM lancto 
							WHERE empresa=$1 AND mlid=r.mlid AND produto=$2 AND operacao='TS';

						IF NOT found THEN
							op_entrada := TRUE;
						END IF;
					END IF;
				END IF;
			END IF;
		END IF;

		IF op_entrada THEN
			v_custo_medio_ant := v_custo_medio;
			v_ult_custo_ant := v_ult_custo;
			v_custo_medio_fiscal_ant := v_custo_medio_fiscal;
			v_ult_custo_fiscal_ant := v_ult_custo_fiscal;
		
			IF (v_estoque_emp <= 0 OR v_custo_medio = 0) THEN
				v_custo_medio := v_preco_unit;
			ELSE
				-- (valor estoque ant + valor entrada) / estoque final
				BEGIN
					v_custo_medio := ((v_estoque_emp * v_custo_medio) + (r.quantidade * v_preco_unit)) / (v_estoque_emp + r.quantidade);
				EXCEPTION
					WHEN division_by_zero THEN
						v_custo_medio := ((v_estoque_emp * v_custo_medio) + (r.quantidade * v_preco_unit));
				END;
			END IF;

			v_custo_medio := ROUND(v_custo_medio::numeric, 8);
			v_ult_custo := v_preco_unit;

			v_ult_custo_fiscal := v_preco_unit_fiscal;

			IF (v_custo_medio_fiscal = 0 or v_custo_medio_fiscal is null) AND v_ascustom THEN
				SELECT l.preco_unit into v_custo_medio_fiscal
				  FROM lancto l
				 WHERE l.empresa = $1
				   AND l.produto = $2
				   AND l.operacao in ('M', 'I')
			  ORDER BY l.data, l.turno, l.hora LIMIT 1;

				BEGIN
					UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal, ult_custo_fiscal = v_custo_medio_fiscal
				WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
					EXCEPTION
						WHEN OTHERS THEN
							v_msg_erro := upper('20 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
							PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;

			END IF;

			IF (v_estoque_emp <= 0 OR v_custo_medio_fiscal = 0) THEN
				v_custo_medio_fiscal := v_ult_custo_fiscal;
			ELSE
				-- (valor estoque ant + valor entrada) / estoque final
				BEGIN
					v_custo_medio_fiscal := ((v_estoque_emp * v_custo_medio_fiscal) + (r.quantidade * v_ult_custo_fiscal)) / (v_estoque_emp + r.quantidade);
				EXCEPTION 
					WHEN division_by_zero THEN
						v_custo_medio_fiscal := ((v_estoque_emp * v_custo_medio_fiscal) + (r.quantidade * v_ult_custo_fiscal));
				END;
			END IF;

			IF (v_custo_medio_fiscal IS NULL) THEN
				v_custo_medio_fiscal := v_ult_custo_fiscal;
			END IF;

			v_custo_medio_fiscal := ROUND(v_custo_medio_fiscal::numeric, 8);

			---------------------------------------------------------------------------------------------------

			--RAISE INFO '%', v_custo_medio;

			IF v_custo_medio_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET custo_medio = v_custo_medio WHERE empresa=$1 AND produto=$2 AND custo_medio=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('4 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;

				BEGIN
					UPDATE estoque_lancto SET ult_custo = v_ult_custo WHERE empresa=$1 AND produto=$2 AND ult_custo=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('5 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;

			IF v_custo_medio_fiscal_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('13 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;
			
			IF v_ult_custo_fiscal_ant = 0 THEN
				BEGIN
					UPDATE estoque_lancto SET ult_custo_fiscal = v_ult_custo_fiscal WHERE empresa=$1 AND produto=$2 AND ult_custo_fiscal=0;
				EXCEPTION
					WHEN OTHERS THEN
						v_msg_erro := upper('19 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
						PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
				END;
			END IF;

		END IF;

		v_estoque_dep := NULL;

		FOR i IN 1..v_dep_len LOOP
			IF a_deposito[i] = r.deposito THEN
				v_estoque_dep = a_estoque[i];
				EXIT;
			END IF;
		END LOOP;

		IF v_estoque_dep IS NULL THEN
			SELECT estoque_dep, data INTO r_aux FROM estoque_lancto 
				WHERE empresa=$1 AND produto=$2 AND data=($3 - '1 day'::interval) AND deposito=r.deposito
				ORDER BY data DESC, ordem DESC LIMIT 1;

			IF NOT found THEN
				SELECT estoque_dep, data INTO r_aux FROM estoque_lancto 
					WHERE empresa=$1 AND produto=$2 AND data<$3 AND deposito=r.deposito
					ORDER BY data DESC, ordem DESC LIMIT 1;
			END IF;

			IF found THEN
				v_estoque_dep := r_aux.estoque_dep;
				a_data[v_dep_len] := r_aux.data::DATE;
			ELSE
				v_estoque_dep := 0;
				a_data[v_dep_len] := NULL::DATE;
			END IF;

			a_deposito[v_dep_len] := r.deposito;
			a_estoque[v_dep_len] := v_estoque_dep::FLOAT;
			v_dep_len := v_dep_len + 1;
		END IF;

		-- ZERAR GNV 		
		if date_part('d', r.data) = 1 and not r_prod.controlar_estoque and r_prod.tipo = 'C' then
			IF date_part('d', r.data) = 1 THEN -- Primeiro dia do mes
				FOR i IN 1..v_dep_len LOOP
					IF a_deposito[i] = r.deposito THEN
						IF a_data[i] != r.data THEN
							v_estoque_dep := 0;
						END IF;
						EXIT;
					END IF;
				END LOOP;
			END IF;
		END IF;

		v_movimento := 0;

		-- Calcula o estoque conforme a operacao
		IF r.operacao in ('V','C','P','DF','TS','B', 'SD', 'SR', 'DG') then
			v_movimento := r.quantidade * -1;
		ELSIF r.operacao in ('E','S','TE','DC', 'O', 'ED', 'ER') THEN
			v_movimento := r.quantidade;
		ELSIF r.operacao in ('I','M') THEN
			v_movimento := r.quantidade - v_estoque_dep;
		ELSIF r.operacao = 'F' THEN
			v_movimento := v_estoque_dep * -1;
		END IF;

		v_estoque_dep := v_estoque_dep + v_movimento;
		v_estoque_emp := v_estoque_emp + v_movimento;

		SELECT lancto INTO r_aux FROM estoque_lancto
			WHERE lancto = r.grid;

		IF found THEN
			BEGIN
				DELETE FROM estoque_lancto WHERE lancto = r.grid;
			EXCEPTION
				WHEN OTHERS THEN
					v_msg_erro := upper('6 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
					PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
			END;
		END IF;

		BEGIN

			IF v_custo_medio = 0 and r.operacao = 'I' THEN
				v_custo_medio := v_preco_unit;
			END IF;

			IF v_custo_medio_fiscal = 0 and r.operacao = 'I' THEN
				v_custo_medio_fiscal := v_preco_unit_fiscal;
			END IF;

			INSERT INTO estoque_lancto (
				empresa, deposito, produto, data, operacao, ordem, lancto,
				movimento, estoque_dep, estoque_emp, custo_medio, ult_custo,
				custo_medio_fiscal, ult_custo_fiscal
				)
			VALUES (
				$1, r.deposito, $2, r.data, r.operacao, v_ordem, r.grid,
				v_movimento, v_estoque_dep, v_estoque_emp, v_custo_medio, v_ult_custo,
				v_custo_medio_fiscal, v_ult_custo_fiscal
			);
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('7 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;

		FOR i IN 1..v_dep_len LOOP
			IF a_deposito[i] = r.deposito THEN
				a_estoque[i] := v_estoque_dep;
				a_data[i] := r.data;
				EXIT;
			END IF;
		END LOOP;

		v_ordem := v_ordem + 1;
	END LOOP;

	CLOSE c1;

	IF v_ult_custo = 0 THEN
		v_ult_custo := preco_custo_empresa_f($2, $1);
		BEGIN
			UPDATE estoque_lancto SET ult_custo=v_ult_custo	WHERE empresa=$1 AND produto=$2 AND ult_custo = 0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('8 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	IF v_custo_medio = 0 THEN
		v_custo_medio := v_ult_custo;
		BEGIN
			UPDATE estoque_lancto SET custo_medio=v_custo_medio WHERE empresa=$1 AND produto=$2 AND custo_medio = 0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('9 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;	

	IF v_ult_custo_fiscal = 0 or v_ult_custo_fiscal is null THEN

		-- se for rede sim e o produto nao tiver entrada pegar o primeiro custo de inventario
		IF v_ascustom THEN
				SELECT l.preco_unit into v_ult_custo_fiscal
				  FROM lancto l
				 WHERE l.empresa = $1
				   AND l.produto = $2
				   AND l.operacao in ('M', 'I')
			  ORDER BY l.data, l.turno, l.hora LIMIT 1;

			IF NOT FOUND THEN
				v_ult_custo_fiscal := 0;
			END IF;

		END IF;

		BEGIN
			UPDATE estoque_lancto SET ult_custo_fiscal = v_ult_custo_fiscal WHERE empresa=$1 AND produto=$2 AND ult_custo_fiscal=0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('19 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	IF v_custo_medio_fiscal = 0 or v_custo_medio_fiscal is null THEN

		v_custo_medio_fiscal := v_ult_custo_fiscal;

		BEGIN
			UPDATE estoque_lancto SET custo_medio_fiscal = v_custo_medio_fiscal WHERE empresa=$1 AND produto=$2 AND custo_medio_fiscal=0;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('18 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_LANCTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
	END IF;

	----------------------------------------------------------------------------
	-- Atualiza a tabela estoque_prodruto
	-- Tabela responsavel por guardar a ultima movimentacao do produto
	FOR e_aux in select max(data) as data, deposito from estoque_lancto where empresa=$1 and produto=$2 group by deposito LOOP
    
		BEGIN
			INSERT INTO estoque_produto (empresa, deposito, produto, data, estoque, custo_medio, ult_custo, ts_atualizacao, custo_medio_fiscal, ult_custo_fiscal)
				SELECT empresa,deposito,produto,data,coalesce(estoque_dep,0)
				      ,coalesce(custo_medio,v_custo_medio,0),coalesce(ult_custo,v_ult_custo,0), now()::timestamp as ts_atualizacao
					  ,coalesce(custo_medio_fiscal,v_custo_medio_fiscal,0), coalesce(ult_custo_fiscal,v_ult_custo_fiscal,0)
				  FROM estoque_lancto
				 WHERE empresa=$1
				   AND deposito=e_aux.deposito
				   AND produto=$2
				   AND data=e_aux.data
			  ORDER BY ordem desc
                 LIMIT 1;
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('11 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_PRODUTO'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
		END;
		
	END LOOP;
	
	-- manter atualizado o custo para todos os depositos, pois as vezes o produto possui a movimentacao em apenas 1 deposito
	-- com isso o custo acaba ficando diferente de um deposito para o outro
	BEGIN
		UPDATE estoque_produto
		   SET custo_medio=coalesce(v_custo_medio, 0)
			  ,ult_custo=coalesce(v_ult_custo, 0)
			  ,custo_medio_fiscal=coalesce(v_custo_medio_fiscal,0)
			  ,ult_custo_fiscal=coalesce(v_ult_custo_fiscal,0)
		 WHERE empresa=$1
		   AND produto=$2;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('12 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
			PERFORM estoque_log_f ($1, $2, $3, 'ESTOQUE_PRODUTO'::text, 'UPDATE'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
	END;
	---------------------------------------------------------------------------
	
  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f ($1, $2, $3, 'PROGRAMACAO'::text, 'GERAL'::text, 'CALCULA_ESTOQUE_LANCTO_F'::TEXT, v_msg_erro);
  END;  
  
$_$;


ALTER FUNCTION public.calcula_estoque_lancto_f(bigint, bigint, date, boolean) OWNER TO postgres;

--
-- Name: calcula_estoque_valor_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.calcula_estoque_valor_f(bigint, bigint, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r RECORD;
	t record; --somente para testes tirar depois
	sh TEXT;
	nsh TEXT;
	v_msg_erro TEXT := '';
  BEGIN
	-- Apaga dados invalidos da tabela estoque_deposito
	BEGIN
		DELETE FROM estoque_valor WHERE empresa=$1 AND produto=$2 AND data>=$3;
	EXCEPTION
		WHEN OTHERS THEN
			v_msg_erro := upper('13 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		    PERFORM estoque_log_f($1, $2, $3, 'ESTOQUE_VALOR'::text, 'DELETE'::text, 'CALCULA_ESTOQUE_VALOR_F'::text, v_msg_erro);
	END;

	for r in SELECT $1 as empresa, $2 as produto, e.data, e.ult_custo, e.ult_custo_medio, e.cmv_ult_custo, e.cmv_custo_medio, e.preco_unit, e.estoque, e.ult_custo_fiscal, e.ult_custo_medio_fiscal, e.cmv_ult_custo_fiscal, e.cmv_custo_medio_fiscal FROM estoque_valor_data_tf($1, $2, $3, current_date) e (data DATE, ult_custo FLOAT, ult_custo_medio FLOAT, cmv_ult_custo FLOAT, cmv_custo_medio FLOAT, preco_unit FLOAT, estoque FLOAT, ult_custo_fiscal FLOAT, ult_custo_medio_fiscal FLOAT, cmv_ult_custo_fiscal FLOAT, cmv_custo_medio_fiscal FLOAT) loop

		sh := r.data::text||'#$#'||r.empresa::text||'#$#'||round(r.estoque::numeric,6)::text||'#$#'||r.produto::text;
		nsh := (length(sh)^2)::bigint % 7;

		sh := '|L-Z-T|'||nsh||sh||nsh||'|L-Z-T|';
		sh := upper('V001'||md5(sh));

		-- Totaliza as operacoes de estoque simples
		BEGIN
			INSERT INTO estoque_valor (empresa, produto, data, ult_custo, ult_custo_medio, cmv_ult_custo, cmv_custo_medio, preco_unit, estoque, ult_custo_fiscal, ult_custo_medio_fiscal, cmv_ult_custo_fiscal, cmv_custo_medio_fiscal, paf_hash) 
			values (r.empresa, r.produto, r.data, r.ult_custo, r.ult_custo_medio, r.cmv_ult_custo, r.cmv_custo_medio, r.preco_unit, r.estoque, r.ult_custo_fiscal, r.ult_custo_medio_fiscal, r.cmv_ult_custo_fiscal, r.cmv_custo_medio_fiscal, sh);
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('14 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f($1, $2, $3, 'ESTOQUE_VALOR'::text, 'INSERT'::text, 'CALCULA_ESTOQUE_VALOR_F'::text, v_msg_erro);
		END;

	end loop;
		
  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, $2, $3, 'PROGRAMACAO'::text, 'GERAL'::text, 'CALCULA_ESTOQUE_VALOR_F'::text, v_msg_erro);
  END;
  
$_$;


ALTER FUNCTION public.calcula_estoque_valor_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: cardapio_composicao_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cardapio_composicao_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;
        ex BOOLEAN;
        emp BIGINT;
        tipo_cardapio INT;
 
        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;

        sec BIGINT;
        card BIGINT;
        prod BIGINT;        
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;
        ELSE
            rec := NEW;
            rec_old := rec;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM cardapio_composicao_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE cardapio_composicao_sync;
                PERFORM setval('cardapio_composicao_sync', 1);
            END IF;
            RETURN rec;
        END IF;
 
        ex := TG_OP = 'DELETE' or not rec.ativo;
        rel := TG_RELNAME;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        pk := rec.grid;
        card := rec.cardapio;
        sec := rec.secao;
        prod := rec.produto;

        BEGIN
            SELECT C.TIPO INTO tipo_cardapio 
            FROM CARDAPIO_SECAO CS 
            JOIN CARDAPIO C ON C.GRID = CS.CARDAPIO
            WHERE CS.GRID = sec;

            SELECT pkey INTO sel FROM cardapio_composicao_sync WHERE pkey = pk;
            IF NOT FOUND THEN
                INSERT INTO cardapio_composicao_sync (pkey, excluido, cardapio, secao, produto, tipo) VALUES (pk, ex, card, sec, prod, tipo_cardapio);
            ELSE
                UPDATE cardapio_composicao_sync SET seq = NEXTVAL('cardapio_composicao_sync_seq'), excluido = ex, cardapio = card, secao = sec, produto = prod, ts = now() WHERE pkey = pk;
            END IF;
 
        EXCEPTION WHEN unique_violation THEN
         
            UPDATE cardapio_composicao_sync SET seq = NEXTVAL('cardapio_composicao_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
        END;
 
        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.cardapio_composicao_sync_tgf() OWNER TO postgres;

--
-- Name: cardapio_secao_image_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cardapio_secao_image_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;
        ex BOOLEAN;
        emp BIGINT;
        tipo_cardapio INT;
 
        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;
        ELSE
            rec := NEW;
            rec_old := rec;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM cardapio_secao_image_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE cardapio_secao_image_sync;
                PERFORM setval('cardapio_secao_image_sync', 1);
            END IF;
            RETURN rec;
        END IF;
 
        ex := TG_OP = 'DELETE';
        rel := TG_RELNAME;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        pk := rec.grid;

        SELECT ativo INTO sub FROM CARDAPIO_SECAO WHERE grid = rec.secao;
        IF FOUND THEN
            IF not sub.ativo THEN
                ex := TRUE;
            END IF;
        END IF;
 
        BEGIN
            SELECT C.TIPO INTO tipo_cardapio
            FROM CARDAPIO_SECAO CS 
            JOIN CARDAPIO C ON C.GRID = CS.CARDAPIO
            WHERE CS.GRID  = rec.secao;

            SELECT pkey INTO sel FROM cardapio_secao_image_sync WHERE pkey = pk;
            IF NOT FOUND THEN
                INSERT INTO cardapio_secao_image_sync (pkey, excluido, tipo) VALUES (pk, ex, tipo_cardapio);
            ELSE
                UPDATE cardapio_secao_image_sync SET seq = NEXTVAL('cardapio_secao_image_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
            END IF;
 
        EXCEPTION WHEN unique_violation THEN
 
            UPDATE cardapio_secao_image_sync SET seq = NEXTVAL('cardapio_secao_image_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
        END;
 
        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.cardapio_secao_image_sync_tgf() OWNER TO postgres;

--
-- Name: cardapio_secao_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cardapio_secao_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;
        tipo_cardapio INT;
        ex BOOLEAN;
        emp BIGINT;
 
        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;
        ELSE
            rec := NEW;
            rec_old := rec;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM cardapio_secao_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE cardapio_secao_sync;
                PERFORM setval('cardapio_secao_sync', 1);
            END IF;
            RETURN rec;
        END IF;
 
        ex := TG_OP = 'DELETE' or not rec.ativo;
        rel := TG_RELNAME;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        pk := rec.grid;
 
        BEGIN
            SELECT C.TIPO INTO tipo_cardapio FROM CARDAPIO C 
            WHERE C.grid = rec.cardapio;

            FOR sub in SELECT grid FROM cardapio_secao_image WHERE secao = pk LOOP

                SELECT pkey INTO sel FROM cardapio_secao_image_sync WHERE pkey = sub.grid;
                IF NOT FOUND THEN
                    INSERT INTO cardapio_secao_image_sync (pkey, excluido, tipo) VALUES (sub.grid, ex, tipo_cardapio);
                ELSE
                    UPDATE cardapio_secao_image_sync SET seq = NEXTVAL('cardapio_secao_image_sync_seq'), excluido = ex, ts = now() WHERE pkey = sub.grid;
                END IF;

            END LOOP;

            FOR sub in SELECT grid FROM cardapio_composicao WHERE secao = pk LOOP

                SELECT pkey INTO sel FROM cardapio_composicao_sync WHERE pkey = sub.grid;
                IF NOT FOUND THEN
                    INSERT INTO cardapio_composicao_sync (pkey, excluido, tipo) VALUES (sub.grid, ex, tipo_cardapio);
                ELSE
                    UPDATE cardapio_composicao_sync SET seq = NEXTVAL('cardapio_composicao_sync_seq'), excluido = ex, ts = now(), tipo = tipo_cardapio WHERE pkey = sub.grid;
                END IF;

            END LOOP;

            INSERT INTO cardapio_secao_sync (pkey, excluido, tipo) VALUES (pk, ex, tipo_cardapio);
 
        EXCEPTION WHEN unique_violation THEN
 
            UPDATE cardapio_secao_sync SET seq = NEXTVAL('cardapio_secao_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
        END;
 
        RETURN rec;
    END;
    
$$;


