--
-- Name: cartao_fidelidade_saldo_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cartao_fidelidade_saldo_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

begin
	select round(sum(coalesce(ponto,0))::numeric,4) as saldo into r from ponto where cartao_fidelidade=$1;
	
	if found and r.saldo is not null then
		return r.saldo;
	end if;
	
	return 0.0;
end
$_$;


ALTER FUNCTION public.cartao_fidelidade_saldo_f(bigint) OWNER TO postgres;

--
-- Name: check_baixa_pendencia_conta_f(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_baixa_pendencia_conta_f(text, text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

	conta_deb_credor bool;

	conta_deb_pendencia bool;

	conta_cre_credor bool;

	conta_cre_pendencia bool;

	op_debitar text;

	op_creditar text;

begin

	select credor, pendencia into r from conta where codigo = $1;



	if not found then

		return False;

	end if;



	conta_deb_credor := r.credor;

	conta_deb_pendencia := r.pendencia;



	select credor, pendencia into r from conta where codigo = $2;



	if not found then

		return False;

	end if;



	conta_cre_credor := r.credor;

	conta_cre_pendencia := r.pendencia;



	if conta_deb_credor then

		op_debitar := 'S';

	else

		op_debitar := 'E';

	end if;



	if conta_cre_credor then

		op_creditar := 'E';

	else

		op_creditar := 'S';

	end if;



	if op_debitar = 'S' and conta_deb_pendencia then

		return True;

	elsif op_creditar = 'S' and conta_cre_pendencia then

		return True;

	end if;



	return False;

end
$_$;


ALTER FUNCTION public.check_baixa_pendencia_conta_f(text, text) OWNER TO postgres;

--
-- Name: check_baixa_pendencia_motivo_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_baixa_pendencia_motivo_f(bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

	conta_deb text; 

	conta_cre text;

begin

	select conta_debitar, conta_creditar into r from motivo_movto where grid = $1;



	if not found then

		return False;

	end if;



	select check_baixa_pendencia_conta_f(r.conta_debitar, r.conta_creditar) as ret into r;

	return r.ret;

end
$_$;


