--
-- Name: check_estoque_f(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_estoque_f() RETURNS void
    LANGUAGE plpgsql
    AS $$

  DECLARE
	r RECORD;
	r2 RECORD;
	r_aux RECORD;
	r_est RECORD;
	r_aux2 RECORD;
	tini TIMESTAMP;
	i INTEGER := 0;
	v_local_user BOOLEAN := False;
	v_msg_erro TEXT := '';

  BEGIN
  	-- Registro de usuario
  	SELECT * INTO r FROM usuario_pid WHERE pid=pg_backend_pid();

	IF NOT FOUND THEN
		v_local_user := True;
		
		BEGIN
			INSERT INTO usuario_pid (pid, usuario, estacao, modulo) 
				SELECT procpid, -1, client_addr::text, 'check_estoque' FROM pg_stat_activity 
				WHERE procpid=pg_backend_pid();
		EXCEPTION
			WHEN OTHERS THEN
				INSERT INTO usuario_pid (pid, usuario, estacao, modulo) 
				SELECT pid, -1, client_addr::text, 'check_estoque' FROM pg_stat_activity 
				WHERE pid=pg_backend_pid();
		END;
	END IF;

	SELECT ativo, coalesce(quantidade_exec,0) as qtd, to_date(data_ult_exec::text, 'yyyy-mm-dd') as data, data_ativacao into r_est from estoque_controle order by data_ult_exec desc limit 1;
	
	if (found and not r_est.ativo) then
		RAISE INFO 'Tabelas de estoque nao estao ativas';
		RETURN;		
	end if;

	LOCK TABLE estoque_invalida IN SHARE MODE;
	LOCK TABLE estoque_produto IN SHARE MODE;

	SELECT count(*) INTO r_aux2 FROM estoque_invalida;
	
	IF NOT found THEN
		RAISE INFO 'Nenhum produto a processar';
		RETURN;
	END IF;

	RAISE INFO '% registros a processar', r_aux2.count;

	FOR r IN (SELECT ei.empresa, e.codigo as empresa_codigo, ei.produto, p.nome as produto_nome, min(ei.data) as data FROM estoque_invalida ei JOIN pessoa e ON (ei.empresa=e.grid) JOIN produto p on (ei.produto=p.grid) 
			WHERE NOT EXISTS (SELECT 1 FROM produto_composicao pc where pc.produto = ei.produto and (pc.empresa = ei.empresa or pc.empresa is null))
			GROUP BY ei.empresa, e.codigo, ei.produto, p.nome) ORDER BY e.codigo, p.nome
	LOOP
		i := i + 1;

		RAISE INFO '% - Emp(%/%) Prod(%/%) Dt(%)', i, r.empresa, r.empresa_codigo, r.produto, r.produto_nome, r.data;

		-- Calcula a diferenca para todos os inventarios registrados
		tini := timeofday()::timestamp;
		PERFORM calcula_estoque_lancto_f(r.empresa, r.produto, r.data, false);

		SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
		RAISE INFO '  calcula_estoque_lancto_f() = %', r_aux.tempo;

		tini := timeofday()::timestamp;
		PERFORM calcula_estoque_valor_f(r.empresa, r.produto, r.data);
		SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
		RAISE INFO '  calcula_estoque_valor_f() = %', r_aux.tempo;

		FOR r2 IN (SELECT deposito, min(data) AS data FROM estoque_invalida WHERE empresa=r.empresa AND produto=r.produto GROUP BY deposito) LOOP
			tini := timeofday()::timestamp;
			PERFORM calcula_estoque_deposito_f(r.empresa, r2.deposito, r.produto, r2.data);
			SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
			RAISE INFO '  calcula_estoque_deposito_f(%, %) = %', r2.deposito, r2.data, r_aux.tempo;
		END LOOP;
	END LOOP;

	-- PRODUTOS COMPOSTOS
	FOR r IN (SELECT ei.empresa, e.codigo as empresa_codigo, ei.produto, p.nome as produto_nome, min(ei.data) as data FROM estoque_invalida ei JOIN pessoa e ON (ei.empresa=e.grid) JOIN produto p on (ei.produto=p.grid) 
			INNER JOIN produto_composicao pc on pc.produto = ei.produto and (pc.empresa = ei.empresa or pc.empresa is null)
			GROUP BY ei.empresa, e.codigo, ei.produto, p.nome) ORDER BY e.codigo, p.nome
	LOOP
		i := i + 1;

		RAISE INFO '% - Emp(%/%) Prod(%/%) Dt(%)', i, r.empresa, r.empresa_codigo, r.produto, r.produto_nome, r.data;

		-- Calcula a diferenca para todos os inventarios registrados
		tini := timeofday()::timestamp;
		PERFORM calcula_estoque_lancto_f(r.empresa, r.produto, r.data, true);

		SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
		RAISE INFO '  calcula_estoque_lancto_f() = %', r_aux.tempo;

		tini := timeofday()::timestamp;
		PERFORM calcula_estoque_valor_f(r.empresa, r.produto, r.data);
		SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
		RAISE INFO '  calcula_estoque_valor_f() = %', r_aux.tempo;

		FOR r2 IN (SELECT deposito, min(data) AS data FROM estoque_invalida WHERE empresa=r.empresa AND produto=r.produto GROUP BY deposito) LOOP
			tini := timeofday()::timestamp;
			PERFORM calcula_estoque_deposito_f(r.empresa, r2.deposito, r.produto, r2.data);
			SELECT (timeofday()::timestamp - tini) AS tempo INTO r_aux;
			RAISE INFO '  calcula_estoque_deposito_f(%, %) = %', r2.deposito, r2.data, r_aux.tempo;
		END LOOP;
	END LOOP;

	DELETE FROM estoque_invalida;

	SELECT (timeofday()::timestamp - current_timestamp) AS tempo INTO r_aux;
	RAISE INFO 'Tempo total de execucao = %', r_aux.tempo;

	if r_aux2.count > 0 then
		if r_est.ativo then	
			update estoque_controle set data_ult_exec = timeofday()::timestamp, duracao_ult_exec = (timeofday()::timestamp - current_timestamp), quantidade_exec = r_est.qtd+1, quantidade_reg = r_aux2.count;
		else
			insert into estoque_controle(ativo, data_ativacao, data_ult_exec, duracao_ult_exec, quantidade_exec, quantidade_reg) values (true, current_date, timeofday()::timestamp, (timeofday()::timestamp - current_timestamp), 1, r_aux2.count);
		end if;
	end if;

	If v_local_user THEN
		DELETE FROM usuario_pid WHERE pid=pg_backend_pid();
	END IF;
  
  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f(0, 0, current_date, 'PROGRAMACAO'::text, 'GERAL'::text, 'CHECK_ESTOQUE_F'::TEXT, v_msg_erro);
  END;
  
$$;


