	FOR r IN (SELECT ei.empresa, e.codigo as empresa_codigo, ei.produto, p.nome as produto_nome, min(ei.data) as data FROM estoque_invalida ei JOIN pessoa e ON (ei.empresa=e.grid) JOIN produto p on (ei.produto=p.grid)
	where ei.empresa = $1 and NOT EXISTS (SELECT 1 FROM produto_composicao pc where pc.produto = ei.produto and (pc.empresa = ei.empresa or pc.empresa is null))
	GROUP BY ei.empresa, e.codigo, ei.produto, p.nome) ORDER BY e.codigo, p.nome LOOP

		PERFORM calcula_estoque_lancto_f(r.empresa, r.produto, r.data, false);
		PERFORM calcula_estoque_valor_f(r.empresa, r.produto, r.data);

		FOR r2 IN (SELECT deposito, min(data) AS data FROM estoque_invalida WHERE empresa=r.empresa AND produto=r.produto GROUP BY deposito) LOOP
			PERFORM calcula_estoque_deposito_f(r.empresa, r2.deposito, r.produto, r2.data);
		END LOOP;
	END LOOP;

	FOR r IN (SELECT ei.empresa, e.codigo as empresa_codigo, ei.produto, p.nome as produto_nome, min(ei.data) as data FROM estoque_invalida ei JOIN pessoa e ON (ei.empresa=e.grid) JOIN produto p on (ei.produto=p.grid)
	INNER JOIN produto_composicao pc on pc.produto = ei.produto and (pc.empresa = ei.empresa or pc.empresa is null)
	where ei.empresa = $1 GROUP BY ei.empresa, e.codigo, ei.produto, p.nome) ORDER BY e.codigo, p.nome LOOP

		PERFORM calcula_estoque_lancto_f(r.empresa, r.produto, r.data, true);
		PERFORM calcula_estoque_valor_f(r.empresa, r.produto, r.data);

		FOR r2 IN (SELECT deposito, min(data) AS data FROM estoque_invalida WHERE empresa=r.empresa AND produto=r.produto GROUP BY deposito) LOOP
			PERFORM calcula_estoque_deposito_f(r.empresa, r2.deposito, r.produto, r2.data);
		END LOOP;
	END LOOP;

	DELETE FROM estoque_invalida where empresa=$1;

	If v_local_user THEN
		DELETE FROM usuario_pid WHERE pid=pg_backend_pid();
	END IF;

EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, 0, current_date, 'PROGRAMACAO'::text, 'GERAL'::text, 'CHECK_ESTOQUE_F1'::TEXT, v_msg_erro);	
END;
  
$_$;


