	END IF;

EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, $2, current_date, 'PROGRAMACAO'::text, 'GERAL'::text, 'CHECK_ESTOQUE_F2'::TEXT, v_msg_erro);	
END;
  
$_$;


ALTER FUNCTION public.check_estoque_f(bigint, bigint) OWNER TO postgres;

--
-- Name: check_estoque_f(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.check_estoque_f(bigint, bigint, bigint) RETURNS void
    LANGUAGE plpgsql
    AS $_$

DECLARE
	r RECORD;
	r_est RECORD;
	v_local_user BOOLEAN := False;
	v_msg_erro TEXT := '';
	v_composto BOOLEAN := False;

BEGIN
  	-- Registro de usuario
  	SELECT * INTO r FROM usuario_pid WHERE pid=pg_backend_pid();

	IF NOT FOUND THEN
		v_local_user := True;
		
		BEGIN
			INSERT INTO usuario_pid (pid, usuario, estacao, modulo) 
				SELECT procpid, -1, client_addr::text, 'check_estoque' FROM pg_stat_activity 
				WHERE procpid=pg_backend_pid();
		EXCEPTION
			WHEN OTHERS THEN
				INSERT INTO usuario_pid (pid, usuario, estacao, modulo) 
				SELECT pid, -1, client_addr::text, 'check_estoque' FROM pg_stat_activity 
				WHERE pid=pg_backend_pid();
		END;
	END IF;

	SELECT ativo, coalesce(quantidade_exec,0) as qtd, to_date(data_ult_exec::text, 'yyyy-mm-dd') as data, data_ativacao into r_est from estoque_controle order by data_ult_exec desc limit 1;
	
	if (found and not r_est.ativo) then
		RAISE INFO 'Tabelas de estoque nao estao ativas';
		RETURN;		
	end if;
	LOCK TABLE estoque_invalida IN SHARE MODE;
	LOCK TABLE estoque_produto IN SHARE MODE;

	IF EXISTS (SELECT 1 FROM produto_composicao 
				WHERE produto = $3 
				AND (empresa = $1 OR empresa IS NULL)) THEN
		v_composto := True;
	END IF;

	select min(data) as data into r from estoque_invalida where empresa=$1 and deposito=$2 and produto=$3;

	if not found then
		return;
	end if;

	-- Calcula a diferenca para todos os inventarios registrados
	PERFORM calcula_estoque_lancto_f($1, $3, r.data, v_composto);
	PERFORM calcula_estoque_valor_f($1, $3, r.data);
	PERFORM calcula_estoque_deposito_f($1, $2, $3, r.data);

	DELETE FROM estoque_invalida where empresa=$1 and deposito=$2 and produto=$3;

	If v_local_user THEN
		DELETE FROM usuario_pid WHERE pid=pg_backend_pid();
	END IF;

EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, $3, current_date, 'PROGRAMACAO'::text, 'GERAL'::text, 'CHECK_ESTOQUE_F3'::TEXT, v_msg_erro);
END;
  
$_$;


ALTER FUNCTION public.check_estoque_f(bigint, bigint, bigint) OWNER TO postgres;

--
-- Name: classe_pgto_mlid_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.classe_pgto_mlid_f(bigint) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

	class_dinheiro bigint;

begin

	select into r mm.classificacao_pgto from motivo_movto mm join motivo_config mc on

		(mm.grid = mc.motivo) where mc.chave = 'DINHEIRO';



	if not found then

		raise EXCEPTION 'Motivo de movimentacao DINHEIRO nao configurado';

		return null;

	end if;



	class_dinheiro := r.classificacao_pgto;



	if (($1 is null) or ($1 = 0::bigint)) then

		return class_dinheiro;

	end if;



	select mm.classificacao_pgto into r from movto m join motivo_movto mm on 

		(m.motivo=mm.grid) where m.mlid = $1 and mm.forma_pgto = true 

		order by m.valor desc limit 1;

	

	if found then

		return r.classificacao_pgto;

	end if;



	return class_dinheiro;

end;
$_$;


ALTER FUNCTION public.classe_pgto_mlid_f(bigint) OWNER TO postgres;

--
-- Name: codigo_barra_produto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.codigo_barra_produto_f(bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

   DECLARE
	r RECORD;
	barra text = '';
   BEGIN
	select codigo_barra into r from produto where grid=$1 and length(codigo_barra)>0;
	
	if found then
		return r.codigo_barra;
	end if;
	
	FOR r in (select codigo_barra from produto_codigo_barra where produto=$1) loop
		if barra != '' then
			barra := barra || ' *';
			return barra;
 		end if;
 		
 		barra := r.codigo_barra;
	end loop;

	return barra;
   END;
   
$_$;


ALTER FUNCTION public.codigo_barra_produto_f(bigint) OWNER TO postgres;

