--
-- Name: codigo_vendedor_venda_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.codigo_vendedor_venda_f(bigint) RETURNS text
    LANGUAGE plpgsql
    AS $_$

  DECLARE
    r RECORD;
    ret TEXT;

  BEGIN 
    IF (($1 IS NULL) OR ($1 = 0::bigint)) THEN 
        RETURN NULL;
    END IF;

    SELECT INTO r pessoa_codigo_f(l.vendedor) AS vendedor FROM lancto l JOIN produto p ON l.produto=p.grid WHERE l.mlid=$1 AND l.operacao = 'V' ORDER BY abs(l.valor) DESC LIMIT 1;

    IF FOUND THEN 
        ret := r.vendedor;
    END IF;

    RETURN ret;
  END; 
$_$;


