CREATE FUNCTION public.coluna_dinamica_f(text, integer, integer, text, text, integer, integer) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

/*Parametros:
1-sql(obs: dever√° ter 3 atributos com nome fixo: coluna, linha e dado.)
2-tamanho do dado coluna
3-tamanho do dado linha
4-titulo dos dados da primeira coluna
5-titulo da coluna total da linha. Caso n√£o queira exibir esta coluna mandar o parametro como NULL
6-quantidades de casas decimais do dado. Se FOR um inteiro colocar 0
7-totalizador do campo valor*/
DECLARE

	r RECORD;

	lin_dado Text;

	vet_dado Text[];

	vet_cabecalho Text[];

	vet_retorno Text[];

	lin_total Text;

	lin_traco Text;

	lin_cabecalho Text;

	indice integer;

	i integer;

	j integer;

	total_linha numeric;

	total_geral numeric;

	nome_tabela Text;

BEGIN

	indice := 1;

	i := 1;	

	total_linha := 0;

	total_geral := 0;

	

	nome_tabela := 'temp_coluna_dinamica'||md5((timeofday()::timestamp)::text);

	EXECUTE 'create temp table '||nome_tabela||' as '||$1;



	--Inicializa as linhas do cabe√ßalho e do tra√ßo

	lin_cabecalho := '| '||rpad(substr($4,1,$3::int),$3::int+1,' ')||'| ';

	lin_traco := '+-'||rpad('',$3::int,'-')||'-+';



	--Gera o cabe√ßalho	

	FOR r IN EXECUTE 'select distinct coluna from '||nome_tabela||' order by 1' LOOP

		lin_cabecalho := lin_cabecalho||rpad(substr(r.coluna,1,$2::int),$2::int+1,' ')||'| ';

		lin_traco := lin_traco||rpad('',$2::int+1,'-')||'-+';

		vet_cabecalho[i] := r.coluna;

		i := i + 1;

	END LOOP; 

	

	IF $5 IS NOT NULL THEN 

		lin_traco := lin_traco||rpad('',$2::int+1,'-')||'-+';

		lin_cabecalho := lin_cabecalho||rpad($5,$2::int+1,' ')||'| '; 

	END IF;

	

	IF $7 > 0 THEN 

		lin_traco := lin_traco||rpad('',$7::int+1,'-')||'-+';

		lin_cabecalho := lin_cabecalho||rpad('ACUMULADO',$7::int+1,' ')||'| '; 

	END IF;

	

	indice := 1;	

	lin_dado := '';

	j := 1;

	

	--Organiza os dados na sua devida coluna

	FOR r IN EXECUTE 'select * from '||nome_tabela||' where coluna is not null and linha is not null order by linha, coluna'  LOOP

		IF lin_dado = '' THEN			

			lin_dado := r.linha;

		END IF;

		

		--Completa com espa√ßos em branco at√© o final da linha		

		IF lin_dado != r.linha THEN

			FOR i IN j..array_upper(vet_cabecalho,1) LOOP

				vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';

			END LOOP;

			--Coloca o total da linha caso o parametro seja T

			IF $5 IS NOT NULL THEN

				total_geral := total_geral + total_linha;

				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha,$6),$2::int,' ')||' | '||lpad(formata_valor_f(total_geral,$6),$7::int,' ')||' | ';

				total_linha := 0;

			END IF;

			indice := indice + 1;

			j := 1;

			lin_dado := r.linha;

		END IF;		

		

		--Coloca espacos em branco e o dado

		FOR i IN j..array_upper(vet_cabecalho,1) LOOP

			IF i = 1 THEN

				vet_dado[indice] := '| '||rpad(substr(r.linha,1,$3::int),$3::int+1,' ')||'| ';

			END IF;

			

			IF vet_cabecalho[i] != r.coluna THEN

				vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';

			else

				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(r.dado,$6),$2::int,' ')||' | ';

				total_linha := total_linha + r.dado;

				j := i;

--				RAISE INFO 'Dado: %', lpad(formata_valor_f(r.dado,$6),$2::int,' ');

				exit;

			END IF;

		END LOOP;

		--Verifica se o FOR chegou ao final para quebrar a linha

		IF j = array_upper(vet_cabecalho,1) THEN

			--Coloca o total da linha caso o parametro seja T

			IF $5 IS NOT NULL THEN

				total_geral := total_geral + total_linha;

				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha,$6),$2::int,' ')||' | '||lpad(formata_valor_f(total_geral,$6),$7::int,' ')||' | ';

				total_linha := 0;

			END IF;

			indice := indice + 1;

			j := 1;

		else

			j := j+1;

		END IF;

	END LOOP; 

	

	--Completa com espa√ßos em branco na ultima linha se FOR necessario

	while j <= array_upper(vet_cabecalho,1) LOOP

		vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';

		j := j + 1;

	END LOOP;

	

	--Cria a linha com o total de cada coluna

	lin_total := '| '||rpad('TOTAL', $3::int+1,' ')||'| ';

	FOR r IN EXECUTE 'select coluna, sum(dado) as total from '||nome_tabela||' group by coluna order by coluna' LOOP

		lin_total := lin_total||lpad(formata_valor_f(r.total,$6)||' ',$2::int+1,' ')||'| ';		

	END LOOP; 



	--Coloca o total da linha e o total_geral caso a ultima linha nao tenha dados na ultima coluna

	--Acrescenta o total geral a linha de total caso o parametro nao seja NULL

	IF $5 IS NOT NULL THEN

		total_geral := total_geral + total_linha;

		vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha, $6),$2::int,' ')||' | '||lpad(formata_valor_f(total_geral,$6),$7::int,' ')||' | ';

		lin_total := lin_total||lpad(formata_valor_f(total_geral,$6)||' ',$2::int+1,' ')||'| '||lpad(formata_valor_f(total_geral,$6),$7::int,' ')||' | ';

	END IF;

	

	--Adiciona os tracos e o cabecalho ao vetor de retorno

	vet_retorno[1] := lin_traco;

	vet_retorno[2] := lin_cabecalho;

	vet_retorno[3] := array_to_string(vet_dado,'
');

	vet_retorno[4] := lin_total;

	

	EXECUTE 'drop table '||nome_tabela;

	

	return vet_retorno; 

END
$_$;


