	nome_tabela := 'temp_coluna_dinamica'||md5((timeofday()::timestamp)::text);
	EXECUTE 'create temp table '||nome_tabela||' as '||$1;

	--Inicializa as linhas do cabe√ßalho e do tra√ßo
	lin_cabecalho := '| '||rpad(substr($4,1,$3::int),$3::int+1,' ')||'| ';
	lin_traco := '+-'||rpad('',$3::int,'-')||'-+';

	--Gera o cabe√ßalho	
	FOR r IN EXECUTE 'select distinct coluna, '||$7||' from '||nome_tabela||' order by '||$7||', 1' LOOP
		lin_cabecalho := lin_cabecalho||rpad(substr(r.coluna,1,$2::int),$2::int+1,' ')||'| ';
		lin_traco := lin_traco||rpad('',$2::int+1,'-')||'-+';
