		lin_cabecalho := lin_cabecalho||rpad($5,$2::int+1,' ')||'| '; 
	END IF;
	
	indice := 1;	
	lin_dado := '';
	j := 1;
	
	--Organiza os dados na sua devida coluna
    FOR r IN EXECUTE 'select * from '||nome_tabela||' where coluna is not null and linha is not null 
                        order by linha, '||$7||', coluna'  LOOP
		IF lin_dado = '' THEN			
			lin_dado := r.linha;
		END IF;
		
		--Completa com espa√ßos em branco at√© o final da linha		
		IF lin_dado != r.linha THEN
			FOR i IN j..array_upper(vet_cabecalho,1) LOOP
				vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';
			END LOOP;
			--Coloca o total da linha caso o parametro seja T
			IF $5 IS NOT NULL THEN
				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha,$6),$2::int,' ')||' | ';
				total_geral := total_geral + total_linha;
				total_linha := 0;
			END IF;
			indice := indice + 1;
			j := 1;
			lin_dado := r.linha;
		END IF;		
		
		--Coloca espacos em branco e o dado
		FOR i IN j..array_upper(vet_cabecalho,1) LOOP
			IF i = 1 THEN
				vet_dado[indice] := '| '||rpad(substr(r.linha,1,$3::int),$3::int+1,' ')||'| ';
			END IF;
			
			IF vet_cabecalho[i] != r.coluna THEN
				vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';
			else
				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(r.dado,$6),$2::int,' ')||' | ';
				total_linha := total_linha + r.dado;
				j := i;
--				RAISE INFO 'Dado: %', lpad(formata_valor_f(r.dado,$6),$2::int,' ');
				exit;
			END IF;
		END LOOP;
		--Verifica se o FOR chegou ao final para quebrar a linha
		IF j = array_upper(vet_cabecalho,1) THEN
			--Coloca o total da linha caso o parametro seja T
			IF $5 IS NOT NULL THEN
				vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha,$6),$2::int,' ')||' | ';
				total_geral := total_geral + total_linha;
				total_linha := 0;
			END IF;
			indice := indice + 1;
			j := 1;
		else
			j := j+1;
		END IF;
	END LOOP; 
	
	--Completa com espa√ßos em branco na ultima linha se FOR necessario
	while j <= array_upper(vet_cabecalho,1) LOOP
		vet_dado[indice] := vet_dado[indice]||rpad(' ',$2::int+1,' ')||'| ';
		j := j + 1;
	END LOOP;
	
	--Cria a linha com o total de cada coluna
	lin_total := '| '||rpad('TOTAL', $3::int+1,' ')||'| ';
	FOR r IN EXECUTE 'select coluna, sum(dado) as total from '||nome_tabela||' group by coluna order by coluna' LOOP
		lin_total := lin_total||lpad(formata_valor_f(r.total,$6)||' ',$2::int+1,' ')||'| ';
	END LOOP; 

	--Coloca o total da linha e o total_geral caso a ultima linha nao tenha dados na ultima coluna
	--Acrescenta o total geral a linha de total caso o parametro nao seja NULL
	IF $5 IS NOT NULL THEN
		vet_dado[indice] := vet_dado[indice]||lpad(formata_valor_f(total_linha, $6),$2::int,' ')||' | ';
		total_geral := total_geral + total_linha;
		lin_total := lin_total||lpad(formata_valor_f(total_geral,$6)||' ',$2::int+1,' ')||'| ';
	END IF;
	
	--Adiciona os tracos e o cabecalho ao vetor de retorno
	vet_retorno[1] := lin_traco;
	vet_retorno[2] := lin_cabecalho;
	vet_retorno[3] := array_to_string(vet_dado,'
');
	vet_retorno[4] := lin_total;
	
	EXECUTE 'drop table '||nome_tabela;
	
	return vet_retorno; 
END
$_$;


ALTER FUNCTION public.coluna_dinamica_f(text, integer, integer, text, text, integer, text) OWNER TO postgres;

--
-- Name: comanda_cartoes_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.comanda_cartoes_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

		DECLARE
			pk BIGINT;
			ex BOOLEAN;
			rec RECORD;
			rec_old RECORD;
			sel RECORD;
		BEGIN
			IF TG_OP = 'DELETE' THEN
				rec := OLD;
				rec_old := rec;
			ELSIF TG_OP = 'UPDATE' THEN
				rec := NEW;
				rec_old := OLD;
			ELSE
				rec := NEW;
				rec_old := rec;
			END IF;

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = (SELECT grid FROM empresa_local LIMIT 1);
			IF NOT FOUND THEN
				SELECT seq INTO pk FROM comanda_cartoes_sync LIMIT 1;
				IF FOUND THEN
					TRUNCATE comanda_cartoes_sync;
					PERFORM setval('comanda_cartoes_sync_seq', 1);
				END IF;
				RETURN rec;
			END IF;

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
			IF NOT FOUND THEN
				RETURN rec_old;
			END IF;

			ex := TG_OP = 'DELETE';
			pk := rec.id;

			SELECT pkey INTO sel FROM comanda_cartoes_sync WHERE pkey = pk;

			IF NOT FOUND THEN
				INSERT INTO comanda_cartoes_sync (pkey, excluido) VALUES (pk, ex);
			ELSE
				UPDATE comanda_cartoes_sync SET seq = NEXTVAL('comanda_cartoes_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
			END IF;

			RETURN rec;
		END;
	
$$;


ALTER FUNCTION public.comanda_cartoes_sync_tgf() OWNER TO postgres;

