--
-- Name: conta_saldo(text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo(text, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$
declare 
	c record;
	r record;
	deb record;
	cred record;
	saldo float;
	sinal int;
	data_invalida date;
	data_parametro date;
begin
	--TODO: Deve ser diminuido um data que vem, porque a funÁ„o antiga estava bugada
	data_parametro := $2 - 1;

	select credor into c from conta where codigo = $1;

	if c.credor then
		sinal := 1;
	else
		sinal := -1;
	end if;

	saldo := 0;
	data_invalida := '1970-01-01';

	-- Saldo inicial da conta
	select saldo_inicial into c from conta where codigo = $1;

	if not found then
		return saldo;
	else
		if not c.saldo_inicial is null then
			saldo := c.saldo_inicial;
		end if;
	end if;

	--Somente verifica a tabela conta_saldo_empresa se estiver ativo 
	select ativo into r from conta_saldo_controle order by data_ult_exec desc limit 1;

	if found then
		if r.ativo then
			-- Saldo totalizado em determinado periodo
			select min(data) into data_invalida from conta_saldo_invalida where conta = $1 and data <= data_parametro;

			if not found or data_invalida is null then
				data_invalida := data_parametro-1;
			else
				data_invalida := data_invalida - 1;
			end if;

			-- Somando um dia na data pois a funcao conta_saldo_empresa_f ja subtrai um dia em seu processo
			-- Retirando saldo inicial de cada saldo por empresa pois sÛ existe um saldo inicial por conta
			select (sum(conta_saldo_empresa_f($1, data_invalida + 1, e.grid, false) - c.saldo_inicial) + c.saldo_inicial) as saldo_ini into c from empresa e;

			if found and not c.saldo_ini is null then
				saldo := c.saldo_ini;
			end if;

		end if;
	end if;

	select sum(round(valor::numeric, 2)) as valor into deb from movto where data > data_invalida and data <= data_parametro and conta_debitar=$1;

	if not deb.valor is null then
		saldo := saldo - (deb.valor * sinal);
	end if;

	select sum(round(valor::numeric, 2)) as valor into cred from movto where data > data_invalida and data <= data_parametro and conta_creditar=$1;

	if not cred.valor is null then
		saldo := saldo + (cred.valor * sinal);
	end if;

	return saldo;
end;
$_$;


