--
-- Name: conta_saldo_check_f(bigint, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_check_f(bigint, text, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
	r RECORD;
	r_emp RECORD;
	r_aux RECORD;
	r_aux2 RECORD;
	data_ativ timestamp;
	qtd_exec integer;
	cont integer;
BEGIN
	LOCK TABLE conta_saldo_invalida IN SHARE MODE;

	SELECT count(*) INTO r_aux2 FROM conta_saldo_invalida WHERE
			empresa = (CASE WHEN $1 IS NULL THEN empresa ELSE $1 END) AND
			conta = (CASE WHEN $2 IS NULL THEN conta ELSE $2 END) AND
			data <= (CASE WHEN $3 IS NULL THEN data ELSE $3 END);
	
	IF NOT found or r_aux2.count = 0 THEN
		RAISE INFO 'Nenhuma conta a processar';
		RETURN;
	END IF;

	RAISE INFO '% registros a processar', r_aux2.count;
	cont := 0;
	FOR r IN SELECT * FROM conta_saldo_invalida WHERE
			empresa = (CASE WHEN $1 IS NULL THEN empresa ELSE $1 END) AND
			conta = (CASE WHEN $2 IS NULL THEN conta ELSE $2 END) AND
			data <= (CASE WHEN $3 IS NULL THEN data ELSE $3 END) order by empresa, conta 
		LOOP

		cont = cont + 1;
		
		RAISE INFO 'Processando registro % de %=> Empresa: % - Conta: % - Data: %', cont, r_aux2.count, r.empresa, r.conta, r.data;
		PERFORM conta_saldo_empresa_calcula_f(r.empresa, r.conta, r.data);
	END LOOP;

	DELETE FROM conta_saldo_invalida WHERE
		empresa = (CASE WHEN $1 IS NULL THEN empresa ELSE $1 END) AND
		conta = (CASE WHEN $2 IS NULL THEN conta ELSE $2 END) AND
		data <= (CASE WHEN $3 IS NULL THEN data ELSE $3 END);


	select * into r_aux from conta_saldo_controle order by data_ult_exec desc limit 1;

	if found then 
		data_ativ := r_aux.data_ativacao;
		qtd_exec := r_aux.quantidade_exec;
	else
		data_ativ := current_timestamp;
		qtd_exec := 0;
	end if;

	if found and r_aux.data_ult_exec::date = current_date then	
		update conta_saldo_controle set data_ult_exec = timeofday()::timestamp, duracao_ult_exec = (timeofday()::timestamp - current_timestamp), 
			quantidade_exec = qtd_exec+1, quantidade_reg = r_aux2.count;
	else
		insert into conta_saldo_controle(ativo, data_ativacao, data_ult_exec, duracao_ult_exec, quantidade_exec, quantidade_reg) values 
			(true, data_ativ, timeofday()::timestamp, (timeofday()::timestamp - current_timestamp), qtd_exec+1, r_aux2.count);
	end if;
	RAISE INFO 'Tempo de execucao: %', (timeofday()::timestamp - current_timestamp);
END;
$_$;


ALTER FUNCTION public.conta_saldo_check_f(bigint, text, date) OWNER TO postgres;

--
-- Name: conta_saldo_empresa(text, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_empresa(text, date, bigint) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$
declare 
	c record;
	r record;
	deb record;
	cred record;
	saldo float;
	sinal int;
	data_invalida date;	
	data_parametro date;	
begin
	--TODO: Deve ser diminuido um data que vem, porque a funcao antiga estava bugada
	data_parametro := $2 - 1;

	select credor into c from conta where codigo=$1;

	if c.credor then
		sinal := 1;
	else
		sinal := -1;
	end if;

	saldo := 0;
	data_invalida := '1970-01-01';

	-- Saldo inicial da conta
	select saldo_inicial into c from conta where codigo=$1;

	if not found then
		--RAISE INFO 'saiu aki 1 ';
		return saldo;
	else
		if not c.saldo_inicial is null then
			saldo := c.saldo_inicial;
		end if;
	end if;

	--Somente verifica a tabela conta_saldo_empresa se estiver ativo 
	select ativo into r from conta_saldo_controle order by data_ult_exec desc limit 1;

	if found then
		if r.ativo then
			-- Saldo totalizado em determinado periodo
			select min(data) into data_invalida from conta_saldo_invalida where conta=$1 and data <= data_parametro and empresa = $3;

			if not found or data_invalida is null then
				data_invalida := data_parametro-1;
			else
				data_invalida := data_invalida-1;
			end if;
			--RAISE INFO '1- % - %', data_invalida, saldo;

			select data, cse.saldo as saldo_ini into c from conta_saldo_empresa cse where conta=$1 and data = data_invalida and empresa = $3;

			if found then
				saldo := c.saldo_ini;
				
				if c.data = data_parametro then
					--RAISE INFO 'saiu aki 2 ';
					return saldo;
				end if;			
			end if;

			--RAISE INFO '2- % - %', data_invalida, saldo;
			select data, cse.saldo as saldo_ini into c from conta_saldo_empresa cse where conta=$1 and data < data_invalida and empresa = $3 order by 1 desc limit 1;
			
			if found then
				data_invalida := c.data;
				saldo := c.saldo_ini;
			end if;
		end if;
	end if;
			
	--RAISE INFO '3- % - %', data_invalida, saldo;
	select sum(round(valor::numeric,2)) as valor into deb from movto where data > data_invalida and data <= data_parametro and conta_debitar=$1 and empresa=$3;

	if deb.valor is not null then
		saldo := saldo - (deb.valor * sinal);
	end if;

	select sum(round(valor::numeric,2)) as valor into cred from movto where data > data_invalida and data <= data_parametro and conta_creditar=$1 and empresa=$3;

	--RAISE INFO '4- % - %', data_invalida, saldo;
	if cred.valor is not null then
		saldo := saldo + (cred.valor * sinal);
	end if;

	--RAISE INFO '5- % - %', data_invalida, saldo;
	--RAISE INFO 'saiu aki 3 ';
	return saldo;
end;
$_$;


ALTER FUNCTION public.conta_saldo_empresa(text, date, bigint) OWNER TO postgres;

--
-- Name: conta_saldo_empresa_calcula_f(bigint, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_empresa_calcula_f(bigint, text, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
	DELETE FROM conta_saldo_empresa where empresa = $1 and conta = $2 and data >= $3;

	INSERT INTO conta_saldo_empresa ( empresa, conta, data, saldo, saida, entrada)
		SELECT $1, $2, t.data, round(t.saldo::numeric, 2), t.saida, t.entrada FROM
			(SELECT * FROM conta_saldo_empresa_tf($1, $2, $3, current_date) c 
				(data DATE, entrada FLOAT, saida FLOAT, saldo FLOAT)) t;
END;
$_$;


