--

CREATE FUNCTION public.conta_saldo_empresa_f(text, date, bigint, boolean) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$
declare 
	c record;
	r record;
	deb record;
	cred record;
	saldo float;
	sinal int;
	data_invalida date;	
	data_parametro date;	
begin
	--TODO: Deve ser diminuido um data que vem, porque a funcao antiga estava bugada
	data_parametro := $2 - 1;

	select credor into c from conta where codigo=$1;

	if c.credor then
		sinal := 1;
	else
		sinal := -1;
	end if;

	saldo := 0;
	data_invalida := '1970-01-01';

	-- Saldo inicial da conta
	select saldo_inicial into c from conta where codigo=$1;

	if not found then
		--RAISE INFO 'saiu aki 1 ';
		return saldo;
	else
		if not c.saldo_inicial is null then
			saldo := c.saldo_inicial;
		end if;
	end if;

	--Somente verifica a tabela conta_saldo_empresa se estiver ativo 
	select ativo into r from conta_saldo_controle order by data_ult_exec desc limit 1;

	if found then
		if r.ativo then
			-- Saldo totalizado em determinado periodo
			select min(data) into data_invalida from conta_saldo_invalida where conta=$1 and data <= data_parametro and empresa = $3;

			if not found or data_invalida is null then
				data_invalida := data_parametro-1;
			else
				data_invalida := data_invalida-1;
			end if;
			--RAISE INFO '1- % - %', data_invalida, saldo;

			select data, cse.saldo as saldo_ini into c from conta_saldo_empresa cse where conta=$1 
			and data = data_invalida and empresa = $3;

			if found then
				saldo := c.saldo_ini;
				
				if c.data = data_parametro then
					--RAISE INFO 'saiu aki 2 ';
					return saldo;
				end if;			
			end if;

			--RAISE INFO '2- % - %', data_invalida, saldo;
			select data, cse.saldo as saldo_ini into c from conta_saldo_empresa cse where conta=$1 and data < data_invalida 
			and empresa = $3 order by 1 desc limit 1;
			
			if found then
				data_invalida := c.data;
				saldo := c.saldo_ini;
			end if;
		end if;
	end if;
	
	--RAISE INFO '3- % - %', data_invalida, saldo;
	
	-- Somente baixado.
	if $4 then
		select sum(round(valor::numeric,2)) as valor into deb from movto where data > data_invalida and data <= data_parametro 
		and conta_debitar=$1 and empresa=$3 and child != 0;
	else
		select sum(round(valor::numeric,2)) as valor into deb from movto where data > data_invalida and data <= data_parametro 
		and conta_debitar=$1 and empresa=$3;
	end if;

	if deb.valor is not null then
		saldo := saldo - (deb.valor * sinal);
	end if;

	-- Somente baixado.
	if $4 then
		select sum(round(valor::numeric,2)) as valor into cred from movto where data > data_invalida and data <= data_parametro 
		and conta_creditar=$1 and empresa=$3 and child != 0;
	else
		select sum(round(valor::numeric,2)) as valor into cred from movto where data > data_invalida and data <= data_parametro 
		and conta_creditar=$1 and empresa=$3;
	end if;

	--RAISE INFO '4- % - %', data_invalida, saldo;
	if cred.valor is not null then
		saldo := saldo + (cred.valor * sinal);
	end if;

	--RAISE INFO '5- % - %', data_invalida, saldo;
	--RAISE INFO 'saiu aki 3 ';
	return saldo;
end;
$_$;


ALTER FUNCTION public.conta_saldo_empresa_f(text, date, bigint, boolean) OWNER TO postgres;

--
-- Name: conta_saldo_empresa_tf(bigint, text, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_empresa_tf(bigint, text, date, date) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$
DECLARE
	r RECORD;
	raux RECORD;
	ret RECORD;
	v_sinal INTEGER;
	v_data_ini DATE;
	v_saldo FLOAT;
	v_saida FLOAT;
	v_entrada FLOAT;
	c1 REFCURSOR;
BEGIN
	SELECT data, saldo INTO r FROM conta_saldo_empresa
		WHERE empresa = $1 AND conta = $2 AND data = $3 - '1 day'::interval
		ORDER BY data DESC LIMIT 1;

	IF NOT found THEN	
		SELECT data, saldo INTO r FROM conta_saldo_empresa
			WHERE empresa = $1 AND conta = $2 AND data < $3
			ORDER BY data DESC LIMIT 1;
	END IF;
		
	IF FOUND THEN
		v_data_ini := r.data + '1 day'::INTERVAL;
		v_saldo := r.saldo;
		--RAISE INFO '1- % - %', v_data_ini, v_saldo;
	ELSE
		SELECT data INTO r FROM conta_saldo_empresa order by data limit 1;

		IF found and v_data_ini > r.data THEN
			v_data_ini := r.data;
		ELSE
			v_data_ini := $3-1;
		END IF;

		SELECT COALESCE(conta_saldo_empresa($2, v_data_ini+1, $1), 0) INTO v_saldo;
		
		IF NOT FOUND THEN
			v_saldo := 0;
		END IF;
	END IF;
	
	--RAISE INFO '2- % - %', v_data_ini, v_saldo;
	SELECT (CASE WHEN credor THEN 1 ELSE -1 END) INTO v_sinal FROM conta WHERE codigo=$2;

	IF NOT found THEN
		--RAISE INFO 'Conta % nao existe', $2;
		RETURN;
	END IF;
	
--	RAISE INFO 'Saldo: % - Conta: %', v_saldo, $2;
	v_saida := 0;
	v_entrada := 0;

	OPEN c1 FOR select data, 
		SUM((CASE WHEN conta_debitar=$2 THEN valor ELSE 0 END)) AS debito, 
		SUM((CASE WHEN conta_creditar=$2 THEN valor ELSE 0 END)) AS credito 
		FROM movto 
		WHERE empresa=$1 AND data BETWEEN v_data_ini AND $4 AND (conta_debitar=$2 OR conta_creditar=$2)
		GROUP BY data ORDER BY data;

	LOOP
		FETCH c1 INTO r;
		EXIT WHEN NOT found;
		
		-- Envia o mesmo saldo e entrada e saida zerada enquanto houver lacuna na data
		WHILE v_data_ini < r.data LOOP
			SELECT v_data_ini, 0::FLOAT, 0::FLOAT, v_saldo INTO ret;
			--RAISE INFO 'SAIU AKI 1';
			RETURN NEXT ret;
			v_data_ini = v_data_ini + '1 day'::INTERVAL;
		END LOOP;

		v_entrada := coalesce(r.credito, 0) * v_sinal;
		v_saida := coalesce(r.debito, 0) * v_sinal;
		v_saldo := v_saldo + v_entrada - v_saida;

		--RAISE INFO '3- % - %', v_data_ini, v_saldo;
		SELECT v_data_ini, v_entrada, v_saida, v_saldo INTO ret;
		--RAISE INFO 'SAIU AKI 2';
		RETURN NEXT ret;

		v_data_ini := v_data_ini + '1 day'::INTERVAL;
	END LOOP;

	CLOSE c1;

	WHILE v_data_ini <= $4 LOOP
		SELECT v_data_ini, 0::FLOAT, 0::FLOAT, v_saldo INTO ret;
		--RAISE INFO '4- % - %', v_data_ini, v_saldo;
		--RAISE INFO 'SAIU AKI 3';
		RETURN NEXT ret;
		v_data_ini := v_data_ini + '1 day'::INTERVAL;
	END LOOP;
END;

$_$;


ALTER FUNCTION public.conta_saldo_empresa_tf(bigint, text, date, date) OWNER TO postgres;

