-- Name: conta_saldo_init_f(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_init_f() RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
	PERFORM conta_saldo_init_f(null, null, null);
END;
$$;


ALTER FUNCTION public.conta_saldo_init_f() OWNER TO postgres;

--
-- Name: conta_saldo_init_f(bigint, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_init_f(bigint, text, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$
DECLARE
	r RECORD;
BEGIN
	DELETE from conta_saldo_invalida where 
	(case when $1 is null then true else empresa = $1 end) and
	(case when $2 is null then true else conta = $2 end);

	DELETE from conta_saldo_empresa where 
	(case when $1 is null then true else empresa = $1 end) and
	(case when $2 is null then true else conta = $2 end);

	INSERT INTO conta_saldo_invalida (empresa, conta, data) SELECT empresa, conta_debitar, MIN(data) FROM movto where 
	(case when $1 is null then true else empresa = $1 end) and
	(case when $2 is null then true else conta_debitar = $2 end) and
	(case when $3 is null then true else data >= $3 end) GROUP BY 1, 2;

	FOR r IN SELECT empresa, conta_creditar AS conta, MIN(data) AS data FROM movto where 
	(case when $1 is null then true else empresa = $1 end) and
	(case when $2 is null then true else conta_creditar = $2 end) and
	(case when $3 is null then true else data >= $3 end) GROUP BY 1, 2 LOOP
		BEGIN
			INSERT INTO conta_saldo_invalida (empresa, conta, data) VALUES (r.empresa, r.conta, r.data);
			EXCEPTION
				WHEN unique_violation THEN
					UPDATE conta_saldo_invalida SET data=r.data WHERE empresa=r.empresa AND conta=r.conta AND data>r.data;
		END;
	END LOOP;

	PERFORM conta_saldo_check_f();
END;
$_$;


ALTER FUNCTION public.conta_saldo_init_f(bigint, text, date) OWNER TO postgres;

--
-- Name: conta_saldo_invalida_f(bigint, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_invalida_f(bigint, text, date) RETURNS void
    LANGUAGE plpgsql
    AS $_$
BEGIN
	INSERT INTO conta_saldo_invalida (empresa, conta, data) VALUES ($1, $2, $3);
	EXCEPTION
		WHEN unique_violation THEN
			UPDATE conta_saldo_invalida SET data=$3 WHERE empresa=$1 AND conta=$2 AND data>$3;
END;
$_$;


