--
-- Name: conta_saldo_pessoa(text, integer, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_pessoa(text, integer, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$
	declare c record;
		deb record;
		cred record;
		saldo float;
		sinal int;
	begin
		if $2 = null then
			return(0);
		end if;

		select saldo_ini into c from conta_saldo where conta=$1 and data=$2;
		if found then 
			return(c.saldo_ini);
		end if;

		select credor into c from conta where codigo=$1;

    		if c.credor then 
			sinal = 1; 
		else 
			sinal = -1; 
		end if;

		select sum(valor) into deb from movto where data<$3 and
		conta_debitar=$1 and pessoa=$2;

		if deb.sum = null then
			saldo := 0;
		else
			saldo := (deb.sum * sinal) * -1;
		end if;

		select sum(valor) into cred from movto where data<$3 and 
		conta_creditar=$1 and pessoa=$2;

		if cred.sum = null then
			-- N„o faz nada
		else
			saldo := saldo + (cred.sum * sinal);
		end if;

     		return(saldo);
	end;
	$_$;


