ALTER FUNCTION public.conta_saldo_pessoa(text, bigint, date) OWNER TO postgres;

--
-- Name: conta_saldo_pessoa(text, bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_pessoa(text, bigint, date, bigint) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

declare

	c record;
	deb record;
	cred record;
	saldo float :=0;
	sinal int;

begin

	if $2 = null then
		return(0);
	end if;

	select credor into c from conta where codigo=$1;

	if c.credor then 
		sinal = 1; 
	else 
		sinal = -1; 
	end if;

	if $4 IS NULL then
		select sum(round(valor::numeric, 2)) into deb from movto 
		where data<$3 and conta_debitar=$1 and pessoa=$2;
	else
		select sum(round(valor::numeric, 2)) into deb from movto
		where data<$3 and conta_debitar=$1 and pessoa=$2 and empresa=$4;
	end if;

	if deb.sum IS NOT NULL then
		saldo := (deb.sum * sinal) * -1;
	end if;

	if $4 IS NULL then
		select sum(round(valor::numeric, 2)) into cred from movto where data<$3 and 
		conta_creditar=$1 and pessoa=$2;
	else
		select sum(round(valor::numeric, 2)) into cred from movto where data<$3 and 
		conta_creditar=$1 and pessoa=$2 and empresa=$4;
	end if;

	if cred.sum IS NOT NULL then
		saldo := saldo + (cred.sum * sinal);
	end if;

	return(saldo);

end;
$_$;


