--
-- Name: conta_saldo_teste_f(date, date, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.conta_saldo_teste_f(date, date, bigint, text) RETURNS void
    LANGUAGE plpgsql
    AS $_$
declare 
	r RECORD;
	saldo_old NUMERIC;
	saldo NUMERIC;
	entrada NUMERIC;
	entrada_old NUMERIC;
	saida NUMERIC;
	saida_old NUMERIC;
	saldo_geral NUMERIC;
	saldo_geral_emp NUMERIC;
	saldo_calculado NUMERIC;
BEGIN
	for r in select cse.*, c.credor from conta_saldo_empresa cse join conta c on (c.codigo = cse.conta) where data between $1 and $2 and (case when $3 is null then true else empresa = $3 end) 
			 and (case when $4 is null then true else (conta = $4 or conta LIKE $4||'.%') end) order by empresa, conta, data loop
		begin

		RAISE INFO '-----------------------------------------------------';
		RAISE INFO 'Empresa: % - Conta: % - Data: %', r.empresa, r.conta, to_char(r.data, 'dd/mm/yyyy');
		
		select round(cse.saldo::numeric, 2) into saldo_calculado from conta_saldo_empresa cse where cse.empresa = r.empresa and cse.data = r.data-1 and cse.conta = r.conta;
		if not found then
			saldo_calculado := round(conta_saldo_empresa(r.conta, r.data, r.empresa)::numeric, 2);
		end if;
		RAISE INFO 'Saldo Anterior: %', saldo_calculado;

		--Testa as entradas da conta
		entrada := round(r.entrada::numeric, 2);
		select coalesce(round(sum(valor)::numeric, 2), 0.00)*(case when r.credor then 1 else -1 end) into entrada_old from movto where empresa = r.empresa and data = r.data and conta_creditar = r.conta;

		RAISE INFO 'Entrada New: %', entrada;
		RAISE INFO 'Entrada Old: %', entrada_old;		
		RAISE INFO 'Entrada Teste: %', test.assert(abs(entrada-entrada_old) <= 0.01, entrada ||' != '|| entrada_old);
		
		--Testa as saidas da conta
		saida := round(r.saida::numeric, 2);
		select coalesce(round(sum(valor)::numeric, 2), 0.00)*(case when r.credor then 1 else -1 end) into saida_old from movto where empresa = r.empresa and data = r.data and conta_debitar = r.conta;

		RAISE INFO 'Saida New: %', saida;
		RAISE INFO 'Saida Old: %', saida_old;		
		RAISE INFO 'Saida Teste: %', test.assert(abs(saida-saida_old) <= 0.01, saida ||' != '|| saida_old);
		
		--Testa o saldo da conta
		saldo := round(r.saldo::numeric, 2);
		saldo_old := round(conta_saldo_empresa(r.conta, r.data+1, r.empresa)::numeric, 2);
		
		RAISE INFO 'Saldo New: %', saldo;
		RAISE INFO 'Saldo Old: %', saldo_old;		
		RAISE INFO 'Saldo Teste: %', test.assert(abs(saldo-saldo_old) <= 0.01, saldo ||' != '|| saldo_old);

		saldo_calculado := round((saldo_calculado + entrada - saida)::numeric, 2);
		RAISE INFO 'Saldo Calculado: %', saldo_calculado;
		RAISE INFO 'Saldo Teste Calculado: %', test.assert(abs(saldo-saldo_calculado) <= 0.01, saldo ||' != '|| saldo_calculado);

		/*
		EXCEPTION
			when raise_exception then
				RAISE NOTICE 'DEU PROBLEMA!!!!!';
		*/
		end;
	end loop;	

	--Testa o saldo geral na data final
	if $4 is not null then
		RAISE INFO '';
		RAISE INFO '======================================================';
		RAISE INFO '>>> TESTA SALDO GERAL';

		for r in select codigo from conta where (codigo = $4 or codigo LIKE $4||'.%') order by 1 loop
			RAISE INFO '-----------------------------------------------------';
			RAISE INFO 'Conta: %', r.codigo;
		
			select round(sum(conta_saldo_empresa(r.codigo, $2+1, e.grid))::numeric, 2) into saldo_geral_emp from empresa e;
			select round(conta_saldo(r.codigo, $2+1)::numeric, 2) into saldo_geral;

			RAISE INFO 'Saldo Geral Empresa: %', saldo_geral_emp;
			RAISE INFO 'Saldo Geral: %', saldo_geral;		
			RAISE INFO 'Saldo Geral Teste: %', test.assert(abs(saldo_geral_emp-saldo_geral) <= 0.01, saldo_geral_emp ||' != '|| saldo_geral);
		end loop;
		
	end if;

	return ;
	END;

$_$;


ALTER FUNCTION public.conta_saldo_teste_f(date, date, bigint, text) OWNER TO postgres;

