    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare
	r record;
begin 
	select 1 into r from conta where codigo like $1||'.%';
	if found then
		return 't'::text;
	else
		return 'f'::text;
	end if;
end;
   
$_$;


