--
-- Name: control_retorno_boleto_f(bigint, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.control_retorno_boleto_f(bigint, double precision) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

/*Parametros
1 - movto
2 - valor
*/
declare
	r RECORD;
	r2 RECORD;
	saldo float;
	v_novo_grid bigint;
	v_caixa_adm text;
	v_motivo_baixa bigint;
begin
	if (select 1 from movto where grid = $1) = 1 then 
		if (select 1 from boleto b where movto = $1 and situacao != 6) = 1 then
			update boleto set situacao = 6 where movto = $1;
			DROP TABLE IF exists temp_movto;
			create temp table temp_movto as select * from movto where grid = $1;
		else
			DROP TABLE IF exists temp_movto;
			create temp table temp_movto as select * from movto where grid = (
				with recursive parcial as (
					select child from grid_map where parent = $1
					union 
					select gm.child from grid_map gm inner join parcial p on p.child = gm.parent 
				) 
				select * from parcial where movto_data_baixa_f(child) is null order by child desc limit 1
			);
		end if;
		if (select count(*) from temp_movto) = 0 then
			return 2;
		end if;
		
		DROP TABLE IF exists temp_movto_info;
		create temp table temp_movto_info as select * from movto_info where movto = $1;
	
		select conta into v_caixa_adm from conta_config where chave = 'CAIXA ADM';
	
		for r in select * from temp_movto loop
			select grid into v_motivo_baixa from motivo_movto where conta_creditar=r.conta_debitar and conta_debitar=v_caixa_adm and flag='A' order by grid;
			--se valor maior que o pagamento baixa parcial.
			if r.valor > $2 then
				saldo := r.valor - $2;
				--faz a baixa
				insert into movto (data,
									hora,
									turno,
									seq,
									motivo,
									conta_debitar,
									conta_creditar,
									pessoa,
									pessoa_id,
									documento,
									data_doc,
									tipo_doc,
									lote,
									vencto,
									valor,
									parent,
									child,
									usuario,
									estacao,
									obs,
									info,
									empresa,
									mlid,
									pessoa_simples,
									marcador)
				values(current_date,
						now(), 
						r.turno, 
						r.seq, 
						v_motivo_baixa,
						v_caixa_adm,
						r.conta_debitar,
						r.pessoa,
						r.pessoa_id,
						r.documento,
						r.data_doc,
						r.tipo_doc,
						r.lote,
						r.vencto,
						$2,
						r.grid,
						r.child,
						r.usuario,
						r.estacao,
						'BAIXADO AUTOMATICAMENTE RETORNO MAKRO',
						r.info,
						r.empresa,
						r.mlid,
						r.pessoa_simples,
						r.marcador);
					
				select grid into v_novo_grid from movto where parent = 	r.grid;
				update movto set valor = $2, child = v_novo_grid where grid = r.grid;
				insert into movto_map (parent, child) values (r.grid, v_novo_grid);
				
				--inclui o movto parcial	
				insert into movto (data,
									hora,
									turno,
									seq,
									motivo,
									conta_debitar,
									conta_creditar,
									pessoa,
									pessoa_id,
									documento,
									data_doc,
									tipo_doc,
									lote,
									vencto,
									valor,
									parent,
									child,
									usuario,
									estacao,
									obs,
									info,
									empresa,
									mlid,
									pessoa_simples,
									marcador)
				values(r.data,
						r.hora, 
						r.turno, 
						r.seq, 
						r.motivo,
						r.conta_debitar,
						r.conta_creditar,
						r.pessoa,
						r.pessoa_id,
						concat(r.documento, '(P)'),
						r.data_doc,
						r.tipo_doc,
						r.lote,
						r.vencto,
						saldo, 
						r.parent,
						r.child,
						r.usuario,
						r.estacao,
						r.obs,
						r.info,
						r.empresa,
						r.mlid,
						r.pessoa_simples,
						r.marcador);
					
				select grid into v_novo_grid from movto where documento = concat(r.documento, '(P)');
			
				insert into movto_map (parent, child) values (r.grid, v_novo_grid);
			
				for r2 in select * from temp_movto_info loop
					if not(select true from movto_info where movto = v_novo_grid and tipo = r2.tipo) then
						insert into movto_info (movto, tipo, info) values (v_novo_grid, r2.tipo, r2.info);
					end if;			
				end loop;

			
				insert into grid_map (chave, parent, child) values ('parcial', r.grid, v_novo_grid);
			else
				insert into movto (data,
									hora,
									turno,
									seq,
									motivo,
									conta_debitar,
									conta_creditar,
									pessoa,
									pessoa_id,
									documento,
									data_doc,
									tipo_doc,
									lote,
									vencto,
									valor,
									parent,
									child,
									usuario,
									estacao,
									obs,
									info,
									empresa,
									mlid,
									pessoa_simples,
									marcador)
				values(current_date,
						now(), 
						r.turno, 
						r.seq, 
						v_motivo_baixa,
						v_caixa_adm,
						r.conta_debitar,
						r.pessoa,
						r.pessoa_id,
						r.documento,
						r.data_doc,
						r.tipo_doc,
						r.lote,
						r.vencto,
						$2,
						r.grid,
						r.child,
						r.usuario,
						r.estacao,
						'BAIXADO AUTOMATICAMENTE RETORNO MAKRO',
						r.info,
						r.empresa,
						r.mlid,
						r.pessoa_simples,
						r.marcador);
					
				select grid into v_novo_grid from movto where parent = 	r.grid;
			
				insert into movto_map (parent, child) values (r.grid, v_novo_grid);	
			
			end if;
		
		end loop;
	
		return 1;
	else
		return 0;
	end if;

end
	
$_$;


ALTER FUNCTION public.control_retorno_boleto_f(bigint, double precision) OWNER TO postgres;

--
-- Name: cpf_cliente_cupom_f(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cpf_cliente_cupom_f(bigint, bigint, bigint) RETURNS text
    LANGUAGE plpgsql
    AS $_$

	/*Parametros
	1 - cupom
	2 - pessoa_simples
	3 - movto
	*/
	DECLARE
		r text;

	BEGIN
		SELECT (CASE WHEN LENGTH(p.cpf) > 0 THEN p.cpf 
				WHEN LENGTH(ps.cpf) > 0 THEN ps.cpf
				WHEN LENGTH(c.pessoa_cpf) > 0 THEN c.pessoa_cpf END) 
		INTO r 
		FROM cupom c 
		JOIN cupom_total ct ON (c.grid = ct.cupom)
		LEFT JOIN pessoa_simples ps ON (c.pessoa_simples = ps.grid) 
		LEFT JOIN pessoa p ON (p.pessoa = coalesce(ct.pessoa, c.pessoa)) WHERE c.grid = $1;

		if r IS NULL THEN
			SELECT movto_info_f($3, 'cpf') INTO r;
		END IF;
		RETURN r;
	END;
	
$_$;


