--
-- Name: current_host_name(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.current_host_name() RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
	declare r record;
	begin
		select estacao into r from usuario_pid where pid=backend_pid();
		
		if found then
			return r.estacao;
		else
			return null;
		end if;
	end;
$$;


