--
-- Name: custo_medio_composto_empresa_f(bigint, bigint, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.custo_medio_composto_empresa_f(bigint, bigint, date, bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

		declare
			r record;
			total_custo float := 0.0;
			custo_comp float;
			result_found boolean := FALSE;
		begin
			for r in
					select l1.produto, l1.quantidade
					from lancto l1 
					join lancto l2 on l1.mlid = l2.mlid	
						and l2.grid = $4 and l2.empresa = $1 
					where l1.seq_cupom = l2.seq_cupom and l1.operacao = 'SR'
			loop
				result_found := TRUE;
				select custo_medio_empresa_f($1, r.produto, $3) * r.quantidade into custo_comp;

				total_custo := total_custo + custo_comp;
			end loop;
			
			if not result_found then
				select custo_medio_empresa_f($1, $2, $3) into total_custo;
			end if;

			return total_custo;

		end;
	
$_$;


ALTER FUNCTION public.custo_medio_composto_empresa_f(bigint, bigint, date, bigint) OWNER TO postgres;

--
-- Name: custo_medio_empresa_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.custo_medio_empresa_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare r record;
begin
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3 and ult_custo_medio <> 0 limit 1;
	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'1 day'::interval and ult_custo_medio <> 0 limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'2 day'::interval and ult_custo_medio <> 0 limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'3 day'::interval and ult_custo_medio <> 0 limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'4 day'::interval and ult_custo_medio <> 0 limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'5 day'::interval and ult_custo_medio <> 0 limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select ult_custo_medio as custo_medio into r from estoque_valor
	where empresa = $1 and produto = $2 and data <= $3-'6 day'::interval and ult_custo_medio <> 0 order by data desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3 and custo_medio <> 0 order by ordem desc limit 1;
	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3-'1 day'::interval and custo_medio <> 0 order by ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3-'2 day'::interval and custo_medio <> 0 order by ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3-'3 day'::interval and custo_medio <> 0 order by ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3-'4 day'::interval and custo_medio <> 0 order by ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data = $3-'5 day'::interval and custo_medio <> 0 order by ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;
	
	select custo_medio into r from estoque_lancto where empresa=$1 and produto = $2 and data <= $3-'6 day'::interval and custo_medio <> 0 order by data desc, ordem desc limit 1;

	if found then
		return r.custo_medio;
	end if;

	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3 limit 1;
	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'1 day'::interval limit 1;

	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'2 day'::interval limit 1;

	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'3 day'::interval limit 1;

	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'4 day'::interval limit 1;

	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data = $3-'5 day'::interval limit 1;

	if found then
		return r.ult_custo;
	end if;
	
	select ult_custo into r from estoque_valor
	where empresa = $1 and produto = $2 and data <= $3-'6 day'::interval order by data desc limit 1;

	if found then
		return r.ult_custo;
	end if;

	if not found then
		return 0;
	end if;
end;

$_$;


ALTER FUNCTION public.custo_medio_empresa_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: custo_medio_fiscal_empresa_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.custo_medio_fiscal_empresa_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE

	v_ult_custo_medio_fiscal float :=0;
   
BEGIN

	SELECT ev.ult_custo_medio_fiscal INTO v_ult_custo_medio_fiscal
	  FROM estoque_valor ev
	 WHERE ev.empresa=$1
	   AND ev.produto=$2
	   AND ev.data=$3;

	IF NOT FOUND THEN
		SELECT ev.ult_custo_medio_fiscal INTO v_ult_custo_medio_fiscal
		  FROM estoque_valor ev
	     WHERE ev.empresa=$1
	       AND ev.produto=$2
		   AND ev.data<$3 order by data desc LIMIT 1;

		IF NOT FOUND THEN
			SELECT ev.ult_custo_medio_fiscal INTO v_ult_custo_medio_fiscal
		      FROM estoque_valor ev
	         WHERE ev.empresa=$1
	           AND ev.produto=$2
		       AND ev.data>$3 order by data LIMIT 1;
		END IF;
	END IF;
	
	IF NOT FOUND THEN
		v_ult_custo_medio_fiscal := 0;
	END IF;

	RETURN v_ult_custo_medio_fiscal;

END;

$_$;


ALTER FUNCTION public.custo_medio_fiscal_empresa_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: custo_medio_periodo_f(bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.custo_medio_periodo_f(bigint, bigint, date, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
	r RECORD;
	v_retorno float;

BEGIN
	
	select l.preco_unit
	into v_retorno
	from lancto l
	where l.data < $3
		and (case when $1 is null then true else l.empresa=$1 end)
		and l.produto= $2
		and l.operacao = 'E'
	order by l.data desc, l.turno desc, l.hora desc
	limit 1;
	
	FOR r IN select l.preco_unit as preco_unit_entrada,
					l.quantidade as quantidade_entrada,
					produto_estoque_f($1, null, $2, l.data, l.turno, l.hora-interval '1 second') as estoque_ant
			from lancto l
			where (l.data between $3 and $4)
				and (case when $1 is null then true else l.empresa=$1 end)
				and l.produto=$2
				and l.operacao = 'E' LOOP
	
		if r.estoque_ant > 0 then
			v_retorno := ((r.estoque_ant * v_retorno) + (r.preco_unit_entrada * r.quantidade_entrada)) / (r.estoque_ant + r.quantidade_entrada);
		else
			v_retorno := r.preco_unit_entrada;
		end if;

	END LOOP; --fim do loop

	return v_retorno;
END;

$_$;


ALTER FUNCTION public.custo_medio_periodo_f(bigint, bigint, date, date) OWNER TO postgres;

--
-- Name: datasul_produto_map_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.datasul_produto_map_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
	cod BIGINT;
BEGIN
	PERFORM 1 FROM pg_attribute pa JOIN pg_class pc on (pa.attrelid = pc.oid) 
		LEFT JOIN pg_attrdef pr on (attnum = adnum and pc.oid=adrelid) 
		WHERE relname = 'produto' and attstattarget <> 0 and attname in 
		('c_conta', 'c_item', 'c_natureza_oper_ext', 'c_natureza_oper_int', 'c_baixa_estoque');

	IF not found THEN
		RETURN NEW;
	END IF;

	IF NEW.c_item is null OR NEW.c_item = '' THEN
		RETURN NEW;
	END IF;

	SELECT codigo INTO cod FROM exc_datasul_produto_map WHERE produto=NEW.grid;	

	IF found THEN
		IF NEW.c_item is not null THEN
			UPDATE exc_datasul_produto_map SET conta_contabil=NEW.c_conta, item_ems=NEW.c_item, 
				nat_oper_fora=NEW.c_natureza_oper_ext, nat_oper_dentro=NEW.c_natureza_oper_int,
				baixa_estoque=NEW.c_baixa_estoque WHERE codigo=cod;
		END IF;
	ELSE
		INSERT INTO exc_datasul_produto_map (codigo, produto, conta_contabil, item_ems, nat_oper_fora,
			nat_oper_dentro, baixa_estoque) VALUES (nextval('exc_datasul_seq'), NEW.grid, NEW.c_conta, 
			NEW.c_item, NEW.c_natureza_oper_ext, NEW.c_natureza_oper_int, NEW.c_baixa_estoque);
	END IF;
			
	RETURN NEW;
END;
	
$$;


ALTER FUNCTION public.datasul_produto_map_tgf() OWNER TO postgres;

--
-- Name: delete_orcamento_vazio(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_orcamento_vazio() RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    r record;
BEGIN
	-- Esta funcao deleta todos os orcamentos que nao tem nenhum produto relacionado
    loop
        SELECT o.grid INTO r FROM orcamento o WHERE o.status in ('A', 'P') AND 
		NOT EXISTS (SELECT 1 FROM comanda_produto cp WHERE cp.orcamento = o.grid) AND 
		NOT EXISTS (SELECT 1 FROM orcamento_produto op WHERE op.orcamento = o.grid);

		if found then
            RAISE NOTICE 'Deletando orcamento %...', r.grid;
            EXECUTE 'DELETE FROM orcamento WHERE grid = ' || r.grid;
        else
            exit;
        end if;
    end loop;

    RAISE NOTICE 'Finalizado!';

    return true;
END;
$$;


ALTER FUNCTION public.delete_orcamento_vazio() OWNER TO postgres;

--
-- Name: deposito_movimenta_produto_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.deposito_movimenta_produto_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

begin
	select p.grid into r from produto p join deposito_grupo_produto dgp on (p.grupo=dgp.grupo and p.grid=$2 and dgp.deposito=$1);
	
	if found then
		select movimenta into r from produto_deposito where deposito=$1 and produto=$2;
		
		if found then
			if r.movimenta is null then
				return true;
			else
				return r.movimenta;
			end if;
		else		
			return true;
		end if;		
	else
		select p.grid into r from produto p join deposito d on (p.grid=d.produto and p.grid=$2 and d.grid=$1);
		
		if found then 
			return true;
		else
			return false;
		end if;
	end if;

end;
$_$;


