--

CREATE FUNCTION public.desconto_venda_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	begin
		select coalesce(sum(coalesce(ld.desconto_item_tabela, 0) + coalesce(ld.desconto_item_manual, 0) + coalesce(ld.desconto_item_promo, 0) + 
		coalesce(ld.desconto_venda_tabela, 0) + coalesce(ld.desconto_venda_manual, 0) + 
		coalesce(ld.desconto_venda_vale, 0) + 
		coalesce(ld.desconto_item_diferenciado, 0)), 0)::numeric as desconto into r from lancto_desconto ld 
		where ld.mlid=$1;

	   return r.desconto;
	end;	   

$_$;


