    LANGUAGE sql IMMUTABLE
    AS $_$

	   select (case when $1 = 0 then 'Domingo' 
	   else   (case when $1 = 1 then 'Segunda-Feira'
	   else   (case when $1 = 2 then 'Terca-Feira'
	   else   (case when $1 = 3 then 'Quarta-Feira'    
	   else   (case when $1 = 4 then 'Quinta-Feira'
	   else   (case when $1 = 5 then 'Sexta-Feira'    	   
	   else   'Sabado' end) end) end) end) end) end);
   
$_$;


