--
-- Name: disable_triggers(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.disable_triggers(text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

declare
	versao int;
begin
	/*verifica a versao do banco, porque apartir da versao 8.4 mudou o nome da coluna
	que idenifica se a tabela possui uma trigger*/
	select to_number(split_part(version(),' ',2),'9999') into versao;

	if versao <= 83 then
		UPDATE pg_class SET reltriggers = 0 WHERE relname = $1;
	else
		UPDATE pg_class SET relhastriggers = false WHERE relname = $1;
	end if;
	
		
	RAISE log 'Enable - Tabela: % - Usuario: % - Host: % - User: %',  $1, current_user_name(), current_host(), current_user;

	return true;
end;

$_$;


ALTER FUNCTION public.disable_triggers(text) OWNER TO postgres;

--
-- Name: drop_temp_table(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.drop_temp_table() RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    t record;
BEGIN
    loop
        select tablename into t from pg_tables where tablename like 'temp_%';
        if found then
            RAISE NOTICE 'Dropando tabela %...', t.tablename;
            EXECUTE 'DROP TABLE ' || t.tablename;
        else
            exit;
        end if;
    end loop;

    RAISE NOTICE 'Finalizado!';

    return true;
END;
$$;


