--
-- Name: empresa_serie_nf_numero_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.empresa_serie_nf_numero_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN
	IF TG_OP = 'INSERT' THEN
		INSERT INTO empresa_serie_nf_numero_log (empresa, modelo_doc, serie, numero, host, usuario, hora, operacao)
		VALUES (NEW.empresa, NEW.modelo_doc, NEW.serie, NEW.numero, CURRENT_HOST(), CURRENT_USER_NAME(), NOW(), 'I');
		
		RETURN NEW;
	END IF;

	IF TG_OP = 'DELETE' THEN
		INSERT INTO empresa_serie_nf_numero_log (empresa, modelo_doc, serie, numero, host, usuario, hora, operacao)
		VALUES (OLD.empresa, OLD.modelo_doc, OLD.serie, OLD.numero, CURRENT_HOST(), CURRENT_USER_NAME(), NOW(), 'D');

		RETURN OLD;
	END IF;
	
	INSERT INTO empresa_serie_nf_numero_log (empresa, modelo_doc, serie, numero, host, usuario, hora, operacao)
	VALUES (OLD.empresa, OLD.modelo_doc, OLD.serie, OLD.numero, CURRENT_HOST(), CURRENT_USER_NAME(), NOW(), 'Uo');
		
	INSERT INTO empresa_serie_nf_numero_log (empresa, modelo_doc, serie, numero, host, usuario, hora, operacao)
	VALUES (NEW.empresa, NEW.modelo_doc, NEW.serie, NEW.numero, CURRENT_HOST(), CURRENT_USER_NAME(), NOW(), 'Un');

	RETURN NEW;
END;	
	
$$;


ALTER FUNCTION public.empresa_serie_nf_numero_tgf() OWNER TO postgres;

--
-- Name: enable_triggers(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enable_triggers(text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

declare
	versao int;
begin
	/*verifica a versao do banco, porque apartir da versao 8.4 mudou o nome da coluna
	que idenifica se a tabela possui uma trigger*/
	select to_number(split_part(version(),' ',2),'9999') into versao;

	if versao <= 83 then
		UPDATE pg_class SET reltriggers = (SELECT count(*) FROM pg_trigger where pg_class.oid = tgrelid) WHERE relname = $1;
	else
		UPDATE pg_class SET relhastriggers = (SELECT (case when count(*) > 0 then true else false end) FROM pg_trigger 
			where pg_class.oid = tgrelid) WHERE relname = $1;

	end if;

	RAISE log 'Enable - Tabela: % - Usuario: % - Host: % - User: %',  $1, current_user_name(), current_host(), current_user;

	return true;
end;

$_$;


ALTER FUNCTION public.enable_triggers(text) OWNER TO postgres;

--
-- Name: estoque_grupo_produto_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estoque_grupo_produto_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

declare
        r record;
        estoque double precision;
        tot_estoque double precision;
begin
        tot_estoque := 0;

        FOR r IN select grid, nome from produto where grupo = $2 loop
                estoque = estoque_produto_f($1, r.grid, $3);

                if abs(estoque) > 0 then
                        tot_estoque = tot_estoque +  estoque;
                end if;
        end loop;
        return tot_estoque;
end;

$_$;


ALTER FUNCTION public.estoque_grupo_produto_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: estoque_lancto_data_tf(bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estoque_lancto_data_tf(bigint, bigint, date, date) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r RECORD;
	ret RECORD;
	data_ant DATE;
	v_data_ini DATE;
	v_estoque FLOAT;
	c1 REFCURSOR;
  BEGIN

	SELECT data, estoque_emp INTO r FROM estoque_lancto
		WHERE empresa=$1 AND produto=$2 AND data<$3
		ORDER BY data DESC, ordem DESC LIMIT 1;

	IF found THEN
		v_data_ini := r.data;
		v_estoque := r.estoque_emp;
	ELSE
		v_data_ini := '0000-01-01';
		v_estoque := 0;
	END IF;

	data_ant := $3 - '1 day'::interval;

	OPEN c1 FOR SELECT data, estoque_emp FROM estoque_lancto
		WHERE empresa=$1 AND produto=$2 AND data > v_data_ini AND data <= $4
		ORDER BY data, ordem;

	LOOP
		FETCH c1 INTO r;
		EXIT WHEN NOT found;

		IF (data_ant < r.data) THEN
			WHILE data_ant < r.data LOOP
				IF (data_ant >= $3) THEN
					SELECT data_ant, v_estoque INTO ret;
					RETURN NEXT ret;
				END IF;

				data_ant := data_ant + '1 day'::interval;
			END LOOP;
		END IF;

		v_estoque := r.estoque_emp;
	END LOOP;

	CLOSE c1;

	-- Retorna o ultimo estoque ate alcancar a data fim
	WHILE data_ant <= $4 LOOP
		IF data_ant >= $3 THEN
			SELECT data_ant, v_estoque INTO ret;
			RETURN NEXT ret;
		END IF;

		data_ant := data_ant + '1 day'::interval;
	END LOOP;
  END;
  
$_$;


ALTER FUNCTION public.estoque_lancto_data_tf(bigint, bigint, date, date) OWNER TO postgres;

