--
-- Name: estoque_produto_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estoque_produto_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

declare r record;
begin
  	select p.tipo, p.controlar_estoque into r from produto p where p.grid = $2;
  	
	if date_part('d', $3) = 1 and not r.controlar_estoque and r.tipo = 'C' then
		select (sum(compra) - sum(venda)) as estoque into r
		from estoque_deposito ed 
		where ed.empresa=$1
		and ed.data between to_char($3,'yyyy-mm-01')::date and $3
		and ed.produto=$2
		and ed.deposito in (select grid from deposito where flag = 'A' and grid = ed.deposito);
		return r.estoque;
	else
		select coalesce(produto_estoque_f($1, $2, $3), 0) as estoque into r;		
		return r.estoque;
	end if;
end;

$_$;


ALTER FUNCTION public.estoque_produto_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: estoque_valor_data_tf(bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.estoque_valor_data_tf(bigint, bigint, date, date) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r RECORD;
	r_aux RECORD;
	ret RECORD;
	c1 REFCURSOR;
	v_data_ant DATE;
	v_maior_data_mov DATE;
	v_ult_custo FLOAT;
	v_ult_custo_medio FLOAT;
	v_ult_custo_fiscal FLOAT;
	v_ult_custo_medio_fiscal FLOAT;

	v_cmv_ult_custo FLOAT := 0;
	v_cmv_custo_medio FLOAT := 0;
	v_cmv_ult_custo_fiscal FLOAT := 0;
	v_cmv_custo_medio_fiscal FLOAT := 0;
	
	v_estoque FLOAT := 0;
  BEGIN

	---------------------------------------------------------------------------
	-- Determina a data do ultimo registro conhecido na estoque_valor
	-- para comecar a partir dele o preenchimento da tabela
	SELECT data INTO v_maior_data_mov FROM estoque_valor
		WHERE empresa=$1 AND produto=$2 AND data=($3 - '1 day'::interval)
		ORDER BY data DESC LIMIT 1;

	IF NOT found THEN
		SELECT data INTO v_maior_data_mov FROM estoque_valor
			WHERE empresa=$1 AND produto=$2 AND data<$3 
			ORDER BY data DESC LIMIT 1;
	END IF;

	IF found THEN
		v_data_ant := v_maior_data_mov + '1 day'::interval;
	ELSE
		v_data_ant := $3;
	END IF;
		
	-- Busca o estoque antes da data informada
	SELECT estoque_dep INTO r FROM estoque_lancto
		WHERE empresa=$1 AND produto=$2 AND data=(v_data_ant - '1 day'::interval)
		ORDER BY data DESC, ordem DESC LIMIT 1;

	IF NOT found THEN
		SELECT estoque_dep INTO r FROM estoque_lancto
			WHERE empresa=$1 AND produto=$2 AND data<v_data_ant 
			ORDER BY data DESC, ordem DESC LIMIT 1;
	END IF;
	----------------------------------------------------------------------------

	OPEN c1 FOR SELECT el.data, el.operacao, el.movimento, el.custo_medio, el.ult_custo, el.custo_medio_fiscal, el.ult_custo_fiscal, el.estoque_emp
		FROM estoque_lancto el
		WHERE el.empresa=$1 AND el.produto=$2 AND el.data BETWEEN v_data_ant AND $4
		ORDER BY el.data, el.ordem;

	FETCH c1 INTO r;

	IF NOT found OR r.data > v_data_ant THEN
		SELECT ult_custo, custo_medio, custo_medio_fiscal, ult_custo_fiscal, estoque_emp INTO r_aux FROM estoque_lancto
			WHERE empresa=$1 AND produto=$2 AND data=(v_data_ant - '1 day'::interval)
			ORDER BY data DESC, ordem DESC LIMIT 1;

		IF NOT found THEN
			SELECT ult_custo, custo_medio, custo_medio_fiscal, ult_custo_fiscal, estoque_emp INTO r_aux FROM estoque_lancto
				WHERE empresa=$1 AND produto=$2 AND data<v_data_ant
				ORDER BY data DESC, ordem DESC LIMIT 1;
		END IF;

		IF found THEN
			v_ult_custo := r_aux.ult_custo;
			v_ult_custo_medio := r_aux.custo_medio;
			v_ult_custo_fiscal := r_aux.ult_custo_fiscal;
			v_ult_custo_medio_fiscal := r_aux.custo_medio_fiscal;
			v_estoque := r_aux.estoque_emp;
		ELSE
			v_ult_custo := 0;
			v_ult_custo_medio := 0;
			v_ult_custo_fiscal := 0;
			v_ult_custo_medio_fiscal := 0;
			v_estoque := 0;
		END IF;
	END IF;


	LOOP
		IF (v_data_ant < r.data) THEN
			WHILE v_data_ant < r.data LOOP

				IF (v_data_ant >= v_data_ant) THEN
					SELECT v_data_ant, v_ult_custo, v_ult_custo_medio, v_cmv_ult_custo, v_cmv_custo_medio,
						   preco_unit_empresa_f($2,$1) as preco_unit, v_estoque,
						   v_ult_custo_fiscal, v_ult_custo_medio_fiscal, v_cmv_ult_custo_fiscal, v_cmv_custo_medio_fiscal INTO ret;
					RETURN NEXT ret;
				END IF;

				v_data_ant := v_data_ant + '1 day'::interval;
				v_cmv_ult_custo := 0;
				v_cmv_custo_medio := 0;
				v_cmv_ult_custo_fiscal := 0;
				v_cmv_custo_medio_fiscal := 0;
			END LOOP;
		END IF;

		v_ult_custo := r.ult_custo;
		v_ult_custo_medio := r.custo_medio;
		v_ult_custo_fiscal := r.ult_custo_fiscal;
		v_ult_custo_medio_fiscal := r.custo_medio_fiscal;
		v_estoque := r.estoque_emp;

		IF r.operacao = 'V' THEN
			v_cmv_ult_custo := v_cmv_ult_custo + (r.movimento * r.ult_custo * -1);
			v_cmv_custo_medio := v_cmv_custo_medio + (r.movimento * r.custo_medio * -1);
			v_cmv_ult_custo_fiscal := v_cmv_ult_custo_fiscal + (r.movimento * r.ult_custo_fiscal * -1);
			v_cmv_custo_medio_fiscal := v_cmv_custo_medio_fiscal + (r.movimento * r.custo_medio_fiscal * -1);
		END IF;

		FETCH c1 INTO r;
		EXIT WHEN NOT found;
	END LOOP;

	CLOSE c1;

	WHILE v_data_ant <= $4 LOOP

		IF v_data_ant >= v_data_ant THEN
			SELECT v_data_ant, v_ult_custo, v_ult_custo_medio, v_cmv_ult_custo, v_cmv_custo_medio,
			       preco_unit_empresa_f($2,$1) as preco_unit, v_estoque,
				   v_ult_custo_fiscal, v_ult_custo_medio_fiscal, v_cmv_ult_custo_fiscal, v_cmv_custo_medio_fiscal INTO ret;
			RETURN NEXT ret;
		END IF;

		v_data_ant := v_data_ant + '1 day'::interval;
		v_cmv_ult_custo := 0;
		v_cmv_custo_medio := 0;
		v_cmv_ult_custo_fiscal := 0;
		v_cmv_custo_medio_fiscal := 0;
	END LOOP;
  END;
 
$_$;


ALTER FUNCTION public.estoque_valor_data_tf(bigint, bigint, date, date) OWNER TO postgres;

--
-- Name: exc_amedigital_transacao_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exc_amedigital_transacao_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

		BEGIN
			IF (TG_OP = 'INSERT') THEN
				RAISE NOTICE 'Inserindo pendencia da transaÁ„o Ame Digital %...', NEW.grid;
				INSERT INTO exc_amedigital_transacao_pendencia (transacao, data, hora, payment_id, order_id, order_status, order_message, nsu, nr_cupom, estacao, mlid) VALUES (NEW.grid, NEW.data, NEW.hora, NEW.payment_id, NEW.order_id, NEW.order_status, NEW.order_message, NEW.nsu, NEW.nr_cupom, NEW.estacao, NEW.mlid);
				RETURN NEW;
			ELSIF (TG_OP = 'DELETE') THEN
				RAISE NOTICE 'Apagando pendencia da transaÁ„o Ame Digital %...', OLD.grid;
				DELETE FROM exc_amedigital_transacao_pendencia WHERE transacao = OLD.grid;
				RETURN NULL;
			ELSIF (TG_OP = 'UPDATE') THEN
				RAISE NOTICE 'Atualizando a pendencia da transaÁ„o Ame Digital %...', NEW.grid;
				UPDATE exc_amedigital_transacao_pendencia SET transacao=NEW.grid, data=NEW.data, hora=NEW.hora, payment_id=NEW.payment_id, order_id=NEW.order_id, order_status=NEW.order_status, order_message=NEW.order_message, nsu=NEW.nsu, nr_cupom=NEW.nr_cupom, estacao=NEW.estacao, mlid=NEW.mlid WHERE transacao=NEW.grid;
				RETURN NEW;
			ELSE
				RETURN OLD;
			END IF;
		END;
	
$$;


ALTER FUNCTION public.exc_amedigital_transacao_tgf() OWNER TO postgres;

--
-- Name: exc_ipp_produto_distribuidora_f(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exc_ipp_produto_distribuidora_f(bigint, bigint, bigint) RETURNS TABLE(id bigint, produto_id bigint, codigo text, nome text, nome_resumido text, data_bloq_venda date, negocio integer, bloqueado boolean)
    LANGUAGE plpgsql
    AS $_$

	/*
	Parametros:	
	1-$1 empresa 
	2-$2 produto 
	3-$3 distribuidora
	*/
	BEGIN
		RETURN QUERY SELECT eip.grid AS id, pd.produto AS produto_id, eip.codigo, eip.nome, eip.nome_resumido, eip.data_bloq_venda,
			(CASE WHEN eip.negocio = 'P' THEN 1 WHEN eip.negocio = 'L' THEN 2 WHEN eip.negocio = 'J' THEN 3 END) AS negocio,
			(CASE WHEN eip.data_bloq_venda IS NOT NULL AND eip.data_bloq_venda < now() THEN true ELSE false END) AS bloqueado
		FROM produto_distribuidora pd
			JOIN exc_ipp_produto eip ON (eip.grid = pd.produto_dist)
			JOIN exc_ipp_produto_empresa eipe ON (eipe.produto = eip.grid AND eipe.empresa = $1)
		WHERE pd.produto = $2 AND pd.distribuidora = $3
		ORDER BY eip.data_bloq_venda DESC, pd.grid DESC LIMIT 1;
	END;
	
$_$;


ALTER FUNCTION public.exc_ipp_produto_distribuidora_f(bigint, bigint, bigint) OWNER TO postgres;

--
-- Name: exc_ipp_produto_livre_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exc_ipp_produto_livre_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

	DECLARE
		rel TEXT;
		pk BIGINT;
		ex BOOLEAN;
		emp BIGINT;
		sel BIGINT;
		rec RECORD;
		rec_old RECORD;
	BEGIN
		IF TG_OP = 'DELETE' THEN
			rec := OLD;
			rec_old := rec;
		ELSIF TG_OP = 'UPDATE' THEN
			rec := NEW;
			rec_old := OLD;
		ELSE
			rec := NEW;
			rec_old := rec;
		END IF;

		SELECT grid INTO emp FROM empresa_local LIMIT 1;
	
		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
		IF NOT FOUND THEN
			SELECT seq INTO pk FROM exc_ipp_produto_livre_sync LIMIT 1;
			IF FOUND THEN
				TRUNCATE exc_ipp_produto_livre_sync;
				PERFORM setval('exc_ipp_produto_livre_sync', 1);
			END IF;
			RETURN rec;
		END IF;

		ex := TG_OP = 'DELETE';
		rel := TG_RELNAME;

		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
		IF NOT FOUND THEN
			RETURN rec_old;
		END IF;

		pk := rec.grid;
	
		BEGIN
			INSERT INTO exc_ipp_produto_livre_sync (pkey, excluido) VALUES (pk, ex);

		EXCEPTION WHEN unique_violation THEN
	
			UPDATE exc_ipp_produto_livre_sync SET seq = NEXTVAL('exc_ipp_produto_livre_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
		END;
		
		SELECT pkey INTO sel FROM exchange_sync WHERE pkey = rec.produto AND tabela = 'produto';
		IF NOT FOUND THEN
			INSERT INTO exchange_sync (tabela, pkey) VALUES ('produto', rec.produto);
		ELSE
			UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq') WHERE pkey = rec.produto AND tabela = 'produto';
		END IF;
		
		RETURN rec;
	END;
	
$$;


ALTER FUNCTION public.exc_ipp_produto_livre_sync_tgf() OWNER TO postgres;

--
-- Name: exc_recolha_nota_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exc_recolha_nota_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

		DECLARE
			rel TEXT;
			rel_sync TEXT;
			pk BIGINT;
			ex BOOLEAN;
			rec RECORD;
			rec_old RECORD;
			sel RECORD;
		BEGIN
			IF TG_OP = 'DELETE' THEN
				rec := OLD;
				rec_old := rec;

			ELSIF TG_OP = 'UPDATE' THEN
				rec := NEW;
				rec_old := OLD;

			ELSE
				rec := NEW;
				rec_old := rec;
			END IF;

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = (SELECT grid FROM empresa_local LIMIT 1);
			
			IF NOT FOUND THEN
				SELECT seq INTO pk FROM exc_recolha_nota_config_sync LIMIT 1;

				IF FOUND THEN
					TRUNCATE exc_recolha_nota_config_sync;
					PERFORM setval('exc_recolha_nota_config_sync_seq', 1);
				END IF;
				RETURN rec;
			END IF;

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
			IF NOT FOUND THEN
				RETURN rec_old;
			END IF;

			ex := TG_OP = 'DELETE';
			rel := TG_RELNAME;
			pk := rec.grid;

			IF rel NOT IN ('exc_recolha_nota_config') THEN

				DELETE FROM exc_recolha_nota_config_sync WHERE excluido = true AND ts::date BETWEEN (now() - '300 days'::interval) AND (now() - '30 days'::interval);
			END IF;

			-- Verificar quando tabela exc_recolha_nota_config ou exc_recolha_nota_config_motivo
			IF rel = 'exc_recolha_nota_config' THEN
				rel_sync := 'exc_recolha_nota_config_sync';

				BEGIN
					SELECT pkey INTO sel FROM exc_recolha_nota_config_sync WHERE pkey = pk;

					IF NOT FOUND THEN
						INSERT INTO exc_recolha_nota_config_sync (pkey, excluido) VALUES (pk, ex);
					ELSE
						UPDATE exc_recolha_nota_config_sync SET excluido = ex, seq = NEXTVAL('exc_recolha_nota_config_sync_seq') WHERE pkey = pk;
					END IF;

				EXCEPTION WHEN unique_violation THEN

					UPDATE exc_recolha_nota_config_sync SET seq = NEXTVAL('exc_recolha_nota_config_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;

				END;

			ELSIF rel = 'exc_recolha_nota_config_motivo' THEN
				rel_sync := 'exc_recolha_nota_config_motivo_sync';

				BEGIN
					SELECT pkey INTO sel FROM exc_recolha_nota_config_motivo_sync WHERE pkey = pk;

					IF NOT FOUND THEN
						INSERT INTO exc_recolha_nota_config_motivo_sync (pkey, excluido) VALUES (pk, ex);
					ELSE
						UPDATE exc_recolha_nota_config_motivo_sync SET excluido = ex, seq = NEXTVAL('exc_recolha_nota_config_motivo_sync_seq') WHERE pkey = pk;
					END IF;

				EXCEPTION WHEN unique_violation THEN

					UPDATE exc_recolha_nota_config_motivo_sync SET seq = NEXTVAL('exc_recolha_nota_config_motivo_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
				
				END;

			END IF;

			RETURN rec;
		END;
	
$$;


