--
-- Name: exchange_dl_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_dl_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

		DECLARE
			r RECORD;
			u RECORD;

		BEGIN

			SELECT empresa into r FROM empresa_local;

			IF TG_RELNAME = 'cupom' THEN
				IF NEW.empresa != r.empresa THEN
					return NEW;
				END IF;
			END IF;

			IF TG_RELNAME = 'nota_fiscal_situacao' THEN
				SELECT TRUE AS existe INTO u FROM nota_fiscal_situacao nfs 
				JOIN nota_fiscal nf ON nf.grid = nfs.nota_fiscal WHERE nfs.grid = NEW.grid and nf.empresa = r.empresa;
				
				IF u.existe IS NULL THEN
					RETURN NEW;
				END IF;
			END IF;

			IF TG_RELNAME = 'nota_fiscal' THEN
				SELECT TRUE AS existe INTO u FROM nota_fiscal nf WHERE nf.grid = NEW.grid and nf.empresa = r.empresa;
				
				IF u.existe IS NULL THEN
					RETURN NEW;
				END IF;
			END IF;

			SELECT current_user INTO u;
			IF u.current_user = 'distro' THEN
				RETURN NEW;
			END IF;

			IF TG_OP = 'INSERT' THEN
				INSERT INTO exchange_dl_sync (tabela, pkey) VALUES (TG_RELNAME, NEW.grid);

			ELSEIF TG_OP = 'UPDATE' THEN
				r:= NEW;
				IF TG_RELNAME IN('produto', 'pessoa') THEN
					r.ult_alteracao:= 	OLD.ult_alteracao;
				END IF;

				IF OLD IS DISTINCT FROM r THEN 
					INSERT INTO exchange_dl_sync (tabela, pkey) VALUES (TG_RELNAME, NEW.grid);
				END IF;	
			END IF;	
			RETURN NEW;
		END;	
  
$$;


ALTER FUNCTION public.exchange_dl_tgf() OWNER TO postgres;

