--
-- Name: exchange_emsys_gestao_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_emsys_gestao_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
 	cur_movto REFCURSOR;
 	rec_movto RECORD;
 	reg_exc RECORD;
	reg_movto_pgto RECORD;
	reg_movto_map RECORD;
	reg_pendencia RECORD;
	txt_retorno TEXT;
BEGIN
	IF (TG_OP = 'INSERT') THEN
		reg_exc := NEW;
	ELSE
		RETURN OLD;
	END IF;
	
	IF reg_exc.requisicao = 'venda_registra' THEN
		OPEN cur_movto FOR
			SELECT m.grid
			      ,m.mlid
			      ,m.child 
			  FROM movto m 
			 WHERE m.mlid = reg_exc.mlid;
		LOOP
			FETCH cur_movto INTO rec_movto;
			EXIT WHEN NOT FOUND;

			-- Valida se o motivo È do tipo vale
			SELECT m.grid AS movto
			  INTO reg_movto_pgto
			  FROM movto m 
			  JOIN motivo_movto mm 
			    ON mm.grid = m.motivo 
			   AND mm.tipo_vale IS NOT NULL
			 WHERE m.mlid = rec_movto.mlid;
			
			IF FOUND THEN
				SELECT m.mlid 
				  INTO reg_movto_map
				  FROM movto m 
				  JOIN movto_map mm 
				    ON mm.parent = m.grid 
				 WHERE mm.child = reg_movto_pgto.movto;

				IF FOUND THEN
					-- ApÛs consultar deve atualizar a pendÍncia para n„o ser processada
					SELECT codigo 
					  INTO reg_pendencia
					  FROM exchange_emsys_gestao_pendencia 
					 WHERE mlid = reg_movto_map.mlid 
					   AND requisicao = 'compensacao_registra';

					IF FOUND THEN
						UPDATE exchange_emsys_gestao_pendencia
						   SET situacao = 1
						      ,ts_geracao = reg_exc.ts_geracao - INTERVAL '2' MINUTE
						 WHERE codigo = reg_pendencia.codigo;
						
						RETURN reg_exc;
					END IF;
				END IF;
			END IF;
		END LOOP;
		
		CLOSE cur_movto;
	ELSIF reg_exc.requisicao = 'turno_abre' THEN
		SELECT codigo 
		  INTO reg_pendencia
		  FROM exchange_emsys_gestao_pendencia_historico
		 WHERE True
		   AND requisicao = 'turno_abre'
		   AND data = reg_exc.data
		   AND caixa = reg_exc.caixa
		   AND turno = reg_exc.turno
		   AND empresa = reg_exc.empresa
		 ORDER BY codigo ASC
		 LIMIT 1;
		 
		IF FOUND THEN
			--Faz o insert deste registro na tabela exchange_emsys_gestao_pendencia_historico informando no campo 'retorno' que j· foi enviado este mesmo turno para o emsys
			txt_retorno := 'PendÍncia de cÛdigo "' || reg_pendencia.codigo || '" com caixa, data, turno, empresa j· enviado ao EMSYS GESTAO';
			INSERT INTO exchange_emsys_gestao_pendencia_historico 
				(codigo, empresa, caixa, data, turno, mlid, requisicao, situacao, ts_geracao, ts_envio, conteudo, retorno, nota_fiscal)
			VALUES 
				(reg_exc.codigo, reg_exc.empresa, reg_exc.caixa, reg_exc.data, reg_exc.turno, reg_exc.mlid, reg_exc.requisicao, 2, to_timestamp(to_char(reg_exc.ts_geracao, 'YYYY-MM-DD HH24:MI:SS'), 'YYYY-MM-DD HH24:MI:SS'), to_timestamp(to_char(now(), 'YYYY-MM-DD HH24:MI:SS'), 'YYYY-MM-DD HH24:MI:SS'), reg_exc.conteudo, txt_retorno, reg_exc.nota_fiscal);
			
			RETURN NULL;
		END IF;
	ELSE
		RETURN reg_exc;
	END IF;

	RETURN reg_exc;
END;
  
$$;


ALTER FUNCTION public.exchange_emsys_gestao_pendencia_tgf() OWNER TO postgres;

--
-- Name: exchange_linxpay_qr_transacao_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_linxpay_qr_transacao_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

	DECLARE
		u RECORD;
	
	BEGIN
		SELECT current_user INTO u;
		IF u.current_user = 'distro' THEN
			RAISE NOTICE 'Usu·rio distro n„o pode alterar a tabela exchange_linxpay_qr_transacao_pendencias';
			RETURN NEW;
		END IF;

		IF (TG_OP = 'INSERT') THEN
			RAISE NOTICE 'Inserindo pendencia da transaÁ„o qrlinx %...', NEW.grid;
			INSERT INTO exchange_linxpay_qr_transacao_pendencias (transacao, data, hora, amount, subtotal, add_value, discount_value, payment_id, transaction_id, payment_status, pos_id, order_id, mlid, payment_method, nr_cupom, mensagem, estacao, venda_dict, id_end_to_end) VALUES (NEW.grid, NEW.data, NEW.hora, NEW.amount, NEW.subtotal, NEW.add_value, NEW.discount_value, NEW.payment_id, NEW.transaction_id, NEW.payment_status, NEW.pos_id, NEW.order_id, NEW.mlid, NEW.payment_method, NEW.nr_cupom, NEW.mensagem, NEW.estacao, NEW.venda_dict, NEW.id_end_to_end);
			RETURN NEW;
		ELSIF (TG_OP = 'DELETE') THEN
			RAISE NOTICE 'Apagando pendencia da transaÁ„o qrlinx %...', OLD.grid;
			DELETE FROM exchange_linxpay_qr_transacao_pendencias WHERE transacao = OLD.grid;
			RETURN NULL;
		ELSIF (TG_OP = 'UPDATE') THEN
			RAISE NOTICE 'Atualizando a pendencia da transaÁ„o qrlinx %...', NEW.grid;
			UPDATE exchange_linxpay_qr_transacao_pendencias SET transacao=NEW.grid, data=NEW.data, hora=NEW.hora, amount=NEW.amount, subtotal=NEW.subtotal, add_value=NEW.add_value, discount_value=NEW.discount_value, payment_id=NEW.payment_id, transaction_id=NEW.transaction_id, payment_status=NEW.payment_status, pos_id=NEW.pos_id, order_id=NEW.order_id, mlid=NEW.mlid, movto=NEW.movto, payment_method=NEW.payment_method, nr_cupom=NEW.nr_cupom, mensagem=NEW.mensagem, venda_dict=NEW.venda_dict, id_end_to_end=NEW.id_end_to_end WHERE transacao=NEW.grid;
			RETURN NEW;
		ELSE
			RETURN OLD;
		END IF;
	END; 
  
$$;


ALTER FUNCTION public.exchange_linxpay_qr_transacao_tgf() OWNER TO postgres;

