--
-- Name: exchange_sync_produto_origem_comb_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_sync_produto_origem_comb_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        pk BIGINT;        
        ex BOOLEAN;

        emp BIGINT;

        rec RECORD;
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
        ELSE
            rec := NEW;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;

        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM exchange_sync_produto_origem_comb LIMIT 1;
            IF FOUND THEN
                TRUNCATE exchange_sync_produto_origem_comb;
                PERFORM setval('exchange_sync_produto_origem_comb_seq', 1);
            END IF;
            RETURN rec;
        END IF;

        ex := TG_OP = 'DELETE';

        BEGIN
            INSERT INTO exchange_sync_produto_origem_comb (pkey, excluido) VALUES (rec.grid, ex);

        EXCEPTION WHEN unique_violation THEN

            UPDATE exchange_sync_produto_origem_comb SET seq = NEXTVAL('exchange_sync_produto_origem_comb_seq'), excluido = ex, ts = now() WHERE pkey = rec.grid;
        END;

        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.exchange_sync_produto_origem_comb_tgf() OWNER TO postgres;

--
-- Name: exchange_sync_seq_f(text, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_sync_seq_f(text, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

    DECLARE
      sel bigint;
    BEGIN
      execute format('CREATE or REPLACE temp view exchange_sync_view as SELECT seq FROM %s_sync WHERE seq > %s LIMIT 1', $1, $2);
      SELECT seq into sel FROM exchange_sync_view;
      IF sel IS NOT NULL THEN
        return True;
      ELSE
        return False;
      END IF;
    EXCEPTION WHEN undefined_table THEN
      SELECT seq into sel FROM exchange_sync WHERE tabela = $1 and seq > $2 LIMIT 1;
      IF sel IS NOT NULL THEN
        return True;
      ELSE
        return False;
      END IF;
    END;
  
$_$;


ALTER FUNCTION public.exchange_sync_seq_f(text, bigint) OWNER TO postgres;

--
-- Name: exchange_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

		DECLARE
			rel TEXT;
			pk BIGINT;
			find_rec BOOLEAN;
			ex BOOLEAN;
			rec RECORD;
			rec_old RECORD;
			sel RECORD;
			sub RECORD;
			slc RECORD;
			tab_orig TEXT;
		BEGIN
			IF TG_OP = 'DELETE' THEN
				rec := OLD;
				rec_old := rec;
			ELSIF TG_OP = 'UPDATE' THEN
				rec := NEW;
				rec_old := OLD;
			ELSE
				rec := NEW;
				rec_old := rec;
			END IF;

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND valor ilike 'TRUE' AND empresa = (SELECT grid FROM empresa_local LIMIT 1);
			IF NOT FOUND THEN
				SELECT seq INTO pk FROM exchange_sync LIMIT 1;
				IF FOUND THEN
					TRUNCATE exchange_sync;
					PERFORM setval('exchange_sync_seq', 1);
				END IF;
				RETURN rec;
			END IF;

			tab_orig := TG_RELNAME;
			rel := TG_RELNAME;
			ex := TG_OP = 'DELETE';

			SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
			IF NOT FOUND THEN
				RETURN rec_old;
			END IF;

			IF rel = 'bico_bomba' THEN
				pk := rec.bico::BIGINT;
			ELSIF rel in ('lancto', 'exchange_emsys_gestao_produto_empresa') THEN
				ex := FALSE;
				pk := rec.produto;
			ELSIF rel IN ('tef_bandeira', 'tef_operadora', 'tef_tipo_transacao', 'brpremmia_webservice', 'grupo_combustivel') THEN
				pk := rec.codigo;
			ELSIF rel IN ('caixa_conf_deposito', 'exc_jetoil_marca', 'exc_jetoil_modelo', 'exc_jetoil_modelo_tipo', 'exc_jetoil_motor', 
						'exc_jetoil_check_point', 'exc_jetoil_check_point_status', 'exc_jetoil_check_point_itens',
						'exc_jetoil_check_point_grupo_produto_map', 'caixa_conf_cancela_pista', 'regra_preco_condicao') THEN
				pk := rec.id;
			ELSIF rel in ('tef_credenciadora', 'tef_credenciadora_config', 'combustivel_ad_rem') THEN
				pk := rec.codigo::INT8;
			ELSIF rel = 'ncm_estado' THEN
				pk := rec.codigo::INT8;
			ELSIF rel IN ('regra_preco', 'tabela_preco_produto') THEN
				pk := rec.tabela_preco;
			ELSIF rel IN ('exc_rv_produto', 'exc_rv_operadora', 'exc_rv_produto_abrangencia', 'exc_rv_operadora_estado', 'produto_deposito_grupo') THEN
				pk := rec.id;
			ELSIF rel in ('exc_ipp_cartao_presente') THEN
				pk := rec.id;
			ELSE
				pk := rec.grid;
			END IF;

			IF rel = 'empresa_conta' THEN
				IF NOT ex THEN
					RETURN rec;
				END IF;
				SELECT grid INTO pk FROM caixa_conf WHERE conta = rec.conta;
				IF NOT FOUND THEN
					RETURN rec_old;
				END IF;
				rel := 'caixa_conf';
			ELSIF rel = 'caixa_conf' THEN
				IF TG_OP = 'INSERT' AND NEW.deposito IS NOT NULL THEN
					SELECT id INTO sub FROM caixa_conf_deposito WHERE caixa_conf = NEW.grid AND deposito = NEW.deposito;
					IF NOT FOUND THEN
						INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (NEW.grid, NEW.deposito);
					END IF;
				ELSIF TG_OP = 'UPDATE'THEN
					IF OLD.deposito != NEW.deposito THEN
						IF OLD.deposito IS NOT NULL AND NEW.deposito IS NOT NULL THEN						
							SELECT id INTO sub FROM caixa_conf_deposito WHERE caixa_conf = OLD.grid AND deposito = OLD.deposito;
							IF NOT FOUND THEN
								INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (NEW.grid, NEW.deposito);
							ELSE						
								UPDATE caixa_conf_deposito SET deposito = NEW.deposito WHERE caixa_conf = OLD.grid AND deposito = OLD.deposito;
							END IF;							
						ELSIF OLD.deposito IS NOT NULL THEN
							DELETE FROM caixa_conf_deposito WHERE caixa_conf = OLD.grid AND deposito = OLD.deposito;
						ELSIF NEW.deposito IS NOT NULL THEN
							SELECT id INTO sub FROM caixa_conf_deposito WHERE caixa_conf = NEW.grid AND deposito = NEW.deposito;
							IF NOT FOUND THEN
								INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (NEW.grid, NEW.deposito);
							END IF;
						END IF;
					ELSIF NEW.deposito IS NOT NULL THEN
						SELECT id INTO sub FROM caixa_conf_deposito WHERE caixa_conf = NEW.grid AND deposito = NEW.deposito;
						IF NOT FOUND THEN
							INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (NEW.grid, NEW.deposito);
						END IF;					
					END IF;
				ELSIF TG_OP = 'DELETE' THEN
					DELETE FROM caixa_conf_deposito WHERE caixa_conf = OLD.grid;
				END IF;
				IF NEW.nivel_preco IS NOT NULL THEN
					FOR sub in SELECT grid, preco_unit_b FROM exchange_emsys_gestao_produto_empresa LOOP
						UPDATE exchange_emsys_gestao_produto_empresa set preco_unit_b = preco_unit_b where grid = sub.grid;
					END LOOP;
				END IF;
			ELSIF rel = 'caixa_conf_bico' THEN
				IF TG_OP = 'INSERT' THEN
					SELECT cc.grid, b.deposito INTO sub FROM caixa_conf cc JOIN empresa_conta ec ON (ec.conta = cc.conta) JOIN bico b ON (b.empresa = ec.empresa) WHERE cc.conta = NEW.conta AND b.nome = NEW.bico;
					IF FOUND THEN
						SELECT id INTO sel FROM caixa_conf_deposito WHERE caixa_conf = sub.grid AND deposito = sub.deposito;
						IF NOT FOUND THEN
							INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (sub.grid, sub.deposito);
						END IF;
					END IF;
				ELSIF TG_OP = 'UPDATE' THEN
					SELECT cc.grid, b.deposito INTO sub FROM caixa_conf cc JOIN empresa_conta ec ON (ec.conta = cc.conta) JOIN bico b ON (b.empresa = ec.empresa) WHERE cc.conta = OLD.conta AND b.nome = OLD.bico;
					IF FOUND THEN
