						IF NOT FOUND THEN
							DELETE FROM caixa_conf_deposito WHERE caixa_conf = sub.grid AND deposito = sub.deposito;
						END IF;
					END IF;
					SELECT cc.grid, b.deposito INTO sub FROM caixa_conf cc JOIN empresa_conta ec ON (ec.conta = cc.conta) JOIN bico b ON (b.empresa = ec.empresa) WHERE cc.conta = NEW.conta AND b.nome = NEW.bico;
