						IF NOT FOUND THEN
							INSERT INTO caixa_conf_deposito(caixa_conf, deposito) VALUES (sub.grid, sub.deposito);
						END IF;
					END IF;
				ELSIF TG_OP = 'DELETE' THEN
					SELECT cc.grid, b.deposito INTO sub FROM caixa_conf cc JOIN empresa_conta ec ON (ec.conta = cc.conta) JOIN bico b ON (b.empresa = ec.empresa) WHERE cc.conta = OLD.conta AND b.nome = OLD.bico;
					IF FOUND THEN
