				FOR sub IN SELECT p.grid FROM produto p JOIN produto_distribuidora pd ON (pd.produto=p.grid and pd.distribuidora=1) WHERE pd.produto_dist=rec.grid LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'produto';
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey) VALUES ('produto', sub.grid);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq') WHERE pkey = sub.grid AND tabela = 'produto';
					END IF;
				END LOOP;
				FOR sub IN SELECT pe.grid FROM produto_empresa pe JOIN produto p ON (p.grid=pe.produto) JOIN produto_distribuidora pd ON (pd.produto=p.grid and pd.distribuidora=1) where pd.produto_dist=rec.grid LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'produto_empresa';
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey) VALUES ('produto_empresa', sub.grid);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq') WHERE pkey = sub.grid AND tabela = 'produto_empresa';
					END IF;
				END LOOP;
			ELSIF rel = 'brpremmia_webservice' THEN
				FOR sub IN SELECT grid FROM exc_br_config LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'exc_br_config';
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey, excluido) VALUES ('exc_br_config', sub.grid, FALSE);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = FALSE WHERE pkey = sub.grid AND tabela = 'exc_br_config';
					END IF;
				END LOOP;
			ELSIF rel = 'codigo_beneficio_fiscal' THEN
				FOR sub IN SELECT p.grid FROM produto p WHERE REPLACE(p.codigo_ncm, '.', '') = REPLACE(rec.ncm, '.', '') LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'produto';
					IF NOT FOUND THEN
