					END IF;
				END LOOP;

				RETURN rec;
			ELSIF rel = 'classificacao_pgto' THEN
				FOR sub in SELECT mm.grid FROM motivo_movto mm JOIN classificacao_pgto cp ON (cp.grid = mm.classificacao_pgto AND cp.tipo_pgto = rec.tipo_pgto) LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'motivo_movto';
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey, excluido) VALUEs ('motivo_movto', sub.grid, FALSE);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = FALSE WHERE pkey = sub.grid AND tabela = 'motivo_movto';
