			ELSIF rel = 'rel_ecf_confere_estoque_deposito' THEN
				SELECT pkey INTO sel FROM exchange_sync WHERE pkey = rec.rel_ecf_confere_estoque AND tabela = 'relatorio_confere_estoque';
				IF NOT FOUND THEN
					INSERT INTO exchange_sync (tabela, pkey, excluido) VALUEs ('relatorio_confere_estoque', rec.rel_ecf_confere_estoque::BIGINT, FALSE);
				ELSE
					UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = FALSE WHERE pkey = rec.rel_ecf_confere_estoque AND tabela = 'relatorio_confere_estoque';
				END IF;

				RETURN rec;
			ELSIF rel = 'regra_preco' THEN
				ex := FALSE;
				IF TG_OP = 'DELETE' THEN
					ex := TRUE;
					FOR sub in select id from regra_preco_condicao where regra_preco = rec.grid LOOP
						DELETE FROM regra_preco_condicao WHERE id = sub.id;
						SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.id AND tabela = 'regra_preco_condicao';
					END LOOP;
				ELSIF TG_OP = 'INSERT' THEN

					IF (rec.empresa = (SELECT empresa FROM empresa_local)) OR rec.empresa is null THEN

						INSERT INTO regra_preco_condicao (codigo, empresa, regra_preco_id, motivo_movto_id, data_fim, data_inicio, regra_preco, cliente_id, grupo_pessoa_id, produto_id, grupo_produto_id, valor, tipo, sobre, acao, aplicar, flag_cliente, operacao, emsys, tabela_preco_produto) 
							select	rec.codigo, rec.empresa, tpp.tabela_preco, 
									rec.forma_pgto, rec.data_fim, rec.data_ini, rec.grid, 
									rec.pessoa, rec.grupo_pessoa, tpp.produto, tpp.grupo_produto,
									(CASE WHEN tpp.tipo = '%' THEN (CASE WHEN tpp.acao = 'A' THEN ABS(tpp.valor) ELSE valor * -1 END)
										WHEN tpp.acao = 'D' THEN (CASE 
										WHEN tpp.tipo = 'D' THEN ABS(tpp.valor)
										WHEN tpp.tipo = 'A' THEN ABS(tpp.valor) * -1 ELSE tpp.valor END)
										ELSE tpp.valor END) AS valor,
									(CASE WHEN tpp.tipo IN ('A', 'D') THEN 'V' WHEN tpp.tipo = 'F' THEN 'F' ELSE 'P' END) AS tipo, REPLACE(tpp.sobre, 'B', 'V') AS sobre, tpp.acao, 
									(CASE WHEN tpp.acao = 'D' THEN 'P' WHEN tpp.tipo = 'A' OR (tpp.tipo = '%' AND tpp.valor > 0)
										OR (tpp.tipo = 'F' AND tpp.valor > preco_unit_empresa_f(tpp.produto, rec.empresa)) THEN 'A' ELSE 'D' END) AS aplicar, 
									(CASE WHEN rec.pessoa IS NULL AND rec.grupo_pessoa IS NULL THEN 1 ELSE 0 END) AS flag_cliente,
									rec.operacao, rec.emsys, tpp.grid
							FROM 
								tabela_preco_produto tpp
							JOIN 
								regra_preco rp ON (tpp.tabela_preco = rp.tabela_preco)
							WHERE 
								rp.grid = rec.grid
								AND rp.tabela_preco IS NOT NULL
								AND tpp.tipo IS NOT NULL
								AND tpp.tipo != ''
								AND tpp.sobre IS NOT NULL
								AND tpp.sobre != ''
								AND tpp.valor IS NOT NULL
								AND rp.operacao = 'V';
					END IF;

				ELSIF TG_OP = 'UPDATE' THEN

					IF (rec.empresa = (SELECT empresa FROM empresa_local)) OR rec.empresa is null THEN

						SELECT id INTO sel FROM regra_preco_condicao WHERE regra_preco = rec.grid;
						IF NOT FOUND THEN
							INSERT INTO regra_preco_condicao (codigo, empresa, regra_preco_id, motivo_movto_id, data_fim, data_inicio, regra_preco, cliente_id, grupo_pessoa_id, produto_id, grupo_produto_id, valor, tipo, sobre, acao, aplicar, flag_cliente, operacao, emsys, tabela_preco_produto) 
								select 	rec.codigo, rec.empresa, tpp.tabela_preco, rec.forma_pgto, rec.data_fim, rec.data_ini, 
										rec.grid, rec.pessoa, rec.grupo_pessoa, tpp.produto, tpp.grupo_produto,
										(CASE WHEN tpp.tipo = '%' THEN (CASE WHEN tpp.acao = 'A' THEN ABS(tpp.valor) ELSE tpp.valor * -1 END)
											WHEN tpp.acao = 'D' THEN (CASE 
											WHEN tpp.tipo = 'D' THEN ABS(tpp.valor)
											WHEN tpp.tipo = 'A' THEN ABS(tpp.valor) * -1 ELSE tpp.valor END)
											ELSE tpp.valor END) AS valor,
										(CASE WHEN tpp.tipo IN ('A', 'D') THEN 'V' WHEN tpp.tipo = 'F' THEN 'F' ELSE 'P' END) AS tipo, tpp.sobre, tpp.acao, 
										(CASE WHEN tpp.acao = 'D' THEN 'P' WHEN tpp.tipo = 'A' OR (tpp.tipo = '%' AND tpp.valor > 0)
											OR (tpp.tipo = 'F' AND tpp.valor > preco_unit_empresa_f(tpp.produto, rec.empresa)) THEN 'A' ELSE 'D' END) AS aplicar, 
										(CASE WHEN rec.pessoa IS NULL AND rec.grupo_pessoa IS NULL THEN 1 ELSE 0 END) AS flag_cliente,
										rec.operacao, rec.emsys, tpp.grid
								FROM 
									tabela_preco_produto tpp
								JOIN 
									regra_preco rp ON (tpp.tabela_preco = rp.tabela_preco)
								where 
									rp.grid = rec.grid
									AND rp.tabela_preco IS NOT NULL
									AND tpp.tipo IS NOT NULL
									AND tpp.tipo != ''
									AND tpp.sobre IS NOT NULL
									AND tpp.sobre != ''
									AND tpp.valor IS NOT NULL
									AND rp.operacao = 'V';
						ELSIF (SELECT COUNT(*) 
								FROM 
									tabela_preco_produto tpp
								JOIN 
									regra_preco rp ON (tpp.tabela_preco = rp.tabela_preco)
								where 
									rp.grid = rec.grid
									AND rp.tabela_preco IS NOT NULL
									AND tpp.tipo IS NOT NULL
									AND tpp.tipo != ''
									AND tpp.sobre IS NOT NULL
									AND tpp.sobre != ''
									AND tpp.valor IS NOT NULL
									AND rp.operacao = 'V') > 0 THEN

								UPDATE regra_preco_condicao set empresa = rec.empresa, codigo = rec.codigo, regra_preco_id = rec.tabela_preco, 
									motivo_movto_id = rec.forma_pgto, data_fim = rec.data_fim, operacao = rec.operacao, emsys = rec.emsys,
									data_inicio = rec.data_ini, cliente_id = NEW.pessoa, grupo_pessoa_id = NEW.grupo_pessoa,
									flag_cliente = (CASE WHEN rec.pessoa IS NULL AND rec.grupo_pessoa IS NULL THEN 1 ELSE 0 END)
									WHERE regra_preco = rec.grid;
						ELSE
							DELETE FROM regra_preco_condicao WHERE regra_preco = rec.grid;
						END IF;
					ELSE
						DELETE FROM regra_preco_condicao WHERE regra_preco = rec.grid;
					END IF;
				END IF;
			ELSIF rel = 'produto_deposito' THEN
				IF TG_OP = 'INSERT' THEN
					SELECT id INTO sub FROM produto_deposito_grupo WHERE produto = NEW.produto AND deposito = NEW.deposito;
					IF NOT FOUND THEN
						INSERT INTO produto_deposito_grupo(produto, deposito, est_minimo, est_padrao, est_maximo, movimenta) VALUES (NEW.produto, NEW.deposito, NEW.est_minimo, NEW.est_padrao, NEW.est_maximo, NEW.movimenta);
					ELSE
						UPDATE produto_deposito_grupo SET produto = NEW.produto, deposito = NEW.deposito, est_minimo = NEW.est_minimo, est_padrao = NEW.est_padrao, est_maximo = NEW.est_maximo, movimenta = NEW.movimenta WHERE id = sub.id;
					END IF;
				ELSIF TG_OP = 'UPDATE' THEN
					SELECT id INTO sub FROM produto_deposito_grupo WHERE produto = NEW.produto AND deposito = NEW.deposito;
					IF NOT FOUND THEN
						INSERT INTO produto_deposito_grupo(produto, deposito, est_minimo, est_padrao, est_maximo, movimenta) VALUES (NEW.produto, NEW.deposito, NEW.est_minimo, NEW.est_padrao, NEW.est_maximo, NEW.movimenta);
					ELSE
						UPDATE produto_deposito_grupo SET produto = NEW.produto, deposito = NEW.deposito, est_minimo = NEW.est_minimo, est_padrao = NEW.est_padrao, est_maximo = NEW.est_maximo, movimenta = NEW.movimenta WHERE id = sub.id;
					END IF;
				ELSIF TG_OP = 'DELETE' THEN
					SELECT id INTO sub FROM produto_deposito_grupo WHERE produto = OLD.produto AND deposito = OLD.deposito;
					IF FOUND THEN
						UPDATE produto_deposito_grupo SET produto = OLD.produto, deposito = OLD.deposito, est_minimo = NULL, est_padrao = NULL, est_maximo = NULL, movimenta=TRUE WHERE id = sub.id;
					END IF;
				END IF;
			ELSIF rel = 'deposito_grupo_produto' THEN

				IF TG_OP in ('INSERT', 'UPDATE') THEN
					FOR sel in SELECT grid FROM produto where grupo = NEW.grupo LOOP
						SELECT est_minimo, est_padrao, est_maximo, coalesce(movimenta, true) AS movimenta INTO sub from produto_deposito where deposito = NEW.deposito and produto = sel.grid;
						SELECT * INTO slc from produto_deposito_grupo where deposito = NEW.deposito and produto = sel.grid;
						IF slc.id IS NOT NULL THEN
							UPDATE produto_deposito_grupo SET produto = sel.grid, deposito = NEW.deposito, est_minimo = sub.est_minimo, est_padrao = sub.est_padrao, est_maximo = sub.est_maximo, movimenta = TRUE where id = slc.id;
						ELSE
							INSERT INTO produto_deposito_grupo (produto, deposito, est_minimo, est_padrao, est_maximo, movimenta) values (sel.grid, NEW.deposito, sub.est_minimo, sub.est_padrao, sub.est_maximo, coalesce(sub.movimenta, True));
						END IF;
					END LOOP;
				ELSIF TG_OP = 'DELETE' THEN
					FOR sel in SELECT grid FROM produto where grupo = OLD.grupo LOOP
						SELECT id INTO sel FROM produto_deposito_grupo where produto = sel.grid AND deposito = OLD.deposito;
							IF FOUND THEN
								DELETE FROM produto_deposito_grupo WHERE id= sel.id;
							END IF;
					END LOOP;
				END IF;

			ELSIF rel = 'tabela_preco_produto' THEN
				IF TG_OP = 'DELETE' THEN
					ex = True;
					FOR sub in select id from regra_preco_condicao where regra_preco_id = rec.tabela_preco and ((produto_id=rec.produto or grupo_produto_id=rec.grupo_produto) or (produto_id is null and grupo_produto_id is null)) LOOP
						DELETE FROM regra_preco_condicao where id=sub.id;
					END LOOP;
				ELSE
					SELECT * INTO slc from regra_preco_condicao WHERE tabela_preco_produto = rec.grid;
					IF NOT FOUND THEN
						INSERT INTO regra_preco_condicao (codigo, empresa, regra_preco_id, motivo_movto_id, data_fim, data_inicio, regra_preco, cliente_id, grupo_pessoa_id, produto_id, 
								grupo_produto_id, valor, tipo, aplicar, flag_cliente, sobre, acao, operacao, emsys, tabela_preco_produto)
							select 	rp.codigo, rp.empresa, rec.tabela_preco, rp.forma_pgto, rp.data_fim, rp.data_ini, 
									rp.grid, rp.pessoa, rp.grupo_pessoa, rec.produto, rec.grupo_produto, 
									(CASE 
										WHEN rec.tipo = '%' THEN (CASE WHEN rec.acao = 'A' THEN ABS(rec.valor) ELSE rec.valor * -1 END)
										WHEN rec.acao = 'D' THEN (CASE
											WHEN rec.tipo = 'D' THEN ABS(rec.valor)
											WHEN rec.tipo = 'A' THEN ABS(rec.valor) * -1 ELSE rec.valor END)
										ELSE rec.valor END) AS valor, 
									(CASE WHEN rec.tipo IN ('A', 'D') THEN 'V' WHEN rec.tipo = 'F' THEN 'F' ELSE 'P' END) AS tipo,
									(CASE WHEN rec.acao = 'D' THEN 'P' WHEN rec.tipo = 'A' OR (rec.tipo = '%' AND rec.valor > 0) 
										OR (rec.tipo = 'F' AND rec.valor > preco_unit_empresa_f(rec.produto, rp.empresa)) THEN 'A' ELSE 'D' END) AS aplicar, 
									(CASE WHEN rp.pessoa IS NULL AND rp.grupo_pessoa IS NULL THEN 1 ELSE 0 END) AS flag_cliente,
									REPLACE(rec.sobre, 'B', 'V') AS sobre, rec.acao, rp.operacao, rp.emsys, rec.grid
							FROM 
								regra_preco rp
							JOIN
								tabela_preco_produto tpp ON (rp.tabela_preco = tpp.tabela_preco)
							where 
								tpp.grid = rec.grid
								AND ((empresa = (SELECT empresa FROM empresa_local)) OR empresa is null)
								AND rp.tabela_preco IS NOT NULL
								AND tpp.tipo IS NOT NULL
								AND tpp.tipo != ''
								AND tpp.sobre IS NOT NULL
								AND tpp.sobre != ''
								AND tpp.valor IS NOT NULL
								AND rp.operacao = 'V';

						ex = False;

					ELSIF (SELECT COUNT(*) 
							FROM 
								tabela_preco_produto tpp
							JOIN 
								regra_preco rp ON (tpp.tabela_preco = rp.tabela_preco)
							where 
								tpp.grid = rec.grid
								AND rp.tabela_preco IS NOT NULL
								AND tpp.tipo IS NOT NULL
								AND tpp.tipo != ''
								AND tpp.sobre IS NOT NULL
								AND tpp.sobre != ''
								AND tpp.valor IS NOT NULL
								AND rp.operacao = 'V') > 0 THEN
									
						UPDATE regra_preco_condicao set regra_preco_id = rec.tabela_preco, produto_id = rec.produto, grupo_produto_id = rec.grupo_produto, sobre = REPLACE(rec.sobre, 'B', 'V'), acao = rec.acao,
							valor = (CASE 
								WHEN rec.tipo = '%' THEN (CASE WHEN rec.acao = 'A' THEN ABS(rec.valor) ELSE rec.valor * -1 END)
								WHEN rec.acao = 'D' THEN (CASE WHEN rec.tipo = 'D' THEN ABS(rec.valor) WHEN rec.tipo = 'A' THEN ABS(rec.valor) * -1 ELSE rec.valor END)
								ELSE rec.valor END), 
							tipo = (CASE WHEN rec.tipo IN ('A', 'D') THEN 'V' WHEN rec.tipo = 'F' THEN 'F' ELSE 'P' END), 
							aplicar = (CASE WHEN rec.acao = 'D' THEN 'P' WHEN rec.tipo = 'A' OR (rec.tipo = '%' AND rec.valor > 0) OR (rec.tipo = 'F' AND rec.valor > preco_unit_empresa_f(rec.produto, empresa)) THEN 'A' ELSE 'D' END)
							WHERE tabela_preco_produto=rec.grid;
						
						ex = False;
					ELSE
						DELETE FROM regra_preco_condicao WHERE tabela_preco_produto = rec.grid;

						ex = False;
					END IF;
				END IF;
			ELSIF rel = 'grupo_credito' THEN
				FOR sel in select id from grupo_credito gc join regra_preco rp on rp.grupo_credito = gc.grid join regra_preco_condicao rpc on rpc.regra_preco = rp.grid
					where gc.grid = rec.grid LOOP
					UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = ex, ts = now() WHERE pkey = sel.id AND tabela = 'regra_preco_condicao';
				END LOOP;
			ELSIF rel = 'reajuste_preco' THEN
				IF rec.situacao = 900 OR rec.situacao = 100 OR rec.local NOT IN (2, 4) THEN
					ex := TRUE;
				END IF;

				IF TG_OP in ('DELETE', 'UPDATE') THEN
					FOR sub IN SELECT grid FROM reajuste_preco_produto WHERE reajuste_preco = rec.grid LOOP
						SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'reajuste_preco_produto';
