				ELSE
					UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = ex WHERE pkey = sel.pkey AND tabela = 'bico_set_preco_programado';
				END IF;

				RETURN rec;

			ELSIF rel = 'tef_cartao_combustivel' THEN
				rel := 'tef_produto';
			ELSIF rel = 'tef_credenciadora_config' THEN
				rel := 'tef_credenciadora';			
			ELSIF rel = 'exchange_emsys_gestao_produto_empresa' THEN
				rel := 'produto';
			ELSIF rel = 'comanda_coletora' THEN
				rel := 'equipamento';
				ex:= FALSE;	
				pk := rec.equipamento;
			ELSIF rel in('motivo_movto', 'motivo_movto_empresa') THEN
				pk := rec.grid;

				IF rel = 'motivo_movto_empresa' THEN
					pk := rec.motivo;
					ex:= FALSE;
				ELSE
					IF rec.flag IN ('I', 'D') THEN
						ex:= TRUE;
					END IF;
				END IF;

				rel := 'motivo_movto';

				SELECT True INTO sel FROM motivo_movto WHERE grid=pk;
				IF NOT found or ex THEN
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = pk AND tabela = rel;
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey, excluido) VALUES (rel, pk, True);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = True, ts = now() WHERE pkey = pk AND tabela = rel;
					END IF;
				ELSE
					SELECT True INTO sel FROM motivo_movto WHERE controle_empresa and grid=pk;
					IF NOT FOUND THEN
						SELECT pkey INTO sel FROM exchange_sync WHERE pkey = pk AND tabela = rel;
						IF NOT FOUND THEN
							INSERT INTO exchange_sync (tabela, pkey, excluido) VALUES (rel, pk, ex);
						ELSE
							UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk AND tabela = rel;
						END IF;
					ELSE
						SELECT True INTO sel FROM motivo_movto_empresa WHERE motivo=pk AND empresa = (SELECT grid FROM empresa_local LIMIT 1);
						IF NOT FOUND THEN
							SELECT pkey INTO sel FROM exchange_sync WHERE pkey = pk AND tabela = rel;
