				RETURN rec;
			ELSIF rel = 'combustivel_ad_rem' THEN
				FOR sub IN 
					SELECT p.grid FROM combustivel_ad_rem cad
					INNER JOIN tipo_combustivel tc ON (cad.codigo_anp = tc.codigo_anp)
					INNER JOIN produto p ON (tc.codigo = p.tipo_combustivel)
					WHERE cad.codigo = rec.codigo
				LOOP
					SELECT pkey INTO sel FROM exchange_sync WHERE pkey = sub.grid AND tabela = 'produto';
					IF NOT FOUND THEN
						INSERT INTO exchange_sync (tabela, pkey, excluido) VALUES ('produto', sub.grid, FALSE);
					ELSE
						UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = FALSE WHERE pkey = sub.grid AND tabela = 'produto';
					END IF;
				END LOOP;
				RETURN rec;
			ELSIF rel in ('moeda', 'moeda_cotacao_empresa') THEN

				if rel = 'moeda_cotacao_empresa' then
					pk := rec.moeda;
				ELSE
					pk := rec.grid;
				END IF;

				rel := 'moeda';

			ELSIF rel = 'equipamento' THEN
				IF TG_OP = 'UPDATE' THEN
					ex := NEW.flag != 'A';
				END IF;

			END IF;

			SELECT pkey INTO sel FROM exchange_sync WHERE pkey = pk AND tabela = rel;

			IF NOT FOUND THEN
				INSERT INTO exchange_sync (tabela, pkey, excluido) VALUES (rel, pk, ex);
			ELSE
				UPDATE exchange_sync SET seq = NEXTVAL('exchange_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk AND tabela = rel;
			END IF;

			RETURN rec;
		END;
	
$$;


ALTER FUNCTION public.exchange_sync_tgf() OWNER TO postgres;

--
-- Name: exchange_terc_f(text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.exchange_terc_f(text, text, text) RETURNS text
    LANGUAGE plpgsql
    AS $_$
declare r record;

begin
	if upper($2) = 'CONTA' then
		select codigo into r from exchange_terc_movto_map where conta = $1 and modulo = $3;

	end if;

	if upper($2) = 'MOTIVO' then
		select codigo into r from exchange_terc_movto_map where motivo = $1::int8 and modulo = $3;

	end if;

	if upper($2) = 'EMPRESA' then
		select codigo into r from exchange_terc_movto_map where empresa = $1::int8 and modulo = $3;

	end if;

	if upper($2) = 'PESSOA' then
		select codigo into r from exchange_terc_movto_map where pessoa = $1::int8 and modulo = $3;

	end if;
	
	if upper($2) = 'IMPRESSORA' then
		select codigo into r from exchange_terc_movto_map where impressora = $1::int8 and modulo = $3;

	end if;
	
	if upper($2) = 'CFOP' then
		select codigo into r from exchange_terc_movto_map where cfop = $1::text and modulo = $3;
	end if;
	
	if upper($2) = 'CENTROCUSTO' then
		select codigo into r from exchange_terc_movto_map where centro_custo = $1::int8 and modulo = $3;
	end if;
	
	if not found then
		return Null;
	else
		return r.codigo;
	end if;

end;
$_$;


ALTER FUNCTION public.exchange_terc_f(text, text, text) OWNER TO postgres;

--
-- Name: fatura_desconto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.fatura_desconto_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare 
    rfat record;
	rnota record;
	rdesc record;
	rmulta record;
	vl_parcial double precision;
begin
	select mi.info::float as desconto into rdesc from movto_info mi where mi.movto=$1 and mi.tipo='desconto';
	if found then
		return rdesc.desconto;
	end if;

	if found then
		return rdesc.valor;
	else
		select distinct 
			m.valor as valor into rdesc 
		from 
			movto m 
		   	join movto_map mm on (mm.child = m.grid and mm.child != $1)
		   	join movto_map mm2 on (mm.parent = mm2.parent and mm2.child = $1)
		where 
			m.motivo = (select motivo from motivo_config where chave = 'DESCONTO_FATURA');
		
		if found then
			return rdesc.valor;
		end if;
		
	end if;

	if found then
		return rdesc.valor;
	end if;
	
	select valor into rfat from movto where grid = $1;
	select sum(m.valor) as valor into rnota from movto m join movto_map mm on (mm.parent = m.grid and mm.child = $1)
    where  m.motivo not in (select motivo from motivo_config where chave in ('JUROS', 'VENDA'));	
	
	select distinct 
		m.valor as valor into rdesc
	from 
		movto m 
		   join movto_map mm on (mm.child = m.grid and mm.child != $1)
		   join movto_map mm2 on (mm.parent = mm2.parent and mm2.child = $1);

	if not found then
		rdesc.valor := 0;
	end if;

	select sum(valor) as valor into rmulta from movto m join movto_map mm on(m.grid=mm.parent and mm.child=$1) where
	m.motivo = (select motivo from motivo_config where chave='MULTA');

	if (not found or rmulta.valor is null) then
		rmulta.valor := 0;
	end if;

	select valor into vl_parcial from movto m join grid_map gm on (m.grid = gm.child and gm.parent = $1);	
	if not found then
		vl_parcial := 0;
	end if;

	return coalesce(round((rnota.valor-rfat.valor-rdesc.valor+rmulta.valor-vl_parcial)::numeric,2), 0);

end;   
$_$;


ALTER FUNCTION public.fatura_desconto_f(bigint) OWNER TO postgres;

--
-- Name: faturamento_troco_dinheiro_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.faturamento_troco_dinheiro_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare 
     	rfat record;
     	rpgto record;
     	rtroco record;
     	troco double precision;
     	rjuros record;
begin
	select m.grid into rfat from movto m join motivo_movto mm on (m.motivo = mm.grid and mm.tipo_movto = 5) join movto_map mv on (m.grid = mv.child and mv.parent = $1);
	
	if found then
		return 0;
	end if;
	
	select mm.grid into rfat from movto m join motivo_movto mm on (m.motivo = mm.grid and mm.tipo_movto in (9,10,11)) where m.grid = $1;
	
	if found then
		return 0;
	end if;
	
	select valor into rfat from movto where grid = $1;
	
	select sum(m.valor) as valor into rpgto from movto m join motivo_movto mm on (mm.grid = m.motivo) where m.grid in (select child from movto_map where parent = $1) and mm.forma_baixa and not mm.troco;
	
	if rpgto.valor is null then 	
		select sum(m.valor) as valor into rpgto from movto m join motivo_movto mm on (mm.grid = m.motivo) where m.grid in (select child from movto where grid = $1);
		if rpgto.valor is null then
			return 0;
		end if;
	end if;	
		
	select sum(m.valor) as valor into rtroco from movto m join motivo_movto mm on (mm.grid = m.motivo) where m.grid in (select child from movto_map where parent = (select child from movto where grid = $1)) and mm.forma_baixa and mm.troco;	
	
	if rtroco.valor is null then
		rtroco.valor := 0;
	end if;
	
	 select sum(valor) as valor into rjuros from movto where grid in (select parent from movto_map where child in (select child from movto_map where parent = $1)) and grid <> $1;
	 
	 if rjuros.valor is null then
	 	rjuros.valor := 0;
	 end if;
	
	troco := rpgto.valor-rfat.valor-rtroco.valor-rjuros.valor;
	
	if troco > 0 then
		return troco;
	else
		return 0;
	end if;
end;   
$_$;


ALTER FUNCTION public.faturamento_troco_dinheiro_f(bigint) OWNER TO postgres;

