CREATE FUNCTION public.forma_pgto_mlid_f(bigint) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

begin

	if (($1 is null) or ($1 = 0::bigint)) then

		return null;

	end if;



	select mm.grid into r from movto m join motivo_movto mm on (m.motivo=mm.grid) where

		m.mlid=$1 and mm.forma_pgto = true order by m.valor desc limit 1;

	

	if found then

		return r.grid;

	end if;



	return null;

end;
$_$;


