--
-- Name: forma_pgto_principal_troca_valor_pgto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.forma_pgto_principal_troca_valor_pgto_f(bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare c refcursor;
        r record;
		ret text;
begin
	if (($1 is null) or ($1 = 0::bigint)) then
		return null;
	end if;

	open c for select mm.nome from movto m join motivo_movto mm on (m.motivo = mm.grid) where
		m.mlid = $1 and mm.troco = true order by m.valor desc limit 2;

	fetch c into r;

	ret := 'TROCO EM DINHEIRO';
	
	if found then
		ret := r.nome;

		select into r count(*) from movto where mlid = $1;

		fetch c into r;

		if found then
			ret := '+ ' || ret;
		end if;
	end if;

	return ret;
end
$_$;


