--
-- Name: formata_cpf_cnpj(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.formata_cpf_cnpj(text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

   DECLARE
	   cpf text;
   BEGIN
   	
	   cpf := replace(replace(replace($1, '.', ''), '-', ''), '/', '')::text;

	   if length(cpf) = 14 then
			return substr(cpf, 1, 2) || '.' || substr(cpf, 3, 3) || '.' || substr(cpf, 6, 3) || '/' || substr(cpf, 9, 4) || '-' || substr(cpf, 13, 2);
	   end if;

	   if length(cpf) = 11 then
			return substr(cpf, 1, 3) || '.' || substr(cpf, 4, 3) || '.' || substr(cpf, 7, 3) || '-' || substr(cpf, 10, 2);
	   end if;

	   return 'CPF/CNPJ INV√ÅLIDO !'::text;
   	
   END;	   
   
$_$;


