--
-- Name: formata_valor_f(numeric, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.formata_valor_f(numeric, integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
declare
	mascara text;
	valor text;
BEGIN
	mascara := '999G999G999D'||rpad('9',$2,'9');
	select trim(to_char($1, mascara)) into valor;
	
	--Verifica se o valor formatado esta n√£o no padr√£o brasileiro
	--Sen√£o estiver formata para o padr√£o do Brasil
	if substr(valor,length(valor)-$2,1) = '.' then
		return replace(replace(replace(valor,'.',';'),',','.'),';',',');
	else
		return valor;
	end if;
END
$_$;


