--
-- Name: get_grid_map_tree_f(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_grid_map_tree_f(bigint, text) RETURNS SETOF public.grid_map_stack
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare

	ret grid_map_stack%rowtype;

    r record;

	parent_top bigint;

	x_child bigint;

	count integer;

begin

	if (($1 is null) or ($1 = 0::bigint) or ($2 is null))then

		return;

	end if;



	-- Procura primeiro elemento da fila

	x_child := $1;

	parent_top := $1;



	loop

		select parent into r from grid_map where child = x_child and chave = $2;



		if found then

			parent_top := r.parent;

			x_child := parent_top;

		else

			exit;

		end if;

	end loop;

	

	-- Retorna todos os elementos da fila

	-- return next parent_top;

	count := 0;

	ret.grid := parent_top;

	ret.index := count;



	loop 

		select * into r from grid_map where parent = parent_top and chave = $2;

		if found then

			if count = 0 then

				return next ret;

			end if;	



			count := count + 1;

			parent_top := r.child;

			ret.grid := parent_top;	

			ret.index := count;

			return next ret;		

		else

			return;

		end if;

	end loop;

	return;

end
$_$;


ALTER FUNCTION public.get_grid_map_tree_f(bigint, text) OWNER TO postgres;

