--
-- Name: inativar_cliente_f(bigint, boolean, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inativar_cliente_f(bigint, boolean, boolean, boolean) RETURNS void
    LANGUAGE plpgsql
    AS $_$

	-- Parametros(Periodo, Inativar, Bloquear, ContaReceber)
	DECLARE
		r RECORD;
		data_ini DATE;
		valores_receber TEXT;
	BEGIN
		select now()::date - ($1::text || ' day')::interval as data into r;
		data_ini := r.data;

		select conta into r from conta_config where chave = 'VALORES A RECEBER';
		IF found THEN
			valores_receber := r.conta;
		ELSE
			valores_receber := 0;
		END IF;

		IF $3 THEN
			UPDATE pessoa
				SET bloqueado = TRUE,
					mot_bloq = 'BLOQUEADO POR INATIVIDADE'
			WHERE grid IN
				(SELECT grid
					FROM cliente c
					WHERE NOT EXISTS
						(SELECT 1
							FROM movto m2
							WHERE c.grid = m2.pessoa
								AND DATA >= data_ini
								AND motivo =
									(SELECT motivo
										FROM motivo_config
										WHERE chave = 'VENDA'))
						AND (c.data_cad <= data_ini or c.data_cad is null)
						AND flag = 'A' AND tipo = 'C');
		END IF;

		-- Inativa o clientes
		IF $2 THEN
			-- Inativa apenas os cliente que n„o possuem contas as receber
			IF $4 THEN
				UPDATE pessoa
					SET flag = 'I'
				WHERE grid IN
					(SELECT grid
						FROM cliente c
						WHERE NOT EXISTS
							(SELECT 1
								FROM movto m2
								WHERE c.grid = m2.pessoa
									AND DATA >= data_ini
									AND motivo =
										(SELECT motivo
											FROM motivo_config
											WHERE chave = 'VENDA'))
							AND NOT EXISTS
								(SELECT 1 
									FROM movto m3
										JOIN motivo_movto mm
											ON (mm.grid=m3.motivo)
										JOIN conta co
											ON (co.codigo=mm.conta_debitar)
									WHERE m3.child=0
										AND c.grid=m3.pessoa
									AND co.pendencia
									AND (m3.conta_debitar = valores_receber
										OR m3.conta_debitar LIKE valores_receber || '%'))
							AND (c.data_cad <= data_ini or c.data_cad is null)
							AND flag = 'A' AND tipo = 'C');
			-- Inativa todos os clientes
			ELSE
				UPDATE pessoa
					SET flag = 'I'
				WHERE grid IN
					(SELECT grid
						FROM cliente c
						WHERE NOT EXISTS
							(SELECT 1
								FROM movto m2
								WHERE c.grid = m2.pessoa
									AND DATA >= data_ini
									AND motivo =
										(SELECT motivo
											FROM motivo_config 
											WHERE chave = 'VENDA'))
							AND (c.data_cad <= data_ini or c.data_cad is null)
							AND flag = 'A' AND tipo = 'C');
			END IF;
		END IF;
	END;
	
$_$;


ALTER FUNCTION public.inativar_cliente_f(bigint, boolean, boolean, boolean) OWNER TO postgres;

--
-- Name: init_estoque_comb_f(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.init_estoque_comb_f() RETURNS void
    LANGUAGE plpgsql
    AS $$

  DECLARE
	r RECORD;
  BEGIN
	TRUNCATE estoque_invalida;
	TRUNCATE estoque_lancto;
	TRUNCATE estoque_deposito;
	TRUNCATE estoque_valor;
	TRUNCATE estoque_controle;

	FOR r IN SELECT l.empresa, MIN(l.data) AS data FROM lancto l WHERE l.data >= (current_date - '12 month'::interval) GROUP BY l.empresa LOOP
	
		INSERT INTO estoque_invalida (empresa, deposito, produto, data)
			SELECT l.empresa, l.deposito, l.produto, r.data
			FROM lancto l JOIN produto p ON (l.produto=p.grid AND p.tipo = 'C')
			WHERE l.empresa=r.empresa
			GROUP BY l.empresa, l.deposito, l.produto;
	END LOOP;
	

	insert into estoque_controle(ativo, data_ativacao, data_ult_exec, estoque_produto) values (true, current_timestamp, current_timestamp, false);

	PERFORM check_estoque_f();
  END;
  
$$;


ALTER FUNCTION public.init_estoque_comb_f() OWNER TO postgres;

--
-- Name: init_estoque_f(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.init_estoque_f() RETURNS void
    LANGUAGE plpgsql
    AS $_$

  DECLARE
	r RECORD;
	v_msg_erro TEXT := '';

  BEGIN
	TRUNCATE estoque_invalida;
	TRUNCATE estoque_lancto;
	TRUNCATE estoque_deposito;
	TRUNCATE estoque_valor;
	TRUNCATE estoque_controle;
	TRUNCATE estoque_produto;

	FOR r IN SELECT l.empresa, MIN(l.data) AS data FROM lancto l WHERE l.data >= (current_date - '12 month'::interval) GROUP BY l.empresa LOOP
	
		INSERT INTO estoque_invalida (empresa, deposito, produto, data)
			SELECT l.empresa, l.deposito, l.produto, r.data
			FROM lancto l JOIN produto p ON (l.produto=p.grid)
			WHERE l.empresa=r.empresa
			GROUP BY l.empresa, l.deposito, l.produto;
	END LOOP;
	

	insert into estoque_controle(ativo, data_ativacao, data_ult_exec, estoque_produto) values (true, current_timestamp, current_timestamp, true);

	PERFORM check_estoque_f();
  
  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f($1, $3, $4, 'PROGRAMACAO'::text, 'GERAL'::text, 'INIT_ESTOQUE_F'::TEXT, v_msg_erro);
  END;
  
$_$;


ALTER FUNCTION public.init_estoque_f() OWNER TO postgres;

