	TRUNCATE estoque_invalida;
	TRUNCATE estoque_lancto;
	TRUNCATE estoque_deposito;
	TRUNCATE estoque_valor;
	TRUNCATE estoque_controle;

	FOR r IN SELECT l.empresa, MIN(l.data) AS data FROM lancto l WHERE (case when $1 is null then true else l.data >= $1 end) GROUP BY l.empresa LOOP
	
		INSERT INTO estoque_invalida (empresa, deposito, produto, data)
			SELECT l.empresa, l.deposito, l.produto, r.data
			FROM lancto l JOIN produto p ON (l.produto=p.grid)
			WHERE l.empresa=r.empresa
			GROUP BY l.empresa, l.deposito, l.produto;

	END LOOP;

	insert into estoque_controle(ativo, data_ativacao, data_ult_exec, estoque_produto) values (true, current_timestamp, current_timestamp, true);

	PERFORM check_estoque_f();
  END;
  
$_$;


