--
-- Name: init_estoque_produto_f(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.init_estoque_produto_f() RETURNS void
    LANGUAGE plpgsql
    AS $$

  DECLARE

	r RECORD;
	t bigint := 0;
	estoque_init boolean;
	v_empresa bigint;
	v_deposito bigint;
	v_produto bigint;
	v_data date;
	v_estoque float;
	v_custo_medio float;
	v_ult_custo float;
	v_ts_atualizacao timestamp;
	v_msg_erro TEXT := '';

  BEGIN

	SELECT count(x.*) INTO t FROM (SELECT el.empresa, el.deposito, el.produto, MAX(el.data) AS data FROM estoque_lancto el GROUP BY el.empresa, el.deposito, el.produto) x;

	IF NOT FOUND THEN
		RAISE INFO 'INICIALIZAR A ROTINA DE ESTOQUE PRIMEIRO';
		return;
	ELSE
		RAISE INFO 'TOTAL DE REGISTROS A SEREM PROCESSADOS: %', t;
	END IF;
	
	BEGIN
		TRUNCATE estoque_produto;
	EXCEPTION
		WHEN OTHERS THEN
			NULL;
	END;
	LOCK TABLE estoque_produto IN SHARE MODE;

	t := 0;
	FOR r IN SELECT el.empresa, el.deposito, el.produto, MAX(el.data) AS data FROM estoque_lancto el GROUP BY el.empresa, el.deposito, el.produto ORDER BY el.empresa, el.produto, 4 LOOP
	    t := t+1;
		RAISE INFO '% - Empresa: % , Deposito: % , Produto: % , Data: %', t, r.empresa, r.deposito, r.produto, r.data;

		SELECT empresa,deposito,produto,data,coalesce(estoque_dep,0) as estoque
			  ,coalesce(custo_medio,preco_custo_empresa_f(r.produto, r.empresa),0) as custo_medio
			  ,coalesce(ult_custo,preco_custo_empresa_f(r.produto, r.empresa, r.data),0) as ult_custo
			  ,now()::timestamp as ts_atualizacao
		  INTO v_empresa
	          ,v_deposito
	          ,v_produto
			  ,v_data
	          ,v_estoque
	          ,v_custo_medio
	          ,v_ult_custo
			  ,v_ts_atualizacao
		  FROM estoque_lancto
		 WHERE empresa=r.empresa
		   AND deposito=r.deposito
		   AND produto=r.produto
		   AND data=r.data
		 ORDER BY ordem DESC LIMIT 1;

		BEGIN
			INSERT INTO estoque_produto (empresa, deposito, produto, data, estoque, custo_medio, ult_custo, ts_atualizacao) 
				 values (v_empresa, v_deposito, v_produto, v_data, v_estoque,  v_custo_medio, v_ult_custo, v_ts_atualizacao);
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('15 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f(v_empresa, v_produto, v_data, 'ESTOQUE_PRODUTO'::text, 'INSERT'::text, 'INIT_ESTOQUE_PRODUTO_F'::TEXT, v_msg_erro);
		END;

		-- manter atualizado o custo para todos os depositos, pois as vezes o produto possui a movimentaÁ„o em apenas 1 deposito
		-- com isso o custo acaba ficando diferente de um deposito para o outro
		BEGIN
			UPDATE estoque_produto
			   SET custo_medio=coalesce(v_custo_medio,preco_custo_empresa_f(r.produto, r.empresa),0)
				  ,ult_custo=coalesce(v_ult_custo,preco_custo_empresa_f(r.produto, r.empresa, r.data),0)
			 WHERE empresa=r.empresa 
			   AND deposito!=r.deposito 
			   AND produto=r.produto
			   AND (coalesce(custo_medio, 0)!=coalesce(v_custo_medio, 0) or coalesce(ult_custo, 0)!=coalesce(v_ult_custo, 0));
		EXCEPTION
			WHEN OTHERS THEN
				v_msg_erro := upper('16 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
				PERFORM estoque_log_f(v_empresa, v_produto, v_data, 'ESTOQUE_PRODUTO'::text, 'UPDATE'::text, 'INIT_ESTOQUE_PRODUTO_F'::TEXT, v_msg_erro);
		END;

	END LOOP;

		update estoque_controle set estoque_produto=true;

	RETURN;

  EXCEPTION
	WHEN OTHERS THEN
		v_msg_erro := upper('99 - ERRO: ' || (sqlstate || ' - ' ||  sqlerrm)::text);
		PERFORM estoque_log_f(v_empresa, v_produto, v_data, 'PROGRAMACAO'::text, 'GERAL'::text, 'INIT_ESTOQUE_PRODUTO_F'::TEXT, v_msg_erro);
  END
  
$$;


ALTER FUNCTION public.init_estoque_produto_f() OWNER TO postgres;

