  BEGIN

	SELECT count(x.*) INTO t FROM (SELECT el.empresa, el.deposito, el.produto, MAX(el.data) AS data FROM estoque_lancto el WHERE empresa=$1 GROUP BY el.empresa, el.deposito, el.produto) x;

	IF NOT FOUND THEN
