--
-- Name: insere_caixa_movto_lote_f(bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.insere_caixa_movto_lote_f(bigint, integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

DECLARE
	numeracao bigint;
	now TIMESTAMP := CURRENT_TIMESTAMP;
BEGIN

	FOR i IN 1..$2 LOOP
		SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) INTO numeracao FROM pgd_lsite LIMIT 1;
		INSERT INTO caixa_movto_lote (caixa_conf, numeracao, utilizada, ts)
		VALUES ($1, numeracao, FALSE, now);
	END LOOP;

	return True;
END;

$_$;


ALTER FUNCTION public.insere_caixa_movto_lote_f(bigint, integer) OWNER TO postgres;

--
-- Name: is_lock_table(text, text, text, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.is_lock_table(text, text, text, integer, bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
   
   
   	/*Parametros
	1 - nome_estacao TEXT,
	2 - nome_lock TEXT 
	3 - valor_chave TEXT
	4 - pid_id INT 
	5 - usuario_id bigint
	*/
	DECLARE
		lock_count integer;
	BEGIN
		select COUNT(*) into lock_count from lock_table_temp
		where lock_nome = $2 and chave = $3;
   
		IF lock_count = 0 THEN
			insert into lock_table_temp(estacao, data_lancto, lock_nome, chave, status, pid, usuario)VALUES
									   ($1, NOW(), $2, $3, 'OCUPADO', $4, $5);
		END IF;   
		return lock_count;
	END;	   
   
$_$;


ALTER FUNCTION public.is_lock_table(text, text, text, integer, bigint) OWNER TO postgres;

--
-- Name: isdigit_f(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.isdigit_f(text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $_$
SELECT TRIM($1) ~ '^(-)?[0-9]+$' AS isdigit;
$_$;


