--
-- Name: lancto_desconto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_desconto_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	declare 
		rlancto record;
		desconto double precision;
	begin
		select l.preco_unit, l.quantidade, l.valor, 
		(case when l.preco_unit_orig is not null and l.preco_unit_orig > 0 then 
		l.preco_unit_orig else l.preco_unit end) as preco_unit_orig into rlancto from lancto l where l.grid = $1;
	 
		if not found then
			return 0.0;
		end if;
		
		desconto := (rlancto.preco_unit_orig * rlancto.quantidade) - rlancto.valor;

		return desconto;
	end;
   
$_$;


ALTER FUNCTION public.lancto_desconto_f(bigint) OWNER TO postgres;

--
-- Name: lancto_estoque_invalida_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_estoque_invalida_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
	r RECORD;
	r2 RECORD;
BEGIN
	IF (TG_OP = 'UPDATE' OR TG_OP = 'DELETE') THEN
		SELECT data INTO r FROM estoque_invalida 
			WHERE empresa=OLD.empresa AND deposito=OLD.deposito AND produto=OLD.produto order by data limit 1;

		BEGIN
			IF found THEN
				IF r.data > OLD.data THEN
					UPDATE estoque_invalida SET data=OLD.data
						WHERE empresa=OLD.empresa AND deposito=OLD.deposito AND produto=OLD.produto;
				END IF;
			ELSE
				INSERT INTO estoque_invalida (empresa, deposito, produto, data) 
					VALUES (OLD.empresa, OLD.deposito, OLD.produto, OLD.data);
			END IF;

			IF OLD.operacao IN ('E', 'TE', 'I') THEN
				FOR r2 IN SELECT produto FROM produto_movimenta_materia_prima_empresa_f(OLD.produto, OLD.empresa) as produto(produto bigint)
				LOOP
					SELECT data INTO r FROM estoque_invalida 
					WHERE empresa=OLD.empresa AND deposito=OLD.deposito AND produto=r2.produto order by data limit 1;

					IF found THEN
						IF r.data > OLD.data THEN
							UPDATE estoque_invalida SET data=OLD.data
								WHERE empresa=OLD.empresa AND deposito=OLD.deposito AND produto=r2.produto;
						END IF;
					ELSE
						INSERT INTO estoque_invalida (empresa, deposito, produto, data) 
							VALUES (OLD.empresa, OLD.deposito, r2.produto, OLD.data);
					END IF;
				END LOOP;
			END IF;
		EXCEPTION
			WHEN unique_violation THEN
				--NAO FAZ NADA	
		END;
	END IF;

	IF (TG_OP = 'UPDATE' OR TG_OP = 'INSERT') THEN
		SELECT data INTO r FROM estoque_invalida 
		WHERE empresa=NEW.empresa AND deposito=NEW.deposito AND produto=NEW.produto order by data limit 1;

		BEGIN
			IF found THEN
				IF r.data > NEW.data THEN
					UPDATE estoque_invalida SET data=NEW.data
						WHERE empresa=NEW.empresa AND deposito=NEW.deposito AND produto=NEW.produto;
				END IF;
			ELSE
				INSERT INTO estoque_invalida (empresa, deposito, produto, data) 
					VALUES (NEW.empresa, NEW.deposito, NEW.produto, NEW.data);
			END IF;

			IF NEW.operacao IN ('E', 'TE', 'I') THEN
				FOR r2 IN SELECT produto FROM produto_movimenta_materia_prima_empresa_f(NEW.produto, NEW.empresa) as produto(produto bigint)
				LOOP
					SELECT data INTO r FROM estoque_invalida 
					WHERE empresa=NEW.empresa AND deposito=NEW.deposito AND produto=r2.produto order by data limit 1;

					IF found THEN
						IF r.data > NEW.data THEN
							UPDATE estoque_invalida SET data=NEW.data
								WHERE empresa=NEW.empresa AND deposito=NEW.deposito AND produto=r2.produto;
						END IF;
					ELSE
						INSERT INTO estoque_invalida (empresa, deposito, produto, data) 
							VALUES (NEW.empresa, NEW.deposito, r2.produto, NEW.data);
					END IF;
				END LOOP;
			END IF;

		EXCEPTION
			WHEN unique_violation THEN
				--NAO FAZ NADA	
		END;
	END IF;

	IF (TG_OP = 'UPDATE' OR TG_OP = 'INSERT') THEN
		RETURN NEW;
	ELSE
		RETURN OLD;
	END IF;
END;
  
$$;


ALTER FUNCTION public.lancto_estoque_invalida_tgf() OWNER TO postgres;

--
-- Name: lancto_mng_estoque_del(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_mng_estoque_del() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	delete from estoque where empresa=old.empresa and deposito=old.deposito
	and produto=old.produto and data>=old.data;

	/* ManutenÁ„o da tabela de HistÛrico de Custo de Produtos */
	if old.data < date(now()) or old.operacao = 'E' then
	   	delete from produto_hist_custo where empresa=old.empresa and 
	   	produto=old.produto and data>=old.data;
	end if;

	return old;
end;
$$;


ALTER FUNCTION public.lancto_mng_estoque_del() OWNER TO postgres;

--
-- Name: lancto_mng_estoque_ins(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_mng_estoque_ins() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	delete from estoque where empresa=new.empresa and deposito=new.deposito
	and produto=new.produto and data>=new.data;

	/* ManutenÁ„o da tabela de HistÛrico de Custo de Produtos */
	if new.data < date(now()) or new.operacao = 'E' then
		delete from produto_hist_custo where empresa=new.empresa and 
		produto=new.produto and data>=new.data;
	end if;

	return new;
end;
$$;


