--
-- Name: lancto_mng_estoque_upd(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_mng_estoque_upd() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
	if new.empresa!=old.empresa or new.deposito!=old.deposito or new.operacao!=old.operacao or 
	   new.produto!=old.produto or new.data!=old.data or new.quantidade!=old.quantidade then

	   delete from estoque where empresa=old.empresa and deposito=old.deposito
	   and produto=old.produto and data>=old.data;

	   delete from estoque where empresa=new.empresa and deposito=new.deposito
	   and produto=new.produto and data>=new.data;

	   /* ManutenÁ„o da tabela de HistÛrico de Custo de Produtos */
	   if old.data < date(now()) or old.operacao = 'E' then
		   delete from produto_hist_custo where empresa=old.empresa and 
		   produto=old.produto and data>=old.data;
	   end if;

	   if new.data < date(now()) or new.operacao = 'E' then
		   delete from produto_hist_custo where empresa=new.empresa and 
		   produto=new.produto and data>=new.data;
	   end if;
	end if;
   
	return new;
end;
$$;


ALTER FUNCTION public.lancto_mng_estoque_upd() OWNER TO postgres;

--
-- Name: lancto_next_seq(date, integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_next_seq(date, integer, bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
	declare r record;
	begin
		select max(seq) into r from lancto where data=$1
		and turno=$2 and empresa=$3;

		if found then
			if (r.max is null) then
				return(1);
			else
				return(r.max+1);
			end if;
		else
			return(1);
		end if;
	end;
	$_$;


ALTER FUNCTION public.lancto_next_seq(date, integer, bigint) OWNER TO postgres;

--
-- Name: lancto_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lancto_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
 	r RECORD;
 	reg RECORD;
 	json TEXT;
	req TEXT;
	SCS TEXT;
	saldo_estoque FLOAT;
	saldo_inicial BOOLEAN;
	cnpj TEXT;
	codigo_deposito INTEGER;
	codigo_produto INTEGER;
	responsavel INTEGER;
	empresa_loc BIGINT;
	registrar_contagem_as3 BOOLEAN;
BEGIN
	IF TG_OP = 'DELETE' THEN
		reg := OLD;
	ELSE
		reg := NEW;
	END IF;

	SELECT grid FROM empresa_local INTO empresa_loc;
	SELECT True INTO r FROM exchange_emsys_gestao_config_empresa WHERE empresa = empresa_loc;
	
	--Valida se È saldo inicial proveniente da descida do EMSys
	saldo_inicial = COALESCE(reg.saldo_inicial, False);

	--Sair da funcao se a empresa nao for integrada ao EMSys Gestao, ou o registro nao for da empresa local ou nao for medicao/inventario.
	--Se for saldo inicial vindo do EMSys sai da funÁ„o, soluÁ„o para n„o desabilitar a trigger toda vez que desce o estoque
	IF (NOT found) OR (reg.empresa <> empresa_loc) OR (reg.operacao NOT IN ('I', 'M')) OR (reg.saldo_inicial = True) THEN
		RETURN reg;
	END IF;

	-- INVENTARIO
	IF reg.operacao = 'I' THEN
		SELECT somente_numero_f(cpf) FROM pessoa WHERE grid = reg.empresa INTO cnpj;
		SELECT codigo FROM deposito WHERE grid = reg.deposito INTO codigo_deposito;
		SELECT codigo FROM produto WHERE grid = reg.produto INTO codigo_produto;
		SELECT produto_estoque_f(reg.empresa, reg.deposito, reg.produto, reg.data, reg.turno, (reg.hora - INTERVAL '1' SECOND)) INTO saldo_estoque;
		SELECT coalesce(registrar_contagem, false) FROM exchange_emsys_gestao_config INTO registrar_contagem_as3;

		IF TG_OP = 'DELETE' THEN
			req := 'inventario_estorna';
		ELSE
			req := 'inventario_registra';
		END IF;

		IF registrar_contagem_as3 THEN
			saldo_estoque := -1;
		END IF;

		json := '{
			"id": ' || reg.mlid || ',
			"cnpjEmpresa": "' || cnpj || '",
			"idAlmoxarifado": ' || codigo_deposito || ',
			"data": "' || TO_CHAR(reg.data, 'yyyy-mm-dd') || '",
			"hora": "' || TO_CHAR(reg.hora, 'hh24:mi:ss') || '",
			"contagens": [{
				"idProduto": ' || codigo_produto || ',
				"qtdContagem": ' || reg.quantidade || ',
				"qtdSistema": ' || saldo_estoque || '
			}]
		}';

	-- MEDICAO
	ELSE
		SELECT codigo FROM deposito WHERE grid = reg.deposito INTO codigo_deposito;
		SELECT codigo FROM exchange_emsys_gestao_map WHERE pessoa = reg.pessoa INTO responsavel;

		IF TG_OP = 'DELETE' THEN
			req := 'medicaotanque_estorna';
		ELSE
			req := 'medicaotanque_registra';
		END IF;

		json := '[{
			"id": ' || reg.grid || ',
			"idAlmoxarifado": ' || codigo_deposito || ',
			"data": "' || TO_CHAR(reg.hora, 'yyyy-mm-dd') || '",
			"hora": "' || TO_CHAR(reg.hora, 'hh24:mi:ss') || '",
			"dataFiscalLmc": "' || TO_CHAR(reg.data, 'yyyy-mm-dd') || '",
			"quantidade": ' || reg.quantidade;

		IF responsavel IS NOT NULL THEN
			json := json || ',"responsavel": ' || responsavel;
		END IF;

		json := json || '}]';
	END IF;

	--raise info 'JSON: %', json;
	SHOW standard_conforming_strings INTO SCS;

	IF SCS = 'off' THEN
		set standard_conforming_strings = on;
	END IF;

	json := regexp_replace(json, E'[\n\r\t]+', '', 'g');

	INSERT INTO exchange_emsys_gestao_pendencia
	(empresa, caixa, data, turno, requisicao, conteudo, mlid)
	VALUES
	(reg.empresa, '', reg.data, reg.turno, req, json, reg.mlid);

	IF SCS = 'off' THEN
		set standard_conforming_strings = off;
	END IF;

	RETURN reg;
END;
  
$$;


ALTER FUNCTION public.lancto_pendencia_tgf() OWNER TO postgres;

--
-- Name: margem_lucro_empresa_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.margem_lucro_empresa_f(bigint, bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
begin
	select margem_lucro into r from produto_empresa where produto=$1 and 
		empresa=$2 and not margem_lucro is null;

	if found then
		if r.margem_lucro > 0 then
			return r.margem_lucro;
		end if;
	end if;

	select (case when ((p.margem_lucro is null) or (p.margem_lucro = 0)) then coalesce(gp.margem_lucro,0) else p.margem_lucro end) 
	as margem into r from produto p join grupo_produto gp on (p.grupo=gp.grid) where p.grid=$1;

	return r.margem;
end;
$_$;


