CREATE FUNCTION public.margem_lucro_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

begin

	select pe.margem_lucro into r from produto_empresa pe join empresa_local e on 

		(pe.empresa=e.empresa) where pe.produto=$1 and not margem_lucro is null;

	

	if found then

		return r.margem_lucro;

	end if;



	select margem_lucro into r from produto where grid=$1;

	return r.margem_lucro;

end;
$_$;


