--
-- Name: mes_extenso_f(date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mes_extenso_f(date) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

   DECLARE
   	mes integer;
   BEGIN
   	
   	mes := to_char($1, 'mm')::integer;
   	
	if mes =  1 then return  'JANEIRO'; end if;
	if mes =  2 then return  'FEVEREIRO'; end if;
	if mes =  3 then return  'MARCO'; end if;
	if mes =  4 then return  'ABRIL'; end if;
	if mes =  5 then return  'MAIO'; end if;
	if mes =  6 then return  'JUNHO'; end if;
	if mes =  7 then return  'JULHO'; end if;   	       	   
	if mes =  8 then return  'AGOSTO'; end if;
	if mes =  9 then return  'SETEMBRO'; end if;
	if mes = 10 then return  'OUTUBRO'; end if;
	if mes = 11 then return  'NOVEMBRO'; end if;   	       	   
	if mes = 12 then return  'DEZEMBRO'; end if;
   END;	   
   
$_$;


