--
-- Name: motivo_movto_contador(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.motivo_movto_contador(bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$
   
   
   	/*Parametros
	1 - grid BIGINT,	
	*/
	DECLARE
		contador_temp integer;
	BEGIN
		select coalesce(contador, 1) into contador_temp from motivo_movto where grid = $1;
   
		update motivo_movto set contador = contador_temp + 1 where grid = $1;
		
		return contador_temp;
	END;	   
   
$_$;


