--
-- Name: movto_baixa_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_baixa_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	DECLARE
		r RECORD;
		v_ret float;
		v_valor_baixa float;
		v_encontrou boolean;
		v_tem_reg boolean;
		v_bancos text;
		v_caixa_adm text;
		v_pontos_venda text;
		v_juros bigint;
		v_multa bigint;
		v_acrescimo bigint;
		v_desconto bigint;
		v_dinheiro bigint;
	BEGIN
		v_valor_baixa := 0.0;
		v_tem_reg := false;
		v_encontrou := false;		

		select conta into v_bancos from conta_config where chave = 'BANCOS';
		select conta into v_caixa_adm from conta_config where chave = 'CAIXA ADM';
		select conta into v_pontos_venda from conta_config where chave = 'PONTOS DE VENDA';
		select mc.motivo into v_juros from motivo_config mc where mc.chave = 'JUROS';
		select mc.motivo into v_multa from motivo_config mc where mc.chave = 'MULTA';
		select mc.motivo into v_acrescimo from motivo_config mc where mc.chave = 'ACRESCIMO_FATURA';
		select mc.motivo into v_desconto from motivo_config mc where mc.chave = 'DESCONTO_FATURA';
		select mc.motivo into v_dinheiro from motivo_config mc where mc.chave = 'DINHEIRO';
		
		--busca pelo valor pago em dinheiro atraves do grid da venda
		select valor_forma_pgto into v_ret
		from venda_pgto_view 
		where mlid = (select mlid 
					  from movto 
					  where grid = $1) 
		and forma_pgto=v_dinheiro;
		
		if v_ret > 0 then
			v_valor_baixa := v_ret;
			v_tem_reg := true;
			v_encontrou := true;
		END IF;
		
		LOOP		
			--faz um for para buscar as possiveis baixas
			FOR r IN select mf.grid
				  , mf.conta_debitar
				  , mf.child
				  , mf.valor
				 from movto mf
				 where mf.motivo not in (v_juros, v_multa, v_acrescimo, v_desconto)
				 and mf.grid in (select child
									from movto_map
									where parent in (select grid
													 from movto
													 where grid in (select child
																	 from movto_map
																	 where parent= $1))) LOOP

				v_tem_reg := true;
				v_ret := r.valor;			
				--se a conta nao for um filho da v_caixa_adm, nem do v_bancos, nem do pontos_vendas e possuir child = 0
				IF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
					like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%') and r.child = 0) THEN				
					--RETURN 0 CASO NAO TENHA SIDO BAIXADO
					v_ret := 0.0;

				--se a conta nao for um filho da v_caixa_adm, nem do v_bancos, nem do pontos_vendas e possuir child != 0
				ELSIF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
									like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%')) then	
					--Quando baixado com outra baixa, verifica se outra baixa foi baixada e assim vai...
					select movto_baixa_f(r.grid) into v_ret;
					
					if v_ret = 0 then
						v_ret := 0.0;
					END IF;
					
				END IF;
				
				--se chegar no final do for , porque v_encontrou a baixa
				v_encontrou := true;	
				v_valor_baixa := v_valor_baixa + v_ret;

			END LOOP; --fim do for


			if (not v_tem_reg) then
				--executa outro sql, significa q este , baixa a prazo de uma outra baixa
				for r in select m.grid
							, m.conta_debitar
							, m.child
							, m.valor
						 from movto m
						 where  m.motivo not in (v_juros, v_multa, v_acrescimo, v_desconto)
						 and m.grid in (select child
										 from movto_map
										 where parent= $1) LOOP
					
					v_tem_reg := true;
					v_ret := r.valor;
					IF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
						like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%') and r.child = 0) THEN				
						--retorna 0 caso nao tenha sido paga 
						v_ret := 0.0;

					ELSIF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
										like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%')) then	
						--verifica se a conta foi baixada com outra do tipo nota prazo
						select movto_baixa_f(r.grid) into v_ret;
						
						if v_ret = 0 then					
							v_ret :=  0.0;
						END IF;

					END IF;

					--se chegou aqui , porque v_encontrou a baixa
					v_encontrou := true;	
					v_valor_baixa	:= v_valor_baixa + v_ret;
				
				END LOOP;

			END IF;							


			if (not v_tem_reg) then
				--se nao tiver registro em nenhum dos 2 sql , porque esta pendente ou nao , uma conta a prazo
				return 0.0;
			elsif (v_tem_reg and v_encontrou) then
				--se teve registro e v_encontrou entao retorna o valor
				return v_valor_baixa;
			END IF;					
		
		-- caso tenha registro, mas n tenha encontrado, vai para a proximo
		END LOOP; -- fim do while
		
		--por fim caso termine de executar o loop retorna o valor
		return v_valor_baixa;
	END;
   
$_$;


ALTER FUNCTION public.movto_baixa_f(bigint) OWNER TO postgres;

--
-- Name: movto_baixa_f(bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_baixa_f(bigint, date, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	DECLARE
		r RECORD;
		v_ret float;
		v_valor_baixa float;
		v_encontrou boolean;
		v_tem_reg boolean;
		v_bancos text;
		v_caixa_adm text;
		v_pontos_venda text;
		v_juros bigint;
		v_multa bigint;
		v_acrescimo bigint;
		v_desconto bigint;
		v_dinheiro bigint;
	BEGIN
		v_valor_baixa := 0.0;
		v_tem_reg := false;
		v_encontrou := false;		

		select conta into v_bancos from conta_config where chave = 'BANCOS';
		select conta into v_caixa_adm from conta_config where chave = 'CAIXA ADM';
		select conta into v_pontos_venda from conta_config where chave = 'PONTOS DE VENDA';
		select mc.motivo into v_juros from motivo_config mc where mc.chave = 'JUROS';
		select mc.motivo into v_multa from motivo_config mc where mc.chave = 'MULTA';
		select mc.motivo into v_acrescimo from motivo_config mc where mc.chave = 'ACRESCIMO_FATURA';
		select mc.motivo into v_desconto from motivo_config mc where mc.chave = 'DESCONTO_FATURA';
		select mc.motivo into v_dinheiro from motivo_config mc where mc.chave = 'DINHEIRO';
		
		--busca pelo valor pago em dinheiro atraves do grid da venda
		select valor_forma_pgto into v_ret
		from venda_pgto_view 
		where mlid = (select mlid 
					  from movto 
					  where grid = $1) 
		and forma_pgto=v_dinheiro;
		
		if v_ret > 0 then
			v_valor_baixa := v_ret;
			v_tem_reg := true;
			v_encontrou := true;
		END IF;
		
		LOOP		
			--faz um for para buscar as possiveis baixas
			FOR r IN select mf.grid
				  , mf.conta_debitar
				  , mf.child
				  , mf.valor
				 from movto mf
				 where (mf.data between $2 and $3)
				 and mf.motivo not in (v_juros, v_multa, v_acrescimo, v_desconto)
				 and mf.grid in (select child
									from movto_map
									where parent in (select grid
													 from movto
													 where grid in (select child
																	 from movto_map
																	 where parent= $1))) LOOP

				v_tem_reg := true;
				v_ret := r.valor;			
				--se a conta nao for um filho da v_caixa_adm, nem do v_bancos, nem do pontos_vendas e possuir child = 0
				IF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
					like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%') and r.child = 0) THEN				
					--RETURN 0 CASO NAO TENHA SIDO BAIXADO
					v_ret := 0.0;

				--se a conta nao for um filho da v_caixa_adm, nem do v_bancos, nem do pontos_vendas e possuir child != 0
				ELSIF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
									like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%')) then	
					--Quando baixado com outra baixa, verifica se outra baixa foi baixada e assim vai...
					select movto_baixa_f(r.grid, $2, $3) into v_ret;
					
					if v_ret = 0 then
						v_ret := 0.0;
					END IF;
					
				END IF;
				
				--se chegar no final do for , porque v_encontrou a baixa
				v_encontrou := true;	
				v_valor_baixa	:= v_valor_baixa + v_ret;

			END LOOP; --fim do for


			if (not v_tem_reg) then
				--executa outro sql, significa q este , baixa a prazo de uma outra baixa
				for r in select m.grid
							, m.conta_debitar
							, m.child
							, m.valor
						 from movto m
						 where (m.data between $2 and $3)
						 and m.motivo not in (v_juros, v_multa, v_acrescimo, v_desconto)
						 and m.grid in (select child
										 from movto_map
										 where parent= $1) LOOP
					
					v_tem_reg := true;
					v_ret := r.valor;
					IF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
						like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%') and r.child = 0) THEN				
						--retorna 0 caso nao tenha sido paga 
						v_ret := 0.0;

					ELSIF ( not (r.conta_debitar::text like v_caixa_adm||'%' or r.conta_debitar::text 
										like v_pontos_venda||'%' or r.conta_debitar::text like v_bancos||'%')) then	
						--verifica se a conta foi baixada com outra do tipo nota prazo
						select movto_baixa_f(r.grid, $2, $3) into v_ret;
						
						if v_ret = 0 then					
							v_ret :=  0.0;
						END IF;

					END IF;

					--se chegou aqui , porque v_encontrou a baixa
					v_encontrou := true;	
					v_valor_baixa	:= v_valor_baixa + v_ret;
				
				END LOOP;

			END IF;							


			if (not v_tem_reg) then
				--se nao tiver registro em nenhum dos 2 sql , porque esta pendente ou nao , uma conta a prazo
				return 0.0;
			elsif (v_tem_reg and v_encontrou) then
				--se teve registro e v_encontrou entao retorna o valor
				return v_valor_baixa;
			END IF;					
		
		-- caso tenha registro, mas nao tenha encontrado, vai para a proximo
		END LOOP; -- fim do while
		
		--por fim caso termine de executar o loop retorna o valor
		return v_valor_baixa;
	END;
   
$_$;


