--
-- Name: movto_conta_invalida_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_conta_invalida_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN
	-- Caso nao mudou nenhum campo que interessa, nao invalida
	IF (TG_OP = 'UPDATE') THEN
		IF NOT ((NEW.empresa <> OLD.empresa) OR (NEW.data <> OLD.data) OR (NEW.conta_debitar <> OLD.conta_debitar) OR 
				(NEW.conta_creditar <> OLD.conta_creditar) OR (NEW.valor <> OLD.valor)) THEN
			RETURN NEW;
		END IF;
	END IF;

	IF (TG_OP = 'UPDATE' OR TG_OP = 'DELETE') THEN
		PERFORM conta_saldo_invalida_f(OLD.empresa, OLD.conta_debitar, OLD.data);
		PERFORM conta_saldo_invalida_f(OLD.empresa, OLD.conta_creditar, OLD.data);
	END IF;
		
	IF (TG_OP = 'UPDATE' OR TG_OP = 'INSERT') THEN
		PERFORM conta_saldo_invalida_f(NEW.empresa, NEW.conta_debitar, NEW.data);
		PERFORM conta_saldo_invalida_f(NEW.empresa, NEW.conta_creditar, NEW.data);
	END IF;

	IF (TG_OP = 'DELETE') THEN
		RETURN OLD;
	ELSE
		RETURN NEW;
	END IF;
END;
  
$$;


