--

CREATE FUNCTION public.movto_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN
	IF CURRENT_USER != 'distro' THEN

		DELETE FROM MOVTO_MAP WHERE PARENT=OLD.GRID OR CHILD=OLD.GRID;

	END IF;

	RETURN OLD;
END;
  
$$;


