--
-- Name: movto_fatura_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_fatura_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	DECLARE
		VALOR_FATURA FLOAT;	
		V_MOTIVO_FATURA BIGINT;
		V_MOTIVO_CONTA TEXT;
	BEGIN
		
		SELECT MOTIVO
			  ,MM.CONTA_DEBITAR
		  INTO V_MOTIVO_FATURA
			  ,V_MOTIVO_CONTA
		  FROM MOTIVO_CONFIG MC 
		  JOIN MOTIVO_MOVTO  MM ON (MM.GRID=MC.MOTIVO)
		 WHERE CHAVE = 'FATURA_NOTA';

		SELECT SUM(M.VALOR) INTO VALOR_FATURA 
		FROM MOVTO M
		WHERE M.GRID IN (SELECT CHILD 
						FROM MOVTO_MAP 
						WHERE PARENT IN (SELECT CHILD 
										FROM MOVTO_MAP 
										WHERE PARENT = $1))
		AND (M.MOTIVO=V_MOTIVO_FATURA OR (M.CONTA_DEBITAR=V_MOTIVO_CONTA OR M.CONTA_DEBITAR LIKE V_MOTIVO_CONTA||'.%'));

		RETURN COALESCE(VALOR_FATURA, 0);
	END;
   
$_$;


ALTER FUNCTION public.movto_fatura_f(bigint) OWNER TO postgres;

--
-- Name: movto_info_acrescimo_f(bigint, text, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_info_acrescimo_f(bigint, text, double precision) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

declare
	r record;
begin /* o segundo parametro deve ser passado a palavra 'juros' ou 'multa' */
	select info::numeric into r from movto_info where movto = $1 and tipo = 'vlr_'||$2;
	if found then
	   	return r.info;
	end if;

	select info::numeric into r from movto_info where movto = $1 and tipo = 'perc_'||$2;
	if found then		
	   	return $3 * (r.info/100);
	end if;
	return 0;
end;

$_$;


ALTER FUNCTION public.movto_info_acrescimo_f(bigint, text, double precision) OWNER TO postgres;

--
-- Name: movto_info_f(bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_info_f(bigint, text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

	DECLARE r text;
	BEGIN	
		IF $2 = 'placa' THEN
			select coalesce((select info from movto_info mi where movto=$1 and tipo=$2),(select placa from venda_placa_km v join movto m on m.mlid=v.mlid where m.grid=$1)) into r ;
		ELSEIF $2 = 'km' THEN
			select coalesce((select info from movto_info mi where movto=$1 and tipo=$2),(select km::text from venda_placa_km v join movto m on m.mlid=v.mlid where m.grid=$1)) into r ;
		ELSE
			select info from movto_info into r where movto=$1 and tipo=$2;
		END IF;

		return r;

	END;   
   
$_$;


ALTER FUNCTION public.movto_info_f(bigint, text) OWNER TO postgres;

--
-- Name: movto_map_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_map_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE

r RECORD;

BEGIN

	IF CURRENT_USER != 'distro' THEN
		SELECT PARENT INTO r FROM MOVTO_MAP WHERE PARENT=OLD.PARENT AND CHILD!=OLD.CHILD;

		IF NOT FOUND THEN
			UPDATE MOVTO SET CHILD=0 WHERE GRID=OLD.PARENT;
		END IF;

	END IF;

	RETURN OLD;

END;
  
$$;


ALTER FUNCTION public.movto_map_delete() OWNER TO postgres;

--
-- Name: movto_map_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_map_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

BEGIN

	IF CURRENT_USER != 'distro' THEN
		UPDATE MOVTO SET CHILD=1 WHERE GRID=NEW.PARENT;
	END IF;

	RETURN NEW;

END;
  
$$;


ALTER FUNCTION public.movto_map_insert() OWNER TO postgres;

--
-- Name: movto_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.movto_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
 	r RECORD;
	reg RECORD;
	r_pend RECORD;
	r_hist RECORD;
	json TEXT;
	req TEXT;
	SCS TEXT;
	placa TEXT;
	autorizante TEXT;
	empresa_loc BIGINT;
	sit_pend INTEGER;
	ts_geracao TIMESTAMP;
BEGIN

	IF TG_OP = 'DELETE' THEN
		reg := OLD;
	ELSE
		reg := NEW;
	END IF;

	placa := '';
	autorizante := '';

	SELECT grid FROM empresa_local INTO empresa_loc;
	SELECT True INTO r FROM exchange_emsys_gestao_config_empresa WHERE empresa = empresa_loc;

	--Sair da funcao se a empresa nao for integrada ao EMSys Gestao, ou o registro nao for da empresa local.
	IF NOT found OR reg.empresa <> empresa_loc THEN
		RETURN reg;
	END IF;

	IF reg.exporta_sap THEN

		SELECT
			reg.grid
			,reg.conta_debitar
			,reg.conta_creditar
			,reg.codigo_centro_custo
			,somente_numero_f(e.cpf) AS cnpj
			,cx.grid AS idTurno
			,cx.data
			,cx.turno
			,cx.conta AS caixa
			,eegm.codigo as cliente_codigo
			,p.nome AS cliente_nome
			,NULL as operador_codigo
			,NULL AS operador_nome
			,NULL AS id_venda
			,motivo_movto_nome_f(reg.motivo) || coalesce(' | ' || NULLIF(reg.obs, ''), '') AS observacao
		INTO r
		FROM empresa e
		LEFT JOIN caixa cx ON (reg.conta_debitar = cx.conta AND reg.data = cx.data AND reg.turno = cx.turno)
		LEFT JOIN pessoa p ON (p.grid = reg.pessoa)
		LEFT JOIN exchange_emsys_gestao_map eegm ON (eegm.pessoa = reg.pessoa)
		WHERE e.grid = reg.empresa;

	ELSE

		SELECT
			m.grid
			,m.grid as id_venda
			,cx.grid AS idTurno
			,cx.data
			,cx.turno
			,cx.conta AS caixa
			,eegmo.codigo as operador_codigo
			,oper.nome AS operador_nome
			,somente_numero_f(e.cpf) AS cnpj
			,NULL as cliente_codigo
			,NULL AS cliente_nome
			,NULL AS conta_debitar
			,NULL AS conta_creditar
			,NULL AS observacao
			,NULL AS codigo_centro_custo
			INTO r
			FROM motivo_movto mm
			JOIN tipo_vale tv
			ON tv.grid = mm.tipo_vale
			AND tv.tipo = 1
			AND tv.conta = reg.conta_creditar
			JOIN movto m
			ON m.mlid = reg.mlid
			AND m.motivo = (SELECT motivo FROM motivo_config WHERE chave = 'VENDA')
		JOIN empresa e ON(e.grid = reg.empresa)
		LEFT JOIN caixa cx ON (m.conta_debitar = cx.conta AND m.data = cx.data AND m.turno = cx.turno)
		LEFT JOIN pessoa oper ON (oper.grid = cx.pessoa)
		LEFT JOIN exchange_emsys_gestao_map eegmo ON (eegmo.pessoa = cx.pessoa)
		WHERE mm.grid = reg.motivo;

	END IF;

	IF NOT FOUND THEN
		RETURN reg;
	END IF;

	SELECT coalesce(mi.info, '') FROM movto_info mi WHERE mi.tipo='placa' AND mi.movto = reg.grid INTO placa;
	SELECT coalesce(mi.info, '') FROM movto_info mi WHERE mi.tipo='autorizado' AND mi.movto = reg.grid INTO autorizante;

	IF placa IS NULL THEN
		placa := '';
	END IF;

	IF autorizante IS NULL THEN
		autorizante := '';
	END IF;

	IF TG_OP = 'DELETE' THEN
		req := 'valebrinde_estorna';

		IF reg.exporta_sap THEN
			req := 'conta_estorna';
		END IF;

	ELSE
		req := 'valebrinde_registra';

		IF reg.exporta_sap THEN
			req := 'conta_registra';
		END IF;

	END IF;

	json := '{
		"id": ' || reg.grid || ',
		"numero": "' || reg.documento || '",
		"valor": ' || reg.valor || ',
		"vencimento": "' || TO_CHAR(reg.vencto, 'yyyy-mm-dd') || '",
		"data": "' || TO_CHAR(reg.data, 'yyyy-mm-dd') || '",
		"hora": "' || TO_CHAR(reg.hora, 'hh24:mi:ss') || '",
		"placa": "' || placa || '",
		"autorizante": "' || autorizante || '"';

		IF r.cnpj IS NOT NULL THEN
			json := json || ',"cnpj": "' || r.cnpj || '"';
		END IF;

		IF r.id_venda IS NOT NULL THEN
			json := json || ',"idVenda": "' || r.id_venda || '"';
		END IF;

		IF r.observacao IS NOT NULL THEN
			json := json || ',"observacao": "' || r.observacao || '"';
		END IF;

		IF r.idTurno IS NOT NULL THEN
			json := json || ',"idTurno": "' || r.idTurno || '"';
		END IF;

		IF r.caixa IS NOT NULL THEN
			json := json || ',"numCaixa": "' || r.caixa || '"';
		END IF;

		IF r.turno IS NOT NULL THEN
			json := json || ',"numTurno": ' || r.turno::text;
		END IF;

		IF r.conta_debitar IS NOT NULL THEN
			json := json || ',"contaDebitar": "' || r.conta_debitar || '"';
		END IF;

		IF r.conta_creditar IS NOT NULL THEN
			json := json || ',"contaCreditar": "' || r.conta_creditar || '"';
		END IF;

		IF r.codigo_centro_custo IS NOT NULL THEN
			json := json || ',"centroCusto": "' || r.codigo_centro_custo || '"';
		END IF;

		IF r.operador_codigo IS NOT NULL THEN
			json := json || ',"operador": {';
			json := json || '"id": ' || r.operador_codigo || ',';
			json := json || '"nome": "' || r.operador_nome || '"';
			json := json || '}';
		END IF;

		IF r.cliente_codigo IS NOT NULL THEN
			json := json || ',"pessoa": {';
			json := json || '"id": ' || r.cliente_codigo || ',';
			json := json || '"nome": "' || r.cliente_nome || '"';
			json := json || '}';
		END IF;

		IF TG_OP = 'DELETE' THEN
			json := json || ',"dataHoraEstorno": "' || TO_CHAR((select now()), 'yyyy-mm-dd hh24:mi:ss') || '"';
			json := json || ',"dataHoraOrigem": "' || TO_CHAR(reg.data, 'yyyy-mm-dd') || '"';
		END IF;

		json := json || '}';

	--raise info 'JSON: %', json;
	SHOW standard_conforming_strings INTO SCS;

	IF SCS = 'off' THEN
		set standard_conforming_strings = on;
	END IF;

	json := regexp_replace(json, E'[\n\r\t]+', '', 'g');

	SELECT True AS valor INTO r_pend
		FROM exchange_emsys_gestao_pendencia eegp
	WHERE true 
		AND eegp.mlid = reg.mlid
		AND eegp.requisicao = 'venda_registra';

	SELECT True AS valor INTO r_hist
		FROM exchange_emsys_gestao_pendencia_historico eegph
	WHERE true
		AND eegph.mlid = reg.mlid
		AND eegph.requisicao='venda_registra';

	ts_geracao = now() + interval '1 minutes';

	-- Se nao encontrou a venda referente o documento na tabela de pendencia a mesma ja foi enviada.
	IF (r_hist.valor AND r_pend IS NULL) OR reg.exporta_sap THEN
		sit_pend := 1;
	ELSE
		sit_pend := 6;
	END IF;

	INSERT INTO exchange_emsys_gestao_pendencia
	(empresa, caixa, data, turno, requisicao, conteudo, mlid, situacao, ts_geracao)
	VALUES
	(reg.empresa, reg.conta_debitar, reg.data, reg.turno, req, json, reg.mlid, sit_pend, ts_geracao);

	IF SCS = 'off' THEN
		set standard_conforming_strings = off;
	END IF;

	RETURN reg;
END;
  
$$;


ALTER FUNCTION public.movto_pendencia_tgf() OWNER TO postgres;

--
-- Name: nfe_inutilizacao_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nfe_inutilizacao_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
 	r RECORD;
 	json TEXT;
	SCS TEXT;
	cnpj_empresa_loc TEXT;
	empresa_loc BIGINT;
BEGIN
	SELECT grid FROM empresa_local INTO empresa_loc;
	SELECT somente_numero_f(cpf) FROM pessoa WHERE grid = empresa_loc INTO cnpj_empresa_loc;
	SELECT True INTO r FROM exchange_emsys_gestao_config_empresa WHERE empresa = empresa_loc;

	--Sair da funcao se a empresa nao for integrada ao EMSys Gestao, ou o registro nao for da empresa local, ou nao houver protocolo.
	IF NOT found OR NEW.emitente_cnpj <> cnpj_empresa_loc OR NEW.numero_protocolo IS NULL THEN
		RETURN NEW;
	END IF;

	json := '{
		"cnpj": "' || NEW.emitente_cnpj || '",
		"ano": ' || TO_CHAR(NEW.data, 'yyyy') || ',
		"modelo": ' || NEW.modelo_doc || ',
		"serie": "' || NEW.serie || '",
		"numIni": ' || NEW.numero_ini || ',
		"numFim": ' || NEW.numero_fim || ',
		"codigoSefaz": "102",
		"motivoSefaz": "Inutilizacao de numero homologado",
		"protocolo": {
			"numero": "' || NEW.numero_protocolo || '",
			"data": "' || TO_CHAR(NEW.ts_protocolo, 'yyyy-mm-dd') || '",
			"hora": "' || TO_CHAR(NEW.ts_protocolo, 'hh24:mi') || '"
		}';

	json := json || '}';

	--raise info 'JSON: %', json;
	SHOW standard_conforming_strings INTO SCS;

	IF SCS = 'off' THEN
		set standard_conforming_strings = on;
	END IF;

	json := regexp_replace(json, E'[\n\r\t]+', '', 'g');

	INSERT INTO exchange_emsys_gestao_pendencia
	(empresa, caixa, data, turno, requisicao, conteudo)
	VALUES
	(empresa_loc, '', NEW.data, 0, 'inutiliza', json);

	IF SCS = 'off' THEN
		set standard_conforming_strings = off;
	END IF;

	RETURN NEW;
END;
  
$$;


ALTER FUNCTION public.nfe_inutilizacao_pendencia_tgf() OWNER TO postgres;

--
-- Name: nome_forma_pgto_mlid_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nome_forma_pgto_mlid_f(bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

begin

	if (($1 is null) or ($1 = 0::bigint)) then

		return null;

	end if;



	select mm.nome into r from movto m join motivo_movto mm on (m.motivo=mm.grid) where

		m.mlid=$1 and mm.forma_pgto = true order by m.valor desc limit 1;

	

	if found then

		return r.nome;

	end if;



	return null;

end;
$_$;


ALTER FUNCTION public.nome_forma_pgto_mlid_f(bigint) OWNER TO postgres;

--
-- Name: nota_fiscal_produto_lancto_preencher(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nota_fiscal_produto_lancto_preencher() RETURNS boolean
    LANGUAGE plpgsql
    AS $$

declare
  v_lancto_grid BIGINT;
	rec_lancto RECORD;
	cur_lancto CURSOR
	FOR SELECT nfp.grid,
	nf.data_emissao,
	nfp.produto,
	nfp.quantidade,
	nfp.preco_unit,
	nfp.valor,
	nfp.empresa,
	nfp.numero_nota::text AS numero_nota,
	nfp.valor_desconto,
	nf.mlid,
	nf.grid as nf_grid
	FROM nota_fiscal nf
  JOIN nota_fiscal_produto nfp
    ON (nfp.nota_fiscal = nf.grid)
  JOIN nota_fiscal_situacao nfs
    ON (nfs.nota_fiscal = nf.grid)
  JOIN caixa_conf cc
    ON (cc.conta = nf.caixa_conta)
  JOIN exc_ipp_caixa_conf eicc
    ON (cc.grid = eicc.caixa_conf)
  JOIN produto p
    ON (p.grid = nfp.produto)
	WHERE nf.modelo IN ('55', '59', '65')
       AND nfs.situacao = '310'
       AND (CASE
               WHEN Length(Coalesce(nf.tipo_emitente, '')) != 0 THEN (
               CASE
                 WHEN nf.tipo_emitente = 'P' THEN '0'
                 ELSE '1'
               END)
               WHEN (Substr(nfp.cfop, 1, 1)::INT NOT IN (1, 2, 3)) THEN
               '0'
               ELSE '1'
             END ) = '0'
       AND nf.cfop NOT IN ('5.929', '6.929')
       AND nfp.lancto IS null
       ORDER BY data_emissao ASC;
BEGIN
  OPEN cur_lancto;

  LOOP

	  FETCH cur_lancto INTO rec_lancto;

	  EXIT WHEN NOT FOUND;

    v_lancto_grid := NULL;

    SELECT l.grid
    INTO v_lancto_grid
    FROM lancto l
    WHERE l.data = rec_lancto.data_emissao
    AND l.produto = rec_lancto.produto
    AND l.quantidade = rec_lancto.quantidade AND l.preco_unit = rec_lancto.preco_unit
    AND (l.valor + coalesce(desconto_venda_lancto_f(l.grid),0)) = rec_lancto.valor AND l.empresa = rec_lancto.empresa
    AND l.documento = rec_lancto.numero_nota AND l.valor_desconto = rec_lancto.valor_desconto
    AND l.mlid = rec_lancto.mlid AND not exists (SELECT nfp.lancto FROM nota_fiscal_produto nfp
    WHERE nfp.nota_fiscal = rec_lancto.nf_grid AND nfp.empresa = rec_lancto.empresa 
    AND nfp.produto = rec_lancto.produto AND nfp.lancto = l.grid);

    UPDATE nota_fiscal_produto
    SET lancto = v_lancto_grid
    WHERE grid = rec_lancto.grid
    AND empresa = rec_lancto.empresa;

  END LOOP;

  CLOSE cur_lancto;

  RETURN true;
END; 
   
$$;


ALTER FUNCTION public.nota_fiscal_produto_lancto_preencher() OWNER TO postgres;

--
-- Name: nota_fiscal_situacao_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.nota_fiscal_situacao_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
 	r RECORD;
 	r2 RECORD;
 	r_nf RECORD;
	r_pend RECORD;
	r_hist RECORD;
	r_info RECORD;
	r_propr RECORD;
 	c_nf_prod REFCURSOR;
 	json TEXT;
 	json_p TEXT;
 	json_prod TEXT;	
	json_trib_ICMS TEXT;
 	json_trib TEXT;
	json_trib_fcp TEXT;
 	tipo_nf INTEGER; --1: NF associada a Doc Fiscal; 2: NF de venda; 3: NF de uso e consumo
	req TEXT;
	sit_pend INTEGER;
	SCS TEXT;
	empresa_loc BIGINT;
	xml_proc TEXT;
	ts_geracao TIMESTAMP;
	km TEXT;
BEGIN
	SELECT grid FROM empresa_local INTO empresa_loc;
	SELECT True INTO r FROM exchange_emsys_gestao_config_empresa WHERE empresa = empresa_loc;

	--Sair da funcao se a empresa nao for integrada ao EMSys Gestao.
	--Sair da funcao tambem se for usuario emsys, paliativo para NFS-e :(.
	IF NOT found OR CURRENT_USER = 'emsys' THEN
		RETURN NEW;
	END IF;

	SELECT empresa, data_emissao INTO r FROM nota_fiscal WHERE grid = NEW.nota_fiscal;

	--Sair da funcao se o registro nao for da empresa local.
	IF r.empresa <> empresa_loc THEN
		RETURN NEW;
	END IF;

	SELECT True INTO r2
	FROM config
	WHERE empresa = empresa_loc
	AND chave = 'integracao_emsys_gestao_data_inicio'
	AND r.data_emissao < DATE(valor);

	-- Sair da funcao se a data do documento eh menor que a data de inicio da integracao.
	IF found THEN
		RETURN NEW;
	END IF;

	IF NEW.situacao NOT in (110, 310, 330) THEN
		--Sair da funcao se a nota nao estiver autorizada
		RETURN NEW;
	ELSE
		tipo_nf := 1;
		IF NEW.situacao in (310, 330) THEN
			req := 'notafiscal_registra';
		ELSE
			req := 'notafiscal_cancela';
		END IF;
	END IF;

	-- Verifica se eh uma NF-e associada a NFC-e ou CF-e
	SELECT 1 INTO r FROM nota_fiscal_referenciada WHERE nota_fiscal = NEW.nota_fiscal;

	IF NOT found THEN
		-- Verifica se eh uma NF associada a Cupom
		SELECT 1 INTO r FROM nota_fiscal_cupom WHERE nota_fiscal = NEW.nota_fiscal;

		IF NOT found THEN
			SELECT cfop INTO r2 FROM nota_fiscal WHERE grid = NEW.nota_fiscal;

			-- Verifica se eh uma NF de venda
			SELECT nf.modelo
				   ,nf.mlid
			  INTO r
			  FROM nota_fiscal nf
			  JOIN movto m
				ON (m.mlid = nf.mlid
			   AND m.motivo = (SELECT motivo FROM motivo_config WHERE chave = 'VENDA'))
			 WHERE nf.grid = NEW.nota_fiscal;

			-- Se nao for NF de venda e for CFOP de uso e consumo.
			IF NOT found AND r2.cfop in ('5.949', '5.927') THEN
				tipo_nf := 3;
				req := 'venda_atualizanf';
			ELSE
				-- Permite venda_atualizanf somente se nao for cupom.
				SELECT True FROM cupom_total WHERE mlid = r.mlid
				INTO r2;

				IF NOT found THEN
					tipo_nf := 2;
					req := 'venda_atualizanf';
				END IF;
			END IF;
		END IF;
	END IF;

	SELECT nf.grid AS id
		  ,m.grid AS movto_grid
		  ,cx.grid AS idTurno
		  ,COALESCE(somente_numero_f(COALESCE(nfpe.cpf, e.cpf, '')), '') AS cnpj
		  ,nf.data_emissao
		  ,to_char(nf.hora_saida, 'hh24:mi') AS hraEmissao
		  ,nf.modelo AS modelo
		  ,COALESCE(nfse.numero_nfse, nf.numero_nota::TEXT) AS numero
		  ,nfse.numero_rps
		  ,COALESCE(nfse.codigo_verificacao, '') AS codigo_verificacao
		  ,nl.numero AS numero_lote
		  ,COALESCE(nl.nr_recibo, '') AS protocolo_lote
		  ,COALESCE(cfe.serie_sat, nf.serie, '') AS serie
		  ,nf.cfop AS cfop
		  ,eegm.codigo AS cliente_id
		  ,nfpd.nome AS destinatario_nome
		  ,COALESCE(somente_numero_f(nfpd.cpf), '') AS destinatario_cnpjCpf
		  ,nfpd.inscr_est AS destinatario_inscr_est
		  ,COALESCE(nfpd.fone, '') AS destinatario_fone
		  ,nfpd.logradouro AS destinatario_logradouro
		  ,nfpd.numero AS destinatario_numero
		  ,COALESCE(nfpd.complemento, '') AS destinatario_complemento
		  ,nfpd.bairro AS destinatario_bairro
		  ,(SELECT m.nome FROM municipio m WHERE m.codigo = nfpd.municipio) AS destinatario_cidade
		  ,nfpd.municipio AS destinatario_municipio
		  ,nfpd.uf AS destinatario_uf
		  ,COALESCE(nfpd.cep, '') AS destinatario_cep
		  ,TO_CHAR(nf.data_emissao, 'yyyy-mm-dd') AS destinatario_dataCadastro
		  ,SUBSTRING(TRANSLATE(coalesce(nf.obs, ''), '·ÈÌÛ˙‡ËÏÚ˘„ı‚ÍÓÙ˚‰ÎÔˆ¸Á¡…Õ”⁄¿»Ã“Ÿ√’¬ Œ‘€ƒÀœ÷‹«', 
		  	'aeiouaeiouaoaeiouaeioucAEIOUAEIOUAOAEIOUAEIOUC'), 1 ,1250) AS obs_nota
		  ,nf.valor_desconto AS vlrDesconto
		  ,abs(nf.valor_acrescimo) AS vlrAcrescimo
		  ,nf.valor_nota AS vlrTotal
		  ,COALESCE(cfe.chave_acesso, nfe.chave_acesso, '') AS chave
		  ,COALESCE(cfe.serie_sat, '') AS serie_sat
		  ,COALESCE(CASE 
						WHEN NEW.situacao = 110 and nf.modelo != 59 THEN
							'101'
						ELSE
							COALESCE(nfe.retorno::text, mi.retorno)
					END, '0') AS codigoSefaz
		  ,COALESCE(CASE
						WHEN NEW.situacao = 110 and nf.modelo != 59 THEN
							'Cancelamento de NF-e homologado.'
						ELSE
							COALESCE(nfemr.nome, mmr.nome)
					END, '') AS motivoSefaz
		  ,COALESCE(CASE
						WHEN NEW.situacao = 110 THEN
							SUBSTR(nfs.obs, 1, 100)
						ELSE
							NULL
					END, '') AS motivoCanc
		  ,nfep.numero AS protocoloAut_numero
		  ,TO_CHAR(nfep.ts, 'yyyy-mm-dd') AS protocoloAut_data
		  ,TO_CHAR(nfep.ts, 'hh24:mi') AS protocoloAut_hora
		  ,nfepc.numero AS protocoloCan_numero
		  ,TO_CHAR(nfepc.ts, 'yyyy-mm-dd') AS protocoloCan_data
		  ,TO_CHAR(nfepc.ts, 'hh24:mi') AS protocoloCan_hora
		  ,COALESCE(m.grid, nfr.nf_referenciada, nfc.cupom) AS documentosRef_id
		  ,(CASE 
				WHEN c.grid IS NOT NULL THEN
					'2D'
				ELSE
					nfr.modelo_doc
			END) AS documentosRef_modelo
		  ,COALESCE(c.nr_cupom, nfr.numero_nota) AS documentosRef_numero
		  ,(CASE 
				WHEN c.grid IS NOT NULL THEN
					''
				WHEN nfr.modelo_doc = '59' THEN
					SUBSTR(regexp_replace(nf.caixa_conta, '[^0-9]', '', 'g'), length(regexp_replace(nf.caixa_conta, '[^0-9]', '', 'g'))-2, length(regexp_replace(nf.caixa_conta, '[^0-9]', '', 'g')))
				ELSE 
					nfr.serie
			END) AS documentosRef_serie
		  ,COALESCE(nfr.nfe_chave_acesso, nfr.cfe_chave_acesso, '') AS documentosRef_chave
		  ,ENCODE(
				CONVERT_TO(
					TRANSLATE(
						COALESCE(nfeex.fonte_xml, cfex.fonte_xml, nfex.fonte_xml, nfsex.fonte_xml), 
						'·ÈÌÛ˙‡ËÏÚ˘„ı‚ÍÓÙ˚‰ÎÔˆ¸Á¡…Õ”⁄¿»Ã“Ÿ√’¬ Œ‘€ƒÀœ÷‹«',
						'aeiouaeiouaoaeiouaeioucAEIOUAEIOUAOAEIOUAEIOUC'
					),
					'UTF-8'
				), 
				'base64'
			) AS xml
		  ,ENCODE(CONVERT_TO(cfex.fonte_xml_cancelado, 'UTF-8'), 'base64') AS xml_canc_cfe
		  ,cfe.chave_acesso_cancelamento AS chave_canc_cfe
		  ,nf.empresa
		  ,cx.data
		  ,cx.turno
		  ,cx.conta AS caixa
		  ,eegmv.codigo as vendedor_codigo
		  ,vend.nome AS vendedor_nome
		  ,eegmo.codigo as operador_codigo
		  ,oper.nome AS operador_nome
		  ,nf.placa::TEXT
		  ,nf.km
		  ,nf.mlid
		  ,COALESCE(nfe.versao, '4.00') AS versao
		  ,COALESCE(nfep.versao_sefaz, '0') AS protocoloAut_versao_sefaz
		  ,nfep.ts_proc AS protocoloAut_ts_proc
		  ,nfep.digest AS protocoloAut_digest
		  ,nfe.tipo_ambiente
		  ,STRPOS(nfex.fonte_xml, chr(60) || 'nfeProc versao=') AS protocoloAut_pos_ini
		  ,STRPOS(nfex.fonte_xml, chr(60) || '/nfeProc' || chr(62)) AS protocoloAut_pos_fim
		  ,COALESCE(nfeex.fonte_xml, cfex.fonte_xml, nfex.fonte_xml, nfsex.fonte_xml) AS fonte_xml
		  ,nfs.situacao AS nf_sit
		  ,nf.modelo_doc
	  INTO r_nf
	  FROM nota_fiscal nf
	  JOIN empresa e ON (e.grid = nf.empresa)
	  LEFT JOIN nota_fiscal_pessoa nfpe ON (nf.emitente = nfpe.grid)
	  JOIN nota_fiscal_situacao nfs ON (nf.grid = nfs.nota_fiscal)
	  LEFT JOIN nota_fiscal_pessoa nfpd ON (nf.destinatario = nfpd.grid)
	  LEFT JOIN nfe ON (nfe.nota_fiscal = nf.grid)
	  LEFT JOIN nfe_mensagem_retorno nfemr ON (nfemr.codigo = nfe.retorno)
	  LEFT JOIN nfe_protocolo nfep ON (nfep.nfe = nfe.grid
	  		AND nfep.tipo_protocolo in (1,2))
	  LEFT JOIN nfe_protocolo nfepc ON (nfepc.nfe = nfe.grid
	  		AND nfepc.tipo_protocolo = 3)
	  LEFT JOIN nfe_xml nfex ON (nfex.nfe = nfe.grid)
	  LEFT JOIN cfe ON cfe.nota_fiscal = nf.grid
	  LEFT JOIN cfe_xml cfex ON cfex.cfe = cfe.grid
	  LEFT JOIN mide mi ON mi.grid = cfe.mide
	  LEFT JOIN mide_mensagem_retorno mmr ON mmr.codigo = mi.retorno
	  LEFT JOIN nfse ON (nfse.nota_fiscal = nf.grid)
	  LEFT JOIN nfse_lote_nfse nln ON (nln.nfse = nfse.grid)
	  LEFT JOIN nfse_lote nl ON (nl.grid = nln.lote)
	  LEFT JOIN nfse_xml nfsex ON (nfsex.nfse = nfse.grid)
	  LEFT JOIN nfe_evento nfee ON (nfee.nfe = nfe.grid
	  		AND nfee.tipo = 110111)
	  LEFT JOIN nfe_evento_xml nfeex ON (nfeex.nfe_evento = nfee.grid)
	  LEFT JOIN exchange_emsys_gestao_map eegm ON (eegm.pessoa = nfpd.pessoa)
	  LEFT JOIN caixa cx ON (nf.caixa_conta = cx.conta
	  		AND nf.caixa_data = cx.data
	  		AND nf.caixa_turno = cx.turno)
	  LEFT JOIN movto m ON (m.mlid = nf.mlid
	  		AND m.motivo in (SELECT motivo FROM motivo_config WHERE chave in ('VENDA', 'PONTO_TROCADO_BRINDE')))
	  LEFT JOIN nota_fiscal_referenciada nfr ON (nfr.nota_fiscal = nf.grid)
	  LEFT JOIN nota_fiscal_cupom nfc ON (nfc.nota_fiscal = nf.grid)
	  LEFT JOIN cupom c ON (nfc.cupom = c.grid)
	  LEFT JOIN pessoa oper ON oper.grid = cx.pessoa
	  LEFT JOIN exchange_emsys_gestao_map eegmv ON eegmv.pessoa = cx.pessoa
	  LEFT JOIN pessoa vend ON vend.grid = cx.pessoa
	  LEFT JOIN exchange_emsys_gestao_map eegmo ON eegmo.pessoa = cx.pessoa
	 WHERE nf.modelo IN (55, 59, 65, 99)
	   AND nf.grid = NEW.nota_fiscal;

	IF NOT FOUND THEN
		--Sair da funcao se o documento nao for NF-e, NFC-e ou NFS-e
		RETURN new;
	END IF;

	json := '{';

	--Demanda: 88251 - Notas Cancelas nao estao integrando com EMSYS
	--Segundo o Jackson Ramos Braga, o erro da demanda acima havia sido corrigido.
	--Foi conversado como Mariel de quando isso acontecesse seria enviado o id nulo e a situacao cancelada.
	--No cenario, verificamos que o usuario apos demora na resposta do Sefaz fecha o caixa pelo gerenciador de tarefas.
	--Ocorre o envio da nota cancelada e o mlid. Assim, neste caso, e enviado o ID incorretamente para o EMSYS.

	IF (tipo_nf = 1) THEN
		json := json || '"id": ' || r_nf.id || ', ';
	ELSIF (tipo_nf = 2) THEN
		--ATENCAO: Leia a Nota acima
		IF r_nf.movto_grid IS NOT NULL THEN
			json := json || '"id": ' || r_nf.movto_grid || ', ';
		ELSE
			--Se for aprovada e nao tem id, veio da nota_fiscal_pendente.
			--Enquanto o mide_proc nao processar o status final, nao manda pra integracao --Essa e a primeira nota em que devera ser cancelada ou inutilizada.
			IF NEW.situacao in (310, 330) and r_nf.modelo in(55,65,59,99) THEN
				RETURN new;
			END IF;
			
			json := json || '"id": null, ';
		END IF;
	ELSE
		json := json || '"id": ' || r_nf.mlid || ', ';
	END IF;

	IF r_nf.idTurno IS NOT NULL THEN
		json := json || '"idTurno": ' || r_nf.idTurno || ', ';
	END IF;

	IF r_nf.caixa IS NOT NULL THEN
		json := json || '"numCaixa": "' || r_nf.caixa || '", ';
	END IF;

	IF r_nf.turno IS NOT NULL THEN
		json := json || '"numTurno": ' || r_nf.turno || ', ';
	END IF;

	json := json || '
		"cnpj": "' || r_nf.cnpj || '",
		"dtaEmissao": "' || to_char(r_nf.data_emissao, 'yyyy-mm-dd') || '",
		"hraEmissao": "' || r_nf.hraEmissao || '",
		"modelo": ' || r_nf.modelo || ',
		"numero": ' || r_nf.numero || ',
		"serie": "' || r_nf.serie || '",
		"msgNota": "' || REPLACE(REPLACE(REPLACE(r_nf.obs_nota, CHR(92), ''), CHR(34), ''), CHR(39), '') || '",
		"cfop": ' || replace(r_nf.cfop, '.', '') || ', ';

	IF (tipo_nf = 2) THEN
		json := json || '"usoConsumo": false, ';
	ELSIF (tipo_nf = 3) THEN
		json := json || '"usoConsumo": true, ';
	END IF;

	--Insere as informaÁıes de vendedor
	IF r_nf.vendedor_codigo IS NOT NULL THEN
		json := json || '"vendedor": {';
		json := json || '"id": ' || r_nf.vendedor_codigo || ',';
		json := json || '"nome": "' || REPLACE(REPLACE(REPLACE(r_nf.vendedor_nome, CHR(92), ''), CHR(34), ''), CHR(39), '') || '"';
		json := json || '}, ';
	END IF;

	--Insere as informaÁıes de operador
	IF r_nf.operador_codigo IS NOT NULL THEN
		json := json || '"operador": {';
		json := json || '"id": ' || r_nf.operador_codigo || ',';
		json := json || '"nome": "' || REPLACE(REPLACE(REPLACE(r_nf.operador_nome, CHR(92), ''), CHR(34), ''), CHR(39), '') || '"';
		json := json || '}, ';
	END IF;

	-- Insere as informaÁıes de Cliente
	json := json || '"cliente": {';

	IF r_nf.cliente_id is NOT null THEN
		IF r_nf.destinatario_nome is NOT null THEN
			json := json || '"id": ' || r_nf.cliente_id || ',';
		ELSE
			json := json || '"id": ' || r_nf.cliente_id || '';
		END IF;
	END IF;

	IF r_nf.destinatario_nome is NOT null THEN
		json := json || '
			"nome": "' || REPLACE(REPLACE(REPLACE(r_nf.destinatario_nome, CHR(92), ''), CHR(34), ''), CHR(39), '') || '",
			"cnpjCpf": "' || r_nf.destinatario_cnpjCpf || '"';
	END IF;
	
	json := json || '}, ';

	-- Envia os dados da pessoaSimples para que o EMSys faca o cadastro.
	IF r_nf.cliente_id IS NULL AND r_nf.modelo = 55 THEN
		json := json || '
			"pessoaSimples": {
				"nome": "' || REPLACE(REPLACE(REPLACE(r_nf.destinatario_nome, CHR(92), ''), CHR(34), ''), CHR(39), '') || '",
				"nomeFantasia": "' || REPLACE(REPLACE(REPLACE(r_nf.destinatario_nome, CHR(92), ''), CHR(34), ''), CHR(39), '') || '",
				"cnpjCpf": "' || r_nf.destinatario_cnpjCpf || '",
				"ie": "' || r_nf.destinatario_inscr_est || '",
				"rg": null,
				"fone": "' || r_nf.destinatario_fone || '",
				"celular": null,
				"email": null,
				"endereco": {
					"logradouro": "' || r_nf.destinatario_logradouro || '",
					"numero": "' || r_nf.destinatario_numero || '",
					"complemento": "' || r_nf.destinatario_complemento || '",
					"bairro": "' || r_nf.destinatario_bairro || '",
					"cidade": "' || r_nf.destinatario_cidade || '",
					"ibge": ' || r_nf.destinatario_municipio || ',
					"uf": "' || r_nf.destinatario_uf || '",
					"cep": "' || r_nf.destinatario_cep || '"
				},
				"dataNascimento": null,
				"dataCadastro": "' || r_nf.destinatario_dataCadastro || '",
				"cnpjEmpresaCad": "' || r_nf.cnpj || '"
			},';
	END IF;

	IF (tipo_nf <> 1) THEN
		-- Obtendo os dados das informaÁıes gerais da venda.	
		SELECT m.obs AS obs
			  ,movto_info_f(m.grid, 'km') AS km
			  ,movto_info_f(m.grid, 'placa') AS placa
			  ,movto_info_f(m.grid, 'motorista') AS motorista
			  ,movto_info_f(m.grid, 'frota') AS frota
			  ,movto_info_f(m.grid, 'veiculo') AS veiculo
			  ,movto_info_f(m.grid, 'propr_rural') AS propr_rural
		  INTO r_info
		  FROM movto m
		 WHERE m.motivo = (SELECT motivo FROM motivo_config WHERE chave = 'VENDA')
		   AND m.mlid = r_nf.mlid;
		   
		IF r_info.placa IS NOT NULL OR REPLACE(r_info.placa, CHR(92), '') <> '' THEN
			json := json || '"placa": "' || REPLACE(REPLACE(REPLACE(r_info.placa, CHR(92), ''), CHR(34), ''), CHR(39), '') || '", ';
		END IF;

		IF r_info.km IS NOT NULL AND r_info.km <> '' THEN
			km := LTRIM(REGEXP_REPLACE(r_info.km, '[^0-9.]', '', 'g'), '0');

			IF km NOT IN ('', '.') THEN
				IF (POSITION('.' IN km)) > 0 THEN
					json := json || '"km": "' || SUBSTRING(km FROM 1 FOR POSITION('.' IN km)-1) || '", ';
				ELSE
					json := json || '"km": "' || km || '", ';
				END IF;
			END IF;
		END IF;

		IF r_info.motorista IS NOT NULL AND r_info.motorista <> '' THEN
			json := json || '"motorista": "' || REPLACE(REPLACE(REPLACE(r_info.motorista, CHR(92), ''), CHR(34), ''), CHR(39), '') || '", ';
		END IF;
		IF r_info.propr_rural IS NOT NULL AND r_info.propr_rural <> '' THEN
			SELECT propriedade_rural into r_propr FROM pessoa_propriedade_rural WHERE grid = r_info.propr_rural::bigint;
			IF FOUND THEN
				json := json || '"idPropriedadeRural": ' || r_propr.propriedade_rural || ', ';
			END IF;
		END IF;
		IF r_info.frota IS NOT NULL AND r_info.frota <> '' THEN
			json := json || '"frota": "' || REPLACE(REPLACE(REPLACE(r_info.frota, CHR(92), ''), CHR(34), ''), CHR(39), '') || '", ';
		END IF;
		IF r_info.veiculo IS NOT NULL AND r_info.veiculo <> '' THEN
			json := json || '"veiculo": "' || REPLACE(REPLACE(REPLACE(r_info.veiculo, CHR(92), ''), CHR(34), ''), CHR(39), '') || '", ';
		END IF;
	END IF;

	json := json || '
		"vlrDesconto": ' || r_nf.vlrDesconto || ',
		"vlrAcrescimo": ' || r_nf.vlrAcrescimo || ',
		"vlrTotal": ' || r_nf.vlrTotal || ',
		"chave": "' || r_nf.chave || '",
		"serieSat": "' || r_nf.serie_sat || '",
		"cancelado": ' || (case when NEW.situacao in (310, 330) THEN 'false' ELSE 'true' END) ||',
		"codigoSefaz": "' || r_nf.codigoSefaz || '",
		"motivoSefaz": "' || r_nf.motivoSefaz || '",';

	IF r_nf.protocoloAut_numero IS NOT NULL THEN
		json := json || '
			"protocoloAut": {
				"numero": "' || r_nf.protocoloAut_numero || '",
				"data": "' || r_nf.protocoloAut_data || '",
				"hora": "' || r_nf.protocoloAut_hora || '"
			}, ';
	END IF;

	IF NEW.situacao = 110 THEN
		json := json || '"motivoCanc": "' || regexp_replace(r_nf.motivoCanc, E'[^0-9A-Za-z\s]', '', 'g') || '",';

		IF r_nf.protocoloCan_numero IS NOT NULL THEN
			json := json || '
				"protocoloCan": {
					"numero": "' || r_nf.protocoloCan_numero || '",
					"data": "' || r_nf.protocoloCan_data || '",
					"hora": "' || r_nf.protocoloCan_hora || '"
				}, ';
		END IF;

		IF r_nf.chave_canc_cfe IS NOT NULL THEN
			json := json || '
				"cancelamentoCFe": {
					"chave": "' || r_nf.chave_canc_cfe || '",
					"xml": "' || r_nf.xml_canc_cfe || '"
				}, ';
		END IF;
	END IF;

	IF r_nf.numero_rps IS NOT NULL THEN
		json := json || '
			"rps": { 
				"numero": ' || r_nf.numero_rps || ', 
				"codigoVerificacao": "' || r_nf.codigo_verificacao || '", 
				"protocoloLote": "' || r_nf.protocolo_lote || '", 
				"numeroLote": "' || r_nf.numero_lote || '"
			}, ';
	END IF;

	json := json || '"itens": [';
	json_prod = '';

	OPEN c_nf_prod FOR
		SELECT
			nfp.numero_item AS itens_seqItem,
			coalesce(p.codigo, nfp.codigo) AS itens_id,
			COALESCE(nfp.codigo_barra, '') AS itens_codBarra,
			nfp.descricao AS itens_descricao,
			nfp.cfop AS itens_cfop,
			COALESCE(nfp.quantidade, 0) AS itens_quantidade,
			nfp.unid_med AS itens_unidade,
			COALESCE(nfp.preco_unit, 0) AS itens_vlrUnitario,
			COALESCE(nfp.valor, 0) AS itens_vlrBruto,
			COALESCE(nfp.valor_desconto, 0) AS itens_vlrDesconto,
			COALESCE(nfp.valor_acrescimo, 0) AS itens_vlrAcrescimo,
			(COALESCE(nfp.valor,0) - COALESCE(nfp.valor_desconto,0) + COALESCE(nfp.valor_acrescimo,0)) AS itens_vlrTotal,
			nfp.cst AS cst_icms,
			nfp.cst_ipi,
			nfp.cst_pis,
			nfp.cst_cofins,
			COALESCE(nfp.aliquota_icms, 0) AS aliquota_icms,
			COALESCE(nfp.aliquota_ipi, 0) AS aliquota_ipi,
			COALESCE(nfp.aliquota_pis, 0) AS aliquota_pis,
			COALESCE(nfp.aliquota_cofins, 0) AS aliquota_cofins,
			COALESCE(nfp.aliquota_iss, 0) AS aliquota_iss,
			COALESCE(t.reducao_base,0) AS trib_reducao,
			COALESCE(nfp.perc_red_base_icms,0) AS perc_red_base_icms,
			nfp.base_icms,
			(case when nfp.cst_ipi is NOT null THEN nfp.preco_unit * nfp.quantidade ELSE 0 END) AS base_ipi,
			COALESCE(nfp.base_pis, 0) AS base_pis,
			COALESCE(nfp.base_cofins, 0) AS base_cofins,
			COALESCE(nfp.base_iss, 0) AS base_iss,
			COALESCE(nfp.valor_icms, 0) AS valor_icms,
			COALESCE(nfp.valor_ipi, 0) AS valor_ipi,
			COALESCE(nfp.valor_pis, 0) AS valor_pis,
			COALESCE(nfp.valor_cofins, 0) AS valor_cofins,
			COALESCE(nfp.valor_iss, 0) AS valor_iss,
			COALESCE(nfp.valor_icms_deson, 0) AS valor_icms_deson,
			COALESCE(nfp.ad_rem, 0) AS ad_rem,
			(nfp.quantidade * COALESCE(nfp.ad_rem, 0)) AS valor_icms_mono,
			nfp.quantidade AS qtd_icms_mono,
			COALESCE(nfp.aliquota_fcp, 0) as aliquota_fcp,
			COALESCE(nfp.valor_fcp, 0) as valor_fcp,
			COALESCE(nfp.valor_st_fcp, 0) as valor_st_fcp,
			COALESCE(nfp.valor_st_ret_fcp, 0) as valor_st_ret_fcp,
			COALESCE(nfp.base_subst, 0) as base_subst,
			COALESCE(nfp.base_subst, nfp.base_subst_destaque, 0) as base_st_ret,
			nfp.cst_ibs_cbs,
			nfp.classificacao_ibs_cbs,
			nfp.base_ibs_cbs,
			COALESCE(nfp.aliquota_cbs, 0) AS aliquota_cbs,
			COALESCE(nfp.perc_red_cbs, 0) AS perc_red_cbs,
			COALESCE(nfp.perc_dif_cbs, 0) AS perc_dif_cbs,
			COALESCE(nfp.valor_cbs, 0) AS valor_cbs,
			COALESCE(nfp.aliquota_ibs_uf, 0) AS aliquota_ibs_uf,
			COALESCE(nfp.perc_red_ibs_uf, 0) AS perc_red_ibs_uf,
			COALESCE(nfp.perc_dif_ibs_uf, 0) AS perc_dif_ibs_uf,
			COALESCE(nfp.valor_ibs_uf, 0) AS valor_ibs_uf,
			COALESCE(nfp.aliquota_ibs_mun, 0) AS aliquota_ibs_mun,
			COALESCE(nfp.perc_red_ibs_mun, 0) AS perc_red_ibs_mun,
			COALESCE(nfp.perc_dif_ibs_mun, 0) AS perc_dif_ibs_mun,
			COALESCE(nfp.valor_ibs_mun, 0) AS valor_ibs_mun,
			COALESCE(nfp.codigo_ncm, '') AS codigo_ncm,
			COALESCE(nfp.cest, '') AS cest,
			COALESCE(nfp.codigo_beneficio, '') AS codigo_beneficio,
			(SELECT d.codigo FROM lancto l LEFT JOIN deposito d ON (d.grid = l.deposito) WHERE l.grid = nfp.lancto LIMIT 1) AS deposito_codigo
		FROM 
			nota_fiscal_produto nfp
			   JOIN produto p on (p.grid = nfp.produto)
			   JOIN tributacao t on (t.codigo = p.tributacao)
		WHERE 
			nfp.nota_fiscal = NEW.nota_fiscal;

	LOOP
		FETCH c_nf_prod INTO r;
		EXIT WHEN NOT found;

		json_p := '{
			"seqItem": ' || r.itens_seqItem || ',
			"id": ' || r.itens_id || ',
			"codBarra": "' || r.itens_codBarra || '",
			"descricao": "' || replace(replace(r.itens_descricao, Chr(34), ''), Chr(92), '') || '",
			"cfop": ' || replace(r.itens_cfop, '.', '') || ',
			"quantidade": ' || r.itens_quantidade || ',
			"unidade": "' || r.itens_unidade || '",
			"vlrUnitario": ' || r.itens_vlrUnitario || ',
			"vlrBruto": ' || r.itens_vlrBruto || ',
			"vlrDesconto": ' || r.itens_vlrDesconto || ',
			"vlrAcrescimo": ' || r.itens_vlrAcrescimo || ',
			"vlrTotal": ' || r.itens_vlrTotal || ',';

		IF r.codigo_ncm IS NOT NULL THEN
			json_p := json_p || '"ncm": "' || r.codigo_ncm || '", ';
		END IF;

		IF r.cest IS NOT NULL THEN
			json_p := json_p || '"cest": "' || r.cest || '", ';
		END IF;

		IF r.codigo_beneficio IS NOT NULL THEN
			json_p := json_p || '"cBenef": "' || r.codigo_beneficio || '", ';
		END IF;

		IF r.deposito_codigo IS NOT NULL THEN
			json_p := json_p || '"idAlmoxarifado": ' || r.deposito_codigo || ', ';
		END IF;

		IF tipo_nf <> 1 THEN
			json_p := json_p || '
				"vlrDescontoRat": 0,
				"vlrAcrescimoRat": 0,
				"cancelado": false,
				';
		END IF;

		json_trib := '';

		-- Se forem feitos ajustes nos impostos, tambÈm dever„o ser ajustados no arquivo de venda.
		-- Class BuilderVenda.__build_tributacao_nota()
		-- Com o SAP (Rede Sim) vamos precisar enviar as mesmas informaÁıes dos impostos no venda_registra.

		IF r.cst_pis IS NOT NULL THEN
			json_trib := json_trib || '{
				"tipo": "PIS",
				"cst": "' || r.cst_pis || '",
				"aliquota": ' || r.aliquota_pis || ',
				"reducao": ' || 0 || ',
				"bc": ' || r.base_pis || ',
				"valor": ' || r.valor_pis || '
			}';
		END IF;

		IF r.cst_cofins IS NOT NULL THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "COFINS",
				"cst": "' || r.cst_cofins || '",
				"aliquota": ' || r.aliquota_cofins || ',
				"reducao": ' || 0 || ',
				"bc": ' || r.base_cofins || ',
				"valor": ' || r.valor_cofins || '
			}';
		END IF;

		IF r.base_iss = 0 or r.base_iss IS NULL THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			IF r.cst_icms = '061' THEN
				json_trib := json_trib || '{
					"tipo": "ICMS",
					"aliquota": "0",
					"reducao": "0",
					"bc": "0",
					"cst": "' || r.cst_icms || '",
					"perIcmsMono": ' || r.ad_rem || ',
					"valIcmsMonoRet": ' || r.valor_icms_mono || ',
					"qtdBcIcmsMonoRet": ' || r.qtd_icms_mono || '
				}';

			ELSE
				json_trib_fcp = '';

				IF r.cst_icms = '000' THEN 
					IF r.aliquota_fcp > 0 THEN
						json_trib_fcp := '
							"bcFcp": ' || r.base_icms || ',
							"perFcp": ' || r.aliquota_fcp || ',
							"fcp": ' || r.valor_fcp || '
						';
					END IF;

				ELSIF r.cst_icms in ('010', '020', '070') THEN

					IF r.aliquota_fcp > 0 and r.base_icms > 0 THEN
						json_trib_fcp := '
							"bcFcp": ' || r.base_icms || ',
							"perFcp": ' || r.aliquota_fcp || ',
							"fcp": ' || r.valor_fcp || '
						';
					END IF;

					IF r.aliquota_fcp > 0 and r.base_subst > 0 THEN
						json_trib_fcp := json_trib_fcp || '
							"bcFcpSt": ' || r.base_subst || ',
							"perFcpSt": ' || r.aliquota_fcp || ',
							"fcpSt": ' || r.valor_st_fcp - r.valor_fcp || '
						';
					END IF;

				ELSIF r.cst_icms = '030' THEN

					IF r.aliquota_fcp > 0 and r.base_subst > 0 THEN
						json_trib_fcp := '
							"bcFcpSt": ' || r.base_subst || ',
							"perFcpSt": ' || r.aliquota_fcp || ',
							"fcpSt": ' || r.valor_st_fcp || '
						';
					END IF;

				ELSIF r.cst_icms = '060' THEN

					IF r.aliquota_fcp > 0 THEN
						json_trib_fcp := '
							"bcFcpStRet": ' || r.base_st_ret || ',
							"perFcpStRet": ' || r.aliquota_fcp || ',
							"fcpStRet": ' || r.valor_st_ret_fcp || '
						';
					END IF;

				ELSIF r.cst_icms = '090' THEN

					IF r.aliquota_fcp > 0 and r.base_icms > 0 THEN
						json_trib_fcp := '
							"bcFcp": ' || r.base_icms || ',
							"perFcp": ' || r.aliquota_fcp || ',
							"fcp": ' || r.valor_fcp || '
						';
					END IF;

					IF r_nf.modelo_doc != '65' and r.aliquota_fcp > 0 and r.base_subst > 0 THEN
						json_trib_fcp := json_trib_fcp || '
							"bcFcpSt": ' || r.base_subst || ',
							"perFcpSt": ' || r.aliquota_fcp || ',
							"fcpSt": ' || r.valor_st_fcp || '
						';
					END IF;

				END IF;

				json_trib_ICMS := '
					"tipo": "ICMS",
					"cst": "' || r.cst_icms || '",
					"aliquota": ' || r.aliquota_icms || ',
					"reducao": ' || r.perc_red_base_icms || ',
					"bc": ' || r.base_icms || ',
					"valor": ' || r.valor_icms || ',
					"vICMSDeson": ' || r.valor_icms_deson || '

				';

				IF json_trib_fcp <> '' THEN
					json_trib_ICMS := json_trib_ICMS || ',' || json_trib_fcp;
				END IF;

				json_trib := json_trib || '{' ||
					json_trib_ICMS ||
				'}';
			END IF;


		END IF;

		IF r.cst_ipi IS NOT NULL THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "IPI",
				"cst": "' || r.cst_ipi || '",
				"aliquota": ' || r.aliquota_ipi || ',
				"reducao": ' || 0 || ',
				"bc": ' || r.base_ipi || ',
				"valor": ' || r.valor_ipi || '
			}';
		END IF;

		IF r.base_iss IS NOT NULL AND r.base_iss > 0 THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "ISS",
				"aliquota": ' || r.aliquota_iss || ',
				"reducao": ' || 0 || ',
				"bc": ' || r.base_iss || ',
				"valor": ' || r.valor_iss || ',
				"cst": "090"
			}';
		END IF;


		IF (r.base_ibs_cbs IS NOT NULL AND r.valor_cbs > 0) OR r.cst_ibs_cbs = '620' THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "CBS",
				"cst": "' || r.cst_ibs_cbs || '",
				"codClassTrib": "' || r.classificacao_ibs_cbs || '",
				"aliquota": ' || r.aliquota_cbs || ',
				"reducao": ' || r.perc_red_cbs || ',
				"pDif": ' || r.perc_dif_cbs || ',
				"bc": ' || r.base_ibs_cbs || ',
				"valor": ' || r.valor_cbs || '
			}';
		END IF;

		IF (r.base_ibs_cbs IS NOT NULL AND r.valor_cbs > 0) OR r.cst_ibs_cbs = '620' THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "IBSUF",
				"cst": "' || r.cst_ibs_cbs || '",
				"codClassTrib": "' || r.classificacao_ibs_cbs || '",
				"aliquota": ' || r.aliquota_ibs_uf || ',
				"reducao": ' || r.perc_red_ibs_uf || ',
				"pDif": ' || r.perc_dif_ibs_uf || ',
				"bc": ' || r.base_ibs_cbs || ',
				"valor": ' || r.valor_ibs_uf || '
			}';
		END IF;

		IF (r.base_ibs_cbs IS NOT NULL AND r.valor_cbs > 0) OR r.cst_ibs_cbs = '620' THEN
			IF json_trib <> '' THEN
				json_trib := json_trib || ',';
			END IF;

			json_trib := json_trib || '{
				"tipo": "IBSMUN",
				"cst": "' || r.cst_ibs_cbs || '",
				"codClassTrib": "' || r.classificacao_ibs_cbs || '",
				"aliquota": ' || r.aliquota_ibs_mun || ',
				"reducao": ' || r.perc_red_ibs_mun || ',
				"pDif": ' || r.perc_dif_ibs_mun || ',
				"bc": ' || r.base_ibs_cbs || ',
				"valor": ' || r.valor_ibs_mun || '
			}';
		END IF;

		json_p := json_p || '"tributacoes": [' || json_trib || ']}';

		--raise info 'JSON_P: %', json_p;
		json_prod := json_prod || json_p || ', ';
	END LOOP;

	CLOSE c_nf_prod;

	json_prod := substr(json_prod, 1, length(json_prod) - 2);
	IF json_prod <> '' THEN
		json := json || json_prod || ']';
	ELSE
		json := json || ']';
	END IF;

	IF (tipo_nf = 1) THEN
		json := json || ', 
			"documentosRef":[
				{
					"id": ' || r_nf.documentosRef_id || ', 
					"modelo": "' || r_nf.documentosRef_modelo || '", 
					"numero": "' || r_nf.documentosRef_numero || '", 
					"serie": "' || r_nf.documentosRef_serie || '", 
					"chave": "' || r_nf.documentosRef_chave || '"
				}
			]';
	END IF;

	SHOW standard_conforming_strings INTO SCS;

	IF SCS = 'off' THEN
		set standard_conforming_strings = on;
	END IF;

	IF r_nf.xml IS NOT NULL THEN
		IF r_nf.modelo IN(55,65) and r_nf.nf_sit in (310, 330) and r_nf.protocoloAut_pos_ini=0 and r_nf.protocoloAut_pos_fim=0 THEN
			xml_proc = ENCODE(
				CONVERT_TO(
					chr(60)||'?xml version="1.0" encoding="UTF-8" ?'||chr(62)||
					chr(60)||'nfeProc versao="'||r_nf.versao||'" xmlns="http://www.portalfiscal.inf.br/nfe"'||chr(62)
					||r_nf.fonte_xml||
					chr(60)||'protNFe versao="'||r_nf.versao||'"'||chr(62)||
					chr(60)||'infProt Id="ID'||r_nf.protocoloAut_numero||'"'||chr(62)||
					chr(60)||'tpAmb'||chr(62)||r_nf.tipo_ambiente||chr(60)||'/tpAmb'||chr(62)||
					chr(60)||'verAplic'||chr(62)||r_nf.protocoloAut_versao_sefaz||chr(60)||'/verAplic'||chr(62)||
					chr(60)||'chNFe'||chr(62)||r_nf.chave||chr(60)||'/chNFe'||chr(62)||
					chr(60)||'dhRecbto'||chr(62)||TO_CHAR(r_nf.protocoloAut_ts_proc, 'yyyy-mm-dd')||'T'||TO_CHAR(r_nf.protocoloAut_ts_proc, 'hh24:mi:ss')||
					(SELECT SUBSTRING(now()::TEXT, length(now()::TEXT)-2, length(now()::TEXT)))||':00'||chr(60)||'/dhRecbto'||chr(62)||
					chr(60)||'nProt'||chr(62)||r_nf.protocoloAut_numero||chr(60)||'/nProt'||chr(62)||
					chr(60)||'digVal'||chr(62)||r_nf.protocoloAut_digest||chr(60)||'/digVal'||chr(62)||
					chr(60)||'cStat'||chr(62)||'100'||chr(60)||'/cStat'||chr(62)||
					chr(60)||'xMotivo'||chr(62)||'Autorizado o uso da NF-e.'||chr(60)||'/xMotivo'||chr(62)||
					chr(60)||'/infProt'||chr(62)||chr(60)||'/protNFe'||chr(62)||
					chr(60)||'/nfeProc'||chr(62)
				,'UTF-8')
			,'base64');

			IF xml_proc IS NOT NULL THEN
				json := json || ', "xml": "' || xml_proc || '"';
			ELSE
				json := json || ', "xml": "' || r_nf.xml || '"';
			END IF;

		ELSE
			json := json || ', "xml": "' || r_nf.xml || '"';
		END IF;
	END IF;

	json := json || '}';
	json := regexp_replace(json, E'[\n\r\t]+', '', 'g');

	-- Dois selects abaixo ser„o para localizar se a Venda j· foi enviada para a pendencia ou se j· foi processada e armazenada na historico.
	-- Quando È POS (DTEF ou Auttar) o venda registra È inserido na pendencia depois do venda_atualizanf. Com isso a requisiÁ„o venda_atualizanf fica presa no painel
	SELECT True AS valor INTO r_pend
	  FROM exchange_emsys_gestao_pendencia eegp
	 WHERE true 
	   AND eegp.mlid = r_nf.mlid
	   AND eegp.requisicao = 'venda_registra';
	
	SELECT True AS valor INTO r_hist
	  FROM exchange_emsys_gestao_pendencia_historico eegph
	 WHERE true
	   AND eegph.mlid = r_nf.mlid
	   AND eegph.requisicao='venda_registra';

	ts_geracao = now()+ interval '1 minutes';

	-- Se nao encontrou a venda referente o documento na tabela de pendencia a mesma ja foi enviada.
	IF (r_hist.valor) AND (r_pend IS NULL) THEN
		sit_pend := 1;
	ELSE
		sit_pend := 6;
	END IF;

	-- Se estiver gerando uma notafiscal_registra e ja houver na base, altera para notafiscal_atualiza.
	IF req = 'notafiscal_registra' THEN
		SELECT True
		FROM exchange_emsys_gestao_pendencia
		WHERE mlid = r_nf.mlid
		AND requisicao = 'notafiscal_registra'
		AND nota_fiscal = NEW.nota_fiscal
		UNION
		SELECT True
		FROM exchange_emsys_gestao_pendencia_historico
		WHERE mlid = r_nf.mlid
		AND requisicao = 'notafiscal_registra'
		AND nota_fiscal = NEW.nota_fiscal
		INTO r;

		IF found THEN
			req := 'notafiscal_atualiza';
		END IF;
	END IF;

	SELECT ativar_integracao_sap INTO r FROM exchange_emsys_gestao_config WHERE ativar_integracao_sap;
	IF r.ativar_integracao_sap THEN
		IF req = 'venda_atualizanf' and NEW.situacao NOT IN(310) THEN
			RETURN NEW;
		END IF;

		IF req = 'notafiscal_atualiza' THEN
			RETURN NEW;
		END IF;

	END IF;

	INSERT INTO exchange_emsys_gestao_pendencia 
	(empresa, caixa, data, turno, requisicao, conteudo, mlid, situacao, nota_fiscal, ts_geracao) 
	VALUES 
	(r_nf.empresa, coalesce(r_nf.caixa, ''), coalesce(r_nf.data, r_nf.data_emissao), coalesce(r_nf.turno, 0), req, json, r_nf.mlid, sit_pend, NEW.nota_fiscal, ts_geracao);

	IF SCS = 'off' THEN
		set standard_conforming_strings = off;
	END IF;

	RETURN new;
END;
  
$$;


ALTER FUNCTION public.nota_fiscal_situacao_pendencia_tgf() OWNER TO postgres;

