--
-- Name: pessoa_credito_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.pessoa_credito_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER TABLE public.pessoa_credito_seq OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: pessoa_credito; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.pessoa_credito (
    id bigint DEFAULT nextval('public.pessoa_credito_seq'::regclass) NOT NULL,
    pessoa_id bigint,
    motivo_movto_id bigint,
    conta_codigo text,
    conta_nome text,
    cpf text DEFAULT ''::text,
    bloqueado boolean DEFAULT false,
    ilimitado boolean DEFAULT false,
    valor_limite double precision,
    limite_pendencia double precision,
    tolerancia double precision,
    exibir_credito_venda boolean,
    nvias_cnfv integer,
    emite_nf boolean,
    bloqueio_nf boolean,
    vende_produtos_diferentes_tipos boolean,
    emite_apenas_nf boolean,
    tipo_vencimento integer,
    empresa_id bigint,
    assinatura_digital boolean,
    prazo integer,
    prazo_fatura integer
);


ALTER TABLE public.pessoa_credito OWNER TO postgres;

--
-- Name: pessoa_credito_f(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_credito_f(bigint, bigint, bigint) RETURNS SETOF public.pessoa_credito
    LANGUAGE plpgsql
    AS $_$

	DECLARE
		t1 pessoa_credito;
	BEGIN
		FOR t1 IN
			SELECT DISTINCT ON (empresa_id, pessoa_id, motivo_movto_id, conta_codigo) id, pessoa_id, motivo_movto_id, conta_codigo, 
				conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, 
				bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura FROM
			(
				SELECT 
					NULL as id,
					p.grid AS pessoa_id,
					mm.grid as motivo_movto_id,
					c.codigo AS conta_codigo,
					c.nome as conta_nome,
					p.cpf,
					p.bloqueado,
					(pc.lim_credito IS NULL) AS ilimitado,
					pc.lim_credito AS valor_limite,
					pc.lim_pendencia AS limite_pendencia,
					cast(pc.tolerancia as DOUBLE PRECISION) AS tolerancia,
					pc.exibir_credito_venda AS exibir_credito_venda,
					pc.pessoa_nvias_cnfv AS nvias_cnfv,
					pc.emite_nf AS emite_nf,
					pc.bloqueia_nota AS bloqueio_nf,
					pc.permite_venda_produtos_tipos_diferentes AS vende_produtos_diferentes_tipos,
					pc.apenas_nf_venda_obrigatoria AS emite_apenas_nf,
					pc.tipo AS tipo_vencimento,
					$1 as empresa_id,
					pc.assinatura_digital,
					NULL AS grupo,
					pc.prazo,
					pc.prazo_fatura
				FROM pessoa p
					LEFT JOIN pessoa_empresa pe ON (pe.pessoa = p.grid)
					JOIN pessoa_conta pc ON (pc.pessoa = p.grid AND (pc.empresa=$1 OR pc.empresa IS NULL))
					JOIN conta c ON (pc.conta = c.codigo)
					JOIN motivo_movto mm ON (mm.conta_debitar = pc.conta)
				WHERE p.flag = 'A'
					AND (pe.empresa = $1 OR pe.empresa IS NULL)
					AND (CASE WHEN $2 IS NOT NULL THEN p.grid = $2 ELSE true END)
				UNION ALL
				SELECT 
					NULL as id,
					p.grid AS pessoa_id,
					mm.grid as motivo_movto_id,
					c.codigo AS conta_codigo,
					c.nome as conta_nome,
					p.cpf,
					p.bloqueado,
					(gpc.lim_credito IS NULL) AS ilimitado,
					gpc.lim_credito AS valor_limite,
					gpc.lim_pendencia AS limite_pendencia,
					cast(gpc.tolerancia as DOUBLE PRECISION) as tolerancia,
					gpc.exibir_credito_venda AS exibir_credito_venda,
					gpc.pessoa_nvias_cnfv AS nvias_cnfv,
					gpc.emite_nf AS emite_nf,
					gpc.bloqueia_nota AS bloqueio_nf,
					gpc.permite_venda_produtos_tipos_diferentes AS vende_produtos_diferentes_tipos,
					gpc.apenas_nf_venda_obrigatoria AS emite_apenas_nf,
					gpc.tipo AS tipo_vencimento,
					$1 as empresa_id,
					gpc.assinatura_digital,
					gpc.grupo,
					gpc.prazo,
					gpc.prazo_fatura
				FROM pessoa p
					LEFT JOIN pessoa_empresa pe ON (pe.pessoa = p.grid)
					JOIN grupo_pessoa_conta gpc ON (gpc.grupo = p.grupo AND (gpc.empresa=$1 OR GPC.empresa IS NULL))
					JOIN conta c ON (gpc.conta = c.codigo)
					JOIN motivo_movto mm ON (mm.conta_debitar = gpc.conta)
				WHERE p.flag = 'A'
					AND (pe.empresa = $1 OR pe.empresa IS NULL)
					AND (CASE WHEN $2 IS NOT NULL THEN p.grid = $2 ELSE true END)
					AND (CASE WHEN $3 IS NOT NULL THEN p.grupo = $3 ELSE true END)
			) AS TAB
			ORDER BY empresa_id, pessoa_id, motivo_movto_id, conta_codigo, grupo DESC
		LOOP
			RETURN NEXT t1; 
		END LOOP;
	END;
	
$_$;


ALTER FUNCTION public.pessoa_credito_f(bigint, bigint, bigint) OWNER TO postgres;

--
-- Name: pessoa_credito_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_credito_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;
        ex BOOLEAN;

        emp BIGINT;

        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;
    BEGIN
        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;
        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;
        ELSE
            rec := NEW;
            rec_old := rec;
        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;

        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;
        IF NOT FOUND THEN
            SELECT seq INTO pk FROM pessoa_credito_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE pessoa_credito_sync;
                PERFORM setval('pessoa_credito_sync_seq', 1);
            END IF;
            RETURN rec;
        END IF;

        ex := TG_OP = 'DELETE';
        rel := TG_RELNAME;

        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        IF rel NOT IN ('pessoa_credito') THEN
            pk := rec.grid;
            -- Aqui nesse delete tem uma perda de performance, vamos remover a responsabilidade da movto limpar a sync
            IF rel <> 'movto' THEN
                DELETE FROM pessoa_credito_sync 
                WHERE ts::date BETWEEN (now() - '300 days'::interval) AND (now() - '30 days'::interval);
            END IF;
        ELSE
            pk := rec.id;
        END IF;

        IF rel = 'movto' THEN

            IF rec.pessoa IS NOT NULL THEN
                SELECT grid INTO sub FROM pessoa_conta WHERE pessoa = rec.pessoa AND conta = rec.conta_debitar;
                IF FOUND THEN
                    DELETE FROM pessoa_credito WHERE pessoa_id = rec.pessoa;
                    FOR sub IN SELECT * FROM pessoa_credito_f(emp, rec.pessoa, NULL)
                    LOOP
                        INSERT INTO pessoa_credito 
                        (pessoa_id, motivo_movto_id, conta_codigo, conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura) 
                        VALUES
                        (sub.pessoa_id, sub.motivo_movto_id, sub.conta_codigo, sub.conta_nome, sub.cpf, sub.bloqueado, sub.ilimitado, sub.valor_limite, sub.limite_pendencia, sub.tolerancia, sub.exibir_credito_venda, sub.nvias_cnfv, sub.emite_nf, sub.bloqueio_nf, sub.vende_produtos_diferentes_tipos, sub.emite_apenas_nf, sub.tipo_vencimento, sub.empresa_id, sub.assinatura_digital, sub.prazo, sub.prazo_fatura);
                    END LOOP;
                END IF;
            END IF;

            RETURN rec;

        ELSIF rel = 'pessoa' THEN

            IF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN

                DELETE FROM pessoa_credito WHERE pessoa_id = rec.grid;
                FOR sub IN SELECT * FROM pessoa_credito_f(emp, rec.grid, NULL)
                LOOP
                    INSERT INTO pessoa_credito 
                    (pessoa_id, motivo_movto_id, conta_codigo, conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura) 
                    VALUES
                    (sub.pessoa_id, sub.motivo_movto_id, sub.conta_codigo, sub.conta_nome, sub.cpf, sub.bloqueado, sub.ilimitado, sub.valor_limite, sub.limite_pendencia, sub.tolerancia, sub.exibir_credito_venda, sub.nvias_cnfv, sub.emite_nf, sub.bloqueio_nf, sub.vende_produtos_diferentes_tipos, sub.emite_apenas_nf, sub.tipo_vencimento, sub.empresa_id, sub.assinatura_digital, sub.prazo, sub.prazo_fatura);
                END LOOP;

            ELSIF TG_OP = 'DELETE' OR ex = TRUE THEN
                DELETE FROM pessoa_credito WHERE pessoa_id = rec.grid;
            END IF;
            
            RETURN rec;

        ELSIF rel = 'pessoa_conta' THEN

            DELETE FROM pessoa_credito WHERE pessoa_id = rec.pessoa;
            FOR sub IN SELECT * FROM pessoa_credito_f(emp, rec.pessoa, NULL)
            LOOP
                INSERT INTO pessoa_credito 
                (pessoa_id, motivo_movto_id, conta_codigo, conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura) 
                VALUES
                (sub.pessoa_id, sub.motivo_movto_id, sub.conta_codigo, sub.conta_nome, sub.cpf, sub.bloqueado, sub.ilimitado, sub.valor_limite, sub.limite_pendencia, sub.tolerancia, sub.exibir_credito_venda, sub.nvias_cnfv, sub.emite_nf, sub.bloqueio_nf, sub.vende_produtos_diferentes_tipos, sub.emite_apenas_nf, sub.tipo_vencimento, sub.empresa_id, sub.assinatura_digital, sub.prazo, sub.prazo_fatura);
            END LOOP;

            RETURN rec;
        ELSIF rel = 'grupo_pessoa_conta' THEN

            DELETE FROM pessoa_credito WHERE pessoa_id IN (SELECT p.grid FROM pessoa p WHERE p.grupo = rec.grupo);
            FOR sub IN SELECT * FROM pessoa_credito_f(emp, NULL, rec.grupo)
            LOOP
                INSERT INTO pessoa_credito 
                (pessoa_id, motivo_movto_id, conta_codigo, conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura) 
                VALUES
                (sub.pessoa_id, sub.motivo_movto_id, sub.conta_codigo, sub.conta_nome, sub.cpf, sub.bloqueado, sub.ilimitado, sub.valor_limite, sub.limite_pendencia, sub.tolerancia, sub.exibir_credito_venda, sub.nvias_cnfv, sub.emite_nf, sub.bloqueio_nf, sub.vende_produtos_diferentes_tipos, sub.emite_apenas_nf, sub.tipo_vencimento, sub.empresa_id, sub.assinatura_digital, sub.prazo, sub.prazo_fatura);
            END LOOP;
        
            RETURN rec;
        ELSIF rel = 'motivo_config' THEN

            IF rec.chave = 'NOTA_PRAZO' THEN
                DELETE FROM pessoa_credito WHERE motivo_movto_id = rec.motivo;
                FOR sub IN SELECT * FROM pessoa_credito_f(emp, NULL, NULL)
                LOOP
                    INSERT INTO pessoa_credito 
                    (pessoa_id, motivo_movto_id, conta_codigo, conta_nome, cpf, bloqueado, ilimitado, valor_limite, limite_pendencia, tolerancia, exibir_credito_venda, nvias_cnfv, emite_nf, bloqueio_nf, vende_produtos_diferentes_tipos, emite_apenas_nf, tipo_vencimento, empresa_id, assinatura_digital, prazo, prazo_fatura) 
                    VALUES
                    (sub.pessoa_id, sub.motivo_movto_id, sub.conta_codigo, sub.conta_nome, sub.cpf, sub.bloqueado, sub.ilimitado, sub.valor_limite, sub.limite_pendencia, sub.tolerancia, sub.exibir_credito_venda, sub.nvias_cnfv, sub.emite_nf, sub.bloqueio_nf, sub.vende_produtos_diferentes_tipos, sub.emite_apenas_nf, sub.tipo_vencimento, sub.empresa_id, sub.assinatura_digital, sub.prazo, sub.prazo_fatura);
                END LOOP;
            END IF;

            RETURN rec;
        END IF;

        BEGIN
            INSERT INTO pessoa_credito_sync (pkey, excluido) VALUES (pk, ex);

        EXCEPTION WHEN unique_violation THEN

            UPDATE pessoa_credito_sync SET seq = NEXTVAL('pessoa_credito_sync'), excluido = ex, ts = now() WHERE pkey = pk;
        END;

        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.pessoa_credito_sync_tgf() OWNER TO postgres;

--
-- Name: pessoa_flag_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_flag_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

	BEGIN

		IF (NEW.flag != OLD.flag) THEN

			NEW.ts_flag := now();

		END IF;

		Return NEW;

	END;
  
$$;


