--
-- Name: pessoa_id_identfid_add(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_id_identfid_add() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE var_existe_cartao BOOLEAN;  BEGIN SELECT count(*) > 0 INTO var_existe_cartao FROM rfid_cartao rc WHERE numero_cartao = NEW.id; IF not var_existe_cartao THEN INSERT INTO identfid_comando(comando, chave, ts, libera_bomba) VALUES ('I', NEW.id, to_char(now(), 'yyyy-mm-dd hh24:mi:ss')::timestamp, (SELECT rfid_libera_bomba FROM identificacao WHERE grid=NEW.tipo_id)); END IF;  RETURN null; END; $$;


ALTER FUNCTION public.pessoa_id_identfid_add() OWNER TO postgres;

--
-- Name: pessoa_id_identfid_change(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_id_identfid_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$ DECLARE var_existe_cartao BOOLEAN;  BEGIN SELECT count(*) > 0 INTO var_existe_cartao FROM rfid_cartao rc WHERE numero_cartao = NEW.id; IF not var_existe_cartao THEN INSERT INTO identfid_comando(comando, chave, ts, libera_bomba) VALUES ('U', OLD.id || '->' || NEW.id, to_char(now(), 'yyyy-mm-dd hh24:mi:ss')::timestamp, (SELECT rfid_libera_bomba FROM identificacao WHERE grid=NEW.tipo_id)); END IF;  RETURN null; END; $$;


ALTER FUNCTION public.pessoa_id_identfid_change() OWNER TO postgres;

--
-- Name: pessoa_id_identfid_delete(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_id_identfid_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$  BEGIN INSERT INTO identfid_comando(comando, chave, ts) VALUES ('D', OLD.id, to_char(now(), 'yyyy-mm-dd hh24:mi:ss')::timestamp); RETURN null; END; $$;


ALTER FUNCTION public.pessoa_id_identfid_delete() OWNER TO postgres;

