--
-- Name: pessoa_tipo_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pessoa_tipo_f(bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
select (case when tipo like 'F%' then 'Fornecedor' else (case when tipo like 'U%' then 'Funcion·rio' else (case when tipo like 'C%' then 'Cliente' else 'Empresa' end) end) end) from pessoa where grid = $1;
$_$;


