--
-- Name: pgd_delete_abastecimento_fiscal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_delete_abastecimento_fiscal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN OLD;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO abastecimento_fiscal_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,codigo,bico,bomba,bomba_codigo,tanque_codigo,quantidade,preco_unit,valor,data_hora,enc_ini,enc_fim,dia_fiscal,flag_info,cupom,operacao,produto_nome,paf_hash) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'D',OLD.grid,OLD.empresa,OLD.codigo,OLD.bico,OLD.bomba,OLD.bomba_codigo,OLD.tanque_codigo,OLD.quantidade,OLD.preco_unit,OLD.valor,OLD.data_hora,OLD.enc_ini,OLD.enc_fim,OLD.dia_fiscal,OLD.flag_info,OLD.cupom,OLD.operacao,OLD.produto_nome,OLD.paf_hash);
	RETURN OLD;
END;
$$;


ALTER FUNCTION public.pgd_delete_abastecimento_fiscal() OWNER TO postgres;

