--
-- Name: pgd_delete_caixa_conf_bico(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_delete_caixa_conf_bico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN OLD;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO caixa_conf_bico_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,conta,bico,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'D',OLD.conta,OLD.bico,OLD.grid);
	RETURN OLD;
END;
$$;


ALTER FUNCTION public.pgd_delete_caixa_conf_bico() OWNER TO postgres;

