--

CREATE FUNCTION public.pgd_delete_rfid_log() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN OLD;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO rfid_log_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,leitor,cartao,pessoa,status,data,registro,operacao,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'D',OLD.leitor,OLD.cartao,OLD.pessoa,OLD.status,OLD.data,OLD.registro,OLD.operacao,OLD.grid);
	RETURN OLD;
END;
$$;


ALTER FUNCTION public.pgd_delete_rfid_log() OWNER TO postgres;

