--
-- Name: pgd_distrib_table(character varying, smallint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_distrib_table(character varying, smallint) RETURNS void
    LANGUAGE sql
    AS $_$
insert into pgd_tables (tablename, ordem) values ($1, $2);
$_$;


ALTER FUNCTION public.pgd_distrib_table(character varying, smallint) OWNER TO postgres;

--
-- Name: pgd_gxid_f(integer, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_gxid_f(integer, bigint) RETURNS bigint
    LANGUAGE sql
    AS $_$
/*  2^32 = 4294967296 */
SELECT int8(int4($1) * 4294967296::int8) + int8($2)
$_$;


ALTER FUNCTION public.pgd_gxid_f(integer, bigint) OWNER TO postgres;

--
-- Name: pgd_insert(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE 
	r RECORD;
	cuname TEXT := '';
	grid BIGINT;

BEGIN
	SELECT current_user INTO r;

	-- Usuario distro nao dispara a trigger
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;

	-- Identifica o usuario que esta fazendo a transacao
	--SELECT current_user_name() INTO r;
	
	--IF NOT r.current_user_name IS NULL THEN
	--	cuname := r.current_user_name;
	--END IF;

	-- Pega um novo grid para o registro adicionado
	SELECT pgd_gxid_f(pgd_sid, nextval('pgd_rid_seq'::text)::int4) AS next_grid INTO r FROM pgd_lsite;
	grid := r.next_grid;

	NEW.grid := grid;
	RETURN NEW;
END;
$$;


ALTER FUNCTION public.pgd_insert() OWNER TO postgres;

