	gfid := r.next_gfid;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq'::text)::int8) AS next_grid 		INTO r FROM pgd_lsite;
	NEW.grid := r.next_grid;
	INSERT INTO exc_brpremmia_resgate_transacao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,transaction_id,alternative_code,mlid,status,cpf,produtos_json,transacao_json,qrcode_base64) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'I',NEW.grid,NEW.transaction_id,NEW.alternative_code,NEW.mlid,NEW.status,NEW.cpf,NEW.produtos_json,NEW.transacao_json,NEW.qrcode_base64);
	RETURN NEW;
END;
$$;


