	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq'::text)::int8) AS next_grid 		INTO r FROM pgd_lsite;
	NEW.grid := r.next_grid;
