--
-- Name: pgd_insert_produto_cfop(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_insert_produto_cfop() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq'::text)::int8) AS next_grid 		INTO r FROM pgd_lsite;
	NEW.grid := r.next_grid;
	INSERT INTO produto_cfop_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,produto,natureza_op,cfop,de,uf,cst,emsys) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'I',NEW.grid,NEW.produto,NEW.natureza_op,NEW.cfop,NEW.de,NEW.uf,NEW.cst,NEW.emsys);
	RETURN NEW;
END;
$$;


