--
-- Name: pgd_rid_f(bigint); Type: FUNCTION; Schema: public; Owner: distro
--

CREATE FUNCTION public.pgd_rid_f(bigint) RETURNS integer
    LANGUAGE sql
    AS $_$
/*  2^32 = 4294967296 */
select int4($1 - int8($1 / 4294967296::int8) * 4294967296::int8)
$_$;


ALTER FUNCTION public.pgd_rid_f(bigint) OWNER TO distro;

--
-- Name: pgd_sid_f(bigint); Type: FUNCTION; Schema: public; Owner: distro
--

CREATE FUNCTION public.pgd_sid_f(bigint) RETURNS integer
    LANGUAGE sql
    AS $_$
/*  2^32 = 4294967296 */
select int4($1 / 4294967296::int8)
$_$;


