CREATE FUNCTION public.pgd_update_abastecimento_fiscal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.bico IS DISTINCT FROM OLD.bico OR NEW.bomba IS DISTINCT FROM OLD.bomba OR NEW.bomba_codigo IS DISTINCT FROM OLD.bomba_codigo OR NEW.tanque_codigo IS DISTINCT FROM OLD.tanque_codigo OR NEW.quantidade IS DISTINCT FROM OLD.quantidade OR NEW.preco_unit IS DISTINCT FROM OLD.preco_unit OR NEW.valor IS DISTINCT FROM OLD.valor OR NEW.data_hora IS DISTINCT FROM OLD.data_hora OR NEW.enc_ini IS DISTINCT FROM OLD.enc_ini OR NEW.enc_fim IS DISTINCT FROM OLD.enc_fim OR NEW.dia_fiscal IS DISTINCT FROM OLD.dia_fiscal OR NEW.flag_info IS DISTINCT FROM OLD.flag_info OR NEW.cupom IS DISTINCT FROM OLD.cupom OR NEW.operacao IS DISTINCT FROM OLD.operacao OR NEW.produto_nome IS DISTINCT FROM OLD.produto_nome OR NEW.paf_hash IS DISTINCT FROM OLD.paf_hash) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO abastecimento_fiscal_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,codigo,bico,bomba,bomba_codigo,tanque_codigo,quantidade,preco_unit,valor,data_hora,enc_ini,enc_fim,dia_fiscal,flag_info,cupom,operacao,produto_nome,paf_hash) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.empresa,OLD.codigo,OLD.bico,OLD.bomba,OLD.bomba_codigo,OLD.tanque_codigo,OLD.quantidade,OLD.preco_unit,OLD.valor,OLD.data_hora,OLD.enc_ini,OLD.enc_fim,OLD.dia_fiscal,OLD.flag_info,OLD.cupom,OLD.operacao,OLD.produto_nome,OLD.paf_hash);
	INSERT INTO abastecimento_fiscal_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,codigo,bico,bomba,bomba_codigo,tanque_codigo,quantidade,preco_unit,valor,data_hora,enc_ini,enc_fim,dia_fiscal,flag_info,cupom,operacao,produto_nome,paf_hash) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.empresa,NEW.codigo,NEW.bico,NEW.bomba,NEW.bomba_codigo,NEW.tanque_codigo,NEW.quantidade,NEW.preco_unit,NEW.valor,NEW.data_hora,NEW.enc_ini,NEW.enc_fim,NEW.dia_fiscal,NEW.flag_info,NEW.cupom,NEW.operacao,NEW.produto_nome,NEW.paf_hash);
	RETURN NEW;
END;
$$;


