CREATE FUNCTION public.pgd_update_bico() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.nome IS DISTINCT FROM OLD.nome OR NEW.deposito IS DISTINCT FROM OLD.deposito OR NEW.tipo_preco IS DISTINCT FROM OLD.tipo_preco OR NEW.casa_decimal_pu IS DISTINCT FROM OLD.casa_decimal_pu OR NEW.enc_ini IS DISTINCT FROM OLD.enc_ini OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.ilha IS DISTINCT FROM OLD.ilha OR NEW.desconto IS DISTINCT FROM OLD.desconto OR NEW.grid IS DISTINCT FROM OLD.grid OR NEW.ctf IS DISTINCT FROM OLD.ctf OR NEW.bomba IS DISTINCT FROM OLD.bomba OR NEW.bico_arla IS DISTINCT FROM OLD.bico_arla) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO bico_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,nome,deposito,tipo_preco,casa_decimal_pu,enc_ini,empresa,ilha,desconto,grid,ctf,bomba,bico_arla) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.nome,OLD.deposito,OLD.tipo_preco,OLD.casa_decimal_pu,OLD.enc_ini,OLD.empresa,OLD.ilha,OLD.desconto,OLD.grid,OLD.ctf,OLD.bomba,OLD.bico_arla);
	INSERT INTO bico_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,nome,deposito,tipo_preco,casa_decimal_pu,enc_ini,empresa,ilha,desconto,grid,ctf,bomba,bico_arla) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.nome,NEW.deposito,NEW.tipo_preco,NEW.casa_decimal_pu,NEW.enc_ini,NEW.empresa,NEW.ilha,NEW.desconto,NEW.grid,NEW.ctf,NEW.bomba,NEW.bico_arla);
	RETURN NEW;
END;
$$;


