ALTER FUNCTION public.pgd_update_config_geral() OWNER TO postgres;

--
-- Name: pgd_update_config_tef_geral(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_config_tef_geral() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.desativa_parcelamento IS DISTINCT FROM OLD.desativa_parcelamento OR NEW.tipo_parcelamento IS DISTINCT FROM OLD.tipo_parcelamento) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO config_tef_geral_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,desativa_parcelamento,tipo_parcelamento) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.empresa,OLD.desativa_parcelamento,OLD.tipo_parcelamento);
	INSERT INTO config_tef_geral_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,desativa_parcelamento,tipo_parcelamento) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.empresa,NEW.desativa_parcelamento,NEW.tipo_parcelamento);
	RETURN NEW;
END;
$$;


