BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.pai IS DISTINCT FROM OLD.pai OR NEW.nome IS DISTINCT FROM OLD.nome OR NEW.saldo_inicial IS DISTINCT FROM OLD.saldo_inicial OR NEW.credor IS DISTINCT FROM OLD.credor OR NEW.lancar IS DISTINCT FROM OLD.lancar OR NEW.pendencia IS DISTINCT FROM OLD.pendencia OR NEW.programacao IS DISTINCT FROM OLD.programacao OR NEW.pesquisa_vencto IS DISTINCT FROM OLD.pesquisa_vencto OR NEW.tipo_conta_receber IS DISTINCT FROM OLD.tipo_conta_receber OR NEW.tipo_conta_pagar IS DISTINCT FROM OLD.tipo_conta_pagar OR NEW.tipo_despesa IS DISTINCT FROM OLD.tipo_despesa OR NEW.impedir_saldo_negativo IS DISTINCT FROM OLD.impedir_saldo_negativo OR NEW.tolerancia_saldo_negativo IS DISTINCT FROM OLD.tolerancia_saldo_negativo OR NEW.controle_limite IS DISTINCT FROM OLD.controle_limite OR NEW.grid IS DISTINCT FROM OLD.grid OR NEW.imprimir IS DISTINCT FROM OLD.imprimir OR NEW.livro_caixa IS DISTINCT FROM OLD.livro_caixa OR NEW.limite_credito_pessoa_fisica IS DISTINCT FROM OLD.limite_credito_pessoa_fisica OR NEW.limite_credito_pessoa_juridica IS DISTINCT FROM OLD.limite_credito_pessoa_juridica OR NEW.exibir_credito_venda IS DISTINCT FROM OLD.exibir_credito_venda OR NEW.conta_analitica IS DISTINCT FROM OLD.conta_analitica OR NEW.validar_alinea IS DISTINCT FROM OLD.validar_alinea OR NEW.compensar_movto IS DISTINCT FROM OLD.compensar_movto OR NEW.codigo_reduzido IS DISTINCT FROM OLD.codigo_reduzido OR NEW.aprovar_lancamento IS DISTINCT FROM OLD.aprovar_lancamento OR NEW.controlar_saldo_limite IS DISTINCT FROM OLD.controlar_saldo_limite OR NEW.saldo_limite IS DISTINCT FROM OLD.saldo_limite) THEN
		RETURN NEW;
