-- Name: pgd_update_exc_mapa_resumo(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_exc_mapa_resumo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.data_emissao IS DISTINCT FROM OLD.data_emissao OR NEW.pagina IS DISTINCT FROM OLD.pagina OR NEW.grid IS DISTINCT FROM OLD.grid) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO exc_mapa_resumo_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,empresa,data_emissao,pagina,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.empresa,OLD.data_emissao,OLD.pagina,OLD.grid);
	INSERT INTO exc_mapa_resumo_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,empresa,data_emissao,pagina,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.empresa,NEW.data_emissao,NEW.pagina,NEW.grid);
	RETURN NEW;
END;
$$;


