-- Name: pgd_update_exc_poshcash_voucher(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_exc_poshcash_voucher() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.mlid IS DISTINCT FROM OLD.mlid OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.hora IS DISTINCT FROM OLD.hora OR NEW.voucher IS DISTINCT FROM OLD.voucher OR NEW.sessao IS DISTINCT FROM OLD.sessao OR NEW.valor_desconto IS DISTINCT FROM OLD.valor_desconto OR NEW.estacao IS DISTINCT FROM OLD.estacao) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO exc_poshcash_voucher_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,mlid,empresa,hora,voucher,sessao,valor_desconto,estacao) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.mlid,OLD.empresa,OLD.hora,OLD.voucher,OLD.sessao,OLD.valor_desconto,OLD.estacao);
	INSERT INTO exc_poshcash_voucher_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,mlid,empresa,hora,voucher,sessao,valor_desconto,estacao) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.mlid,NEW.empresa,NEW.hora,NEW.voucher,NEW.sessao,NEW.valor_desconto,NEW.estacao);
	RETURN NEW;
END;
$$;


