-- Name: pgd_update_exc_wincash_usuario(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_exc_wincash_usuario() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.grid IS DISTINCT FROM OLD.grid OR NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.nome IS DISTINCT FROM OLD.nome OR NEW.cpf IS DISTINCT FROM OLD.cpf OR NEW.data_criacao IS DISTINCT FROM OLD.data_criacao OR NEW.data_alteracao IS DISTINCT FROM OLD.data_alteracao) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO exc_wincash_usuario_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,empresa,grid,codigo,nome,cpf,data_criacao,data_alteracao) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.empresa,OLD.grid,OLD.codigo,OLD.nome,OLD.cpf,OLD.data_criacao,OLD.data_alteracao);
	INSERT INTO exc_wincash_usuario_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,empresa,grid,codigo,nome,cpf,data_criacao,data_alteracao) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.empresa,NEW.grid,NEW.codigo,NEW.nome,NEW.cpf,NEW.data_criacao,NEW.data_alteracao);
	RETURN NEW;
END;
$$;


