CREATE FUNCTION public.pgd_update_exchange_emsys_gestao_config_empresa() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.reprocessamento_estoque_todas IS DISTINCT FROM OLD.reprocessamento_estoque_todas OR NEW.reprocessamento_estoque_filial IS DISTINCT FROM OLD.reprocessamento_estoque_filial OR NEW.movimentacao_estoque_filial IS DISTINCT FROM OLD.movimentacao_estoque_filial OR NEW.movimentacao_estoque_todas IS DISTINCT FROM OLD.movimentacao_estoque_todas OR NEW.tipo_saldo IS DISTINCT FROM OLD.tipo_saldo OR NEW.periodo IS DISTINCT FROM OLD.periodo OR NEW.horario IS DISTINCT FROM OLD.horario OR NEW.turno IS DISTINCT FROM OLD.turno OR NEW.desabilitar_estoque_combustivel_todas IS DISTINCT FROM OLD.desabilitar_estoque_combustivel_todas OR NEW.desabilitar_estoque_combustivel_filial IS DISTINCT FROM OLD.desabilitar_estoque_combustivel_filial OR NEW.desabilitar_estoque_lmc_filial IS DISTINCT FROM OLD.desabilitar_estoque_lmc_filial OR NEW.desabilitar_estoque_lmc_todas IS DISTINCT FROM OLD.desabilitar_estoque_lmc_todas OR NEW.inventario_estoque_filial IS DISTINCT FROM OLD.inventario_estoque_filial OR NEW.inventario_estoque_todas IS DISTINCT FROM OLD.inventario_estoque_todas) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
