	INSERT INTO exchange_emsys_gestao_config_empresa_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,reprocessamento_estoque_todas,reprocessamento_estoque_filial,movimentacao_estoque_filial,movimentacao_estoque_todas,tipo_saldo,periodo,horario,turno,desabilitar_estoque_combustivel_todas,desabilitar_estoque_combustivel_filial,desabilitar_estoque_lmc_filial,desabilitar_estoque_lmc_todas,inventario_estoque_filial,inventario_estoque_todas) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.empresa,NEW.reprocessamento_estoque_todas,NEW.reprocessamento_estoque_filial,NEW.movimentacao_estoque_filial,NEW.movimentacao_estoque_todas,NEW.tipo_saldo,NEW.periodo,NEW.horario,NEW.turno,NEW.desabilitar_estoque_combustivel_todas,NEW.desabilitar_estoque_combustivel_filial,NEW.desabilitar_estoque_lmc_filial,NEW.desabilitar_estoque_lmc_todas,NEW.inventario_estoque_filial,NEW.inventario_estoque_todas);
	RETURN NEW;
END;
$$;


