CREATE FUNCTION public.pgd_update_grupo_credito() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.nome IS DISTINCT FROM OLD.nome OR NEW.credito_padrao IS DISTINCT FROM OLD.credito_padrao OR NEW.credito_max IS DISTINCT FROM OLD.credito_max OR NEW.grid IS DISTINCT FROM OLD.grid) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO grupo_credito_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,codigo,nome,credito_padrao,credito_max,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.codigo,OLD.nome,OLD.credito_padrao,OLD.credito_max,OLD.grid);
	INSERT INTO grupo_credito_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,codigo,nome,credito_padrao,credito_max,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.codigo,NEW.nome,NEW.credito_padrao,NEW.credito_max,NEW.grid);
	RETURN NEW;
END;
$$;


