-- Name: pgd_update_mide(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_mide() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.retorno IS DISTINCT FROM OLD.retorno OR NEW.arquivo_danfe IS DISTINCT FROM OLD.arquivo_danfe OR NEW.arquivo_xml IS DISTINCT FROM OLD.arquivo_xml OR NEW.versao IS DISTINCT FROM OLD.versao OR NEW.force IS DISTINCT FROM OLD.force) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO mide_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,retorno,arquivo_danfe,arquivo_xml,versao,force) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.retorno,OLD.arquivo_danfe,OLD.arquivo_xml,OLD.versao,OLD.force);
	INSERT INTO mide_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,retorno,arquivo_danfe,arquivo_xml,versao,force) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.retorno,NEW.arquivo_danfe,NEW.arquivo_xml,NEW.versao,NEW.force);
	RETURN NEW;
END;
$$;


ALTER FUNCTION public.pgd_update_mide() OWNER TO postgres;

