--

CREATE FUNCTION public.pgd_update_motivo_movto_centro_custo() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.motivo IS DISTINCT FROM OLD.motivo OR NEW.centro_custo IS DISTINCT FROM OLD.centro_custo OR NEW.perc_rateio IS DISTINCT FROM OLD.perc_rateio) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO motivo_movto_centro_custo_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,motivo,centro_custo,perc_rateio) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.empresa,OLD.motivo,OLD.centro_custo,OLD.perc_rateio);
	INSERT INTO motivo_movto_centro_custo_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,empresa,motivo,centro_custo,perc_rateio) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.empresa,NEW.motivo,NEW.centro_custo,NEW.perc_rateio);
	RETURN NEW;
END;
$$;


