ALTER FUNCTION public.pgd_update_nota_fiscal() OWNER TO postgres;

--
-- Name: pgd_update_nota_fiscal_carta_correcao(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_nota_fiscal_carta_correcao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.data IS DISTINCT FROM OLD.data OR NEW.hora IS DISTINCT FROM OLD.hora OR NEW.nota_fiscal IS DISTINCT FROM OLD.nota_fiscal OR NEW.correcao IS DISTINCT FROM OLD.correcao OR NEW.sequencia IS DISTINCT FROM OLD.sequencia OR NEW.nfe_evento IS DISTINCT FROM OLD.nfe_evento) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO nota_fiscal_carta_correcao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,data,hora,nota_fiscal,correcao,sequencia,nfe_evento) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.data,OLD.hora,OLD.nota_fiscal,OLD.correcao,OLD.sequencia,OLD.nfe_evento);
	INSERT INTO nota_fiscal_carta_correcao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,data,hora,nota_fiscal,correcao,sequencia,nfe_evento) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.data,NEW.hora,NEW.nota_fiscal,NEW.correcao,NEW.sequencia,NEW.nfe_evento);
	RETURN NEW;
END;
$$;


ALTER FUNCTION public.pgd_update_nota_fiscal_carta_correcao() OWNER TO postgres;

