	IF r.current_user <> 'linx' AND NOT (NEW.nota_fiscal IS DISTINCT FROM OLD.nota_fiscal OR NEW.cupom IS DISTINCT FROM OLD.cupom OR NEW.grid IS DISTINCT FROM OLD.grid OR NEW.nota_fiscal_devolucao IS DISTINCT FROM OLD.nota_fiscal_devolucao) THEN
		RETURN NEW;
	END IF;
