--

CREATE FUNCTION public.pgd_update_pessoa_agregado() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.tipo IS DISTINCT FROM OLD.tipo OR NEW.pessoa IS DISTINCT FROM OLD.pessoa OR NEW.pessoa_simples IS DISTINCT FROM OLD.pessoa_simples OR NEW.tipo_id IS DISTINCT FROM OLD.tipo_id OR NEW.identificacao IS DISTINCT FROM OLD.identificacao OR NEW.senha IS DISTINCT FROM OLD.senha OR NEW.bloqueado IS DISTINCT FROM OLD.bloqueado OR NEW.utilizar_dados_conveniado_nota_fiscal IS DISTINCT FROM OLD.utilizar_dados_conveniado_nota_fiscal OR NEW.nome_conveniado IS DISTINCT FROM OLD.nome_conveniado OR NEW.cpf_ie_conveniado IS DISTINCT FROM OLD.cpf_ie_conveniado OR NEW.endereco_fone_conveniado IS DISTINCT FROM OLD.endereco_fone_conveniado OR NEW.faturamento_individual IS DISTINCT FROM OLD.faturamento_individual OR NEW.bloqueado_final_semana IS DISTINCT FROM OLD.bloqueado_final_semana OR NEW.motivo_bloqueio IS DISTINCT FROM OLD.motivo_bloqueio OR NEW.conveniado IS DISTINCT FROM OLD.conveniado OR NEW.motorista_obrigatorio IS DISTINCT FROM OLD.motorista_obrigatorio OR NEW.identificacao_obrigatoria IS DISTINCT FROM OLD.identificacao_obrigatoria OR NEW.solicitar_senha_pinpad IS DISTINCT FROM OLD.solicitar_senha_pinpad OR NEW.pessoa_vinculada IS DISTINCT FROM OLD.pessoa_vinculada OR NEW.valida_biometria_pessoa_vinculada IS DISTINCT FROM OLD.valida_biometria_pessoa_vinculada OR NEW.valida_senha_motorista_biometria IS DISTINCT FROM OLD.valida_senha_motorista_biometria OR NEW.emsys IS DISTINCT FROM OLD.emsys OR NEW.placa_emsys IS DISTINCT FROM OLD.placa_emsys) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
