	INSERT INTO pessoa_agregado_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,codigo,tipo,pessoa,pessoa_simples,tipo_id,identificacao,senha,bloqueado,utilizar_dados_conveniado_nota_fiscal,nome_conveniado,cpf_ie_conveniado,endereco_fone_conveniado,faturamento_individual,bloqueado_final_semana,motivo_bloqueio,conveniado,motorista_obrigatorio,identificacao_obrigatoria,solicitar_senha_pinpad,pessoa_vinculada,valida_biometria_pessoa_vinculada,valida_senha_motorista_biometria,emsys,placa_emsys) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.codigo,NEW.tipo,NEW.pessoa,NEW.pessoa_simples,NEW.tipo_id,NEW.identificacao,NEW.senha,NEW.bloqueado,NEW.utilizar_dados_conveniado_nota_fiscal,NEW.nome_conveniado,NEW.cpf_ie_conveniado,NEW.endereco_fone_conveniado,NEW.faturamento_individual,NEW.bloqueado_final_semana,NEW.motivo_bloqueio,NEW.conveniado,NEW.motorista_obrigatorio,NEW.identificacao_obrigatoria,NEW.solicitar_senha_pinpad,NEW.pessoa_vinculada,NEW.valida_biometria_pessoa_vinculada,NEW.valida_senha_motorista_biometria,NEW.emsys,NEW.placa_emsys);
	RETURN NEW;
