--

CREATE FUNCTION public.pgd_update_pessoa_dados_prof() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.pessoa IS DISTINCT FROM OLD.pessoa OR NEW.empresa IS DISTINCT FROM OLD.empresa OR NEW.endereco IS DISTINCT FROM OLD.endereco OR NEW.cidade IS DISTINCT FROM OLD.cidade OR NEW.estado IS DISTINCT FROM OLD.estado OR NEW.cep IS DISTINCT FROM OLD.cep OR NEW.cargo IS DISTINCT FROM OLD.cargo OR NEW.fone IS DISTINCT FROM OLD.fone OR NEW.admissao IS DISTINCT FROM OLD.admissao OR NEW.cpf IS DISTINCT FROM OLD.cpf OR NEW.data_nasc IS DISTINCT FROM OLD.data_nasc OR NEW.grid IS DISTINCT FROM OLD.grid) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO pessoa_dados_prof_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,pessoa,empresa,endereco,cidade,estado,cep,cargo,fone,admissao,cpf,data_nasc,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.pessoa,OLD.empresa,OLD.endereco,OLD.cidade,OLD.estado,OLD.cep,OLD.cargo,OLD.fone,OLD.admissao,OLD.cpf,OLD.data_nasc,OLD.grid);
	INSERT INTO pessoa_dados_prof_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,pessoa,empresa,endereco,cidade,estado,cep,cargo,fone,admissao,cpf,data_nasc,grid) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.pessoa,NEW.empresa,NEW.endereco,NEW.cidade,NEW.estado,NEW.cep,NEW.cargo,NEW.fone,NEW.admissao,NEW.cpf,NEW.data_nasc,NEW.grid);
	RETURN NEW;
END;
$$;


