--
-- Name: pgd_update_ponto_config_condicao(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_ponto_config_condicao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.codigo IS DISTINCT FROM OLD.codigo OR NEW.produto IS DISTINCT FROM OLD.produto OR NEW.grupo_produto IS DISTINCT FROM OLD.grupo_produto OR NEW.tipo_verificacao IS DISTINCT FROM OLD.tipo_verificacao OR NEW.nome IS DISTINCT FROM OLD.nome OR NEW.tipo_condicao IS DISTINCT FROM OLD.tipo_condicao OR NEW.valor_ini IS DISTINCT FROM OLD.valor_ini OR NEW.valor_fim IS DISTINCT FROM OLD.valor_fim) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO ponto_config_condicao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,codigo,produto,grupo_produto,tipo_verificacao,nome,tipo_condicao,valor_ini,valor_fim) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.codigo,OLD.produto,OLD.grupo_produto,OLD.tipo_verificacao,OLD.nome,OLD.tipo_condicao,OLD.valor_ini,OLD.valor_fim);
	INSERT INTO ponto_config_condicao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,codigo,produto,grupo_produto,tipo_verificacao,nome,tipo_condicao,valor_ini,valor_fim) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.codigo,NEW.produto,NEW.grupo_produto,NEW.tipo_verificacao,NEW.nome,NEW.tipo_condicao,NEW.valor_ini,NEW.valor_fim);
	RETURN NEW;
END;
$$;


