ALTER FUNCTION public.pgd_update_portador() OWNER TO postgres;

--
-- Name: pgd_update_portador_layout(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_portador_layout() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.portador IS DISTINCT FROM OLD.portador OR NEW.motivo IS DISTINCT FROM OLD.motivo OR NEW.tipo_layout IS DISTINCT FROM OLD.tipo_layout OR NEW.exibe_cabecalho IS DISTINCT FROM OLD.exibe_cabecalho) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO portador_layout_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,portador,motivo,tipo_layout,exibe_cabecalho) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.portador,OLD.motivo,OLD.tipo_layout,OLD.exibe_cabecalho);
	INSERT INTO portador_layout_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,portador,motivo,tipo_layout,exibe_cabecalho) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.portador,NEW.motivo,NEW.tipo_layout,NEW.exibe_cabecalho);
	RETURN NEW;
END;
$$;


