ALTER FUNCTION public.pgd_update_produto() OWNER TO postgres;

--
-- Name: pgd_update_produto_cfop(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_produto_cfop() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.produto IS DISTINCT FROM OLD.produto OR NEW.natureza_op IS DISTINCT FROM OLD.natureza_op OR NEW.cfop IS DISTINCT FROM OLD.cfop OR NEW.de IS DISTINCT FROM OLD.de OR NEW.uf IS DISTINCT FROM OLD.uf OR NEW.cst IS DISTINCT FROM OLD.cst OR NEW.emsys IS DISTINCT FROM OLD.emsys) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO produto_cfop_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,produto,natureza_op,cfop,de,uf,cst,emsys) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.produto,OLD.natureza_op,OLD.cfop,OLD.de,OLD.uf,OLD.cst,OLD.emsys);
	INSERT INTO produto_cfop_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,produto,natureza_op,cfop,de,uf,cst,emsys) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.produto,NEW.natureza_op,NEW.cfop,NEW.de,NEW.uf,NEW.cst,NEW.emsys);
	RETURN NEW;
END;
$$;


