ALTER FUNCTION public.pgd_update_produto_historico() OWNER TO postgres;

--
-- Name: pgd_update_produto_historico_tributacao(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.pgd_update_produto_historico_tributacao() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
	r RECORD;
	newgrid BIGINT;
	gfid BIGINT;
BEGIN
	SELECT current_user INTO r;
	IF r.current_user = 'distro' THEN
		RETURN NEW;
	END IF;
	IF r.current_user <> 'linx' AND NOT (NEW.grid IS DISTINCT FROM OLD.grid OR NEW.produto IS DISTINCT FROM OLD.produto OR NEW.cst_icms IS DISTINCT FROM OLD.cst_icms OR NEW.aliquota_icms IS DISTINCT FROM OLD.aliquota_icms OR NEW.ts IS DISTINCT FROM OLD.ts) THEN
		RETURN NEW;
	END IF;
	SELECT pgd_gxid_f(pgd_sid::int4, nextval('pgd_fid_seq'::text)::int8) AS next_gfid 		INTO r FROM pgd_lsite;
	gfid := r.next_gfid;
	INSERT INTO produto_historico_tributacao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,produto,cst_icms,aliquota_icms,ts) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Uo',OLD.grid,OLD.produto,OLD.cst_icms,OLD.aliquota_icms,OLD.ts);
	INSERT INTO produto_historico_tributacao_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,produto,cst_icms,aliquota_icms,ts) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.produto,NEW.cst_icms,NEW.aliquota_icms,NEW.ts);
	RETURN NEW;
END;
$$;


