	INSERT INTO web_sessao_config_pessoa_flow (pgd_gfid,pgd_when,pgd_flow_flag,pgd_username,pgd_host,pgd_module,pgd_version,pgd_optype,grid,sessao,chave,tipo,pessoa,valor) values (gfid,now(),'N',current_user_name(),current_host(),current_module(),current_version(),'Un',NEW.grid,NEW.sessao,NEW.chave,NEW.tipo,NEW.pessoa,NEW.valor);
	RETURN NEW;
END;
$$;


