--
-- Name: ponto_resgate_f(bigint, double precision, boolean, boolean, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.ponto_resgate_f(bigint, double precision, boolean, boolean, double precision) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;

	preco_unit float;

	ponto float;

begin



	select g.trocar_ponto as grupo_trocar, p.trocar_ponto as produto_trocar, p.ponto_resgate, p.preco_unit into r from produto p join grupo_produto g on (p.grupo=g.grid) where p.grid=$1;



	if not found then

		return null;

	end if;



	if not $2 is null then

		preco_unit := $2;

	else

		preco_unit := r.preco_unit;

	end if;



	ponto := null;



	if r.grupo_trocar or r.produto_trocar or $3 then

		if $4 then

			ponto := r.ponto_resgate;

		end if;



		if ponto is null then

			if not $5 is null then

				ponto := preco_unit / $5;

			end if;

		end if;

	end if;



	if not ponto is null then

		if ponto < 1 then

			ponto := 1;

		else

			ponto := round(ponto);

		end if;

	end if;



	return ponto;

end;
$_$;


ALTER FUNCTION public.ponto_resgate_f(bigint, double precision, boolean, boolean, double precision) OWNER TO postgres;

--
-- Name: preco_custo_composto_empresa_f(bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_custo_composto_empresa_f(bigint, bigint, bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

		declare
			r record;
			total_custo float := 0.0;
			custo_comp float;
			result_found boolean := FALSE;
		begin
			for r in
					select l1.produto, l1.quantidade
					from lancto l1 
					join lancto l2 on l1.mlid = l2.mlid	
						and l2.grid = $3 and l2.empresa = $2 
					where l1.seq_cupom = l2.seq_cupom and l1.operacao = 'SR'
			loop
				result_found := TRUE;
				select preco_custo_empresa_f(r.produto, $2) * r.quantidade into custo_comp;

				total_custo := total_custo + custo_comp;
			end loop;
			if not result_found then
				select preco_custo_empresa_f($1, $2) into total_custo;
			end if;

			return total_custo;

		end;
	
$_$;


