--
-- Name: preco_custo_empresa_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_custo_empresa_f(bigint, bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE r RECORD;
BEGIN

	-- Verifica se tem produto com composiÁ„o.
	-- Se n„o tem segue o fluxo normal da funÁ„o que j· estava na Stable (n„o modificar esta parte)

	SELECT True INTO r FROM produto_composicao pc WHERE pc.produto=$1;

	IF NOT FOUND THEN
		select preco_custo into r from produto_empresa where produto=$1 and 
			empresa=$2 and not preco_custo is null;

		if found and r.preco_custo is not null then
			return r.preco_custo;
		end if;

		select preco_custo into r from produto where grid=$1;

		if r.preco_custo is null then
			return 0.0;
		end if;

		return r.preco_custo;

	END IF;

	-- Valida se tem composiÁ„o especÌfica por empresa ou geral e
	-- desconsidera do c·lculo de custo os itens que s„o opcionais.
	select True into r from produto_composicao pc where pc.produto=$1 and empresa = $2;

	IF NOT FOUND THEN

		SELECT True INTO r FROM produto_composicao pc WHERE pc.produto=$1 AND empresa IS NULL;

		IF NOT FOUND THEN
			return 0.0;

		ELSE

			SELECT SUM(COALESCE(preco_custo, 0.0)) AS preco_custo INTO r FROM (
				SELECT 
					pc.quantidade * COALESCE(pe.preco_custo, pm.preco_custo, 0.0) AS preco_custo
				FROM produto p 
				JOIN produto_composicao pc ON (pc.produto = p.grid AND pc.empresa is null AND COALESCE(pc.opcional, FALSE) = FALSE)
				JOIN produto pm ON (pm.grid = pc.materia_prima)
				LEFT JOIN produto_empresa pe ON (pe.produto = pm.grid AND pe.empresa = $2 AND pe.preco_custo is not null)
				WHERE pc.produto = $1
			) as t;

			IF NOT FOUND THEN
				return 0.0;
			END IF;

		END IF;

	ELSE

		SELECT SUM(COALESCE(preco_custo, 0.0)) AS preco_custo INTO r FROM (
			SELECT 
				pc.quantidade * COALESCE(pe.preco_custo, pm.preco_custo, 0.0) AS preco_custo
			FROM produto p 
			JOIN produto_composicao pc ON (pc.produto = p.grid AND pc.empresa = $2 AND COALESCE(pc.opcional, FALSE) = FALSE)
			JOIN produto pm ON (pm.grid = pc.materia_prima)
			LEFT JOIN produto_empresa pe ON (pe.produto = pm.grid AND pe.empresa = $2 AND pe.preco_custo is not null)
			WHERE pc.produto = $1
		) as t;

		IF NOT FOUND THEN
			return 0.0;
		END IF;

	END IF;

	return r.preco_custo;
END

$_$;


ALTER FUNCTION public.preco_custo_empresa_f(bigint, bigint) OWNER TO postgres;

--
-- Name: preco_custo_empresa_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_custo_empresa_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare 
	r record;
begin
	select data into r from estoque_invalida where empresa =$2 and produto = $1 and data <= $3 limit 1;
	
	if found then
		select preco_unit into r from lancto where operacao = 'E' and empresa = $2 and produto = $1 and data = $3 order by hora desc limit 1;
		if found then
			return r.preco_unit;
		end if;

		select preco_unit into r from lancto where operacao = 'E' and empresa = $2 and produto = $1 and data = $3 - 1 order by hora desc limit 1;
		if found then
			return r.preco_unit;
		end if;

		select preco_unit into r from lancto where operacao = 'E' and empresa = $2 and produto = $1 and data = $3 - 2 order by hora desc limit 1;
		if found then
			return r.preco_unit;
		end if;

		select preco_unit into r from lancto where operacao = 'E' and empresa = $2 and produto = $1 and data < $3 - 2 order by data desc, hora desc limit 1;
		if found then
			return r.preco_unit;
		end if;

	else

		select ult_custo into r from estoque_valor where empresa = $2 and produto = $1 and data = $3;		
		if found then			
			return r.ult_custo;
		end if;
	
		select ult_custo into r from estoque_valor where empresa = $2 and produto = $1 and data = $3::date - 1;		
		if found then			
			return r.ult_custo;		
		end if;

		select ult_custo into r from estoque_valor where empresa = $2 and produto = $1 and data = $3::date - 2;		
		if found then			
			return r.ult_custo;		
		end if;

		select ult_custo into r from estoque_valor where empresa = $2 and produto = $1 and data < $3::date - 2 order by data desc limit 1;		
		if found then			
			return r.ult_custo;		
		end if;
	end if;

	select preco_custo_empresa_f($1, $2) as custo into r;
	return r.custo;
end;

$_$;


ALTER FUNCTION public.preco_custo_empresa_f(bigint, bigint, date) OWNER TO postgres;

