--
-- Name: preco_custo_fiscal_empresa_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_custo_fiscal_empresa_f(bigint, bigint, date) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
	v_ult_custo_fiscal float :=0;
   
BEGIN
	SELECT ev.ult_custo_fiscal INTO v_ult_custo_fiscal
	  FROM estoque_valor ev
	 WHERE ev.empresa=$1
	   AND ev.produto=$2
	   AND ev.data=$3;
	IF NOT FOUND THEN
		SELECT ev.ult_custo_fiscal INTO v_ult_custo_fiscal
		  FROM estoque_valor ev
	     WHERE ev.empresa=$1
	       AND ev.produto=$2
		   AND ev.data<$3 order by data desc LIMIT 1;
		IF NOT FOUND THEN
			SELECT ev.ult_custo_fiscal INTO v_ult_custo_fiscal
		      FROM estoque_valor ev
	         WHERE ev.empresa=$1
	           AND ev.produto=$2
		       AND ev.data>$3 order by data LIMIT 1;
		END IF;
	END IF;
	
	IF NOT FOUND THEN
		v_ult_custo_fiscal := 0;
	END IF;
	RETURN v_ult_custo_fiscal;
END;
	
$_$;


ALTER FUNCTION public.preco_custo_fiscal_empresa_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: preco_custo_kit_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_custo_kit_f(bigint, bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
BEGIN

	SELECT SUM (preco) as preco_custo INTO r FROM (
		SELECT

			(sum(preco_custo_empresa_f(p2.grid, $2) * pkm.quantidade) / 
				CASE WHEN COUNT(parent) = 0 THEN 1 ELSE COUNT(parent) END) as preco,
			parent

		FROM produto p
		JOIN produto_kit_map pkm ON (p.grid = pkm.kit::bigint)
		JOIN produto p2 ON (pkm.produto = p2.grid)
		WHERE
			p.grid = $1 AND p.flag='A' AND p.tipo='K'
		GROUP BY parent	
	) AS t;
	
	return r.preco_custo;

END

$_$;


