-- Name: preco_unit_ag_f(bigint, bigint, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_unit_ag_f(bigint, bigint, integer) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
begin
/*
3∫ atributo pode conter os seguintes valores:
0= preco normal;
1= preco clube;
2= preco senhor desconto;
*/

	select preco_unit, preco_unit_clube, preco_unit_senhor into r from exc_ag_produto_empresa 
		where produto=$1 and empresa=$2;

	if $3 = 2 and r.preco_unit_senhor > 0 then
		return r.preco_unit_senhor;	
	end if;

	if $3 > 0 and r.preco_unit_clube > 0 then
		return r.preco_unit_clube;
	end if;

	return r.preco_unit;
end;
$_$;


