-- Name: preco_unit_empresa_emsys_f(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.preco_unit_empresa_emsys_f(bigint, bigint, text) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
begin
	if UPPER($3) IN ('B', 'C', 'D', 'E') then
		SELECT CASE UPPER($3)
			   WHEN 'B' THEN preco_unit_b
			   WHEN 'C' THEN preco_unit_c 
			   WHEN 'D' THEN preco_unit_d 
			   WHEN 'E' THEN preco_unit_e
			   END AS preco_unit
		  INTO r
		  FROM exchange_emsys_gestao_produto_empresa
		 WHERE produto = $1
		   AND empresa = $2;
	else
		SELECT preco_unit_empresa_f($1, $2) AS preco_unit
		  INTO r;
	end if;

	if found then
		return r.preco_unit;
	end if;

	SELECT preco_unit
	  INTO r 
	  FROM produto 
	 WHERE grid=$1;

	return r.preco_unit;
end;
$_$;


