--
-- Name: produto_alteracao_descricao_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_alteracao_descricao_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
	r BIGINT;
BEGIN
	IF (NEW.nome != OLD.nome OR NEW.codigo != OLD.codigo) THEN
		SELECT grid INTO r FROM exchange_sped_0205 WHERE produto = OLD.grid ORDER BY grid DESC LIMIT 1;

		IF NOT FOUND THEN
			BEGIN
				IF NEW.nome != OLD.nome THEN
					INSERT INTO exchange_sped_0205
						(grid, produto, descricao, data_inicial, data_final, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), OLD.grid, OLD.nome,
						coalesce(OLD.data_cad,current_date), current_date, to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));

					INSERT INTO exchange_sped_0205
						(grid, produto, descricao, data_inicial, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), NEW.grid, NEW.nome, current_date+1,
						to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));
				END IF;

				IF NEW.codigo != OLD.codigo THEN
					INSERT INTO exchange_sped_0205
						(grid, produto, cod_anterior, data_inicial, data_final, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), OLD.grid, OLD.codigo,
						coalesce(OLD.data_cad,current_date), current_date, to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));

					INSERT INTO exchange_sped_0205
						(grid, produto, cod_anterior, data_inicial, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), NEW.grid, NEW.codigo, current_date+1,
						to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));
				END IF;
			EXCEPTION
				WHEN UNIQUE_VIOLATION THEN
					IF NEW.nome != OLD.nome THEN
						UPDATE exchange_sped_0205 SET descricao = OLD.nome WHERE grid = r;
					END IF;

					IF NEW.codigo != OLD.codigo THEN
						UPDATE exchange_sped_0205 SET cod_anterior = OLD.codigo WHERE grid = r;
					END IF;			
				RETURN NEW;
			END;
		ELSE
			BEGIN
				IF NEW.nome != OLD.nome THEN
					INSERT INTO exchange_sped_0205
						(grid, produto, descricao, data_inicial, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), NEW.grid, NEW.nome, current_date+1,
						to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));
				END IF;

				IF NEW.codigo != OLD.codigo THEN
					INSERT INTO exchange_sped_0205
						(grid, produto, cod_anterior, data_inicial, mes_ref)
					VALUES
						((select pgd_gxid_f(pgd_sid::int4, nextval('pgd_rid_seq')::int8) from pgd_lsite), NEW.grid, NEW.codigo, current_date+1,
						to_date(to_char(current_date,'YYYY-MM-01'), 'YYYY-MM-DD'));
				END IF;
			EXCEPTION
				WHEN UNIQUE_VIOLATION THEN
					IF NEW.nome != OLD.nome THEN
						UPDATE exchange_sped_0205 SET descricao = OLD.nome WHERE grid = r;
					END IF;

					IF NEW.codigo != OLD.codigo THEN
						UPDATE exchange_sped_0205 SET cod_anterior = OLD.codigo WHERE grid = r;
					END IF;			
				RETURN NEW;
			END;
			
			UPDATE exchange_sped_0205 SET data_final = current_date WHERE grid = r;
		END IF;
	END IF;

	RETURN NEW;
END;
	
$$;


ALTER FUNCTION public.produto_alteracao_descricao_tgf() OWNER TO postgres;

--
-- Name: produto_cupom_cfop_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_cupom_cfop_f(bigint) RETURNS text
    LANGUAGE plpgsql
    AS $_$

declare
	r record;
begin
	select pc.cfop into r from produto_cfop pc join natureza_op np on (pc.natureza_op=np.grid and np.sped_cupom_fiscal=True) where pc.produto = $1;
	
	if r.cfop is not null then
		return r.cfop;
	end if;

	select gpc.cfop into r from grupo_produto_cfop gpc join natureza_op np on (gpc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
		where gpc.grupo_produto = (select grupo from produto where grid = $1);

	if r.cfop is not null then
		return r.cfop;
	end if;

	select cfop_dentro into r from produto where grid = $1;
	return r.cfop_dentro;
end;
	
$_$;


