ALTER FUNCTION public.produto_cupom_cfop_f(bigint, text) OWNER TO postgres;

--
-- Name: produto_cupom_cfop_f(bigint, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_cupom_cfop_f(bigint, text, text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
	cfop text;
	cst_cupom text;
	cst_trib text;
	tipo_item text;

BEGIN

	cst_cupom := substr($3,1,1);
	SELECT tipo into tipo_item FROM produto WHERE grid = $1;
	
	IF tipo_item = 'S' THEN
		cst_trib := '090';

	ELSEIF cst_cupom = 'F' THEN
		cst_trib := '060';

	ELSEIF cst_cupom = 'N' THEN
		cst_trib := '041';

	ELSEIF cst_cupom = 'I' THEN
		cst_trib := '040';

	ELSEIF cst_cupom = 'S' THEN
		cst_trib := '090';

	ELSE
		cst_trib := '000';

	END IF;

	-- Tratamento: Campos CST e UF nao sao obrigatorios no cadastro -- 

	SELECT pc.cfop 
	  INTO cfop 
	  FROM produto_cfop pc join natureza_op np on (pc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
		WHERE pc.produto = $1 
		  and substr(pc.cfop, 1,1) = '5' 
		  and pc.uf = $2 
		  and pc.cst = cst_trib;

	IF not FOUND THEN 
		-- Passa Produto, UF e CST is null --	
		SELECT pc.cfop 
		  INTO cfop 
		  FROM produto_cfop pc join natureza_op np on (pc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE pc.produto = $1 
			  and substr(pc.cfop, 1,1) = '5' 
			  and pc.uf = $2 
			  and (length(pc.cst) = 0 or pc.cst is null);
	END IF;

	IF not FOUND THEN 
		-- Passa Produto, UF e CST is null --	
		SELECT pc.cfop 
		  INTO cfop 
		  FROM produto_cfop pc join natureza_op np on (pc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE pc.produto = $1 
			  and substr(pc.cfop, 1,1) = '5' 
			  and (length(pc.uf) = 0 or pc.uf is null)  
			  and pc.cst = cst_trib;
	END IF;

	IF not FOUND THEN 
		-- Passa Produto, UF is null e CST is null --	
		SELECT pc.cfop 
		  INTO cfop 
		  FROM produto_cfop pc join natureza_op np on (pc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE pc.produto = $1 
			  and substr(pc.cfop, 1,1) = '5' 
			  and (length(pc.uf) = 0 or pc.uf is null) 
			  and (length(pc.cst) = 0 or pc.cst is null);
	END IF;

	IF not FOUND THEN
		-- Passa Grupo do produto, UF e CST --
		SELECT gpc.cfop 
		  INTO cfop 
		  FROM grupo_produto_cfop gpc 
			   join natureza_op np on (gpc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE gpc.grupo_produto = (SELECT grupo FROM produto WHERE grid = $1) 
			  and substr(gpc.cfop, 1,1) = '5' 
			  and gpc.uf = $2 
			  and gpc.cst = cst_trib;
	END IF;

	IF not FOUND THEN 
		-- Passa Grupo do produto, UF e CST is null --
		SELECT gpc.cfop 
		  INTO cfop 
		  FROM grupo_produto_cfop gpc 
			   join natureza_op np on (gpc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE gpc.grupo_produto = (SELECT grupo FROM produto WHERE grid = $1) 
			  and substr(gpc.cfop, 1,1) = '5' 
			  and gpc.uf = $2 
			  and (length(gpc.cst) = 0 or gpc.cst is null);
	END IF;

	IF not FOUND THEN 
		-- Passa Grupo do produto, UF is null e CST is null --
		SELECT gpc.cfop 
		  INTO cfop 
		  FROM grupo_produto_cfop gpc 
			   join natureza_op np on (gpc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE gpc.grupo_produto = (SELECT grupo FROM produto WHERE grid = $1) 
			  and substr(gpc.cfop, 1,1) = '5' 
			  and (length(gpc.uf) = 0 or gpc.uf is null) 
			  and gpc.cst = cst_trib;
	END IF;

	IF not FOUND THEN 
		-- Passa Grupo do produto, UF is null e CST is null --
		SELECT gpc.cfop 
		  INTO cfop 
		  FROM grupo_produto_cfop gpc 
			   join natureza_op np on (gpc.natureza_op=np.grid and np.sped_cupom_fiscal=True) 
			WHERE gpc.grupo_produto = (SELECT grupo FROM produto WHERE grid = $1) 
			  and substr(gpc.cfop, 1,1) = '5' 
			  and (length(gpc.uf) = 0 or gpc.uf is null) 
			  and (length(gpc.cst) = 0 or gpc.cst is null);
	END IF;

	RETURN cfop;

END;
	
$_$;


ALTER FUNCTION public.produto_cupom_cfop_f(bigint, text, text) OWNER TO postgres;

--
-- Name: produto_cupom_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_cupom_f(bigint, bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	ret text;
begin
	if (($1 is null) or ($1 = 0::bigint)) then
		return null;
	end if;
	
	if $2 is null then
		return produto_principal_venda_f($1);
	end if;

	select into r p.nome, p.unid_med, round(l.quantidade::numeric, 2) as quantidade from lancto l 
	join produto p on (l.produto=p.grid) where l.mlid=$1 and l.operacao = 'V' and l.produto= $1 order by abs(l.valor) desc limit 1;

	if found then
		ret := r.nome || ' // ' || round(r.quantidade::numeric, 2)::float8::text || ' ' || r.unid_med;

		select into r count(*) from lancto where mlid=$1 and operacao = 'V';

		if r.count > 1 then
			ret := '+ ' || ret;
		end if;
	end if;

	return ret;
end
$_$;


ALTER FUNCTION public.produto_cupom_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_custo_f(bigint, bigint, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_custo_f(bigint, bigint, date, text) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$
declare	r		record;
	curs1 		refcursor;
	data_ini	date;
	turno_ini	int4;
	hora_ini	timestamp;
	estoque		float;
	custo_med	float;
	ult_custo	float;
	est_atu		float;

begin
	select * into r from produto_hist_custo where empresa=$1 and produto=$2 and
		data<=$3 order by data desc limit 1;

	if found then
		data_ini  := r.data;
		turno_ini := r.turno;
		hora_ini  := r.hora;
		estoque   := r.estoque;
		custo_med := r.custo_medio;	
		ult_custo := r.preco_custo;	
	else
		data_ini  := '1970-01-01';
		turno_ini := 0;
		hora_ini  := '1970-01-01 00:00';
		estoque   := 0;
		custo_med := 0;
		ult_custo := 0;
	end if;

	if data_ini = $3 then
		if $4 = 'M' then
			return custo_med;
		else
			return ult_custo;
		end if;
	end if;

	select grid into r from lancto where empresa=$1 and produto=$2 and operacao='E' and (
		(data=data_ini and turno=turno_ini and hora>hora_ini) or
		(data=data_ini and turno>turno_ini) or 
		(data>data_ini)
		) limit 1;

	if not found then
		if $4 = 'M' then
			return custo_med;
		else
			return ult_custo;
		end if;
	end if;

	/* raise NOTICE '%, %, %', data_ini, turno_ini, hora_ini; */
	open curs1 for select operacao, quantidade, preco_unit from lancto where empresa=$1 and produto=$2 and (
		(data=data_ini and turno=turno_ini and hora>hora_ini) or
		(data=data_ini and turno>turno_ini) or (data>data_ini)
		) and data <= $3 order by data, turno, hora;

	fetch curs1 into r;

	while found loop
		if r.operacao = 'E' and r.quantidade > 0 and r.preco_unit > 0 then
			ult_custo:=round(r.preco_unit, 4);

			/*
                	if estoque <= 0 then
				custo_med:=ult_custo;
			*/
			if custo_med <= 0 then
				custo_med:=ult_custo;
			else
				est_atu:=estoque+r.quantidade;
				custo_med:=((estoque * custo_med) + (r.quantidade * ult_custo)) / est_atu;
				custo_med:=round(custo_med, 4);
			end if;
		end if;

		if r.operacao in ('V','C','P','D','TS') then
			estoque:=estoque-r.quantidade;	
		elsif r.operacao in ('E','S','TE') then
			estoque:=estoque+r.quantidade;	
		elsif r.operacao = 'I' then
			estoque:=r.quantidade;	
		elsif r.operacao = 'F' then
			estoque:=0;	
			exit;
		end if;

		fetch curs1 into r;
	end loop;

	if $4 = 'M' then
		return custo_med;
	else
		return ult_custo;
	end if;
end;
$_$;


