-- Name: produto_empresa_diferencia_preco_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_empresa_diferencia_preco_f(bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare v_exists boolean;

begin

	SELECT EXISTS (
		SELECT true
		FROM produto_empresa
		WHERE produto = $1
		  AND preco_unit IS NOT NULL
	) INTO v_exists;

	RETURN v_exists;

end;
$_$;


