--
-- Name: produto_estoque_codigo_anp_f(bigint, text, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_estoque_codigo_anp_f(bigint, text, date) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

/*
1 - EMPRESA
2 - CODIGO ANP
3 - DATA
*/

DECLARE
	r RECORD;
	fator_conv double precision;
	estoque double precision;
	t_estoque double precision := 0.0;

BEGIN

	-- SE UMA DAS VARIAVEIS VIEREM VAZIAS RETORNA ZERO
	IF $1 IS NULL or $2 IS NULL OR $3 IS NULL THEN
		RETURN 0;
	END IF;

	FOR r IN SELECT p.grid as grid
	              , pd.deposito  as deposito
	           from produto p 
	           join produto_deposito_view pd on (pd.produto = p.grid) 
			   join tipo_combustivel tc on (tc.codigo = p.tipo_combustivel) 
			  where tc.codigo_anp = $2  and empresa = $1 group by grid, deposito
		  
	LOOP

		SELECT produto_estoque_f($1, r.deposito, r.grid, $3) INTO estoque;

		-- O FATOR DE CONVERS√ÉO DEVE SER PEGO SEMPRE PARA A UNIDADE DE MEDIDA DE LITROS
		SELECT fator INTO fator_conv FROM produto_unidade_medida WHERE produto = r.grid AND unid_med = 'L' limit 1; 

		IF abs(estoque) > 0 THEN
			IF fator_conv IS NOT NULL THEN
				t_estoque := t_estoque + (estoque * fator_conv);
			ELSE
				t_estoque := t_estoque + (estoque * 1);
			END IF;
		END IF;

	END LOOP;

	RETURN t_estoque;
END;

  
$_$;


ALTER FUNCTION public.produto_estoque_codigo_anp_f(bigint, text, date) OWNER TO postgres;

--
-- Name: produto_estoque_data_f(bigint, bigint, bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_estoque_data_f(bigint, bigint, bigint, bigint, date, date) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$

  DECLARE r RECORD;
  ret RECORD;
  v_data_ini DATE;
  v_data_ant DATE;
  v_estoque FLOAT;
  c1 REFCURSOR;
  BEGIN
	SELECT data, estoque INTO r FROM estoque_deposito
		WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data<$4 
		ORDER BY data DESC LIMIT 1;

	IF found THEN
		v_data_ini := r.data;
		v_estoque := r.estoque;
	ELSE
		v_data_ini := '0001-01-01';
		v_estoque := 0;
	END IF;

	--RAISE INFO 'Iniciando estoque em % com %', v_data_ini, v_estoque;
	v_data_ant := $4 - '1 day'::interval;

	OPEN c1 FOR SELECT data, turno, hora, operacao, quantidade FROM lancto 
		WHERE empresa=$1 AND deposito=$2 AND produto=$3 AND data > v_data_ini and data <= $5
		ORDER BY data, turno, hora, grid;

	LOOP
		FETCH c1 INTO r;
		EXIT WHEN NOT found;

		IF (v_data_ant < r.data) THEN
			WHILE v_data_ant < r.data LOOP

				IF (v_data_ant >= $4) THEN
					SELECT v_data_ant, v_estoque INTO ret;
					RETURN NEXT ret;
				END IF;

				v_data_ant := v_data_ant + '1 day'::interval;
			END LOOP;
		END IF;

		-- Calcula o estoque conforme a operacao
		IF r.operacao in ('V','C','P','DF','TS','B', 'SD', 'SR', 'DG' ) then
			v_estoque := v_estoque - r.quantidade;
		ELSIF r.operacao in ('E','S','TE','DC', 'ED', 'ER') THEN
			v_estoque := v_estoque + r.quantidade;
		ELSIF r.operacao in ('I','M') THEN
			v_estoque := r.quantidade;
		ELSIF r.operacao = 'F' THEN
			v_estoque := 0;
			EXIT;
		END IF;
	END LOOP;

	CLOSE c1;

	WHILE v_data_ant <= $5 LOOP

		IF v_data_ant >= $4 THEN
			SELECT v_data_ant, v_estoque INTO ret;
			RETURN NEXT ret;
		END IF;

		v_data_ant := v_data_ant + '1 day'::interval;
	END LOOP;
  END;  
  
$_$;


