ALTER FUNCTION public.produto_estoque_f(bigint, bigint, bigint, date, integer) OWNER TO postgres;

--
-- Name: produto_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

/*Parametros
1- Empresa
2- Deposito
3- Produto
4- Data
5- Turno
6- Hora
*/
DECLARE	
	r RECORD;
	r1 RECORD;
	p_empresa INT8;
	p_data DATE;
	data_ini DATE;
	data_invalida DATE;
	estoque_final FLOAT;
	curs1 REFCURSOR;
	est_ativo BOOLEAN;
BEGIN

	-- Caso o produto seja servico, retorna sempre Zero
	SELECT grid INTO r FROM produto WHERE grid=$3 AND tipo='S';

	IF found THEN 
		RETURN 0;
	END IF;

	-- Estrutura do banco nao suporta calcular do estoque apenas pela hora
	IF $5 IS NULL AND NOT $6 IS NULL THEN
		RAISE EXCEPTION 'Impossivel calcular estoque de um horario sem informar o turno';
	END IF;

	-- Utiliza a empresa local caso nao tenha sido informada empresa
	IF $1 IS NULL THEN
		SELECT empresa INTO r FROM empresa_local;
		p_empresa := r.empresa;
	ELSE
		p_empresa := $1;
	END IF;

	-- Utiliza a data de hoje caso nao tenha sido informada data
	IF $4 IS NULL THEN
		p_data := current_date;
	ELSE
		p_data := $4;
	END IF;

	IF $2 IS NULL THEN
		-- Caso o deposito nao tenha sido informado, busca de todos os depositos da empresa
		-- que movimentam o produto solicitado

		estoque_final := 0;

		FOR r IN SELECT grid, nome FROM deposito WHERE empresa=p_empresa AND produto=$3 UNION SELECT DISTINCT d.grid, d.nome FROM deposito d 
			     JOIN deposito_grupo_produto dpg ON (dpg.deposito=d.grid) JOIN produto p ON (p.grupo=dpg.grupo) LEFT JOIN produto_deposito pd on 
			     (pd.deposito=d.grid and pd.produto=p.grid) WHERE p.grid=$3 AND d.empresa=p_empresa AND (pd.movimenta OR pd.movimenta IS NULL) AND 
			     d.produto IS NULL LOOP

			-- Executa a funcao recursivamente para cada deposito
			SELECT produto_estoque_f(p_empresa, r.grid, $3, p_data, $5, $6) AS estoque INTO r1;
			estoque_final := estoque_final + r1.estoque;
		END LOOP;

		RETURN estoque_final;
	END IF;

	select ativo into est_ativo from estoque_controle order by data_ult_exec desc limit 1;

	IF NOT found THEN
		est_ativo := True;
	END IF;

	IF est_ativo THEN	
		--Verifica ate quando o estoque eh valido
		select data into data_invalida from estoque_invalida where empresa = $1 and deposito = $2 and produto = $3;

		IF found THEN
			IF data_invalida <= p_data THEN
				p_data := data_invalida;
			END IF;
		END IF;

		--A data de pesquisa sempre deve ser menor que a desejada para nao ocorrer problema quando for informado turno e hora
		p_data := p_data - 1;

		--Tentativa 1: Tabela estoque_deposito, data igual
		select data, sum(estoque) as quantidade into r from estoque_deposito where empresa = $1 and produto = $3 and data = p_data and deposito = $2 group by data;

		IF NOT found THEN
			--Tentativa 2: Tabela estoque_deposito, data anterior
			select data, sum(estoque) as quantidade into r from estoque_deposito where empresa = $1 and produto = $3 and data=(p_data - 1) and deposito = $2  group by 1;

			-- rafael faria
			IF NOT found THEN
				--Tentativa 3: Tabela estoque_produto, ultima movimentacao do produto
				select data, estoque as quantidade into r from estoque_produto where empresa = $1 and deposito = $2 and produto = $3 and data <= p_data;

				IF NOT found THEN
					--Tentativa 4: Tabela estoque_deposito, data menor
					select data, sum(estoque) as quantidade into r from estoque_deposito where empresa = $1 and produto = $3 and data < p_data and deposito = $2  
					group by 1 order by 1 desc limit 1;
				END IF;
			END IF;
		END IF;
	END IF;

	IF found AND est_ativo THEN
		data_ini := r.data;
		estoque_final := r.quantidade;
	ELSE
		data_ini := '0001-01-01';
		estoque_final := 0;
	END IF;

	--RAISE INFO '1- % - %', $2, estoque_final;
	--RAISE INFO 'Empresa: % - Deposito: % - Produto: % - Data_ini: % - Data_fim: %', p_empresa, $2, $3, data_ini, $4;
	-- Busca a movimentacao de estoque na faixa de data determinada
	OPEN curs1 FOR SELECT data, turno, hora, operacao, quantidade FROM lancto WHERE empresa=p_empresa AND deposito=$2 AND produto=$3 AND 
				   data>data_ini and data<=$4 ORDER BY data, turno, hora, grid;

	FETCH curs1 INTO r;

	WHILE found LOOP

		-- Controla o turno e a hora informada
		IF NOT $5 IS NULL AND r.data = $4 THEN

			-- Se for o mesmo turno entao compara a hora
			IF NOT $6 IS NULL AND r.turno = $5 AND r.hora > $6 THEN
				EXIT;
			END IF;

			-- Se o turno for maior que o informado, para de calcular
			IF r.turno > $5 THEN
				EXIT;
			END IF;
		END IF;

		-- Calcula o estoque conforme a operacao
		IF r.operacao in ('V','C','P','DF','TS','B','SD', 'SR', 'DG') then
			estoque_final := estoque_final - r.quantidade;	
		ELSIF r.operacao in ('E','S','TE','DC', 'O','ED', 'ER') THEN
			estoque_final := estoque_final + r.quantidade;	
		ELSIF r.operacao in ('I','M') THEN
			estoque_final := r.quantidade;	
		ELSIF r.operacao = 'F' THEN
			estoque_final := 0;	
			EXIT;
		END IF;
		--RAISE INFO '2- % - %', $2, estoque_final;

		FETCH curs1 INTO r;
	END LOOP;

	--RAISE INFO '3- % - %', $2, estoque_final;
	RETURN estoque_final;
END;

$_$;


ALTER FUNCTION public.produto_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone) OWNER TO postgres;

--
-- Name: produto_estoque_paf_f(bigint, bigint, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_estoque_paf_f(bigint, bigint, date) RETURNS double precision[]
    LANGUAGE plpgsql
    AS $_$

declare
	r record;
	est_ativo boolean;
	sh Text;
	nsh bigint;
begin
	SELECT ativo INTO est_ativo FROM estoque_controle;
	
	IF not found or (found and est_ativo) THEN
		SELECT 1 INTO r FROM estoque_invalida WHERE empresa = $1 and produto = $2 and data <= $3;
		IF found THEN
			PERFORM check_estoque_f($1, $2);
		END IF;
	
		SELECT p.tipo, p.controlar_estoque INTO r FROM produto p WHERE p.grid = $2;
  	
		IF date_part('d', $3) = 1 and not r.controlar_estoque and r.tipo = 'C' THEN
			SELECT ev.empresa, ev.produto, ev.data, ev.paf_hash, ev.estoque, sum(compra - venda) as estoque_gnv INTO r
			FROM estoque_deposito ed join estoque_valor ev on (ed.empresa = ev.empresa and ed.data = ev.data and ed.produto = ev.produto)
			WHERE ed.empresa=$1
			and ed.data between to_char($3,'yyyy-mm-01')::date and $3
			and ed.produto=$2
			and ed.deposito in (SELECT grid FROM deposito WHERE flag = 'A' and grid = ed.deposito)
			group by 1,2,3,4,5;
		ELSE
			SELECT ev.empresa, ev.produto, ev.data, ev.paf_hash, ev.estoque, 0 as estoque_gnv INTO r 
			FROM estoque_valor ev 
			WHERE ev.empresa=$1 and ev.produto = $2 and ev.data <= $3 
			ORDER BY ev.data desc limit 1;					
		END IF;

		IF found THEN
			sh := r.data::text||'#$#'||r.empresa::text||'#$#'||round(r.estoque::numeric,6)::text||'#$#'||r.produto::text;
			nsh := (length(sh)^2)::bigint % 7;
			sh := '|L-Z-T|'||nsh||sh||nsh||'|L-Z-T|';
			sh := upper('V001'||md5(sh));

			IF r.estoque_gnv <> 0 THEN
				r.estoque = r.estoque_gnv;
			END IF;
		
			IF ((sh = r.paf_hash) or (r.paf_hash is null)) THEN
				return '{' || coalesce(r.estoque,0)::float || ',' || 1::float || '}';
			ELSE
				return '{' || coalesce(r.estoque,0)::float || ',' || 0::float || '}';
			END IF;
		END IF;
	END IF;

	SELECT produto_estoque_f(null, null, $2, $3::date, $1::int, null) as estoque INTO r;
	return '{' || coalesce(r.estoque,0)::float || ',' || 1::float || '}';
END;

$_$;


ALTER FUNCTION public.produto_estoque_paf_f(bigint, bigint, date) OWNER TO postgres;

--
-- Name: produto_historico_tributacao_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_historico_tributacao_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE 
	v_aliquota_icms_old FLOAT;
	v_aliquota_icms_new FLOAT;
	v_cst_tributacao_old TEXT;
	v_cst_tributacao_new TEXT;
	r RECORD;

BEGIN
	-- Se for usuario distro eh a sincronia, entao cai fora.
	IF CURRENT_USER = 'distro' THEN
		RETURN NEW;
	END IF;

	IF TG_OP = 'UPDATE' THEN

		IF upper(TG_RELNAME) = 'PRODUTO' THEN

			IF OLD.tributacao != NEW.tributacao THEN

				SELECT cst_tributacao, tributacao INTO v_cst_tributacao_old, v_aliquota_icms_old FROM TRIBUTACAO WHERE OLD.tributacao = codigo;
				SELECT cst_tributacao, tributacao INTO v_cst_tributacao_new, v_aliquota_icms_new FROM TRIBUTACAO WHERE NEW.tributacao = codigo;

				IF v_cst_tributacao_old != v_cst_tributacao_new or v_aliquota_icms_old != v_aliquota_icms_new THEN

					INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO (produto,cst_icms,aliquota_icms,ts)
					VALUES (OLD.grid,v_cst_tributacao_old,v_aliquota_icms_old, now());

				END IF;

			END IF;	

		ELSIF upper(TG_RELNAME) = 'TRIBUTACAO' THEN

			IF OLD.tributacao != NEW.tributacao or OLD.cst_tributacao != NEW.cst_tributacao THEN

				FOR r IN (SELECT grid FROM PRODUTO WHERE OLD.codigo = tributacao) LOOP

					INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO (produto,cst_icms,aliquota_icms,ts)
					VALUES (r.grid, OLD.cst_tributacao, OLD.tributacao, now());

				END LOOP;

				FOR r IN (SELECT produto, de, para FROM PRODUTO_TRIBUTACAO WHERE OLD.codigo = tributacao) LOOP

						INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO_ESTADO (produto,cst_icms,aliquota_icms,ts,de, para)
						VALUES (r.produto, OLD.cst_tributacao, OLD.tributacao, now(), r.de, r.para);

				END LOOP;
				

			END IF;

		ELSIF upper(TG_RELNAME) = 'PRODUTO_TRIBUTACAO' THEN

			SELECT cst_tributacao, tributacao INTO v_cst_tributacao_old, v_aliquota_icms_old FROM TRIBUTACAO WHERE OLD.tributacao = codigo;

			IF OLD.tributacao != NEW.tributacao and OLD.de = NEW.de and OLD.para = NEW.para THEN

				SELECT cst_tributacao, tributacao INTO v_cst_tributacao_new, v_aliquota_icms_new FROM TRIBUTACAO WHERE NEW.tributacao = codigo;

				IF v_cst_tributacao_old != v_cst_tributacao_new or v_aliquota_icms_old != v_aliquota_icms_new THEN
					INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO_ESTADO (produto,cst_icms,aliquota_icms,ts,de, para)
					VALUES (OLD.produto, v_cst_tributacao_old, v_aliquota_icms_old, now(),OLD.de, OLD.para);

				END IF;

			ELSIF OLD.de != NEW.de or OLD.para != NEW.para THEN
				
				INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO_ESTADO (produto,cst_icms,aliquota_icms,ts,de, para)
				VALUES (OLD.produto, v_cst_tributacao_old, v_aliquota_icms_old, now(),OLD.de, OLD.para);
		
			END IF;

		ELSIF upper(TG_RELNAME) = 'TRIBUTACAO_ESTADO' THEN

			IF OLD.cst_tributacao != NEW.cst_tributacao or OLD.aliquota != NEW.aliquota or OLD.de != NEW.de or OLD.para != NEW.para THEN

				FOR r IN (SELECT grid FROM PRODUTO WHERE OLD.tributacao = tributacao) LOOP

						INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO_ESTADO (produto,cst_icms,aliquota_icms,ts,de, para)
						VALUES (r.grid, OLD.cst_tributacao, OLD.aliquota, now(),OLD.de, OLD.para);

				END LOOP;

				FOR r IN (SELECT produto FROM PRODUTO_TRIBUTACAO WHERE OLD.tributacao = tributacao) LOOP

						INSERT INTO PRODUTO_HISTORICO_TRIBUTACAO_ESTADO (produto,cst_icms,aliquota_icms,ts,de, para)
						VALUES (r.produto, OLD.cst_tributacao, OLD.aliquota, now(),OLD.de, OLD.para);

				END LOOP;

			END IF;

		END IF;

	END IF;
	RETURN NEW;

END;
  
$$;


ALTER FUNCTION public.produto_historico_tributacao_tgf() OWNER TO postgres;

--
-- Name: produto_mais_vendido_f(bigint, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_mais_vendido_f(bigint, integer, integer) RETURNS void
    LANGUAGE sql IMMUTABLE
    AS $_$

	   TRUNCATE produto_mais_vendido;

	   insert into produto_mais_vendido(produto, quantidade) SELECT l.produto, sum(l.quantidade) 
	   FROM lancto l JOIN produto p on (l.produto=p.grid) WHERE l.empresa = $1 AND p.tipo='M' AND 
	   l.data BETWEEN current_date-$2 and current_date GROUP BY l.produto LIMIT $3;
	      
$_$;


