--
-- Name: produto_movimenta_deposito_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_deposito_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

declare 
	r record;
begin	
	select true into r from produto_movimenta_deposito_tf($2) pe (produto bigint) where pe.produto = $1;

	if found then
		return true;
	else
		return false;
	end if;
end;

$_$;


ALTER FUNCTION public.produto_movimenta_deposito_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_movimenta_deposito_tf(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_deposito_tf(bigint) RETURNS SETOF record
    LANGUAGE sql
    AS $_$
select p.grid from produto p join deposito_grupo_produto dgp on (p.grupo=dgp.grupo) where dgp.deposito = $1 group by p.grid except (select pd.produto from produto_deposito pd where pd.deposito = $1 and pd.movimenta=False) union select produto from deposito where grid = $1 and not produto is null;
$_$;


ALTER FUNCTION public.produto_movimenta_deposito_tf(bigint) OWNER TO postgres;

--
-- Name: produto_movimenta_empresa_00tf(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_empresa_00tf(bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$
declare r1 record;
	    r2 record;
begin
	for r1 in select grid from deposito where empresa = $1 and produto is null loop
		for r2 in select * from produto_movimenta_deposito_tf(r1.grid) p (grid bigint) loop
			return next r2;
		end loop;
	end loop;

	for r1 in select distinct produto from deposito where empresa = $1 and not produto is null and flag='A' loop
		return next r1;
	end loop;

	return;
end;
$_$;


ALTER FUNCTION public.produto_movimenta_empresa_00tf(bigint) OWNER TO postgres;

--
-- Name: produto_movimenta_empresa_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_empresa_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

DECLARE 

	r record;
	v_movimenta boolean := FALSE;

BEGIN

	FOR r in SELECT d.grid AS deposito
	           FROM produto p
	           LEFT JOIN deposito_grupo_produto dgp ON (dgp.grupo=p.grupo)
	           JOIN deposito d ON ((d.grid=dgp.deposito OR d.produto=p.grid) AND d.empresa=$2 AND d.flag='A')
	          WHERE p.grid=$1
	LOOP

		SELECT FALSE INTO v_movimenta FROM produto_deposito pd WHERE pd.produto=$1 AND pd.deposito=r.deposito AND pd.movimenta=FALSE LIMIT 1;

		IF NOT FOUND THEN

			RETURN TRUE;

		END IF;

	END LOOP;

	RETURN FALSE;

END;

$_$;


ALTER FUNCTION public.produto_movimenta_empresa_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_movimenta_empresa_tf(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_empresa_tf(bigint) RETURNS SETOF record
    LANGUAGE sql
    AS $_$
select distinct grid from produto_movimenta_empresa_00tf($1) p (grid bigint);
$_$;


