--
-- Name: produto_movimenta_materia_prima_empresa_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_movimenta_materia_prima_empresa_f(bigint, bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$

BEGIN
  RETURN QUERY
	SELECT produto FROM produto_composicao
	WHERE materia_prima = $1 AND empresa = $2
	UNION
	SELECT produto FROM produto_composicao
	WHERE materia_prima = $1 AND empresa IS NULL
	AND produto NOT IN (SELECT produto FROM produto_composicao WHERE empresa = $2);
END;
  
$_$;


