--
-- Name: produto_negocio_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_negocio_f(bigint, bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

	/*Parametros:
	1-$1 produto
	2-$2 empresa
	3-Retorno o negocio do produto
	*/
	DECLARE
		v_negocio INTEGER := 1;
		v_empresa BIGINT;
		v_distribuidora INTEGER;
	BEGIN

		IF $2 is null THEN
			select empresa into v_empresa from empresa_local;
		ELSE
			v_empresa = $2;
		END IF;

		SELECT distribuidora INTO v_distribuidora FROM empresa_distribuidora WHERE empresa=v_empresa;

		-- ipiranga
		IF v_distribuidora = 1 THEN

			SELECT (CASE WHEN eip.negocio='P' THEN 1 WHEN eip.negocio='L' THEN 2  WHEN eip.negocio='J' THEN 3 END) as negocio 
			  INTO v_negocio
			  FROM produto_distribuidora pd
			  JOIN exc_ipp_produto eip on (eip.grid=pd.produto_dist)
			 WHERE pd.produto=$1;

			 -- se nao for ipp valida se e produto livre
			IF not found THEN

				SELECT eipl.negocio
				  INTO v_negocio
				  FROM exc_ipp_produto_livre eipl
				 WHERE eipl.produto=$1;

				-- se for kit sem vinculo com ipp retorna 1 para liberar a venda na loja e pista
				IF not found THEN
					SELECT 1
					  INTO v_negocio
					  FROM produto p
					 WHERE p.grid=$1
					   AND p.tipo='K'
					   AND produto_movimenta_empresa_f(p.grid, v_empresa);

					-- se nao for nenhuma das 3 opcoes ele retorna 0 para bloquear a venda
					IF not found THEN
						return 0;
					END IF;

				END IF; -- not found produto livre
			END IF; -- not found produto ipp
		END IF; -- if distribuidora ipp

		return v_negocio;

	END;
   
$_$;


ALTER FUNCTION public.produto_negocio_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_negocio_texaco_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_negocio_texaco_f(bigint, bigint) RETURNS integer
    LANGUAGE plpgsql
    AS $_$

	/*Parametros:
	1-$1 produto
	2-$2 empresa
	3-Retorno o negocio do produto
	*/
	DECLARE
		v_negocio INTEGER := 1;
		v_empresa BIGINT;
		v_distribuidora INTEGER;
	BEGIN

		IF $2 is null THEN
			select empresa into v_empresa from empresa_local;
		ELSE
			v_empresa = $2;
		END IF;

		SELECT distribuidora INTO v_distribuidora FROM empresa_distribuidora WHERE empresa=v_empresa;

		-- Texaco
		IF v_distribuidora = 6 THEN

			SELECT (CASE WHEN eip.negocio='P' THEN 1 WHEN eip.negocio='L' THEN 2  WHEN eip.negocio='J' THEN 3 END) as negocio 
			  INTO v_negocio
			  FROM produto_distribuidora pd
			  JOIN exc_texaco_produto eip on (eip.grid=pd.produto_dist)
			  JOIN exc_texaco_produto_empresa eipe on (eipe.produto=eip.grid and eipe.empresa=v_empresa)
			 WHERE pd.produto=$1;

			 -- se nao for Texaco valida se e produto livre
			IF not found THEN

				SELECT eiple.negocio
				  INTO v_negocio
				  FROM exc_texaco_produto_livre eipl
				  JOIN exc_texaco_produto_livre_empresa eiple on (eiple.produto_livre=eipl.grid and eiple.empresa=v_empresa)
				 WHERE eipl.produto=$1;

				-- se for kit sem vinculo com texaco retorna 1 para liberar a venda na loja e pista
				IF not found THEN
					SELECT 1
					  INTO v_negocio
					  FROM produto p
					 WHERE p.grid=$1
					   AND p.tipo='K'
					   AND produto_movimenta_empresa_f(p.grid, v_empresa);

					-- se nao for nenhuma das 3 opcoes ele retorna 0 para bloquear a venda
					IF not found THEN
						return 0;
					END IF;

				END IF; -- not found produto livre
			END IF; -- not found produto texaco
		END IF; -- if distribuidora texaco

		return v_negocio;

	END;
   
$_$;


ALTER FUNCTION public.produto_negocio_texaco_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_nome_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
