CREATE FUNCTION public.produto_nome_f(bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
select nome from produto where grid = $1;
$_$;


ALTER FUNCTION public.produto_nome_f(bigint) OWNER TO postgres;

--
-- Name: produto_nome_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_nome_f(bigint, bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
	selcon BOOL;
	dist INTEGER;
	descricao TEXT;
BEGIN
	SELECT distribuidora INTO dist FROM empresa_distribuidora WHERE empresa = $2;

	IF dist IS NOT NULL THEN

		-- IPIRANGA
		IF dist = 1 THEN
			
			SELECT nome INTO descricao 
			FROM produto_distribuidora pd
			JOIN exc_ipp_produto eip on (eip.grid=pd.produto_dist)
			JOIN exc_ipp_produto_empresa eipe on (eipe.produto=eip.grid and eipe.empresa=$2) 
			WHERE pd.produto=$1 AND pd.distribuidora = dist;

		-- TEXACO
		ELSEIF dist = 6 THEN

			SELECT nome INTO descricao
			FROM produto_distribuidora pd
			JOIN exc_texaco_produto etp on (etp.grid=pd.produto_dist)
			JOIN exc_texaco_produto_empresa etpe on (etpe.produto=etp.grid and etpe.empresa=$2)
			WHERE pd.produto=$1 AND pd.distribuidora = dist;

		-- RAIZEN SHELL/COSAN
		ELSEIF dist in (2, 3, 5) THEN

			SELECT true INTO selcon FROM exc_rz_config WHERE (coalesce(integracao_ws, 0)&2)::BOOL LIMIT 1;
			IF FOUND THEN
				SELECT nome INTO descricao 
				FROM exc_rz_selcon_produto rzp
					JOIN produto_distribuidora pd 
						ON (pd.produto = $1 AND pd.distribuidora = dist AND pd.produto_dist = rzp.grid);
			ELSE
				SELECT nome INTO descricao 
				FROM exc_rz_produto rzp
					JOIN produto_distribuidora pd 
						ON (pd.produto = $1 AND pd.distribuidora = dist AND pd.produto_dist = rzp.grid);
			END IF;

		END IF;

		IF descricao IS NULL THEN
			SELECT produto_nome_f($1) INTO descricao;
		END IF;

		RETURN descricao;
	END IF;

	SELECT produto_nome_f($1) INTO descricao;
	RETURN descricao;
END;
   
$_$;


ALTER FUNCTION public.produto_nome_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_nome_reduzido_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_nome_reduzido_f(bigint) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $_$
select substr(split_part(p.nome,' ',1),1,1)||substr(split_part(p.nome,' ',2),1,1)||substr(split_part(p.nome,' ',3),1,1) as nome from produto p where grid = $1;
$_$;


ALTER FUNCTION public.produto_nome_reduzido_f(bigint) OWNER TO postgres;

--
-- Name: produto_nome_reduzido_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_nome_reduzido_f(bigint, bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE
	selcon BOOL;
	dist INTEGER;
	descricao TEXT;
BEGIN
	SELECT distribuidora INTO dist FROM empresa_distribuidora WHERE empresa = $2;

	IF dist IS NOT NULL THEN

		-- IPIRANGA
		IF dist = 1 THEN

			SELECT nome_resumido INTO descricao 
			FROM produto_distribuidora pd
			JOIN exc_ipp_produto eip on (eip.grid=pd.produto_dist)
			JOIN exc_ipp_produto_empresa eipe on (eipe.produto=eip.grid and eipe.empresa=$2) 
			WHERE pd.produto=$1 AND pd.distribuidora = dist;

		-- TEXACO
		ELSEIF dist = 6 THEN

			SELECT nome_resumido INTO descricao
			FROM produto_distribuidora pd
			JOIN exc_texaco_produto etp on (etp.grid=pd.produto_dist)
			JOIN exc_texaco_produto_empresa etpe on (etpe.produto=etp.grid and etpe.empresa=$2)
			WHERE pd.produto=$1 AND pd.distribuidora = dist;

		-- RAIZEN SHELL/COSAN
		ELSEIF dist in (2, 3, 5) THEN

			SELECT true INTO selcon FROM exc_rz_config WHERE (coalesce(integracao_ws, 0)&2)::BOOL LIMIT 1;
			IF FOUND THEN
				SELECT nome_resumido INTO descricao 
				FROM exc_rz_selcon_produto rzp
					JOIN produto_distribuidora pd 
						ON (pd.produto = $1 AND pd.distribuidora = dist AND pd.produto_dist = rzp.grid);
			ELSE
				SELECT nome_resumido INTO descricao 
				FROM exc_rz_produto rzp
					JOIN produto_distribuidora pd 
						ON (pd.produto = $1 AND pd.distribuidora = dist AND pd.produto_dist = rzp.grid);
			END IF;

		END IF;
		
		IF descricao IS NULL THEN
			SELECT nome_resumido INTO descricao FROM produto WHERE grid = $1;
		END IF;

		RETURN descricao;
	END IF;

	SELECT nome_resumido INTO descricao FROM produto WHERE grid = $1;
	RETURN descricao;
END;
	
$_$;


ALTER FUNCTION public.produto_nome_reduzido_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_permite_compra_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_permite_compra_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

/*Parametros:
1-$1 produto
2-$2 empresa
3-Retorno TRUE or FALSE
*/

DECLARE

v_permite_compra BOOLEAN;
v_empresa BIGINT;
v_distribuidora BIGINT;
r_produto RECORD;

BEGIN

IF $2 IS NULL THEN
select empresa into v_empresa from empresa_local;
ELSE
v_empresa := $2;
END IF;

select distribuidora into v_distribuidora from empresa_distribuidora where empresa=v_empresa;

IF v_distribuidora in (4, 5) THEN
select coalesce(p.permite_compra, TRUE) as permite_compra, coalesce(p.permite_compra_dist, TRUE) as permite_compra_dist into r_produto from produto p where p.grid=$1;

IF not (r_produto.permite_compra and r_produto.permite_compra_dist) THEN
-- se for false para o produto automaticamente e false para todas as empresas
return FALSE;
END IF;

select coalesce((case when permite_compra=1 then TRUE when permite_compra=2 then FALSE else (select permite_compra from produto p where p.grid=$1) end), TRUE) as permite_compra, coalesce((case when permite_compra_dist=1 then TRUE when permite_compra_dist=2 then FALSE else (select permite_compra_dist from produto p where p.grid=$1) end), TRUE) as permite_compra_dist into r_produto from produto_empresa where produto=$1 and empresa=v_empresa;

IF NOT FOUND THEN
-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
return TRUE;
END IF;

return r_produto.permite_compra and r_produto.permite_compra_dist;

END IF;

select coalesce(p.permite_compra, TRUE) into v_permite_compra from produto p where p.grid=$1;

IF not v_permite_compra THEN
-- se for false para o produto automaticamente e false para todas as empresas
return FALSE;
END IF;

select coalesce((case when permite_compra=1 then TRUE when permite_compra=2 then FALSE else (select permite_compra from produto p where p.grid=$1) end), TRUE) into v_permite_compra  from produto_empresa where produto=$1 and empresa=$2;

IF NOT FOUND THEN
-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
return TRUE;
END IF;

return v_permite_compra;

END;

$_$;


ALTER FUNCTION public.produto_permite_compra_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_permite_venda_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_permite_venda_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

/*Parametros:
1-$1 produto
2-$2 empresa
3-Retorno TRUE or FALSE
*/

DECLARE

	v_permite_venda BOOLEAN;
	v_empresa BIGINT;
	v_distribuidora BIGINT;
	r_produto RECORD;

BEGIN

	IF $2 IS NULL THEN
		select empresa into v_empresa from empresa_local;
	ELSE
		v_empresa := $2;
	END IF;

	select distribuidora into v_distribuidora from empresa_distribuidora where empresa=v_empresa;

	IF v_distribuidora in (4, 5, 6) THEN
		select coalesce(p.permite_venda, TRUE) as permite_venda, coalesce(p.permite_venda_dist, TRUE) as permite_venda_dist into r_produto from produto p where p.grid=$1;

		IF not (r_produto.permite_venda and r_produto.permite_venda_dist) THEN
			-- se for false para o produto automaticamente e false para todas as empresas
			return FALSE;
		END IF;

		select coalesce(permite_venda, TRUE) as permite_venda, coalesce(permite_venda_dist, TRUE) as permite_venda_dist into r_produto from produto_empresa where produto=$1 and empresa=v_empresa;

		IF NOT FOUND THEN
			-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
			return TRUE;
		END IF;

		return r_produto.permite_venda and r_produto.permite_venda_dist;

	END IF;

	select coalesce(p.permite_venda, TRUE) into v_permite_venda from produto p where p.grid=$1;

	IF not v_permite_venda THEN
		-- se for false para o produto automaticamente e false para todas as empresas
		return FALSE;
	END IF;

	select coalesce(permite_venda, TRUE) into v_permite_venda from produto_empresa where produto=$1 and empresa=v_empresa;

	IF NOT FOUND THEN
		-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
		return TRUE;
	END IF;

	return v_permite_venda;

END;

$_$;


ALTER FUNCTION public.produto_permite_venda_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_permite_venda_f(bigint, bigint, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_permite_venda_f(bigint, bigint, text) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

	/*Parametros:
	1-$1 produto
	2-$2 empresa
	3-$3 codigo_barra
	4-Retorno TRUE or FALSE
	*/

	DECLARE
		v_produto RECORD;
		v_empresa BIGINT;
		v_resultado BOOLEAN;
		v_distribuidora BIGINT;
		v_permite_venda BOOLEAN;
		v_ativo BOOLEAN;
		v_produto_sencundario BOOLEAN;
		v_componente_empresa RECORD;
		v_componente_somente_pista BOOLEAN;
		v_produto_info RECORD;
		v_produto_livre BOOLEAN;

	BEGIN
		v_resultado := FALSE;
		
		IF $2 IS NULL THEN
			SELECT empresa INTO v_empresa FROM empresa_local;
		ELSE
			v_empresa := $2;
		END IF;

		-- Se produto n„o permite venda, n„o precisa ser verificado o codigo de barras
		SELECT produto_verifica_permite_venda_f($1, v_empresa) INTO v_permite_venda;

		RAISE NOTICE 'valor de v_permite_venda : %', v_permite_venda;		

		IF not v_permite_venda THEN
			RETURN FALSE;
		END IF;

		IF $3 IS NULL THEN
			RAISE NOTICE 'Codigo nulo';
			RETURN TRUE;
		END IF;

		SELECT distribuidora INTO v_distribuidora FROM empresa_distribuidora WHERE empresa = v_empresa;
		
		RAISE NOTICE 'Distribuidora : %', v_distribuidora;

		IF v_distribuidora = 1 THEN --Ipiranga	

			-- Se codigo do produto, j· foi validado na funcao produto_verifica_permite_venda_f 
			SELECT count(p.grid) > 0 INTO v_resultado FROM produto p WHERE p.grid = $1 AND p.codigo = $3;

			IF v_resultado THEN
				RETURN TRUE;
			END IF;

			RAISE NOTICE 'Validando produto vinculado/livre Ipiranga';

			SELECT pd.grid as produto_vinculado, 
						(CASE WHEN eip.data_bloq_venda IS NOT NULL AND eip.data_bloq_venda < now() 
							THEN true ELSE false END) as produto_bloqueado,
						eip.negocio as produto_negocio,
						COALESCE((SELECT true from produto_codigo_barra pcb where pcb.codigo_barra = $3), false) as produto_secundario
			INTO v_produto_info 
			FROM produto_distribuidora pd
			JOIN produto p ON p.grid = pd.produto
			JOIN exc_ipp_produto eip ON pd.produto_dist = eip.grid AND coalesce(eip.codigo, p.codigo_barra, p.codigo) = $3
			LEFT JOIN exc_ipp_produto_empresa eipe ON eip.grid = eipe.produto AND eipe.empresa = v_empresa
			WHERE pd.produto = $1
					AND pd.distribuidora = 1
					AND (eip.codigo = $3 OR p.codigo_barra = $3 OR p.codigo = $3)
			ORDER BY (CASE WHEN eip.codigo = $3 OR p.codigo_barra = $3 OR p.codigo = $3 THEN 0 ELSE 1 END)
			LIMIT 1;

			SELECT count(eipl.grid) > 0 
			INTO v_produto_livre 
			FROM exc_ipp_produto_livre eipl
			LEFT JOIN exc_ipp_produto_livre_empresa eiple ON eiple.produto_livre = eipl.grid and eiple.empresa = v_empresa
			WHERE eipl.produto = $1 
				AND NOT EXISTS (SELECT 1 FROM produto_distribuidora pd
					JOIN exc_ipp_produto eip ON eip.grid = pd.produto_dist
					LEFT JOIN exc_ipp_produto_empresa eipe ON eipe.produto = eip.grid
					WHERE pd.produto = $1 
								AND eipe.empresa = v_empresa
								AND pd.distribuidora = 1 
								AND eip.codigo = $3 LIMIT 1);

			SELECT count(pcb1.grid) > 0 INTO v_produto_sencundario FROM produto_codigo_barra pcb1 WHERE pcb1.codigo_barra = $3;

			SELECT tipo INTO v_produto FROM produto WHERE grid = $1;

			RAISE NOTICE 'Validando negocio do produto com Caixa';

			SELECT CASE WHEN LENGTH(COALESCE(codigo_pista, '')) > 0 THEN true ELSE false END as is_pista,
					CASE WHEN LENGTH(COALESCE(codigo_jetoil, '')) > 0 THEN true ELSE false END as is_jetoil,
					CASE WHEN LENGTH(COALESCE(codigo_ampm, '')) > 0 THEN true ELSE false END as is_ampm
			INTO v_componente_empresa 
			FROM exc_ipp_config 
			WHERE empresa = v_empresa;

			RAISE NOTICE 'Produto esta vinculado % ', v_produto_info.produto_vinculado;
			RAISE NOTICE 'Produto esta bloqueado % ', v_produto_info.produto_bloqueado;
			RAISE NOTICE 'Produto esta livre % ', v_produto_livre;
			RAISE NOTICE 'Produto tipo % ', v_produto.tipo;
			RAISE NOTICE 'Valor de v_produto_sencundario: %', v_produto_info.produto_secundario;
			RAISE NOTICE 'Valor de v_produto_info.produto_negocio: %', v_produto_info.produto_negocio;

			IF (v_produto_info.produto_vinculado IS NOT NULL AND NOT v_produto_info.produto_bloqueado) OR (v_produto_livre) THEN
				v_resultado = True;
			END IF;

			if v_produto_info.produto_vinculado IS NULL AND v_produto_info.produto_secundario IS NULL AND NOT v_produto_livre AND v_produto.tipo = 'K' THEN
				v_resultado = True;
			END IF;

			v_componente_somente_pista = False;
			IF (v_componente_empresa.is_pista AND (NOT v_componente_empresa.is_jetoil OR NOT v_componente_empresa.is_ampm)) THEN
				v_componente_somente_pista = True;
			END IF;

			RAISE NOTICE 'Valor de v_componente_somente_pista: %', v_componente_somente_pista;

			IF NOT v_resultado AND v_produto_info.produto_bloqueado THEN
				RAISE NOTICE 'Validando negocio do produto Jet ou Loja';
				
				IF v_componente_somente_pista AND NOT v_componente_empresa.is_jetoil AND v_produto_info.produto_negocio = 'J' THEN
					v_resultado = True;
				END IF;

				IF v_componente_somente_pista AND NOT v_componente_empresa.is_ampm AND v_produto_info.produto_negocio = 'L' THEN
					v_resultado = True;
				END IF;

			END IF;

			RAISE NOTICE 'Valor de v_resultado para retorno: %', v_resultado;

			RETURN v_resultado;

		ELSIF v_distribuidora = 4 THEN --BR
			select ativo into v_ativo from exc_br_config where empresa = v_empresa;
			RAISE NOTICE 'Distribuidora ativa: %', v_ativo;
			IF v_ativo THEN
				SELECT count(*) > 0 into v_resultado FROM produto_distribuidora pd
					JOIN produto p ON p.grid = pd.produto
					JOIN exc_br_produto br ON br.grid = pd.produto_dist
					WHERE pd.produto = $1 AND (br.codigo_barra = $3 or p.codigo = $3);

				--verificar produto livre
				IF NOT v_resultado THEN
					RAISE NOTICE 'Validando produto livre';
					SELECT count(*) > 0 into v_resultado FROM exc_br_inclusao_cadastro eic
						WHERE eic.produto = $1 AND eic.empresa = v_empresa;
				END IF;	

				--verificar kit comum
				IF NOT v_resultado THEN			
					RAISE NOTICE 'Validando kit comum';
					SELECT count(*) > 0 into v_resultado FROM produto p LEFT JOIN produto_codigo_barra pcb ON (p.grid = pcb.produto)
					WHERE p.grid = $1 AND (p.codigo = $3 OR p.codigo_barra = $3 OR pcb.codigo_barra = $3) AND p.tipo = 'K';
				END IF;

				RETURN v_resultado;

			END IF;

		ELSIF v_distribuidora = 5 THEN --RAIZEN
			-- Falta implementar
			RETURN TRUE;
			
		END IF;

		-- Se codigo do produto
		SELECT count(*) > 0 INTO v_resultado FROM produto p WHERE p.grid = $1 AND p.codigo = $3;
		RAISE NOTICE 'permite venda produto pelo codigo: %', v_resultado;
		-- Se codigo de barras
		IF NOT v_resultado THEN
			select count(*) > 0 INTO v_resultado from produto p where p.grid = $1 AND p.codigo_barra = $3;
			RAISE NOTICE 'permite venda produto pelo codigo barra produto: %', v_resultado;
		END IF;

		IF NOT v_resultado THEN
			SELECT COUNT(*) > 0 INTO v_resultado FROM produto_codigo_barra pcb where pcb.produto = $1 and pcb.codigo_barra = $3;
			RAISE NOTICE 'permite venda produto pelo codigo barra adicional do produto: %', v_resultado;
		END IF;			

		RETURN v_resultado;

	END;
	
$_$;


ALTER FUNCTION public.produto_permite_venda_f(bigint, bigint, text) OWNER TO postgres;

--
-- Name: produto_permite_venda_ipp_f(bigint, bigint, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_permite_venda_ipp_f(bigint, bigint, text, integer) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

	/*
    Parametros:
	1-$1 produto
	2-$2 empresa
	3-$3 codigo_barra
    4-$4 negocio_caixa
            ver lista em classe/ipiranga.py:
            IPIRANGA_NEGOCIO_PISTA = 1
            IPIRANGA_NEGOCIO_AMPM = 2
            IPIRANGA_NEGOCIO_JETOIL = 3
            IPIRANGA_NEGOCIO_PADRAO_GRUPO = 4
            IPIRANGA_NEGOCIO_PADARIA = 5
            IPIRANGA_NEGOCIO_CONECTA = 8
	5-Retorno TRUE or FALSE
    */

	DECLARE
		v_componente_empresa RECORD;
		v_empresa BIGINT;
        v_negocio_caixa INTEGER;
        v_negocio_permite_venda BOOLEAN;
		v_permite_venda BOOLEAN;
		v_produto RECORD;
        v_produto_codigo TEXT;
        v_produto_distr RECORD;
		v_produto_livre_negocio INTEGER;
		v_resultado BOOLEAN;
        v_somente_pista BOOLEAN;

	BEGIN
		IF $2 IS NULL THEN
			SELECT empresa INTO v_empresa FROM empresa_local;
		ELSE
			v_empresa := $2;
		END IF;

		-- Se produto n„o permite venda, n„o precisa ser verificado o codigo de barras
		SELECT produto_verifica_permite_venda_f($1, v_empresa) INTO v_permite_venda;

		RAISE NOTICE 'Produto permite venda (cadastro): %', v_permite_venda;		

		IF not v_permite_venda THEN
			RETURN False;
		END IF;

        -- Busca dados do produto pelo grid
        SELECT p.tipo, p.codigo_barra, pcb.codigo_barra AS codigo_secundario
        INTO v_produto 
        FROM produto p
            LEFT JOIN produto_codigo_barra pcb ON (pcb.produto = p.grid and pcb.codigo_barra = $3)
        WHERE p.grid = $1;
        
        IF v_produto.codigo_secundario IS NOT NULL THEN
            v_produto_codigo := v_produto.codigo_secundario;
        ELSE
            v_produto_codigo := v_produto.codigo_barra;
        END IF;

        -- Verifica se È produto livre
        SELECT eipl.negocio 
        INTO v_produto_livre_negocio 
        FROM exc_ipp_produto_livre eipl
        LEFT JOIN exc_ipp_produto_livre_empresa eiple ON eiple.produto_livre = eipl.grid and eiple.empresa = v_empresa
        WHERE eipl.produto = $1 
            AND NOT EXISTS (
                SELECT 1 FROM produto_distribuidora pd
                    JOIN exc_ipp_produto eip ON eip.grid = pd.produto_dist
                    LEFT JOIN exc_ipp_produto_empresa eipe ON eipe.produto = eip.grid
                    WHERE pd.produto = $1 
                        AND eipe.empresa = v_empresa
                        AND pd.distribuidora = 1
                    LIMIT 1
                );

        v_negocio_caixa := $4;

        IF v_produto_livre_negocio = 1 THEN
            RAISE NOTICE 'Produto livre pista: Venda liberada!';
            RETURN True;
        
        ELSIF v_produto_livre_negocio = 2 AND v_negocio_caixa IN (2, 8) THEN
            RAISE NOTICE 'Produto livre ampm: Venda liberada!';
            RETURN True;
        
        END IF;

        -- Busca informaÁıes de vÌnculo do produto
        SELECT pd.grid as vinculado, eip.negocio,
            (CASE WHEN eip.data_bloq_venda IS NOT NULL AND eip.data_bloq_venda < now() THEN true ELSE false END) as bloqueado
        INTO v_produto_distr
        FROM produto_distribuidora pd
            JOIN exc_ipp_produto eip ON eip.grid = pd.produto_dist
            LEFT JOIN exc_ipp_produto_empresa eipe ON (eip.grid = eipe.produto AND eipe.empresa = v_empresa)
        WHERE pd.distribuidora = 1 AND pd.produto = $1 AND eip.codigo = v_produto_codigo;

        RAISE NOTICE 'Caixa negocio:      % ', v_negocio_caixa;
        RAISE NOTICE 'Produto bloq.venda: % ', v_produto_distr.bloqueado;
        RAISE NOTICE 'Produto tipo:       % ', v_produto.tipo;
        RAISE NOTICE 'Produto negocio:    % ', v_produto_distr.negocio;
        RAISE NOTICE 'Produto vinculado:  % ', v_produto_distr.vinculado;
        RAISE NOTICE 'Produto secundario: % ', v_produto.codigo_secundario;

        SELECT CASE WHEN LENGTH(COALESCE(codigo_pista, '')) > 0 THEN true ELSE false END as is_pista,
            CASE WHEN LENGTH(COALESCE(codigo_jetoil, '')) > 0 THEN true ELSE false END as is_jetoil,
            CASE WHEN LENGTH(COALESCE(codigo_ampm, '')) > 0 THEN true ELSE false END as is_ampm
        INTO v_componente_empresa 
        FROM exc_ipp_config 
        WHERE empresa = v_empresa;

        -- Libera produtos de loja e jet oil quando a empresa È AS3/Conecta ou AIL somente pista
        v_somente_pista := v_componente_empresa.is_pista AND NOT (v_componente_empresa.is_jetoil OR v_componente_empresa.is_ampm);

        IF (v_negocio_caixa = 8 OR v_somente_pista) AND v_produto_distr.negocio <> 'P' THEN
            RAISE NOTICE 'Somente pista: Liberado produto que nao eh de pista!';
            RETURN True;
        END IF;

        -- Valida demais regras de negÛcio
        IF v_produto_distr.negocio = 'J' THEN
            v_negocio_permite_venda := True;

        ELSIF v_produto_distr.negocio = 'P' AND v_negocio_caixa IN (1, 2, 8) THEN
            v_negocio_permite_venda := True;

        ELSIF v_produto_distr.negocio = 'L' AND (v_negocio_caixa = 2 OR NOT v_componente_empresa.is_ampm) THEN
            v_negocio_permite_venda := True;
        
        ELSE
            v_negocio_permite_venda := False;

        END IF;

        IF v_negocio_permite_venda AND v_produto_distr.vinculado IS NOT NULL AND NOT v_produto_distr.bloqueado THEN
            v_resultado := True;

        ELSIF v_produto_distr.vinculado IS NULL AND v_produto.codigo_secundario IS NULL AND v_produto.tipo = 'K' THEN
            v_resultado := True;

        ELSE
            v_resultado := False;

        END IF;

        RAISE NOTICE 'Negocio permite venda: %', v_negocio_permite_venda;
        RAISE NOTICE 'Produto permite venda: %', v_resultado;

        RETURN v_resultado;

	END;
	
$_$;


ALTER FUNCTION public.produto_permite_venda_ipp_f(bigint, bigint, text, integer) OWNER TO postgres;

--
-- Name: produto_permite_venda_ipp_f(bigint, bigint, text, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_permite_venda_ipp_f(bigint, bigint, text, integer, boolean) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

	/*
    Parametros:
	1-$1 produto
	2-$2 empresa
	3-$3 codigo_barra
    4-$4 negocio_caixa
            ver lista em classe/ipiranga.py:
            IPIRANGA_NEGOCIO_PISTA = 1
            IPIRANGA_NEGOCIO_AMPM = 2
            IPIRANGA_NEGOCIO_JETOIL = 3
            IPIRANGA_NEGOCIO_PADRAO_GRUPO = 4
            IPIRANGA_NEGOCIO_PADARIA = 5
            IPIRANGA_NEGOCIO_CONECTA = 8
	5-$5 regras_venda_ativas
    6-Retorno TRUE or FALSE
    */

	DECLARE
		v_componente_empresa RECORD;
		v_empresa BIGINT;
        v_negocio_caixa INTEGER;
        v_negocio_permite_venda BOOLEAN;
		v_permite_venda BOOLEAN;
		v_produto RECORD;
        v_produto_codigo TEXT;
        v_produto_distr RECORD;
		v_produto_livre_negocio INTEGER;
		v_resultado BOOLEAN;
        v_somente_pista BOOLEAN;

	BEGIN
        -- Se n„o È informada a empresa, busca grid da empresa local
		IF $2 IS NULL THEN
			SELECT empresa INTO v_empresa FROM empresa_local;
		ELSE
			v_empresa := $2;
		END IF;

		-- Valida bloqueio de venda no cadastro do produto
		SELECT produto_verifica_permite_venda_f($1, v_empresa) INTO v_permite_venda;

		RAISE NOTICE 'Produto permite venda (cadastro): %', v_permite_venda;		

		IF not v_permite_venda THEN
			RETURN False;
		END IF;

        -- Busca dados do produto pelo grid
        SELECT p.tipo, p.codigo_barra, pcb.codigo_barra AS codigo_secundario
        INTO v_produto 
        FROM produto p
            LEFT JOIN produto_codigo_barra pcb ON (pcb.produto = p.grid and pcb.codigo_barra = $3)
        WHERE p.grid = $1;
        
        IF v_produto.codigo_secundario IS NOT NULL THEN
            v_produto_codigo := v_produto.codigo_secundario;
        ELSE
            v_produto_codigo := v_produto.codigo_barra;
        END IF;

        -- Verifica se È produto livre
        SELECT eipl.negocio 
        INTO v_produto_livre_negocio 
        FROM exc_ipp_produto_livre eipl
        LEFT JOIN exc_ipp_produto_livre_empresa eiple ON eiple.produto_livre = eipl.grid and eiple.empresa = v_empresa
        WHERE eipl.produto = $1 
            AND NOT EXISTS (
                SELECT 1 FROM produto_distribuidora pd
                    JOIN exc_ipp_produto eip ON eip.grid = pd.produto_dist
                    LEFT JOIN exc_ipp_produto_empresa eipe ON eipe.produto = eip.grid
                    WHERE pd.produto = $1 
                        AND eipe.empresa = v_empresa
                        AND pd.distribuidora = 1
                    LIMIT 1
                );

        v_negocio_caixa := $4;

        IF v_produto_livre_negocio = 1 AND v_negocio_caixa IN (1, 2, 8) THEN
            RAISE NOTICE 'Produto livre pista: Venda liberada!';
            RETURN True;
        
        ELSIF v_produto_livre_negocio = 2 AND v_negocio_caixa IN (2, 8) THEN
            RAISE NOTICE 'Produto livre ampm: Venda liberada!';
            RETURN True;

        ELSIF v_produto_livre_negocio = 2 AND NOT $5 THEN
            RAISE NOTICE 'Produto livre ampm: O bloqueio n„o ser· aplicado pois as regras de venda n„o est„o ativas para esta empresa.';
            RETURN True;

        END IF;

        -- Busca informaÁıes de vÌnculo do produto
        SELECT pd.grid as vinculado, eip.negocio,
            (CASE WHEN eip.data_bloq_venda IS NOT NULL AND eip.data_bloq_venda < now() THEN true ELSE false END) as bloqueado
        INTO v_produto_distr
        FROM produto_distribuidora pd
            JOIN exc_ipp_produto eip ON eip.grid = pd.produto_dist
            LEFT JOIN exc_ipp_produto_empresa eipe ON (eip.grid = eipe.produto AND eipe.empresa = v_empresa)
        WHERE pd.distribuidora = 1 AND pd.produto = $1
        ORDER BY eip.data_bloq_venda DESC, eip.grid DESC
        LIMIT 1;

        RAISE NOTICE 'Caixa negocio:      % ', v_negocio_caixa;
        RAISE NOTICE 'Produto bloq.venda: % ', v_produto_distr.bloqueado;
        RAISE NOTICE 'Produto tipo:       % ', v_produto.tipo;
        RAISE NOTICE 'Produto negocio:    % ', v_produto_distr.negocio;
        RAISE NOTICE 'Produto vinculado:  % ', v_produto_distr.vinculado;
        RAISE NOTICE 'Codigo secundario:  % ', v_produto.codigo_secundario;

        SELECT CASE WHEN LENGTH(COALESCE(codigo_pista, '')) > 0 THEN true ELSE false END as is_pista,
            CASE WHEN LENGTH(COALESCE(codigo_jetoil, '')) > 0 THEN true ELSE false END as is_jetoil,
            CASE WHEN LENGTH(COALESCE(codigo_ampm, '')) > 0 THEN true ELSE false END as is_ampm
        INTO v_componente_empresa 
        FROM exc_ipp_config 
        WHERE empresa = v_empresa;

        -- Libera produtos de loja e jet oil quando a empresa È AS3/Conecta ou AIL somente pista
        v_somente_pista := v_componente_empresa.is_pista AND NOT (v_componente_empresa.is_jetoil OR v_componente_empresa.is_ampm);

        IF (v_negocio_caixa = 8 OR v_somente_pista) AND v_produto_distr.negocio <> 'P' THEN
            RAISE NOTICE 'Somente pista: Liberado produto que nao eh de pista!';
            RETURN True;
        END IF;

        -- Valida demais regras de negÛcio
        IF v_produto_distr.negocio = 'J' THEN
            v_negocio_permite_venda := True;

        ELSIF v_produto_distr.negocio = 'P' AND v_negocio_caixa IN (1, 2, 8) THEN
            v_negocio_permite_venda := True;

        ELSIF v_produto_distr.negocio = 'L' AND (v_negocio_caixa = 2 OR NOT v_componente_empresa.is_ampm) THEN
            v_negocio_permite_venda := True;
        
        ELSE
            v_negocio_permite_venda := False;

        END IF;

        IF v_negocio_permite_venda AND v_produto_distr.vinculado IS NOT NULL AND NOT v_produto_distr.bloqueado THEN
            v_resultado := True;

        ELSIF v_produto_distr.vinculado IS NULL AND v_produto.codigo_secundario IS NULL AND v_produto.tipo = 'K' THEN
            v_resultado := True;

        ELSE
            v_resultado := False;

        END IF;

        RAISE NOTICE 'Negocio permite venda: %', v_negocio_permite_venda;
        RAISE NOTICE 'Produto permite venda: %', v_resultado;

        IF NOT v_resultado AND NOT $5 AND NOT v_produto_distr.bloqueado THEN
            RAISE NOTICE 'O bloqueio n„o ser· aplicado pois as regras de venda n„o est„o ativas para esta empresa.';
            v_resultado := True;
        END IF;

        RETURN v_resultado;

	END;
	
$_$;


ALTER FUNCTION public.produto_permite_venda_ipp_f(bigint, bigint, text, integer, boolean) OWNER TO postgres;

--
-- Name: produto_principal_venda_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_principal_venda_f(bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	ret text;
begin
	if (($1 is null) or ($1 = 0::bigint)) then
		return null;
	end if;

	select into r p.nome, p.unid_med, round(l.quantidade::numeric, 3) as quantidade from lancto l join produto p on (l.produto=p.grid) where l.mlid=$1 and l.operacao = 'V' order by abs(l.valor) desc limit 1;

	if found then
		ret := r.nome || ' // ' || round(r.quantidade::numeric, 3)::float8::text || ' ' || r.unid_med;

		select into r count(*) from lancto where mlid=$1 and operacao = 'V';

		if r.count > 1 then
			ret := '+ ' || ret;
		end if;
	end if;

	return ret;
end
$_$;


ALTER FUNCTION public.produto_principal_venda_f(bigint) OWNER TO postgres;

--
-- Name: produto_trib_cfop_seq; Type: SEQUENCE; Schema: public; Owner: postgres
--

CREATE SEQUENCE public.produto_trib_cfop_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;


ALTER TABLE public.produto_trib_cfop_seq OWNER TO postgres;

--
-- Name: produto_trib_cfop; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.produto_trib_cfop (
    id bigint DEFAULT nextval('public.produto_trib_cfop_seq'::regclass) NOT NULL,
    produto_id bigint,
    natureza_op_id bigint,
    uf text,
    cfop text,
    tributacao_id bigint
);


ALTER TABLE public.produto_trib_cfop OWNER TO postgres;

--
-- Name: produto_trib_cfop_f(text, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_trib_cfop_f(text, bigint, bigint, bigint, bigint) RETURNS SETOF public.produto_trib_cfop
    LANGUAGE plpgsql
    AS $_$

	DECLARE
		t1 produto_trib_cfop;
		t2 produto_trib_cfop;
		t3 produto_trib_cfop;
		not_in_pos_1 text;
		not_in_pos_2 text;
	BEGIN
		not_in_pos_1 := '{0';
		not_in_pos_2 := '{0';

		FOR t1 IN
			SELECT
				CAST(p.grid AS BIGINT) AS id,
				CAST(p.grid AS BIGINT) AS produto_id,
				CAST(nop.grid AS BIGINT) AS natureza_op_id,  
				CAST(pc.uf AS TEXT) AS uf,  
				CAST(pc.cfop AS TEXT) AS cfop,
				CASE WHEN pt.grid is NOT NULL then (SELECT grid FROM tributacao WHERE codigo = pt.tributacao) ELSE t.grid END AS tributacao_id
			FROM produto p
			LEFT JOIN produto_cfop pc ON (pc.produto = p.grid AND (coalesce(pc.de, null) is null or coalesce(pc.de, '') = '' or pc.de = $1)) 
			JOIN natureza_op nop ON (nop.grid = pc.natureza_op)  
			LEFT JOIN produto_tributacao pt ON (p.grid = pt.produto AND pt.de = $1 AND pt.tipo = 'E') 
			JOIN tributacao t ON (t.codigo = (CASE WHEN pt.tributacao IS NOT NULL THEN pt.tributacao ELSE p.tributacao END))
			WHERE p.flag = 'A'  
				AND p.tipo in ('M', 'C', 'K')
				AND produto_movimenta_empresa_f(p.grid, $2)
				AND (CASE WHEN $3 IS NOT NULL THEN p.grid = $3 ELSE true END)
				AND (CASE WHEN $4 IS NOT NULL THEN nop.grid = $4 ELSE true END)
				AND (CASE WHEN $5 IS NOT NULL THEN t.grid = $5 ELSE true END)
		LOOP
			not_in_pos_1 := not_in_pos_1 || ', ' || t1.id::text;
			RETURN NEXT t1; 
		END LOOP;
	
		not_in_pos_1 := not_in_pos_1 || '}';
		FOR t2 IN
			SELECT  
				CAST(p.grid AS BIGINT) AS id,
				CAST(p.grid AS BIGINT) AS produto_id,
				CAST(nop.grid AS BIGINT) AS natureza_op_id,  
				CAST(gpc.uf AS TEXT) AS uf,  
				CAST(gpc.cfop AS TEXT) AS cfop,
				CASE WHEN pt.grid is NOT NULL then (SELECT grid FROM tributacao WHERE codigo = pt.tributacao) ELSE t.grid END AS tributacao_id
			FROM produto p   
			LEFT JOIN produto_cfop pc ON (pc.produto = p.grid AND (coalesce(pc.de, null) is null or coalesce(pc.de, '') = '' or pc.de = $1))  
			LEFT JOIN grupo_produto_cfop gpc ON (gpc.grupo_produto = p.grupo AND (coalesce(gpc.de, null) is null or coalesce(gpc.de, '') = '' or gpc.de = $1)) 
			JOIN natureza_op nop ON (nop.grid =  gpc.natureza_op)  
			LEFT JOIN produto_tributacao pt ON (p.grid = pt.produto AND pt.de = $1 AND pt.tipo = 'E') 
			JOIN tributacao t ON (t.codigo = (CASE WHEN pt.tributacao IS NOT NULL THEN pt.tributacao ELSE p.tributacao END))
			WHERE p.flag = 'A'
				AND p.tipo in ('M', 'C', 'K') 
				AND produto_movimenta_empresa_f(p.grid, $2)
				AND not p.grid = ANY(not_in_pos_1::bigint[])
				AND (CASE WHEN $3 IS NOT NULL THEN p.grid = $3 ELSE true END)
				AND (CASE WHEN $4 IS NOT NULL THEN nop.grid = $4 ELSE true END)
				AND (CASE WHEN $5 IS NOT NULL THEN t.grid = $5 ELSE true END)
		LOOP
			not_in_pos_2 := not_in_pos_2 || ', ' || t2.id::text;
			RETURN NEXT t2; 
		END LOOP;

		not_in_pos_2 := not_in_pos_2 || '}';
		FOR t3 IN
			SELECT
				CAST(p.grid AS BIGINT) AS id,
				CAST(p.grid AS BIGINT) AS produto_id,
				CAST(nop.grid AS BIGINT) AS natureza_op_id,  
				CAST(cno.uf AS TEXT) AS uf,  
				CAST(cno.cfop AS TEXT) AS cfop,
				CASE WHEN pt.grid is NOT NULL then (SELECT grid FROM tributacao WHERE codigo = pt.tributacao) ELSE t.grid END AS tributacao_id
			FROM produto p 
			JOIN natureza_op nop on (p.grid is not null and nop.grid is not null) 
			JOIN cfop_natureza_op cno on (cno.natureza_op = nop.grid and (coalesce(cno.de, null) is null or coalesce(cno.de, '') = '' or cno.de = $1)) 
			LEFT JOIN produto_tributacao pt ON (p.grid = pt.produto AND pt.de = $1 AND pt.tipo = 'E')
			JOIN tributacao t ON (t.codigo = (CASE WHEN pt.tributacao IS NOT NULL THEN pt.tributacao ELSE p.tributacao END)) 
			WHERE p.flag = 'A'
				AND p.tipo in ('M', 'C', 'K') 
				AND produto_movimenta_empresa_f(p.grid, $2)
				AND not p.grid = ANY(not_in_pos_1::bigint[])
				AND not p.grid = ANY(not_in_pos_2::bigint[])
				AND (CASE WHEN $3 IS NOT NULL THEN p.grid = $3 ELSE true END)
				AND (CASE WHEN $4 IS NOT NULL THEN nop.grid = $4 ELSE true END)
				AND (CASE WHEN $5 IS NOT NULL THEN t.grid = $5 ELSE true END)
		LOOP 
			RETURN NEXT t3; 
		END LOOP;
	END;
	
$_$;


ALTER FUNCTION public.produto_trib_cfop_f(text, bigint, bigint, bigint, bigint) OWNER TO postgres;

--
-- Name: produto_validade_tf(bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_validade_tf(bigint, bigint, bigint, bigint) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$
 
declare
	saldo float;
	r_produto record;
	r record;
	r_ret record;
	qtde_ret float := 0;
	c1 refcursor;
	ult_validade date := null;
	lote_ret text := null;
	mlid_ret bigint := null;
	temperatura_ret float := 0;
	fabricacao_ret date := null;

	begin
		--Parametros grid, nome, produto_estoque

		for r_produto in select grid, nome, produto_estoque_f($1, grid) as estoque from produto where (case when $2 is null then true else grupo=$2 end) and (case when $3 is null then true else subgrupo=$3 end) and (case when $4 is null then true else grid=$4 end) order by nome loop
			saldo := r_produto.estoque;
			OPEN c1 for 
				SELECT grid, mlid, empresa, produto, lote, quantidade::float, validade, fabricacao, temperatura FROM lancto_lote_produto WHERE empresa=$1 and produto=r_produto.grid order by validade desc, grid desc;

			while saldo > 0 LOOP
				fetch c1 into r;
				exit when not found;

				if saldo < r.quantidade then
					r.quantidade := saldo;
				end if;

				if ult_validade is null then
					qtde_ret := qtde_ret + r.quantidade;
				else
					select r_produto.grid, r_produto.estoque, lote_ret, qtde_ret, ult_validade, mlid_ret, temperatura_ret, fabricacao_ret into r_ret;
					return next r_ret;
					qtde_ret := r.quantidade;
				end if;

				saldo := saldo - r.quantidade;
				ult_validade := r.validade;
				lote_ret := r.lote;
				mlid_ret = r.mlid;
				temperatura_ret := r.temperatura;
				fabricacao_ret := r.fabricacao;
			end loop;

			-- Tem mais produtos que lotes
			if not ult_validade is null then
				qtde_ret := qtde_ret + saldo;
				select r_produto.grid, r_produto.estoque, lote_ret, qtde_ret, ult_validade, mlid_ret, temperatura_ret, fabricacao_ret into r_ret;
				return next r_ret;
			end if;

			close c1;
	end loop;
end;
 
$_$;


ALTER FUNCTION public.produto_validade_tf(bigint, bigint, bigint, bigint) OWNER TO postgres;

--
-- Name: produto_venda_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_venda_f(bigint, bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	ret text;
begin
	if (($1 is null) or ($1 = 0::bigint)) then
		return null;
	end if;
	
	if (($2 is null) or ($2 = 0::bigint)) then
		return produto_principal_venda_f($1);
	end if;

	select into r p.nome, p.unid_med, round(l.quantidade::numeric, 3) as quantidade from lancto l 
	join produto p on (l.produto=p.grid) where l.mlid=$1 and l.operacao = 'V' and l.produto= $2 order by abs(l.valor) desc limit 1;

	if found then
		ret := r.nome || ' // ' || round(r.quantidade::numeric, 3)::float8::text || ' ' || r.unid_med;

		select into r count(*) from lancto where mlid=$1 and operacao = 'V';

		if r.count > 1 then
			ret := '+ ' || ret;
		end if;
	end if;

	return ret;
end
$_$;


ALTER FUNCTION public.produto_venda_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produto_verifica_permite_venda_f(bigint, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produto_verifica_permite_venda_f(bigint, bigint) RETURNS boolean
    LANGUAGE plpgsql
    AS $_$

	/*Parametros:
	1-$1 produto
	2-$2 empresa
	3-Retorno TRUE or FALSE
	*/

	DECLARE
		r_produto RECORD;
		var_distribuidora BIGINT;
		var_permite_venda BOOLEAN;

	BEGIN
		SELECT distribuidora INTO var_distribuidora FROM empresa_distribuidora WHERE empresa = $2;

		IF var_distribuidora in (4, 5) THEN
			SELECT coalesce(p.permite_venda, TRUE) as permite_venda, coalesce(p.permite_venda_dist, TRUE) as permite_venda_dist into r_produto FROM produto p WHERE p.grid = $1;

			IF not (r_produto.permite_venda and r_produto.permite_venda_dist) THEN
				-- se for false para o produto automaticamente e false para todas as empresas
				return FALSE;
			END IF;

			SELECT coalesce(permite_venda, TRUE) as permite_venda, coalesce(permite_venda_dist, TRUE) as permite_venda_dist into r_produto FROM produto_empresa WHERE produto = $1 AND empresa = $2;

			IF NOT FOUND THEN
				-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
				RETURN TRUE;
			END IF;

			RETURN r_produto.permite_venda AND r_produto.permite_venda_dist;
		END IF;

		SELECT coalesce(p.permite_venda, TRUE) INTO var_permite_venda FROM produto p WHERE p.grid = $1;

		IF not var_permite_venda THEN
			-- se for false para o produto automaticamente e false para todas as empresas
			RETURN FALSE;
		END IF;

		SELECT coalesce(permite_venda, TRUE) into var_permite_venda FROM produto_empresa WHERE produto = $1 and empresa = $2;

		IF NOT FOUND THEN
			-- se nao tiver produto_empresa e o produto for true retorna true automaticamente
			RETURN TRUE;
		END IF;

		RETURN var_permite_venda;
	END;
	
$_$;


ALTER FUNCTION public.produto_verifica_permite_venda_f(bigint, bigint) OWNER TO postgres;

--
-- Name: produtos_nao_vendidos_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produtos_nao_vendidos_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone) RETURNS double precision
    LANGUAGE plpgsql
    AS $_$

/*Parametros
1- Empresa
2- Deposito
3- Produto
4- Data
5- Turno
6- Hora
*/
DECLARE    
    p_empresa INT8;
    p_data DATE;
    data_invalida DATE;
    estoque_final FLOAT := 0;
    est_ativo BOOLEAN;
    r_data DATE;
    r_turno INTEGER;
    r_hora TIMESTAMP;
    r_operacao TEXT;
    r_quantidade DOUBLE PRECISION;
    r RECORD;

BEGIN

    -- Caso o produto seja serviÁo, retorna sempre zero
    IF EXISTS (SELECT 1 FROM produto WHERE grid = $3 AND tipo = 'S') THEN
        RETURN 0;
    END IF;

    -- Verifica se turno foi informado sem hora
    IF $5 IS NULL AND $6 IS NOT NULL THEN
        RAISE EXCEPTION 'Impossivel calcular estoque de um hor·rio sem informar o turno';
    END IF;

    -- Utiliza a empresa local caso n„o tenha sido informada
    IF $1 IS NULL THEN
        SELECT empresa INTO p_empresa FROM empresa_local;
    ELSE
        p_empresa := $1;
    END IF;

    -- Utiliza a data de hoje caso n„o tenha sido informada
    IF $4 IS NULL THEN
        p_data := current_date;
    ELSE
        p_data := $4;
    END IF;

    -- Recursividade: Calcula o estoque para v·rios depÛsitos se o depÛsito n„o foi informado
    IF $2 IS NULL THEN
        FOR r IN 
            SELECT grid FROM deposito WHERE empresa = p_empresa AND produto = $3
            UNION
            SELECT DISTINCT d.grid FROM deposito d
            JOIN deposito_grupo_produto dgp ON d.grid = dgp.deposito
            JOIN produto p ON p.grupo = dgp.grupo
            WHERE p.grid = $3 AND d.empresa = p_empresa
        LOOP
            -- Chama recursivamente para cada depÛsito
            estoque_final := estoque_final + produtos_nao_vendidos_estoque_f(p_empresa, r.grid, $3, p_data, $5, $6);
        END LOOP;

        RETURN estoque_final;
    END IF;

    -- Verifica se o controle de estoque est· ativo
    SELECT ativo INTO est_ativo FROM estoque_controle ORDER BY data_ult_exec DESC LIMIT 1;
    IF NOT FOUND THEN
        est_ativo := TRUE;
    END IF;

    -- Ajusta a data para buscar estoque, se necess·rio
    IF est_ativo THEN
        SELECT data INTO data_invalida 
        FROM estoque_invalida 
        WHERE empresa = p_empresa AND deposito = $2 AND produto = $3;

        IF FOUND AND data_invalida <= p_data THEN
            p_data := data_invalida - 1;
        END IF;

        -- Busca o estoque mais recente na tabela estoque_deposito
        SELECT COALESCE(SUM(estoque), 0) INTO estoque_final
        FROM estoque_deposito 
        WHERE empresa = p_empresa 
        AND produto = $3 
        AND deposito = $2
        AND data <= p_data
        GROUP BY data
        ORDER BY data DESC
        LIMIT 1;

        IF NOT FOUND THEN
            -- Tenta buscar o estoque na tabela estoque_produto
            SELECT COALESCE(estoque, 0) INTO estoque_final
            FROM estoque_produto
            WHERE empresa = p_empresa
            AND deposito = $2
            AND produto = $3
            AND data <= p_data
            ORDER BY data DESC
            LIMIT 1;
        END IF;
    END IF;

    -- Caso o estoque ativo tenha sido encontrado, ajusta a data e continua com o processamento
    IF estoque_final IS NULL THEN
        estoque_final := 0;
    END IF;

    -- Busca as movimentaÁıes de estoque na tabela lancto
    IF est_ativo THEN
        FOR r_data, r_turno, r_hora, r_operacao, r_quantidade IN 
            SELECT data, turno, hora, operacao, quantidade 
            FROM lancto 
            WHERE empresa = p_empresa AND deposito = $2 AND produto = $3 
            AND data >= p_data AND data <= $4 
            ORDER BY data, turno, hora
        LOOP
            -- Ajuste com base no turno e hora
            IF $5 IS NOT NULL AND r_data = $4 THEN
                IF $6 IS NOT NULL AND r_turno = $5 AND r_hora > $6 THEN
                    EXIT;
                ELSIF r_turno > $5 THEN
                    EXIT;
                END IF;
            END IF;

            -- Calcula o estoque conforme a operaÁ„o
            CASE r_operacao
                WHEN 'V', 'C', 'P', 'DF', 'TS', 'B', 'SD', 'SR', 'DG' THEN                        
                    estoque_final := estoque_final - r_quantidade;
                WHEN 'E', 'S', 'TE', 'DC', 'O', 'ED', 'ER' THEN
                    estoque_final := estoque_final + r_quantidade;
                WHEN 'I', 'M' THEN
                    estoque_final := r_quantidade;
                WHEN 'F' THEN
                    estoque_final := 0;
                    EXIT;
            END CASE;
        END LOOP;
    END IF;

    -- Retorna o estoque final calculado
    RETURN estoque_final;

END;

$_$;


ALTER FUNCTION public.produtos_nao_vendidos_estoque_f(bigint, bigint, bigint, date, integer, timestamp without time zone) OWNER TO postgres;

--
-- Name: produtos_nao_vendidos_f(bigint, bigint, bigint, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produtos_nao_vendidos_f(bigint, bigint, bigint, date, date, text) RETURNS SETOF public.produtos_nao_vendidos_t
    LANGUAGE plpgsql
    AS $_$

/* Par‚metros:
1- Empresa
2- Grupo
3- Subgrupo
4- Data inicial
5- Data final
6- Flag produtos
*/
DECLARE	
	r RECORD;
BEGIN	
	FOR r IN 
		SELECT p.grid AS produto_grid,
			p.codigo AS produto_codigo,
			p.nome AS produto_nome,
			COALESCE(p.preco_unit, 0) AS preco_unit,
			p.tipo,
			gp.grid AS grupo_produto_grid,
			gp.codigo AS grupo_produto_codigo,
			gp.nome AS grupo_produto_nome,
			d.grid AS deposito_grid,
			e.grid AS empresa_grid,
			e.codigo AS empresa_codigo,
			e.nome AS empresa_nome
		FROM produto p
		JOIN grupo_produto gp ON gp.grid = p.grupo
		LEFT JOIN deposito_grupo_produto dgp ON dgp.grupo = gp.grid
		JOIN deposito d ON (d.grid = dgp.deposito OR d.produto = p.grid) 
		JOIN empresa e ON e.grid = d.empresa
		LEFT JOIN lancto l ON l.produto = p.grid
						AND l.empresa = e.grid
						AND l.data BETWEEN $4 AND $5
						AND l.operacao = 'V'
		WHERE (CASE WHEN $1 != -1 THEN e.grid = $1 ELSE TRUE END)
		  AND (CASE WHEN $2 != -1 THEN gp.grid = $2 ELSE TRUE END)
		  AND (CASE WHEN $3 != -1 THEN p.subgrupo = $3 ELSE TRUE END)
		  AND (p.flag = ANY (
			  CASE 
				WHEN $6 = 'A' THEN ARRAY['A']
				WHEN $6 = 'AI' THEN ARRAY['A', 'I']
				WHEN $6 = 'AID' THEN ARRAY['A', 'I', 'D']
				WHEN $6 = 'AD' THEN ARRAY['A', 'D']
				WHEN $6 = 'I' THEN ARRAY['I']
				WHEN $6 = 'ID' THEN ARRAY['I', 'D']
				WHEN $6 = 'D' THEN ARRAY['D']
				ELSE ARRAY['A', 'I', 'D', 'B', 'C']
			END
		))
		AND l.grid IS NULL
	LOOP
		RETURN NEXT r;
	END LOOP;

	RETURN;
END;

$_$;


ALTER FUNCTION public.produtos_nao_vendidos_f(bigint, bigint, bigint, date, date, text) OWNER TO postgres;

--
-- Name: produtos_nao_vendidos_f1(bigint, bigint, bigint, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produtos_nao_vendidos_f1(bigint, bigint, bigint, date, date, text) RETURNS SETOF public.produtos_nao_vendidos_t1
    LANGUAGE plpgsql
    AS $_$

/*Parametros
1- Empresa
2- Grupo
3- Subgrupo
4- Data inicial
5- Data final
6- Flag produtos
*/
DECLARE	
	r RECORD;
BEGIN	
	FOR r IN SELECT t.produto_grid as produto_grid_f1
		, t.produto_codigo 
		, t.produto_nome
		, t.preco_unit
		, t.tipo
		, t.grupo_produto_grid
		, t.grupo_produto_codigo
		, t.grupo_produto_nome
		, t.empresa_grid as empresa_grid_f1
		, t.empresa_codigo
		, t.empresa_nome
		, SUM((select produto_estoque_f(t.empresa_grid, t.deposito_grid, t.produto_grid, $5, NULL, NULL))) as quantidade  
		FROM (SELECT * FROM produtos_nao_vendidos_f($1, $2, $3, $4, $5, $6))  t
		GROUP BY t.produto_grid
				, t.produto_codigo
				, t.produto_nome
				, t.preco_unit
				, t.tipo
				, t.grupo_produto_grid
				, t.grupo_produto_codigo
				, t.grupo_produto_nome
				, t.empresa_grid
				, t.empresa_codigo
				, t.empresa_nome
		ORDER BY t.empresa_grid
				, t.produto_grid
	
	LOOP
		RETURN NEXT r; 
	END LOOP;
	RETURN;
END;

$_$;


ALTER FUNCTION public.produtos_nao_vendidos_f1(bigint, bigint, bigint, date, date, text) OWNER TO postgres;

--
-- Name: produtos_nao_vendidos_f2(bigint, bigint, bigint, date, date, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.produtos_nao_vendidos_f2(bigint, bigint, bigint, date, date, text) RETURNS SETOF public.produtos_nao_vendidos_t2
    LANGUAGE plpgsql
    AS $_$

/*Parametros
1- Empresa
2- Grupo
3- Subgrupo
4- Data inicial
5- Data final
6- Flag produtos
*/
DECLARE	
	r RECORD;
BEGIN	
	FOR r IN SELECT t1.compra_data
	               , COALESCE(x.preco_unit,0) as ultimo_custo
				   , t1.produto_grid_f2
				   , t1.empresa_grid_f2
               FROM (SELECT MAX(data) as compra_data
			               , t.produto_grid as produto_grid_f2
						   , t.empresa_grid as empresa_grid_f2
					   FROM (SELECT * FROM produtos_nao_vendidos_f($1, $2, $3, $4, $5, $6))  t
					   JOIN lancto l on (l.empresa=t.empresa_grid and l.data < $4 and l.produto=t.produto_grid and l.operacao='E')
					   GROUP BY t.empresa_grid, t.produto_grid
					   ORDER BY t.empresa_grid, t.produto_grid
					   ) t1
				JOIN lancto x on (x.empresa=t1.empresa_grid_f2 and x.data=t1.compra_data and x.operacao='E' and x.produto=t1.produto_grid_f2)
	
	LOOP
		RETURN NEXT r; 
	END LOOP;
	RETURN;
END;

$_$;


ALTER FUNCTION public.produtos_nao_vendidos_f2(bigint, bigint, bigint, date, date, text) OWNER TO postgres;

