ALTER FUNCTION public.produtos_nao_vendidos_f6(bigint, bigint, bigint, date, date, text) OWNER TO postgres;

--
-- Name: resumo_estoque2_tf(bigint, bigint, bigint, bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_estoque2_tf(bigint, bigint, bigint, bigint, bigint, date, date) RETURNS SETOF public.resumo_estoque2_tp
    LANGUAGE sql
    AS $_$

SELECT rs.grupo_nome
      ,rs.produto_nome
	  ,rs.produto_codigo
	  ,rs.grupo_codigo
	  ,rs.grid
	  ,rs.estoque_inicial_cvm
	  ,(CASE WHEN rs.estoque_final_cvm!=0 THEN rs.estoque_final_cvm ELSE rs.estoque_inicial_cvm END) as estoque_final_cvm
	  ,rs.estoque_inicial_qtd
	  ,rs.tipo_combustivel
	  ,rs.estoque_final_qtd
	  ,rs.compra_quantidade
	  ,rs.venda_quantidade
	  ,rs.sobra_falta_quantidade
	  ,rs.compra_valor_total
	  ,rs.venda_valor_total
	  ,(CASE WHEN rs.sobra_falta_quantidade!=0 THEN (rs.sobra_falta_valor_medio/rs.sobra_falta_quantidade) ELSE 0 END) as sobra_falta_valor_medio
	  ,rs.consumo_quantidade
	  ,rs.bonificacao_quantidade
	  ,rs.consumo_valor_total
	  ,rs.bonificacao_valor_total
	  ,rs.estoque_inicial_quantidade
	  ,rs.estoque_final_quantidade
	  ,rs.empresa_nome
  FROM (SELECT gp.nome as grupo_nome
			  ,replace(p.nome, '&', 'E') as produto_nome
			  ,p.codigo as produto_codigo
			  ,gp.codigo as grupo_codigo
			  ,p.grid
			  ,SUM((CASE WHEN (t.data=$6-'1 day'::interval and t.estoque!=0) THEN ((t.estoque*round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4))/t.estoque)
						 WHEN (t.data=$6-'1 day'::interval and t.estoque=0) THEN round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4)
						 ELSE 0 END)) as estoque_inicial_cvm
			  ,SUM((CASE WHEN (t.data=$7 and t.estoque!=0) THEN ((t.estoque*round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4))/t.estoque)
						 WHEN (t.data=$7 and t.estoque=0) THEN round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4)
						 ELSE 0 END)) as estoque_final_cvm 
			  ,SUM((CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END)) as estoque_inicial_qtd
			  ,p.tipo_combustivel	  
			  ,SUM((CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END)) as estoque_final_qtd
			  ,SUM((CASE WHEN t.data>=$6 THEN t.compra_quantidade ELSE 0 END)) as compra_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.venda_quantidade ELSE 0 END)) as venda_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.sobra_falta_quantidade ELSE 0 END)) as sobra_falta_quantidade 
			  ,SUM(t.compra_valor_total) as compra_valor_total
			  ,SUM(t.venda_valor_total) as venda_valor_total
			  ,SUM((CASE WHEN (t.data>=$6 and t.sobra_falta_quantidade!=0) THEN (t.sobra_falta_quantidade*round(ev.ult_custo_medio::numeric,4)) ELSE 0 END)) as sobra_falta_valor_medio
			  ,SUM((CASE WHEN t.data>=$6 THEN t.consumo_quantidade ELSE 0 END)) as consumo_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.bonificacao_quantidade ELSE 0 END)) as bonificacao_quantidade
			  ,SUM(t.consumo_valor_total) as consumo_valor_total
			  ,SUM(t.bonificacao_valor_total) as bonificacao_valor_total	  
			  ,SUM((CASE WHEN (p.tipo_combustivel = 6 and to_char($6,'dd') = '01') THEN 0
						 WHEN t.data is null  THEN t.estoque
						 ELSE (CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END) END)) as estoque_inicial_quantidade
			  ,SUM((CASE WHEN (p.tipo_combustivel = 6 and to_char($7,'dd') = '01') THEN 0 
						 WHEN t.data is null  THEN t.estoque
						 ELSE (CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END) END)) as estoque_final_quantidade
			  ,pessoa_nome_f($1) as empresa_nome
		  FROM produto p
		  JOIN grupo_produto gp on (gp.grid=p.grupo)
		  JOIN (SELECT d.produto as produto
					  ,d.data as data
					  ,(CASE WHEN sum(d.estoque) !=0 THEN sum(d.custo_medio*d.estoque)/sum(d.estoque) ELSE sum(d.custo_medio*d.estoque) END)  as custo_medio
					  ,SUM(d.estoque) as estoque
					  ,SUM(d.compra_quantidade) as compra_quantidade
					  ,SUM(d.venda_quantidade) as venda_quantidade
					  ,SUM(d.sobra_falta_quantidade) as sobra_falta_quantidade
					  ,SUM(d.consumo_quantidade) as consumo_quantidade
					  ,SUM(d.bonificacao_quantidade) as bonificacao_quantidade
					  ,SUM(d.compra_valor_total) as compra_valor_total
					  ,SUM(d.venda_valor_total) as venda_valor_total
					  ,SUM(d.consumo_valor_total) as consumo_valor_total
					  ,SUM(d.bonificacao_valor_total) as bonificacao_valor_total
				  FROM (SELECT coalesce(e.produto,ep.produto) as produto
							  ,coalesce(e.deposito,ep.deposito) as deposito
							  ,coalesce(e.empresa,ep.empresa) as empresa
							  ,coalesce(e.data,ep.data_estoque) as data
							  ,coalesce(e.estoque,ep.estoque) as estoque
							  ,coalesce(e.compra_quantidade,0) as compra_quantidade
							  ,coalesce(e.venda_quantidade,0) as venda_quantidade
							  ,coalesce(e.sobra_falta_quantidade,0) as sobra_falta_quantidade
							  ,coalesce(e.consumo_quantidade,0) as consumo_quantidade
							  ,coalesce(e.bonificacao_quantidade,0) as bonificacao_quantidade
							  ,coalesce(v.compra_valor_total,0) as compra_valor_total
							  ,coalesce(v.venda_valor_total,0) as venda_valor_total
							  ,coalesce(v.consumo_valor_total,0) as consumo_valor_total
							  ,coalesce(v.bonificacao_valor_total,0) as bonificacao_valor_total
							  ,round(coalesce(ep.custo_medio,0)::numeric,4) as custo_medio
						FROM (SELECT ed.produto
									,ed.deposito
									,ed.empresa
									,ed.data
									,SUM(ed.estoque) as estoque
									,SUM(ed.compra-ed.dev_for) as compra_quantidade 
									,SUM(ed.venda-ed.dev_cli) as venda_quantidade 
									,SUM((ed.sobra+ed.inv_sobra)-(ed.perda+ed.inv_perda+ed.brinde)) as sobra_falta_quantidade 
									,SUM(ed.consumo) as consumo_quantidade 
									,SUM(ed.bonificacao) as bonificacao_quantidade 
								FROM estoque_deposito ed
							   where (ed.data between $6-'1 day'::interval and $7)
								 and ed.empresa=$1
								 AND (CASE when $2 is null THEN true ELSE ed.deposito = $2 END)
							   GROUP BY ed.produto
									   ,ed.deposito
									   ,ed.empresa
									   ,ed.data) e
						LEFT JOIN (SELECT l.produto
										 ,l.deposito
										 ,l.empresa
										 ,l.data
										 ,SUM((CASE WHEN l.operacao = 'E' THEN l.valor WHEN l.operacao='DF' THEN l.valor*-1 ELSE 0 END)) as compra_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'V' THEN l.valor WHEN l.operacao='DC' THEN l.valor*-1 ELSE 0 END)) as venda_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'C' THEN l.valor ELSE 0 END)) as consumo_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'O' THEN l.valor ELSE 0 END)) as bonificacao_valor_total 
									 FROM lancto l
									 WHERE (l.data between $6 and $7)
									   AND l.empresa=$1
									   AND l.operacao in ('E','V','C','O','DF','DC')
									   AND (CASE when $2 is null THEN true ELSE l.deposito = $2 END)
									 GROUP BY l.produto
											 ,l.deposito
											 ,l.empresa
											 ,l.data) v on (v.empresa=e.empresa and v.data=e.data and v.deposito=e.deposito and v.produto=e.produto)
						FULL JOIN (SELECT *
									 FROM estoque_produto x
									 JOIN (SELECT ($6-'1 day'::interval)::date + x.x AS data_estoque
											 FROM generate_series(0, ($7 - ($6-'1 day'::interval)::date), ($7 - ($6-'1 day'::interval)::date)) x(x)) a on (x.data<a.data_estoque)
									WHERE x.empresa=$1
									  AND x.estoque!=0
									  AND (CASE when $2 is null THEN true ELSE x.deposito = $2 END)) ep on (ep.empresa=e.empresa and ep.deposito=e.deposito and ep.produto=e.produto and ep.data_estoque=e.data)) d
				 GROUP BY d.produto
						 ,d.data) t on (t.produto=p.grid)
		  LEFT JOIN estoque_valor ev on (ev.empresa=$1 and ev.data=t.data and ev.produto=t.produto)
		 WHERE (p.controlar_estoque or p.tipo_combustivel = 6)
		   AND p.tipo != 'S'
		   AND (CASE when $3 is null THEN true ELSE p.grupo = $3 END)
		   AND (CASE when $4 is null THEN true ELSE p.subgrupo = $4 END)
		   AND (CASE when $5 is null THEN true ELSE p.grid = $5 END)
		 GROUP BY gp.nome
				 ,replace(p.nome, '&', 'E')
				 ,p.codigo
				 ,gp.codigo
				 ,p.grid
				 ,p.tipo_combustivel
				 ,empresa_nome
		HAVING NOT (SUM((CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END))=0
				and SUM((CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.compra_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.venda_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.sobra_falta_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.consumo_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.bonificacao_quantidade ELSE 0 END))=0)) rs
	ORDER BY 1,2
   
$_$;


ALTER FUNCTION public.resumo_estoque2_tf(bigint, bigint, bigint, bigint, bigint, date, date) OWNER TO postgres;

--
-- Name: resumo_estoque3_tf(bigint, bigint, bigint, bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_estoque3_tf(bigint, bigint, bigint, bigint, bigint, date, date) RETURNS SETOF public.resumo_estoque3_tp
    LANGUAGE sql
    AS $_$

SELECT rs.grupo_nome
      ,rs.produto_nome
	  ,rs.produto_codigo
	  ,rs.grupo_codigo
	  ,rs.grid
	  ,rs.estoque_inicial_cvm
	  ,(CASE WHEN rs.estoque_final_cvm!=0 THEN rs.estoque_final_cvm ELSE rs.estoque_inicial_cvm END) as estoque_final_cvm
	  ,rs.estoque_inicial_qtd
	  ,rs.tipo_combustivel
	  ,rs.estoque_final_qtd
	  ,rs.compra_quantidade
	  ,rs.venda_quantidade
	  ,rs.sobra_falta_quantidade
	  ,rs.compra_valor_total
	  ,rs.venda_valor_total
	  ,(CASE WHEN rs.sobra_falta_quantidade!=0 THEN (rs.sobra_falta_valor_medio/rs.sobra_falta_quantidade) ELSE 0 END) as sobra_falta_valor_medio
	  ,rs.consumo_quantidade
	  ,rs.bonificacao_quantidade
	  ,rs.consumo_valor_total
	  ,rs.bonificacao_valor_total
	  ,rs.estoque_inicial_quantidade
	  ,rs.estoque_final_quantidade
	  ,rs.empresa_nome
	  ,rs.transf_ent_quantidade
	  ,rs.transf_sai_quantidade
  FROM (SELECT gp.nome as grupo_nome
			  ,replace(p.nome, '&', 'E') as produto_nome
			  ,p.codigo as produto_codigo
			  ,gp.codigo as grupo_codigo
			  ,p.grid
			  ,SUM((CASE WHEN (t.data=$6-'1 day'::interval and t.estoque!=0) THEN ((t.estoque*round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4))/t.estoque)
						 WHEN (t.data=$6-'1 day'::interval and t.estoque=0) THEN round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4)
						 ELSE 0 END)) as estoque_inicial_cvm
			  ,SUM((CASE WHEN (t.data=$7 and t.estoque!=0) THEN ((t.estoque*round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4))/t.estoque)
						 WHEN (t.data=$7 and t.estoque=0) THEN round(coalesce(ev.ult_custo_medio,t.custo_medio)::numeric,4)
						 ELSE 0 END)) as estoque_final_cvm 
			  ,SUM((CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END)) as estoque_inicial_qtd
			  ,p.tipo_combustivel	  
			  ,SUM((CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END)) as estoque_final_qtd
			  ,SUM((CASE WHEN t.data>=$6 THEN t.compra_quantidade ELSE 0 END)) as compra_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.venda_quantidade ELSE 0 END)) as venda_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.sobra_falta_quantidade ELSE 0 END)) as sobra_falta_quantidade 
			  ,SUM(t.compra_valor_total) as compra_valor_total
			  ,SUM(t.venda_valor_total) as venda_valor_total
			  ,SUM((CASE WHEN (t.data>=$6 and t.sobra_falta_quantidade!=0) THEN (t.sobra_falta_quantidade*round(ev.ult_custo_medio::numeric,4)) ELSE 0 END)) as sobra_falta_valor_medio
			  ,SUM((CASE WHEN t.data>=$6 THEN t.consumo_quantidade ELSE 0 END)) as consumo_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.bonificacao_quantidade ELSE 0 END)) as bonificacao_quantidade
			  ,SUM(t.consumo_valor_total) as consumo_valor_total
			  ,SUM(t.bonificacao_valor_total) as bonificacao_valor_total
			  ,SUM((CASE WHEN (p.tipo_combustivel = 6 and to_char($6,'dd') = '01') THEN 0
						 WHEN t.data is null  THEN t.estoque
						 ELSE (CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END) END)) as estoque_inicial_quantidade
			  ,SUM((CASE WHEN (p.tipo_combustivel = 6 and to_char($7,'dd') = '01') THEN 0 
						 WHEN t.data is null  THEN t.estoque
						 ELSE (CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END) END)) as estoque_final_quantidade
			  ,pessoa_nome_f($1) as empresa_nome
			  ,SUM((CASE WHEN t.data>=$6 THEN t.transf_ent_quantidade ELSE 0 END)) as transf_ent_quantidade 
			  ,SUM((CASE WHEN t.data>=$6 THEN t.transf_sai_quantidade ELSE 0 END)) as transf_sai_quantidade 
		  FROM produto p
		  JOIN grupo_produto gp on (gp.grid=p.grupo)
		  JOIN (SELECT d.produto as produto
					  ,d.data as data
					  ,(CASE WHEN sum(d.estoque) !=0 THEN sum(d.custo_medio*d.estoque)/sum(d.estoque) ELSE sum(d.custo_medio*d.estoque) END)  as custo_medio
					  ,SUM(d.estoque) as estoque
					  ,SUM(d.compra_quantidade) as compra_quantidade
					  ,SUM(d.venda_quantidade) as venda_quantidade
					  ,SUM(d.sobra_falta_quantidade) as sobra_falta_quantidade
					  ,SUM(d.consumo_quantidade) as consumo_quantidade
					  ,SUM(d.bonificacao_quantidade) as bonificacao_quantidade
					  ,SUM(d.compra_valor_total) as compra_valor_total
					  ,SUM(d.venda_valor_total) as venda_valor_total
					  ,SUM(d.consumo_valor_total) as consumo_valor_total
					  ,SUM(d.bonificacao_valor_total) as bonificacao_valor_total
					  ,SUM(d.transf_ent_quantidade) as transf_ent_quantidade
					  ,SUM(d.transf_sai_quantidade) as transf_sai_quantidade
				  FROM (SELECT coalesce(e.produto,ep.produto) as produto
							  ,coalesce(e.deposito,ep.deposito) as deposito
							  ,coalesce(e.empresa,ep.empresa) as empresa
							  ,coalesce(e.data,ep.data_estoque) as data
							  ,coalesce(e.estoque,ep.estoque) as estoque
							  ,coalesce(e.compra_quantidade,0) as compra_quantidade
							  ,coalesce(e.venda_quantidade,0) as venda_quantidade
							  ,coalesce(e.sobra_falta_quantidade,0) as sobra_falta_quantidade
							  ,coalesce(e.consumo_quantidade,0) as consumo_quantidade
							  ,coalesce(e.bonificacao_quantidade,0) as bonificacao_quantidade
							  ,coalesce(v.compra_valor_total,0) as compra_valor_total
							  ,coalesce(v.venda_valor_total,0) as venda_valor_total
							  ,coalesce(v.consumo_valor_total,0) as consumo_valor_total
							  ,coalesce(v.bonificacao_valor_total,0) as bonificacao_valor_total
							  ,round(coalesce(ep.custo_medio,0)::numeric,4) as custo_medio
							  ,coalesce(e.transf_ent_quantidade,0) as transf_ent_quantidade
							  ,coalesce(e.transf_sai_quantidade,0) as transf_sai_quantidade
						FROM (SELECT ed.produto
									,ed.deposito
									,ed.empresa
									,ed.data
									,SUM(ed.estoque) as estoque
									,SUM(ed.compra-ed.dev_for) as compra_quantidade 
									,SUM(ed.venda-ed.dev_cli) as venda_quantidade 
									,SUM((ed.sobra+ed.inv_sobra)-(ed.perda+ed.inv_perda+ed.brinde)) as sobra_falta_quantidade 
									,SUM(ed.consumo) as consumo_quantidade 
									,SUM(ed.bonificacao) as bonificacao_quantidade 
									,SUM(ed.transf_ent) as transf_ent_quantidade
									,SUM(ed.transf_sai) as transf_sai_quantidade
								FROM estoque_deposito ed
							   where (ed.data between $6-'1 day'::interval and $7)
								 and ed.empresa=$1
								 AND (CASE when $2 is null THEN true ELSE ed.deposito = $2 END)
							   GROUP BY ed.produto
									   ,ed.deposito
									   ,ed.empresa
									   ,ed.data) e
						LEFT JOIN (SELECT l.produto
										 ,l.deposito
										 ,l.empresa
										 ,l.data
										 ,SUM((CASE WHEN l.operacao = 'E' THEN l.valor WHEN l.operacao='DF' THEN l.valor*-1 ELSE 0 END)) as compra_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'V' THEN l.valor WHEN l.operacao='DC' THEN l.valor*-1 ELSE 0 END)) as venda_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'C' THEN l.valor ELSE 0 END)) as consumo_valor_total 
										 ,SUM((CASE WHEN l.operacao = 'O' THEN l.valor ELSE 0 END)) as bonificacao_valor_total 
									 FROM lancto l
									 WHERE (l.data between $6 and $7)
									   AND l.empresa=$1
									   AND l.operacao in ('E','V','C','O','DF','DC')
									   AND (CASE when $2 is null THEN true ELSE l.deposito = $2 END)
									 GROUP BY l.produto
											 ,l.deposito
											 ,l.empresa
											 ,l.data) v on (v.empresa=e.empresa and v.data=e.data and v.deposito=e.deposito and v.produto=e.produto)
						FULL JOIN (SELECT *
									 FROM estoque_produto x
									 JOIN (SELECT ($6-'1 day'::interval)::date + x.x AS data_estoque
											 FROM generate_series(0, ($7 - ($6-'1 day'::interval)::date), ($7 - ($6-'1 day'::interval)::date)) x(x)) a on (x.data<a.data_estoque)
									WHERE x.empresa=$1
									  AND x.estoque!=0
									  AND (CASE when $2 is null THEN true ELSE x.deposito = $2 END)) ep on (ep.empresa=e.empresa and ep.deposito=e.deposito and ep.produto=e.produto and ep.data_estoque=e.data)) d
				 GROUP BY d.produto
						 ,d.data) t on (t.produto=p.grid)
		  LEFT JOIN estoque_valor ev on (ev.empresa=$1 and ev.data=t.data and ev.produto=t.produto)
		 WHERE (p.controlar_estoque or p.tipo_combustivel = 6)
		   AND p.tipo != 'S'
		   AND (CASE when $3 is null THEN true ELSE p.grupo = $3 END)
		   AND (CASE when $4 is null THEN true ELSE p.subgrupo = $4 END)
		   AND (CASE when $5 is null THEN true ELSE p.grid = $5 END)
		 GROUP BY gp.nome
				 ,replace(p.nome, '&', 'E')
				 ,p.codigo
				 ,gp.codigo
				 ,p.grid
				 ,p.tipo_combustivel
				 ,empresa_nome
		HAVING NOT (SUM((CASE WHEN t.data=$6-'1 day'::interval THEN t.estoque ELSE 0 END))=0
				and SUM((CASE WHEN t.data=$7 THEN t.estoque ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.compra_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.venda_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.sobra_falta_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.consumo_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.bonificacao_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.transf_ent_quantidade ELSE 0 END))=0
			    and SUM((CASE WHEN t.data>=$6 THEN t.transf_sai_quantidade ELSE 0 END))=0)) rs
	ORDER BY 1,2
   
$_$;


ALTER FUNCTION public.resumo_estoque3_tf(bigint, bigint, bigint, bigint, bigint, date, date) OWNER TO postgres;

--
-- Name: resumo_estoque_tf(bigint, bigint, bigint, bigint, date, date); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resumo_estoque_tf(bigint, bigint, bigint, bigint, date, date) RETURNS SETOF record
    LANGUAGE plpgsql
    AS $_$

declare
	r record;
begin
	--Parametros: empresa, grupo, subgrupo, produto, data_ini, data_fim

	for r in select grupo_nome, produto_nome, produto_codigo, grupo_codigo, grid, estoque_inicial_cvm, estoque_final_cvm, estoque_inicial_qtd, tipo_combustivel, estoque_final_qtd, compra_quantidade, venda_quantidade, sobra_falta_quantidade, compra_valor_total, venda_valor_total, sobra_falta_valor_medio, consumo_quantidade, bonificacao_quantidade, consumo_valor_total, bonificacao_valor_total, 
	(case when (tipo_combustivel = 6 and to_char($5::date,'dd') = '01') then 0 else estoque_inicial_qtd end) as estoque_inicial_quantidade, 
	(case when (tipo_combustivel = 6 and to_char($6::date,'dd') = '01') then 0 else estoque_final_qtd end) as estoque_final_quantidade, 
	pessoa_nome_f($1) as empresa_nome 
from (
	select distinct 
		g.nome as grupo_nome, 
		replace(p.nome, '&', 'E') as produto_nome, 
		p.codigo as produto_codigo, 
		g.codigo as grupo_codigo, 
		p.grid, 
		coalesce(round(custo_medio_empresa_f($1, p.grid, $5::date-1)::numeric,4),0) as estoque_inicial_cvm, 
		coalesce(round(custo_medio_empresa_f($1, p.grid, $6::date)::numeric,4),0) as estoque_final_cvm, 
		coalesce(estoque_produto_f($1, p.grid, $5::date-1),0) as estoque_inicial_qtd, 
		p.tipo_combustivel, 
		coalesce(estoque_produto_f($1, p.grid, $6::date),0) as estoque_final_qtd, 
		coalesce((select sum(compra-dev_for) from estoque_deposito ed where ed.empresa=$1 and ed.data between $5 and $6 and ed.produto=p.grid),0) as compra_quantidade,
		coalesce((select sum(venda-dev_cli) from estoque_deposito ed where ed.empresa=$1 and ed.data between $5 and $6 and ed.produto=p.grid),0) as venda_quantidade, 
		coalesce((select sum((sobra+inv_sobra)-(perda+inv_perda+brinde)) from estoque_deposito ed where ed.empresa=$1 and ed.data between $5 and $6 and ed.produto=p.grid),0) as sobra_falta_quantidade, 
		coalesce((select sum(case when l.operacao = 'E' then l.valor else l.valor*-1 end) from lancto l where l.empresa=$1 and l.operacao in ('E','DF') and l.data between $5 and $6 and l.produto=p.grid),0) as compra_valor_total, 
		coalesce((select sum(case when l.operacao = 'V' then l.valor else l.valor*-1 end) from lancto l where l.empresa=$1 and l.operacao in ('V', 'DC') and l.data between $5 and $6 and l.produto=p.grid),0) as venda_valor_total, 
		coalesce((case when coalesce((select sum((sobra+inv_sobra)- (perda+inv_perda+brinde)) from estoque_deposito ed where ed.empresa=$1 and ed.data between $5 and $6 and ed.produto=p.grid),0) <> 0 then custo_medio_empresa_f($1, p.grid, $6::date) else 0 end),0) as sobra_falta_valor_medio, 
		coalesce((select sum(ed.consumo) from estoque_deposito ed where ed.empresa=$1 and ed.data between $5 and $6 and ed.produto=p.grid),0) as consumo_quantidade, 
		coalesce((select sum(l.quantidade) from lancto l where l.empresa=ed.empresa and l.operacao='O' and l.data between $5 and $6 and l.produto=p.grid),0) as bonificacao_quantidade, 
		coalesce((select sum(l.valor) from  lancto l where l.empresa=ed.empresa and l.operacao='C' and l.data between $5 and $6 and l.produto=p.grid),0) as consumo_valor_total, 
		coalesce((select sum(l.valor) from  lancto l where l.empresa=ed.empresa and l.operacao='O' and l.data between $5 and $6 and l.produto=p.grid),0) as bonificacao_valor_total 
	from 
		produto p 
		   join grupo_produto g on (p.grupo=g.grid) 
		   join estoque_deposito ed on (p.grid = ed.produto) 
	where 
		ed.data between (select data from estoque_deposito x where x.empresa=ed.empresa and x.produto=ed.produto and x.data <= $6 order by 1 desc limit 1) and $6 and 
		p.tipo <> 'S' and 
		ed.empresa = $1 and 
		(p.controlar_estoque or (not p.controlar_estoque and p.tipo_combustivel = 6)) and
		(case when $2 is null then true else p.grupo = $2 end) and 
		(case when $3 is null then true else p.subgrupo = $3 end) and 
		(case when $4 is null then true else p.grid = $4 end) and 
		((deposito_movimenta_produto_f(ed.deposito,p.grid)) or (coalesce(estoque_produto_f(ed.empresa, p.grid, $5::date-1),0) > 0) or (produto_movimenta_periodo_f(ed.empresa,p.grid, $5::date, $6::date) or (p.flag = 'A')))) t 
where 
	not (estoque_inicial_qtd = 0 and compra_quantidade = 0 and venda_quantidade = 0 and sobra_falta_quantidade = 0 and bonificacao_quantidade = 0) loop

		return next r; 
	end loop;
	return;
end;
   
$_$;


ALTER FUNCTION public.resumo_estoque_tf(bigint, bigint, bigint, bigint, date, date) OWNER TO postgres;

