--
-- Name: tabela_hash_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tabela_hash_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE 
	  dt DATE;
	  t RECORD;
	  r RECORD;
BEGIN

	SELECT INTO r current_user_name() AS user;

	IF r.user IS NULL THEN
		IF (TG_OP = 'INSERT') THEN
			t := NEW;
		ELSE
			t := OLD;
		END IF;

		IF upper(TG_RELNAME) = 'ABASTECIMENTO' OR upper(TG_RELNAME) = 'BICO_ABASTECIMENTO' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.hora::DATE);

		ELSIF upper(TG_RELNAME) = 'ABASTECIMENTO_FISCAL' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_hora::DATE);

		ELSIF upper(TG_RELNAME) = 'BICO_INTERVENCAO' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data::DATE);

		ELSIF upper(TG_RELNAME) = 'ECF_FORMA_PGTO' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_movto::DATE);

		ELSIF upper(TG_RELNAME) = 'CUPOM' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_movto::DATE);

		ELSIF upper(TG_RELNAME) = 'CUPOM_PRODUTO' OR upper(TG_RELNAME) = 'CUPOM_TOTAL' OR upper(TG_RELNAME) = 'CUPOM_PAGTO' THEN
			SELECT data_movto INTO dt FROM cupom WHERE grid = t.cupom;
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, COALESCE(dt, now()::DATE));

		ELSIF upper(TG_RELNAME) = 'CUPOM_NAO_FISCAL' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_movto::DATE);

		ELSIF upper(TG_RELNAME) = 'CUPOM_NAO_FISCAL_PAGTO' THEN
			SELECT data_movto INTO dt FROM cupom_nao_fiscal WHERE grid = t.cupom_nao_fiscal;
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, COALESCE(dt, now()::DATE));

		ELSIF upper(TG_RELNAME) = 'REDUCAO_Z' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_movto::DATE);

		ELSIF upper(TG_RELNAME) = 'REDUCAO_Z_TOTAL' THEN
			SELECT data_movto INTO dt FROM reducao_z WHERE grid = t.reducao_z;
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, COALESCE(dt, now()::DATE));
			
		ELSIF upper(TG_RELNAME) = 'COMANDA' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.ts_abertura::DATE);

		ELSIF upper(TG_RELNAME) = 'COMANDA_PRODUTO' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.hora::DATE);

		ELSIF upper(TG_RELNAME) = 'ESTOQUE_VALOR' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data::DATE);

		ELSIF upper(TG_RELNAME) = 'NOTA_FISCAL' THEN
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, t.data_emissao::DATE);

		ELSIF upper(TG_RELNAME) = 'NOTA_FISCAL_PRODUTO' THEN
			SELECT data_emissao INTO dt FROM nota_fiscal WHERE grid = t.nota_fiscal;
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, COALESCE(dt, now()::DATE));

		ELSE
			INSERT INTO tabela_hash (tabela, data_movto) VALUES (TG_RELNAME, now()::DATE);

        END IF;

	END IF;

 	IF (TG_OP = 'INSERT') THEN
 	 	RETURN NEW;
 	ELSE
 	 	RETURN OLD;
 	END IF;
END;
  
$$;


ALTER FUNCTION public.tabela_hash_tgf() OWNER TO postgres;

--
-- Name: tabela_preco_produto_set_pendencia_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.tabela_preco_produto_set_pendencia_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

DECLARE
	emp RECORD;
    eic RECORD;

BEGIN
	SELECT e.grid, e.grupo, regexp_replace(e.cpf, '[^0-9]', '', 'g') as cnpj
	  INTO emp
	  FROM empresa e
	  JOIN empresa_local el
        ON el.empresa = e.grid;

	--Sai da funcao se nao localiza os dados da empresa.
	IF NOT found THEN
		RETURN NEW;
	END IF;

	SELECT tipo_atualizacao_preco_pro_frotas as tipo_atualizacao,
		   forma_pgto_pro_frotas as forma_pgto
	  INTO eic 
	  FROM exc_ipp_config 
	 WHERE empresa = emp.grid
	   AND tipo_atualizacao_preco_pro_frotas BETWEEN 1 AND 3;
    
    --Sai se a criacao de pendencia nao for via tabela_preco_produto
	IF NOT FOUND THEN
		RETURN NEW;
	END IF;

	-- Tipo 1: valida se eh tabela que usa a forma de pagto pro-frotas
	IF eic.tipo_atualizacao = 1 AND NOT (NEW.tabela_preco IN (
		SELECT grid as tabela_preco 
		  FROM tabela_preco 
		 WHERE motivo = eic.forma_pgto 
		   AND pessoa is null 
		   AND grupo_pessoa is null 
		   AND (empresa is null or empresa = emp.grid) 
		UNION 
		SELECT tabela_preco 
		  FROM regra_preco 
		 WHERE forma_pgto = eic.forma_pgto 
		   AND pessoa is null
		   AND grupo_pessoa is null
		   AND (empresa is null or empresa = emp.grid or grupo_empresa = emp.grupo))) THEN 
		RETURN NEW;
	
	-- Tipo 2: valida se eh tabela de preco configurada no pro-frotas
	ELSIF eic.tipo_atualizacao = 2 AND NOT (NEW.tabela_preco IN (
		SELECT tabela_preco 
		  FROM exc_ipp_pro_frotas_regra_preco_config 
		 WHERE empresa = emp.grid
		   AND tabela_preco is not null)) THEN
		RETURN NEW;
	
	-- Tipo 3: valida se a tabela se refere a regra de preco configurada no pro-frotas
	ELSIF eic.tipo_atualizacao = 3 AND NOT (NEW.tabela_preco IN (
		SELECT rp.tabela_preco 
		  FROM regra_preco rp
		  JOIN exc_ipp_pro_frotas_regra_preco_config rpc 
		    ON rpc.regra_preco = rp.grid
		 WHERE (rp.empresa is null or rp.empresa = emp.grid))) THEN
		RETURN NEW;
	END IF;

	IF EXISTS (SELECT True FROM exc_ipp_pro_frotas_atualiza_preco_pendencia 
			WHERE tabela_preco_produto = NEW.grid) THEN
		UPDATE exc_ipp_pro_frotas_atualiza_preco_pendencia 
			SET ts = now(), 
				payload = '', 
				status = 0 , 
				retorno = '', 
				codigo_anp = ''
			WHERE tabela_preco_produto = NEW.grid;
	ELSE
		INSERT INTO exc_ipp_pro_frotas_atualiza_preco_pendencia (ts, status, tabela_preco_produto) 
		VALUES (now(), 0, NEW.grid);
	END IF;

	RETURN NEW;
END;
  
$$;


ALTER FUNCTION public.tabela_preco_produto_set_pendencia_tgf() OWNER TO postgres;

