--
-- Name: troca_operador_intervalo_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.troca_operador_intervalo_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

    DECLARE
        rel TEXT;
        pk BIGINT;
        ex BOOLEAN;
        emp BIGINT;
 
        rec RECORD;
        rec_old RECORD;
        sel RECORD;
        sub RECORD;
    BEGIN

        IF TG_OP = 'DELETE' THEN
            rec := OLD;
            rec_old := rec;

        ELSIF TG_OP = 'UPDATE' THEN
            rec := NEW;
            rec_old := OLD;

        ELSE
            rec := NEW;
            rec_old := rec;

        END IF;

        SELECT grid INTO emp FROM empresa_local LIMIT 1;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;

        IF NOT FOUND THEN
            SELECT seq INTO pk FROM troca_operador_intervalo_sync LIMIT 1;
            IF FOUND THEN
                TRUNCATE troca_operador_intervalo_sync;
                PERFORM setval('troca_operador_intervalo_sync', 1);
            END IF;
            RETURN rec;
        END IF;
 
        ex := TG_OP = 'DELETE';
        rel := TG_RELNAME;
 
        SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
        IF NOT FOUND THEN
            RETURN rec_old;
        END IF;

        pk := rec.grid;
 
        BEGIN
            INSERT INTO troca_operador_intervalo_sync (pkey, excluido) VALUES (pk, ex);
 
        EXCEPTION WHEN unique_violation THEN
 
            UPDATE troca_operador_intervalo_sync SET seq = NEXTVAL('troca_operador_intervalo_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
        END;
 
        RETURN rec;
    END;
    
$$;


ALTER FUNCTION public.troca_operador_intervalo_sync_tgf() OWNER TO postgres;

--
-- Name: usuario_desconto_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usuario_desconto_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

	DECLARE
		rel TEXT;
		pk BIGINT;
		ex BOOLEAN;
		emp BIGINT;
		rec RECORD;
		rec_old RECORD;
		sel RECORD;
		sub RECORD;
		usuarios RECORD;
	BEGIN
		IF TG_OP = 'DELETE' THEN
			rec := OLD;
			rec_old := rec;

		ELSIF TG_OP = 'UPDATE' THEN
			rec := NEW;
			rec_old := OLD;

		ELSE
			rec := NEW;
			rec_old := rec;
		END IF;

		SELECT grid INTO emp FROM empresa_local LIMIT 1;

		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;

		IF NOT FOUND THEN
			SELECT seq INTO pk FROM usuario_desconto_sync LIMIT 1;
			IF FOUND THEN
				TRUNCATE usuario_desconto_sync;
				PERFORM setval('usuario_desconto_sync_seq', 1);
			END IF;
			RETURN rec;
		END IF;

		ex := TG_OP = 'DELETE';

		rel := TG_RELNAME;
		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';
		IF NOT FOUND THEN
			RETURN rec_old;
		END IF;

		IF TG_TABLE_NAME in ('usuario', 'grupo_usuario', 'grupo_usuario_desconto', 'usuario_grupo_map') THEN
			pk := rec.grid;
			DELETE FROM usuario_desconto_sync WHERE excluido = true AND ts::date BETWEEN (now() - '300 days'::interval) AND (now() - '30 days'::interval);

		ELSIF TG_TABLE_NAME = 'usuario_desconto' THEN
			pk := rec.id;
		END IF;

		IF TG_TABLE_NAME = 'usuario' THEN
			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_desconto WHERE usuario_id = rec_old.grid;
			END IF;

			RETURN rec;

		ELSIF TG_TABLE_NAME = 'grupo_usuario' THEN
			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_desconto
				WHERE grupo_usuario_id = rec_old.grid;
			END IF;
			
			RETURN rec;
			
		ELSIF TG_TABLE_NAME = 'grupo_usuario_desconto' THEN

			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_desconto
				WHERE grupo_usuario_desconto = rec.grid;

			ELSIF TG_OP = 'INSERT' THEN
				INSERT INTO usuario_desconto (	usuario_id, grupo_usuario_id, produto_id, grupo_produto_id, 
												grupo_usuario_desconto, perc_desconto, valor_desconto, tipo)
				SELECT 	gu.usuario, gu.grupo, rec.produto, 
						COALESCE(rec.subgrupo_produto, rec.grupo_produto), rec.grid,
						rec.perc_desconto, rec.valor_desconto, rec.tipo
				FROM usuario_grupo_map gu
				WHERE gu.grupo = rec.grupo_usuario
				AND (rec.empresa IS NULL OR rec.empresa = (SELECT empresa FROM empresa_local LIMIT 1));

			ELSIF TG_OP = 'UPDATE' THEN
				UPDATE usuario_desconto SET
					produto_id = rec.produto,
					grupo_produto_id = COALESCE(rec.subgrupo_produto, rec.grupo_produto),
					perc_desconto = rec.perc_desconto,
					valor_desconto = rec.valor_desconto,
					tipo = rec.tipo
				WHERE grupo_usuario_desconto = rec.grid;
			END IF;

			RETURN rec;

		ELSIF TG_TABLE_NAME = 'usuario_grupo_map' THEN

			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_desconto 
				WHERE usuario_id = rec_old.usuario 
					AND grupo_usuario_id = rec_old.grupo;

			ELSIF TG_OP = 'INSERT' THEN
				INSERT INTO usuario_desconto (
					usuario_id, 
					grupo_usuario_id,
					produto_id, 
					grupo_produto_id, 
					grupo_usuario_desconto, 
					perc_desconto, 
					valor_desconto, 
					tipo
				)
				SELECT 
					rec.usuario,
					rec.grupo,
					gud.produto,
					COALESCE(gud.subgrupo_produto, gud.grupo_produto),
					gud.grid,
					gud.perc_desconto,
					gud.valor_desconto,
					gud.tipo
				FROM grupo_usuario_desconto gud
				WHERE gud.grupo_usuario = rec.grupo
				AND (gud.empresa IS NULL OR gud.empresa = (SELECT empresa FROM empresa_local LIMIT 1))
				AND NOT EXISTS (
					SELECT 1 FROM usuario_desconto ud
					WHERE ud.usuario_id = rec.usuario
						AND ud.grupo_usuario_desconto = gud.grid
				);
			
			ELSIF TG_OP = 'UPDATE' THEN
				IF rec_old.grupo != rec.grupo THEN
					DELETE FROM usuario_desconto 
					WHERE usuario_id = rec_old.usuario 
						AND grupo_usuario_id = rec_old.grupo;
					INSERT INTO usuario_desconto (
						usuario_id, 
						grupo_usuario_id,
						produto_id, 
						grupo_produto_id, 
						grupo_usuario_desconto, 
						perc_desconto, 
						valor_desconto, 
						tipo
					)
					SELECT 
						rec.usuario,
						rec.grupo,
						gud.produto_id,
						COALESCE(gud.subgrupo_produto, gud.grupo_produto),
						gud.grid,
						gud.perc_desconto,
						gud.valor_desconto,
						gud.tipo
					FROM grupo_usuario_desconto gud
					WHERE gud.grupo_usuario = rec.grupo
					AND (gud.empresa IS NULL OR gud.empresa = (SELECT empresa FROM empresa_local LIMIT 1))
					AND NOT EXISTS (
						SELECT 1 FROM usuario_desconto ud
						WHERE ud.usuario_id = rec.usuario
							AND ud.grupo_usuario_desconto = gud.grid
					);
				END IF;
			END IF;

			RETURN rec;
		END IF;

		BEGIN

			SELECT pkey INTO sel FROM usuario_desconto_sync WHERE pkey = pk;
			IF NOT FOUND THEN
				INSERT INTO usuario_desconto_sync (pkey, excluido) VALUES (pk, ex);
			ELSE
				UPDATE usuario_desconto_sync SET excluido = ex, seq = NEXTVAL('usuario_desconto_sync_seq'), ts = now() WHERE pkey = pk;
			END IF;

		EXCEPTION WHEN unique_violation THEN
			UPDATE usuario_desconto_sync SET seq = NEXTVAL('usuario_desconto_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
		END;
		
		RETURN rec;
	
	END;
	
$$;


ALTER FUNCTION public.usuario_desconto_sync_tgf() OWNER TO postgres;

--
-- Name: usuario_permissao_sync_tgf(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usuario_permissao_sync_tgf() RETURNS trigger
    LANGUAGE plpgsql
    AS $$

	DECLARE
		rel TEXT;
		pk BIGINT;
		ex BOOLEAN;
		emp BIGINT;
		rec RECORD;
		rec_old RECORD;
		sel RECORD;
		sub RECORD;
		usuarios RECORD;
	BEGIN
		IF TG_OP = 'DELETE' THEN
			rec := OLD;
			rec_old := rec;

		ELSIF TG_OP = 'UPDATE' THEN
			rec := NEW;
			rec_old := OLD;

		ELSE
			rec := NEW;
			rec_old := rec;
		END IF;

		SELECT grid INTO emp FROM empresa_local LIMIT 1;

		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync' AND empresa = emp;

		IF NOT FOUND THEN
			SELECT seq INTO pk FROM usuario_permissao_sync LIMIT 1;
			IF FOUND THEN
				TRUNCATE usuario_permissao_sync;
				PERFORM setval('usuario_permissao_sync_seq', 1);
			END IF;
			RETURN rec;
		END IF;

		ex := TG_OP = 'DELETE';

		rel := TG_RELNAME;

		SELECT grid INTO pk FROM config WHERE chave = 'as_linxpos_sync';

		IF NOT FOUND THEN
			RETURN rec_old;
		END IF;

		IF rel IN ('usuario_permissao', 'permissao') THEN
			pk := rec.id;
		ELSE
			pk := rec.grid;
			DELETE FROM usuario_permissao_sync WHERE excluido = true AND ts::date BETWEEN (now() - '300 days'::interval) AND (now() - '30 days'::interval);
		END IF;

		IF rel = 'grupo_usuario_config' THEN

			FOR sub IN 

				SELECT p1.id as permissao_id, coalesce(tab.LEVEL, p1.valor_padrao) AS level, tab.usuario_id 
				FROM (
					SELECT 
						p.id AS permissao_id, 
						u.usuario AS usuario_id,
						(
							(CASE WHEN strpos(guc.valor::TEXT, '1') > 0 THEN 2 ELSE 0 END)::INT8  + 
							(CASE WHEN strpos(guc.valor::TEXT, 'I') > 0 THEN 16 ELSE 0 END)::INT8 + 
							(CASE WHEN strpos(guc.valor::TEXT, 'A') > 0 THEN 8 ELSE 0 END)::INT8  + 
							(CASE WHEN strpos(guc.valor::TEXT, 'E') > 0 THEN 32 ELSE 0 END)::INT8 + 
							(CASE WHEN strpos(guc.valor::TEXT, 'V') > 0 THEN 4 ELSE 0 END)::INT8
						) AS level, u.grupo
					FROM 
						permissao p
					LEFT JOIN 
						grupo_usuario_config guc ON (guc.topico = p.chave_as3)
					LEFT JOIN 
						usuario_grupo_map u ON (u.grupo = guc.grupo)
					LEFT JOIN 
						usuario s ON (u.usuario = s.grid)
					WHERE 
						guc.grupo = rec.grupo AND 
						guc.topico = rec.topico AND 
						(s.empresa = (select empresa from empresa_local) or s.empresa is null) 
					ORDER BY 
						guc.grid 
				) AS TAB 
				INNER JOIN permissao p1 ON p1.id = TAB.permissao_id

			LOOP

				SELECT * INTO sel FROM usuario_permissao WHERE usuario_id = sub.usuario_id AND permissao_id = sub.permissao_id;
				IF FOUND AND sel.level != sub.level THEN
					UPDATE usuario_permissao set level = sub.level WHERE usuario_id = sub.usuario_id AND permissao_id = sub.permissao_id;
				END IF;

			END LOOP;

			RETURN rec;

		ELSIF rel = 'usuario_grupo_map' THEN

			IF TG_OP != 'DELETE' THEN

				FOR usuarios IN
					
					SELECT grid as usuario FROM usuario u 
					WHERE u.grid = rec.usuario AND
						(u.empresa = (select empresa from empresa_local) or u.empresa is null)
				LOOP
					FOR sub IN
						SELECT p1.id as permissao_id, coalesce(tab.LEVEL, p1.valor_padrao) AS level
						FROM (
							SELECT 
								p.id AS permissao_id, 
								u.usuario AS usuario_id,
								(
									(CASE WHEN strpos(guc.valor::TEXT, '1') > 0 THEN 2 ELSE 0 END)::INT8  +
									(CASE WHEN strpos(guc.valor::TEXT, 'I') > 0 THEN 16 ELSE 0 END)::INT8 + 
									(CASE WHEN strpos(guc.valor::TEXT, 'A') > 0 THEN 8 ELSE 0 END)::INT8  + 
									(CASE WHEN strpos(guc.valor::TEXT, 'E') > 0 THEN 32 ELSE 0 END)::INT8 + 
									(CASE WHEN strpos(guc.valor::TEXT, 'V') > 0 THEN 4 ELSE 0 END)::INT8
								) AS level, u.grupo
							FROM 
								permissao p
							LEFT JOIN 
								grupo_usuario_config guc ON (guc.topico = p.chave_as3)
							LEFT JOIN 
								usuario_grupo_map u ON (u.grupo = guc.grupo)
							WHERE 
								u.usuario = usuarios.usuario AND 
								u.grupo = rec.grupo
							ORDER BY 
								guc.grid	
						) AS TAB
						RIGHT JOIN permissao p1 ON p1.id = TAB.permissao_id
					LOOP

						SELECT * INTO sel FROM usuario_permissao WHERE usuario_id = usuarios.usuario AND permissao_id = sub.permissao_id;
						IF NOT FOUND THEN
							INSERT INTO usuario_permissao 
								(permissao_id, usuario_id, level) 
							VALUES
								(sub.permissao_id, usuarios.usuario, sub.level);
						ELSIF sel.level != sub.level THEN
							UPDATE usuario_permissao set level = sub.level WHERE usuario_id = usuarios.usuario AND permissao_id = sub.permissao_id;
						END IF;

					END LOOP;

				END LOOP;

			END IF;

			RETURN rec;

		ELSIF rel = 'usuario' THEN

			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_permissao WHERE usuario_id = rec.grid;
			END IF;

			IF rec.grid IS NOT NULL AND not ex AND (rec.empresa = (select empresa from empresa_local) or rec.empresa is NULL)   THEN
				FOR sub IN
					SELECT p1.id as permissao_id, coalesce(tab.LEVEL, p1.valor_padrao) AS level
					FROM (
						SELECT 
							p.id AS permissao_id, 
							u.usuario AS usuario_id,
							(
								(CASE WHEN strpos(guc.valor::TEXT, '1') > 0 THEN 2 ELSE 0 END)::INT8  +
								(CASE WHEN strpos(guc.valor::TEXT, 'I') > 0 THEN 16 ELSE 0 END)::INT8 + 
								(CASE WHEN strpos(guc.valor::TEXT, 'A') > 0 THEN 8 ELSE 0 END)::INT8  + 
								(CASE WHEN strpos(guc.valor::TEXT, 'E') > 0 THEN 32 ELSE 0 END)::INT8 + 
								(CASE WHEN strpos(guc.valor::TEXT, 'V') > 0 THEN 4 ELSE 0 END)::INT8
							) AS level, u.grupo
						FROM 
							permissao p
						LEFT JOIN 
							grupo_usuario_config guc ON (guc.topico = p.chave_as3)
						LEFT JOIN 
							usuario_grupo_map u ON (u.grupo = guc.grupo)
						WHERE 
							u.usuario = rec.grid 
						ORDER BY 
							guc.grid	
					) AS TAB
					RIGHT JOIN permissao p1 ON p1.id = TAB.permissao_id
				LOOP
					SELECT * INTO sel FROM usuario_permissao WHERE usuario_id = rec.grid AND permissao_id = sub.permissao_id;
					IF NOT FOUND THEN
						INSERT INTO usuario_permissao 
							(permissao_id, usuario_id, level) 
						VALUES
							(sub.permissao_id, rec.grid, sub.level);
					ELSIF sel.level != sub.level THEN
						UPDATE usuario_permissao set level = sub.level WHERE usuario_id = rec.grid AND permissao_id = sub.permissao_id;
					END IF;

				END LOOP;
			ELSE
				DELETE FROM usuario_permissao WHERE usuario_id = rec.grid;
			END IF;
		
			RETURN rec;

		ELSIF rel = 'permissao' THEN

			IF TG_OP = 'DELETE' THEN
				DELETE FROM usuario_permissao WHERE permissao_id = rec.id;
			ELSE

				IF TG_OP = 'UPDATE' and rec_old.id != rec.id THEN
					UPDATE usuario_permissao SET permissao_id = rec.id WHERE permissao_id = rec_old.id;
				END IF;
			
				FOR usuarios IN
					
					SELECT grid as usuario FROM usuario u 
					WHERE (u.empresa = (select empresa from empresa_local) or u.empresa is null)
				LOOP
					FOR sub IN
						SELECT p1.id as permissao_id, coalesce(tab.LEVEL, p1.valor_padrao) AS level
						FROM (
							SELECT 
								p.id AS permissao_id, 
								u.usuario AS usuario_id,
								(
									(CASE WHEN strpos(guc.valor::TEXT, '1') > 0 THEN 2 ELSE 0 END)::INT8  +
									(CASE WHEN strpos(guc.valor::TEXT, 'I') > 0 THEN 16 ELSE 0 END)::INT8 + 
									(CASE WHEN strpos(guc.valor::TEXT, 'A') > 0 THEN 8 ELSE 0 END)::INT8  + 
									(CASE WHEN strpos(guc.valor::TEXT, 'E') > 0 THEN 32 ELSE 0 END)::INT8 + 
									(CASE WHEN strpos(guc.valor::TEXT, 'V') > 0 THEN 4 ELSE 0 END)::INT8
								) AS level, u.grupo
							FROM 
								permissao p
							LEFT JOIN 
								grupo_usuario_config guc ON (guc.topico = p.chave_as3)
							LEFT JOIN 
								usuario_grupo_map u ON (u.grupo = guc.grupo)
							WHERE 
								u.usuario = usuarios.usuario AND 
								p.id = rec.id
							ORDER BY 
								guc.grid	
						) AS TAB
						LEFT JOIN permissao p1 ON p1.id = TAB.permissao_id
					LOOP

						SELECT * INTO sel FROM usuario_permissao WHERE usuario_id = usuarios.usuario AND permissao_id = sub.permissao_id;
						IF NOT FOUND THEN
							INSERT INTO usuario_permissao 
								(permissao_id, usuario_id, level) 
							VALUES
								(sub.permissao_id, usuarios.usuario, sub.level);
						ELSIF sel.level != sub.level THEN
							UPDATE usuario_permissao set level = sub.level WHERE usuario_id = usuarios.usuario AND permissao_id = sub.permissao_id;
						END IF;

					END LOOP;

				END LOOP;

			END IF;
		
			RETURN rec;

		END IF;
		
		BEGIN

			SELECT pkey INTO sel FROM usuario_permissao_sync WHERE pkey = pk;
			IF NOT FOUND THEN
				INSERT INTO usuario_permissao_sync (pkey, excluido) VALUES (pk, ex);
			ELSE
				UPDATE usuario_permissao_sync SET excluido = ex, seq = NEXTVAL('usuario_permissao_sync_seq'), ts = now() WHERE pkey = pk;
			END IF;

		EXCEPTION WHEN unique_violation THEN
		
			UPDATE usuario_permissao_sync SET seq = NEXTVAL('usuario_permissao_sync_seq'), excluido = ex, ts = now() WHERE pkey = pk;
		
		END;
		
		RETURN rec;
	
	END;
	
$$;


ALTER FUNCTION public.usuario_permissao_sync_tgf() OWNER TO postgres;

--
-- Name: usuario_pessoa_f(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.usuario_pessoa_f(text) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
   /*Parametros:
	1-$1 usuario
	2-Retorno pessoa
	*/
	v_pessoa bigint;
	
begin
	select p.grid into v_pessoa from pessoa as p 
		join usuario as u on (u.pessoa=p.grid)
		where u.nome=$1 limit 1;

	return v_pessoa;
END;

$_$;


