--
-- Name: valida_ean_f(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.valida_ean_f(text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare
	i integer = 1;
	cod text;
	peso integer = 3;
	soma integer = 0;
	dv text;
begin
	if isdigit_f($1) = false then
		return False;
	end if;
	
	if length($1) not in (8, 12, 13, 14) then
		return false;
	end if;

	cod = lpad(substr($1, 1, length($1)-1), 17, '0');
	
	while i <= length(cod) loop
		soma = soma + (substr(cod, i, 1)::integer * peso);

		if peso = 3 then
			peso := 1;
		else
			peso := 3;
		end if;

		i = i + 1;
	end loop;

	dv := (abs((soma % 10) - 10))::text;
	dv := substr(dv, length(dv), 1);

	if dv = substr($1, length($1), 1) then
		return true;
	end if;

	return false;
end;
  
$_$;


ALTER FUNCTION public.valida_ean_f(text) OWNER TO postgres;

--
-- Name: valor_extenso_aux_f(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.valor_extenso_aux_f(text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE

	unidade text[];

	dezena text[];

	centena text[];

	excecao text[];

	pos1 integer;

	pos2 integer;

	pos3 integer;

	vl_centena text;

	vl_dezena text;

	vl_unidade text;

	retorno text;

	valor Text;

BEGIN

	IF $1 = '0' THEN

		return 'ZERO';

	END IF;



	--declaraÁ„o de vetores para Unidades, Dezenas, Centenas e de 10 a 19

	unidade[0] := ' ';

	unidade[1] := 'UM ';

	unidade[2] := 'DOIS ';

	unidade[3] := 'TRES ';

	unidade[4] := 'QUATRO ';

	unidade[5] := 'CINCO ';

	unidade[6] := 'SEIS ';

	unidade[7] := 'SETE ';

	unidade[8] := 'OITO ';

	unidade[9] := 'NOVE ';

	

	dezena[1] := ' '; 

	dezena[2] := 'VINTE E';

	dezena[3] := 'TRINTA E';

	dezena[4] := 'QUARENTA E';

	dezena[5] := 'CINQUENTA E';

	dezena[6] := 'SESSENTA E';

	dezena[7] := 'SETENTA E';

	dezena[8] := 'OITENTA E';

	dezena[9] := 'NOVENTA E';



	centena[1] := ' ';

	centena[2] := 'CENTO E';

	centena[3] := 'DUZENTOS E';

	centena[4] := 'TREZENTOS E';

	centena[5] := 'QUATROCENTOS E';

	centena[6] := 'QUINHENTOS E';

	centena[7] := 'SEISCENTOS E';

	centena[8] := 'SETECENTOS E';

	centena[9] := 'OITOCENTOS E';

	centena[10] := 'NOVECENTOS E';



	excecao[0] := 'DEZ ';

	excecao[1] := 'ONZE ';

	excecao[2] := 'DOZE ';

	excecao[3] := 'TREZE ';

	excecao[4] := 'QUATORZE ';

	excecao[5] := 'QUINZE ';

	excecao[6] := 'DESESSEIS ';

	excecao[7] := 'DESESSETE ';

	excecao[8] := 'DEZOITO ';

	excecao[9] := 'DESENOVE ';



	valor := lpad($1::text,3,'0');



	--extrai as posiÁıes de centena, dezena e unidade.

	pos1 := substr(valor,1,1);

	pos2 := substr(valor,2,1);

	pos3 := substr(valor,3,1);



	--busca nos vetores as palavras correspondentes

	vl_centena := centena[pos1::int +1];

	vl_dezena := ' ' || dezena[pos2::int];

	vl_unidade := ' ' || unidade[pos3::int];



	--trata a exceÁ„o: 100

	IF substr(valor,1,3) = '100' THEN

		vl_centena := 'CEM ';

	END IF;



	--trata as exceÁıes de 10 a 19

	IF substr(valor,2,1) = '1' THEN

		vl_dezena := ' ' || excecao[pos3];

		vl_unidade := '';

	END IF;



	--monta a string de resultado

	retorno := trim(coalesce(vl_centena,'') || coalesce(vl_dezena,'') || coalesce(vl_unidade,''));



	--verifica se sobrou um E no final

	IF substr(retorno,length(retorno)-1,2) = ' E' THEN

		retorno := substr(retorno, 1, length(retorno) - 1);

	END IF;



	return retorno;

END;
$_$;


ALTER FUNCTION public.valor_extenso_aux_f(text) OWNER TO postgres;

--
-- Name: valor_extenso_f(numeric); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.valor_extenso_f(numeric) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

DECLARE

	moeda_sing text;

	moeda_plu text;

	milhao text;

	milhar text;

	unidade text;

	centavo text;

	compl_milhao text;

	compl_milhar text;

	compl_unidade text;

	resultado text;

	valor text;

BEGIN

	IF $1 = 0 THEN

		return '';

	END IF;



	--moeda corrente no singular e plural.

	moeda_sing := ' REAL';

	moeda_plu := ' REAIS';



	--formata o valor de acordo com a m·scara 999999999.99

	valor := replace(substr(to_char($1, '999999999D00'), 2), ' ', '0');



	--usa a funÁ„o valor_extenso_aux_f para obter quantos milhıes.

	milhao := valor_extenso_aux_f(substr(valor,1,3));

	IF (substr(valor,1,3)::integer > 1) THEN

		milhao := milhao || ' MILHOES';

	ELSE 

		IF (substr(valor,1,3)::integer = 1) THEN

			milhao := milhao || ' MILHAO';

		END IF;

	END IF;



	--usa a funÁ„o valor_extenso_aux_f para obter quantos mil.

	milhar := valor_extenso_aux_f(substr(valor,4,3));

	IF (substr(valor,4,3)::int > 0) THEN

		IF substr(valor,4,3)::int = 1 THEN

			milhar := ' MIL';

		ELSE

			milhar := milhar || ' MIL';

		END IF;

	END IF;



	--usa a funÁ„o valor_extenso_aux_f para obter quantas unidades.

	unidade := valor_extenso_aux_f(substr(valor,7,3));

	IF (substr(valor,1,9)::integer = 1) THEN

		unidade := unidade || moeda_sing;

	ELSE

		unidade := unidade || moeda_plu;

	END IF;



	--usa a funÁ„o valor_extenso_aux_f para obter quantos centavos

	centavo := valor_extenso_aux_f('0' || substr(valor,11,2));

	IF (substr(valor,11,2)::integer > 1) THEN

		centavo := centavo || ' CENTAVOS';

	ELSE 

		IF (substr(valor,11,2)::integer = 1) THEN

			centavo := centavo || ' CENTAVO';

		END IF;

	END IF;



	--verifica a necessidade de ',' apÛs o milh„o.

	IF length(trim(milhao))::integer <> 0 THEN

		compl_milhao := ' E ';

	ELSE

		compl_milhao := '';

	END IF;



	--verifica a necessidade de , apÛs o mil.
	IF length(ltrim(substr(valor,6,4),'0'))::int < 4 or length(trim(substr(valor,6,4),'0'))::int = 1 THEN	

		compl_milhar := ' ';

	ELSE

		compl_milhar := ' E ';

	END IF;



	--verifica a necessidade de , apÛs as unidades.

	IF length(trim(unidade))::integer <> 0 and length(trim(centavo))::integer <> 0 THEN

		compl_unidade := ' E ';

	ELSE

		compl_unidade := '';

	END IF;



	resultado:= milhao || compl_milhao || milhar || compl_milhar ||

	unidade || compl_unidade || centavo;



	return replace(resultado,'  ',' ');

END;
$_$;


ALTER FUNCTION public.valor_extenso_f(numeric) OWNER TO postgres;

--
-- Name: venda_forma_pgto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venda_forma_pgto_f(bigint) RETURNS SETOF public.venda_forma_pgto_t
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

    DECLARE
        v_motivo_dinheiro BIGINT;
        v_qtd_formas_pgto BIGINT;
    BEGIN
        SELECT mc.motivo INTO v_motivo_dinheiro
        FROM motivo_config mc
        WHERE mc.chave = 'DINHEIRO'
        LIMIT 1;
     
        SELECT COUNT(DISTINCT m.motivo) INTO v_qtd_formas_pgto
        FROM movto m
        JOIN motivo_movto mm ON m.motivo = mm.grid AND mm.forma_pgto
        WHERE m.mlid = $1;
     
        RETURN QUERY
        WITH 
        venda_base AS (
            SELECT 
                m.empresa,
                m.data,
                m.mlid,
                m.usuario,
                m.pessoa,
                m.turno,
                m.valor AS valor_venda,
                m.conta_debitar
            FROM movto m
            JOIN motivo_config mc ON m.motivo = mc.motivo 
                AND mc.chave IN ('VENDA', 'VENDA_TRR')
            WHERE m.mlid = $1
            LIMIT 1
        ),
        total_pgto_filtrado AS (
            SELECT COALESCE(SUM(m1.valor), 0) AS total
            FROM movto m1
            JOIN motivo_movto mm ON mm.grid = m1.motivo AND mm.tipo_movto <> 14
            LEFT JOIN tipo_vale tv ON tv.grid = mm.tipo_vale AND tv.tipo = 1
            JOIN venda_base vb ON m1.mlid = vb.mlid AND m1.conta_creditar = vb.conta_debitar
            WHERE tv.grid IS NULL
        ),
        formas_pgto AS (
            SELECT 
                COALESCE(mp.motivo, v_motivo_dinheiro) AS forma_pgto,
                SUM(mp.valor) AS valor_forma_pgto
            FROM movto mp
            WHERE mp.mlid = $1
            GROUP BY COALESCE(mp.motivo, v_motivo_dinheiro)
        ),
        calculos AS (
            SELECT 
                vb.*,
                fp.forma_pgto,
                fp.valor_forma_pgto,
                COALESCE(tpf.total, vb.valor_venda) AS total_pgto_base,
                vb.valor_venda - COALESCE(tpf.total, vb.valor_venda) AS diferenca
            FROM venda_base vb
            CROSS JOIN total_pgto_filtrado tpf
            LEFT JOIN formas_pgto fp ON TRUE
        ),
        resultado AS (
            SELECT DISTINCT 
                c.empresa,
                c.data,
                c.mlid,
                c.usuario,
                c.pessoa,
                c.turno::SMALLINT AS turno,
                c.forma_pgto,
                c.valor_venda,
                c.valor_forma_pgto,
                c.total_pgto_base + GREATEST(c.diferenca, 0) AS total_forma_pgto,
                GREATEST(-c.diferenca, 0) AS troco,
                CASE 
                    WHEN c.forma_pgto = v_motivo_dinheiro THEN 1
                    WHEN c.diferenca > 0 THEN v_qtd_formas_pgto + 1
                    ELSE v_qtd_formas_pgto
                END AS pgto,
                c.conta_debitar,
                c.diferenca
            FROM calculos c
            UNION ALL
            SELECT DISTINCT
                c.empresa,
                c.data,
                c.mlid,
                c.usuario,
                c.pessoa,
                c.turno::SMALLINT AS turno,
                v_motivo_dinheiro AS forma_pgto,
                c.valor_venda,
                c.diferenca AS valor_forma_pgto,
                c.total_pgto_base + c.diferenca AS total_forma_pgto,
                0 AS troco,
                CASE 
                    WHEN c.diferenca > 0 THEN v_qtd_formas_pgto + 1
                    ELSE v_qtd_formas_pgto
                END AS pgto,
                c.conta_debitar,
                c.diferenca
            FROM calculos c
            WHERE c.diferenca > 0
              AND c.forma_pgto <> v_motivo_dinheiro
        )
        SELECT DISTINCT
            r.empresa,
            r.data,
            r.mlid,
            r.usuario,
            r.pessoa,
            r.turno,
            r.forma_pgto,
            (r.valor_forma_pgto / NULLIF(r.total_forma_pgto,0)) * r.valor_venda AS valor_venda_rateio,
            r.valor_venda,
            r.valor_forma_pgto,
            r.total_forma_pgto,
            r.troco,
            r.pgto,
            r.conta_debitar,
            COALESCE(
                (SELECT cf.data_emissao 
                 FROM cupom cf 
                 WHERE cf.grid = (SELECT ct.cupom 
                                  FROM cupom_total ct 
                                  WHERE ct.mlid = $1 LIMIT 1)
                 LIMIT 1
                ),
                (SELECT nf.data_emissao 
                 FROM nota_fiscal nf 
                 WHERE nf.mlid = $1
                 LIMIT 1
                )
            ) AS data_emissao
        FROM resultado r
        JOIN motivo_movto mm ON mm.grid = r.forma_pgto AND mm.forma_pgto
        WHERE r.valor_forma_pgto > 0.001;
    END;
    
$_$;


ALTER FUNCTION public.venda_forma_pgto_f(bigint) OWNER TO postgres;

--
-- Name: venda_maior_forma_pgto_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venda_maior_forma_pgto_f(bigint) RETURNS bigint
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare 
	c REFCURSOR;
	r RECORD;
	maior_forma BIGINT;
	maior_valor DOUBLE PRECISION;
	total DOUBLE PRECISION;
begin
	total := 0;
	maior_valor := 0;
	
	FOR r IN SELECT DISTINCT valor, m.motivo FROM movto m JOIN motivo_movto mm ON (m.motivo=mm.grid) WHERE
		m.mlid=$1 AND mm.forma_pgto = true LOOP
		
		IF maior_valor <= r.valor THEN
			maior_valor := r.valor;
			maior_forma := r.motivo;
		END IF;
		total := total + r.valor;
	END LOOP;
	
	SELECT valor into r FROM movto m WHERE m.mlid=$1 AND motivo = (SELECT motivo FROM motivo_config WHERE chave = 'VENDA');
	
	IF r.valor-total >= total THEN
		SELECT motivo INTO maior_forma FROM motivo_config WHERE chave = 'DINHEIRO';
	END IF;
	
	RETURN maior_forma;		
END
$_$;


ALTER FUNCTION public.venda_maior_forma_pgto_f(bigint) OWNER TO postgres;

--
-- Name: venda_pagamento_dinheiro_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venda_pagamento_dinheiro_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare
   	rlancto record;
   	rmovto  record;
begin
	select sum(m.valor) as valor into rmovto from movto m join motivo_movto mm on (m.motivo=mm.grid) where m.mlid=$1 and mm.forma_pgto;

	if rmovto.valor is null then
		rmovto.valor:= 0;
	end if;

	select sum(valor) as valor into rlancto from lancto l where l.mlid=$1 and  l.operacao != 'C';

	if rlancto.valor > rmovto.valor then
		return rlancto.valor-rmovto.valor;
	else
		return 0;
	end if;
end;
   
$_$;


ALTER FUNCTION public.venda_pagamento_dinheiro_f(bigint) OWNER TO postgres;

--
-- Name: venda_pagamento_dinheiro_f1(bigint, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venda_pagamento_dinheiro_f1(bigint, text[] DEFAULT ARRAY['C'::text]) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

declare
   	rlancto record;
   	rmovto  record;
begin
	select sum(m.valor) as valor into rmovto from movto m join motivo_movto mm on (m.motivo=mm.grid) where m.mlid=$1 and mm.forma_pgto;

	if rmovto.valor is null then
		rmovto.valor:= 0;
	end if;

	select sum(valor) as valor into rlancto from lancto l where l.mlid=$1 and l.operacao not in (select unnest($2));

	if rlancto.valor > rmovto.valor then
		return rlancto.valor-rmovto.valor;
	else
		return 0;
	end if;
end;
   
$_$;


ALTER FUNCTION public.venda_pagamento_dinheiro_f1(bigint, text[]) OWNER TO postgres;

--
-- Name: venda_troco_dinheiro_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.venda_troco_dinheiro_f(bigint) RETURNS double precision
    LANGUAGE plpgsql IMMUTABLE
    AS $_$

   declare 
     	rlancto record; 
   	rmovto record;
   	rtroco record;
begin
	select sum(m.valor) as valor into rmovto from movto m join motivo_movto mm on (m.motivo=mm.grid) where m.mlid=$1 and mm.forma_pgto;
	
	select sum(l.valor) as valor into rlancto from lancto l where l.mlid=$1;
	 
	if rlancto.valor < rmovto.valor then		
		select sum(m.valor) as valor into rtroco from movto m join motivo_movto mm on (m.motivo=mm.grid) where m.mlid=$1 and mm.troco;
		
		if rtroco.valor is null then
			rtroco.valor:=  0;
		end if;
		
		if (rmovto.valor-rlancto.valor) > rtroco.valor then
			return round((rmovto.valor - rlancto.valor - rtroco.valor)::numeric, 2)::double precision;
		else
			return 0;
		end if;
		
	else
		return 0;
		
	end if;
end;
   
$_$;


ALTER FUNCTION public.venda_troco_dinheiro_f(bigint) OWNER TO postgres;

--
-- Name: vendedor_principal_venda_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.vendedor_principal_venda_f(bigint) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
declare r record;
	ret text;
begin
	if (($1 is null) or ($1 = 0::bigint)) then
		return null;
	end if;

	SELECT INTO r pessoa_nome_f(l.vendedor) AS vendedor FROM lancto l where l.mlid=$1 and l.operacao = 'V' order by abs(l.valor) desc limit 1;

	if found then
		ret :=  r.vendedor;

		select into r count(*) from lancto where mlid=$1 and operacao = 'V';

		if r.count > 1 then
			ret := '+ ' || ret;
		end if;
	end if;

	return ret;
end
$_$;


ALTER FUNCTION public.vendedor_principal_venda_f(bigint) OWNER TO postgres;

--
-- Name: vendedor_venda_f(bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.vendedor_venda_f(bigint) RETURNS text
    LANGUAGE plpgsql
    AS $_$

  DECLARE 
    r RECORD;
    ret TEXT;

  BEGIN 
    IF (($1 IS NULL) OR ($1 = 0::bigint)) THEN 
        RETURN NULL;
    END IF;

    SELECT INTO r pessoa_nome_f(l.vendedor) AS vendedor FROM lancto l WHERE l.mlid=$1 AND l.operacao = 'V' ORDER BY abs(l.valor) DESC LIMIT 1;

    IF FOUND 
        THEN ret := r.vendedor;
    END IF;

    RETURN ret;
  END; 
$_$;


