--
-- Name: vincula_lancto_venda_composicao_f(date, date, bigint); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.vincula_lancto_venda_composicao_f(date, date, bigint) RETURNS void
    LANGUAGE plpgsql
    AS $_$

DECLARE
	r_lancto_venda RECORD;
	r_lancto_insumo RECORD;
	c1 REFCURSOR;
	c2 REFCURSOR;
	v_id_er_sr BIGINT;
	v_qtd_mp INT;

BEGIN
	ALTER TABLE lancto DISABLE TRIGGER pgd_update;

	RAISE NOTICE 'Inicio da execuÁ„o do script.';

	-- busca os lanctos de venda na data
	OPEN c1 FOR 
		SELECT l.grid, l.operacao, l.produto, l.mlid, l.empresa, l.seq FROM lancto l
			WHERE l.operacao in ('V') AND l.produto IN (SELECT DISTINCT produto FROM produto_composicao)
					AND l.data between $1 and $2 AND l.empresa = $3
					ORDER BY l.data, l.mlid, l.seq DESC;
	LOOP
		FETCH c1 INTO r_lancto_venda;
		EXIT WHEN NOT FOUND;

		RAISE NOTICE 'Processando lancto venda: %', r_lancto_venda.grid;

		-- pega o id novo de vinculo
		SELECT NEXTVAL('lancto_er_sr_seq') INTO v_id_er_sr;
		RAISE NOTICE 'Novo id_er_sr gerado: %', v_id_er_sr;

		-- conta quantas mp existem para aquele produto
		SELECT count(*) INTO v_qtd_mp FROM (
			SELECT MATERIA_PRIMA FROM PRODUTO_COMPOSICAO WHERE PRODUTO = r_lancto_venda.produto AND EMPRESA = r_lancto_venda.empresa
			UNION
			SELECT MATERIA_PRIMA FROM PRODUTO_COMPOSICAO WHERE PRODUTO = r_lancto_venda.produto AND EMPRESA IS NULL AND PRODUTO NOT IN 
				(SELECT PRODUTO FROM PRODUTO_COMPOSICAO WHERE EMPRESA = r_lancto_venda.empresa )) as T;

		RAISE NOTICE 'Quantidade de MP para o produto: %', v_qtd_mp;

		-- lanctos SR para cada MP +1 ER
		v_qtd_mp := v_qtd_mp + 1;

		-- busca os lanctos SR e ER da venda
		OPEN c2 FOR
			SELECT l.grid, l.operacao, l.produto, l.mlid, l.empresa FROM lancto l
				WHERE l.mlid = r_lancto_venda.mlid AND l.operacao in ('ER', 'SR', 'V') AND l.seq < r_lancto_venda.seq
				ORDER BY l.data, l.mlid, l.seq DESC LIMIT v_qtd_mp;
			LOOP
				FETCH c2 INTO r_lancto_insumo;
				EXIT WHEN NOT FOUND;

				-- tinha insumo opcional e n„o foi utilizado, ja chegou na proxima venda
				IF r_lancto_insumo.operacao = 'V' THEN
					EXIT;
				END IF;

				RAISE NOTICE 'Atualizando lancto insumo: %', r_lancto_insumo.grid;

				BEGIN

					UPDATE lancto SET id_er_sr = v_id_er_sr where grid = r_lancto_insumo.grid;
					RAISE NOTICE 'AtualizaÁ„o concluÌda para o grid: %', r_lancto_insumo.grid;

				EXCEPTION WHEN OTHERS THEN
					RAISE NOTICE 'Erro ao atualizar o lancto grid: % - %', r_lancto_insumo.grid, SQLERRM;
				END;

			END LOOP;
		CLOSE c2;

		UPDATE lancto SET id_er_sr = v_id_er_sr where grid = r_lancto_venda.grid;
		RAISE NOTICE 'AtualizaÁ„o concluÌda para o grid: %', r_lancto_venda.grid;

	END LOOP;
	CLOSE c1;

	ALTER TABLE lancto ENABLE TRIGGER pgd_update;
	RAISE NOTICE 'ExecuÁ„o do script concluÌda.';

EXCEPTION WHEN OTHERS THEN
	ALTER TABLE lancto ENABLE TRIGGER pgd_update;
	RAISE NOTICE 'Erro no processamento do lancto venda: % - %', r_lancto_venda.grid, SQLERRM;
END;

	
$_$;


