--
-- Name: abastecimento_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.abastecimento_view AS
 SELECT bico.nome AS bico,
    bico.tipo_preco,
    bico.deposito,
    deposito.produto,
    produto.nome AS nome_produto,
    produto.preco_unit,
    produto.preco_prazo,
    abastecimento.quantidade,
    bico_bomba.mecanica,
    abastecimento.codigo,
    abastecimento.valor,
    abastecimento.hora,
    bico_bomba.conta
   FROM public.abastecimento,
    public.bico_bomba,
    public.bico,
    public.deposito,
    public.produto
  WHERE ((abastecimento.bico = bico_bomba.bomba) AND (bico_bomba.bico = bico.nome) AND (bico.deposito = deposito.grid) AND (deposito.produto = produto.grid));


