--
-- Name: bairro_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bairro_view AS
 SELECT b.grid AS bairro_grid,
    b.codigo AS bairro_codigo,
    b.nome AS bairro_nome,
    m.nome AS municipio_nome,
    uf.sigla AS uf
   FROM ((((public.bairro b
     JOIN public.municipio m ON ((b.municipio = m.codigo)))
     JOIN public.micro_regiao mi ON ((m.micro_regiao = mi.codigo)))
     JOIN public.meso_regiao me ON ((mi.meso_regiao = me.codigo)))
     JOIN public.unidade_federativa uf ON ((me.uf = uf.codigo)));


