--
-- Name: empresa_local; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.empresa_local AS
 SELECT pl.pgd_sid AS sid,
    p.grid AS empresa,
    p.grid,
    p.codigo AS empresa_codigo,
    p.nome AS empresa_nome
   FROM public.pgd_lsite pl,
    public.pessoa p
  WHERE (p.grid = ( SELECT pgd_hosts.pessoa
           FROM public.pgd_hosts
          WHERE (pgd_hosts.sid = pl.pgd_sid)));


ALTER TABLE public.empresa_local OWNER TO postgres;

--
-- Name: bico_preco_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.bico_preco_view AS
 SELECT bb.bico,
    d.produto,
    p.nome AS produto_nome,
    bp.preco_unit
   FROM ((((public.bico_preco bp
     JOIN public.bico_bomba bb ON ((bp.bico = bb.bomba)))
     JOIN public.bico b ON ((bb.bico = b.nome)))
     JOIN public.deposito d ON ((b.deposito = d.grid)))
     JOIN public.produto p ON ((d.produto = p.grid)))
  WHERE (b.empresa = ( SELECT empresa_local.empresa
           FROM public.empresa_local))
  ORDER BY bb.bico;


