--
-- Name: cfop_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.cfop_view AS
 SELECT cfop.codigo,
    cfop.nome,
    cfop.tipo
   FROM public.cfop
  WHERE ((NOT (cfop.codigo IN ( SELECT cfop_config.cfop
           FROM public.cfop_config))) AND cfop.lancar)
UNION
 SELECT cc.cfop AS codigo,
    cc.nome,
    ( SELECT c.tipo
           FROM public.cfop c
          WHERE (c.codigo = cc.cfop)) AS tipo
   FROM public.cfop_config cc;


ALTER TABLE public.cfop_view OWNER TO postgres;

