--
-- Name: checkexpress_local; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.checkexpress_local AS
 SELECT cex.empresa,
    cex.codigo,
    cex.senha,
    cex.ip,
    cex.porta,
    cex.ppp_profile,
    cex.consulta_padrao,
    cex.grid
   FROM ((public.checkexpress cex
     JOIN public.pgd_hosts ph ON ((cex.empresa = ph.pessoa)))
     JOIN public.pgd_lsite pl ON ((ph.sid = pl.pgd_sid)));


