--
-- Name: comanda_empresa_config_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.comanda_empresa_config_view AS
 SELECT c.grid,
    COALESCE(c.empresa, e.grid) AS empresa,
    c.numero
   FROM (( SELECT pessoa.grid
           FROM public.pessoa
          WHERE (pessoa.tipo ~~ ('%%E%%'::bpchar)::text)) e
     LEFT JOIN public.comanda_empresa_config c ON ((e.grid = c.empresa)));


