CREATE TABLE public.conta (
    codigo text NOT NULL,
    pai text DEFAULT ''::text,
    nome text NOT NULL,
    saldo_inicial double precision DEFAULT 0,
    credor boolean DEFAULT false,
    lancar boolean DEFAULT false,
    pendencia boolean DEFAULT false,
    programacao boolean DEFAULT false,
    pesquisa_vencto boolean DEFAULT false,
    tipo_conta_receber boolean DEFAULT false,
    tipo_conta_pagar boolean DEFAULT false,
    tipo_despesa boolean DEFAULT false,
    controle_limite smallint DEFAULT 0,
    grid bigint NOT NULL,
    imprimir boolean DEFAULT false,
    livro_caixa boolean DEFAULT false,
    limite_credito_pessoa_fisica double precision,
    limite_credito_pessoa_juridica double precision,
    exibir_credito_venda boolean,
    conta_analitica text,
    impedir_saldo_negativo boolean DEFAULT false,
    tolerancia_saldo_negativo double precision DEFAULT 0.0,
    compensar_movto boolean DEFAULT false,
    codigo_reduzido bigint,
    validar_alinea boolean,
    aprovar_lancamento boolean DEFAULT false,
    controlar_saldo_limite boolean DEFAULT false,
    saldo_limite double precision DEFAULT 0,
    CONSTRAINT conta_codigo_not_empty CHECK (((codigo IS NOT NULL) AND (codigo <> ''::text))),
    CONSTRAINT conta_nome_not_empty CHECK (((nome IS NOT NULL) AND (nome <> ''::text)))
);


