--
-- Name: conta_saldo_v; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.conta_saldo_v AS
 SELECT conta_saldo_empresa.conta,
    conta_saldo_empresa.data,
    sum(conta_saldo_empresa.entrada) AS entrada,
    sum(conta_saldo_empresa.saida) AS saida,
    sum(conta_saldo_empresa.saldo) AS sum
   FROM public.conta_saldo_empresa
  GROUP BY conta_saldo_empresa.conta, conta_saldo_empresa.data;


