--
-- Name: cupom_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.cupom_view AS
 SELECT c.grid AS cupom,
    c.nr_cupom,
    c.data_emissao,
    c.nr_ecf,
    c.empresa,
    c.nr_serie,
    c.situacao AS cupom_sit,
    c.caixa_data,
    c.caixa_turno,
    c.caixa_conta,
    c.pessoa,
        CASE
            WHEN (cp.cst = '010'::text) THEN cp.valor
            ELSE (0)::double precision
        END AS base_subst,
        CASE
            WHEN (cp.cst = '000'::text) THEN cp.valor
            ELSE (0)::double precision
        END AS base_icms,
        CASE
            WHEN (cp.cst = '040'::text) THEN cp.valor
            ELSE (0)::double precision
        END AS base_isento,
        CASE
            WHEN (cp.cst <> ALL (ARRAY['000'::text, '040'::text])) THEN cp.valor
            ELSE (0)::double precision
        END AS base_outras,
    cp.aliquota,
    cp.valor AS produto_valor,
    cp.valor_desconto AS produto_desconto,
    cp.produto,
    cp.codigo AS produto_codigo,
    cp.descricao AS produto_nome,
    cp.quantidade AS produto_quantidade,
    cp.preco_unit,
    cp.nr_item,
    cp.situacao AS produto_situacao,
    cp.tributacao,
    ct.valor_cupom,
    ct.valor_desconto,
    ct.movto,
    ct.mlid,
    p.nome AS pessoa_nome,
    p.codigo AS pessoa_codigo,
    p.estado AS pessoa_estado,
        CASE
            WHEN ((p.estado = e.estado) OR (p.estado IS NULL)) THEN COALESCE(pr.cfop_dentro, enf.cfop_dentro_estado)
            ELSE COALESCE(pr.cfop_fora, enf.cfop_fora_estado)
        END AS cfop
   FROM ((((((public.cupom c
     JOIN public.cupom_produto cp ON ((c.grid = cp.cupom)))
     JOIN public.cupom_total ct ON ((c.grid = ct.cupom)))
     JOIN public.produto pr ON ((pr.grid = cp.produto)))
     JOIN public.pessoa e ON ((e.grid = c.empresa)))
     JOIN public.empresa_nota_fiscal enf ON ((e.grid = enf.empresa)))
     LEFT JOIN public.pessoa p ON ((p.grid = c.pessoa)));


ALTER TABLE public.cupom_view OWNER TO postgres;

