--
-- Name: deposito_procura_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.deposito_procura_view AS
 SELECT d.grid,
    d.codigo,
    d.nome,
    p.nome_reduzido AS empresa_nome,
    d.flag,
    d.empresa,
    d.produto
   FROM (public.deposito d
