--

CREATE TABLE public.exc_ag_totalizador (
    empresa bigint NOT NULL,
    data date NOT NULL,
    total_movto_enviado integer NOT NULL,
    total_movto_transmitir integer NOT NULL,
    total_movto_erro integer NOT NULL,
    total_valor double precision NOT NULL
);


ALTER TABLE public.exc_ag_totalizador OWNER TO postgres;

--
-- Name: exc_ag_totalizador_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.exc_ag_totalizador_view AS
 SELECT exc_ag_pendencia.empresa,
    exc_ag_pendencia.data_movto AS data,
    sum(
        CASE
            WHEN (exc_ag_pendencia.status = 2) THEN 1
            ELSE 0
        END) AS total_movto_enviado,
    sum(
        CASE
            WHEN (exc_ag_pendencia.status = ANY (ARRAY[1, 3])) THEN 1
            ELSE 0
        END) AS total_movto_transmitir,
    sum(
        CASE
            WHEN (exc_ag_pendencia.status = ANY (ARRAY[4, 5])) THEN 1
            ELSE 0
        END) AS total_movto_erro,
    sum(
        CASE
            WHEN (exc_ag_pendencia.status = 2) THEN COALESCE(exc_ag_pendencia.valor, (0.0)::double precision)
            ELSE (0.0)::double precision
        END) AS total_valor
   FROM public.exc_ag_pendencia
  GROUP BY exc_ag_pendencia.empresa, exc_ag_pendencia.data_movto
  ORDER BY exc_ag_pendencia.data_movto;


ALTER TABLE public.exc_ag_totalizador_view OWNER TO postgres;

