--
-- Name: exc_br_promocao_vigente_abrangencia_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.exc_br_promocao_vigente_abrangencia_view AS
 SELECT ebr.grid
   FROM ((public.exc_brpremmia_promocao ebp
     JOIN public.exc_brpremmia_regra ebr ON ((ebr.promocao = ebp.grid)))
     JOIN public.exc_brpremmia_abrangencia eba ON ((eba.promocao = ebp.grid)))
  WHERE ((NOT COALESCE(ebp.inativo, false)) AND ((ebr.vigencia_fim >= CURRENT_DATE) OR (ebr.vigencia_fim IS NULL)) AND (NOT COALESCE(ebp.excluido, false)) AND ((eba.uf_codigo = ( SELECT u.codigo
           FROM public.unidade_federativa u
          WHERE (u.sigla = ( SELECT p.uf
                   FROM public.pessoa p
                  WHERE ((p.tipo ~~ ('%%E%%'::bpchar)::text) AND (p.grid = ( SELECT empresa_local.empresa
                           FROM public.empresa_local))))))) OR (eba.uf_codigo IS NULL)));


ALTER TABLE public.exc_br_promocao_vigente_abrangencia_view OWNER TO postgres;

