--
-- Name: exc_br_send_venda_produto_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.exc_br_send_venda_produto_view AS
 SELECT p.grid,
    nf.grid AS grid_venda,
    nf.mlid AS mlid_venda,
    nfp.grid AS grid_nota_fiscal_produto,
    brpremmia_resgate.codigo_ftc_premmia,
    COALESCE(brpremmia_resgate.valor_ftc_premmia, (0.0)::double precision) AS valor_ftc_premmia,
    COALESCE((brpremmia_resgate.qtde_pontos_premmia)::numeric, 0.0) AS qtde_pontos_premmia,
    p.nome AS produto_nome,
    false AS is_ecf,
        CASE
            WHEN (venda_sugestao_promo.transacao IS NOT NULL) THEN 'S'::text
            ELSE 'N'::text
        END AS indicador_promo_linx,
        CASE
            WHEN (venda_sugestao_promo.transacao IS NOT NULL) THEN venda_sugestao_promo.transacao
            ELSE ''::text
        END AS numero_transacao_promo_linx,
        CASE
            WHEN (p.tipo = 'C'::bpchar) THEN 'P'::text
            WHEN (COALESCE(produto_br.setor, ebic.setor) = 3) THEN 'P'::text
            WHEN (COALESCE(produto_br.setor, ebic.setor) = 4) THEN 'X'::text
            ELSE 'L'::text
        END AS setor,
    'N'::text AS situacao,
        CASE
            WHEN ((COALESCE(pe.custo_medio, (0)::double precision) <> (0)::double precision) AND (pe.empresa = nf.empresa)) THEN pe.custo_medio
            WHEN (COALESCE(p.preco_prazo, (0)::double precision) <> (0)::double precision) THEN p.preco_prazo
            ELSE COALESCE(p.preco_custo, (0)::double precision)
        END AS preco_medio,
    '0'::text AS ordem_servico,
        CASE
            WHEN (venda_sugestao_promo.transacao IS NOT NULL) THEN '2'::text
            WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN '2'::text
            WHEN (ebpromresg.codigo_ftc_premmia IS NOT NULL) THEN '1'::text
            ELSE ''::text
        END AS tipo_promocao,
        CASE
            WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN ebprom.codigo
            WHEN (ebpromresg.codigo_ftc_premmia IS NOT NULL) THEN ebpromresg.codigo_premmia
            ELSE '0'::bigint
        END AS codigo_promocao,
    l.produto_kit_id,
    COALESCE(nfp.valor_iss, (0.0)::double precision) AS valor_iss,
    COALESCE(nfp.valor_icms, (0.0)::double precision) AS valor_icms,
    p.codigo_barra,
    p.codigo,
    COALESCE(nfp.quantidade, (0.0)::double precision) AS quantidade,
    COALESCE(nfp.preco_unit, (0.0)::double precision) AS preco_unit,
    nf.data_emissao,
    COALESCE(nfp.valor_desconto, (0.0)::double precision) AS valor_desconto,
    COALESCE(nfp.valor_acrescimo, (0.0)::double precision) AS valor_acrescimo,
    COALESCE(nfp.valor_ibs_uf, (0.0)::double precision) AS valor_ibs_uf,
    COALESCE(nfp.valor_ibs_mun, (0.0)::double precision) AS valor_ibs_mun,
    COALESCE(nfp.valor_cbs, (0.0)::double precision) AS valor_cbs,
    COALESCE(nfp.codigo_ncm, ''::text) AS codigo_ncm,
    COALESCE(nfp.codigo_anp, ''::text) AS codigo_anp,
    COALESCE(nfp.descricao, ''::text) AS descricao_produto_venda,
    COALESCE(ebprt.transaction_id, ''::text) AS id_premmia,
        CASE
            WHEN ((pj.produto_json ->> 'type'::text) = '0'::text) THEN 'NORMAL'::text
            WHEN ((pj.produto_json ->> 'type'::text) = '1'::text) THEN 'BENEFIT'::text
            WHEN ((pj.produto_json ->> 'type'::text) = '2'::text) THEN 'REDEEM'::text
            ELSE ''::text
        END AS tipo_transacao,
    (pj.produto_json ->> 'idEan'::text) AS codigo_transacao,
    nfp.numero_item AS seq,
        CASE
            WHEN (venda_sugestao_promo.transacao IS NOT NULL) THEN venda_sugestao_promo.codigo
            WHEN (
            CASE
                WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN '2'::text
                WHEN (ebpromresg.codigo_barra_kit_resgate IS NOT NULL) THEN ebpromresg.codigo_barra_kit_resgate
                ELSE '1'::text
            END = '1'::text) THEN ''::text
            ELSE
            CASE
                WHEN (venda_sugestao_promo.transacao IS NOT NULL) THEN venda_sugestao_promo.codigo
                WHEN (ebpromresg.codigo_barra_kit_resgate IS NOT NULL) THEN ebpromresg.codigo_barra_kit_resgate
                ELSE produto_br_kit.codigo_barra
            END
        END AS kit_codigo,
    pkm.quantidade AS quantidade_item,
    pkm.parent AS kit_etapa_ref,
    COALESCE(nfp.preco_unit, (0.0)::double precision) AS preco_unit_produto,
    COALESCE((nfp.preco_unit * nfp.quantidade), (0.0)::double precision) AS valor_bruto,
    COALESCE(((nfp.valor - nfp.valor_desconto) + nfp.valor_acrescimo), (0.0)::double precision) AS valor_liquido,
    public.produto_estoque_f(nfp.empresa, l.deposito, nfp.produto, nf.data_emissao) AS qtde_estoque,
        CASE
            WHEN (ebic.produto IS NOT NULL) THEN
            CASE
                WHEN (p.codigo <> ''::text) THEN (public.somente_numero_f(p.codigo))::bigint
                ELSE (0)::bigint
            END
            ELSE (produto_br.codigo)::bigint
        END AS codigo_distribuidora,
        CASE
            WHEN (length(produto_br.codigo_barra) > 0) THEN produto_br.codigo_barra
            WHEN ((length(p.codigo_barra) > 0) AND (ebic.produto IS NOT NULL) AND (length(nfp.codigo_barra) = 13) AND ("substring"(nfp.codigo_barra, 1, 1) <> (2)::text)) THEN nfp.codigo_barra
            WHEN (ebic.produto IS NOT NULL) THEN p.codigo
            WHEN ((length(nfp.codigo) > 0) AND (nfp.codigo <> p.codigo)) THEN nfp.codigo
            ELSE p.codigo
        END AS produto_codigo,
    produto_br.nome AS nome_distribuidora,
    produto_br.nome_resumido AS nome_resumido_distribuidora,
    produto_br.estrutura_merc AS estrutura_merc_distribuidora,
    produto_br.unid_med AS unid_med_distribuidora,
    venda_sugestao_promo.codigo AS codigo_promo,
    venda_sugestao_promo.descricao AS descricao_promo
   FROM (((((((((((((((public.nota_fiscal nf
     JOIN public.nota_fiscal_produto nfp ON ((nfp.nota_fiscal = nf.grid)))
     JOIN public.produto p ON ((p.grid = nfp.produto)))
     LEFT JOIN public.produto_empresa pe ON (((pe.produto = p.grid) AND (pe.empresa = nf.empresa))))
     JOIN public.lancto l ON ((l.grid = nfp.lancto)))
     LEFT JOIN public.produto_kit_map pkm ON (((pkm.kit = (l.produto_kit)::text) AND (pkm.produto = l.produto))))
     LEFT JOIN public.exc_brpremmia_resgate_transacao ebprt ON ((ebprt.mlid = nf.mlid)))
     LEFT JOIN LATERAL jsonb_array_elements(((ebprt.produtos_json)::jsonb -> 'produtos'::text)) pj(produto_json) ON ((((pj.produto_json ->> 'idEan'::text) = p.codigo_barra) OR ((pj.produto_json ->> 'idEan'::text) = nfp.codigo_barra) OR (EXISTS ( SELECT 1
           FROM public.produto_codigo_barra pcb
          WHERE ((pcb.produto = p.grid) AND (pcb.codigo_barra = (pj.produto_json ->> 'idEan'::text))))) OR (EXISTS ( SELECT 1
           FROM (public.produto_distribuidora pd
             JOIN public.exc_br_produto ebp ON ((ebp.grid = pd.produto_dist)))
          WHERE ((pd.produto = p.grid) AND (pd.distribuidora = 4) AND (ebp.codigo IS NOT NULL) AND (ebp.codigo_barra = (pj.produto_json ->> 'idEan'::text))))))))
     LEFT JOIN ( SELECT cvsp.mlid,
            cvsp.codigo,
            ept.transacao,
            cvsp.produto,
            cvsp.descricao
           FROM (public.caixa_venda_sugestao_promo cvsp
             JOIN public.exc_promo_ticket ept ON (((ept.mlid = cvsp.mlid) AND (ept.transacao IS NOT NULL) AND (cvsp.codigo IS NOT NULL))))
          WHERE (cvsp.aplicado OR (EXISTS ( SELECT true AS bool
                   FROM (public.caixa_venda_sugestao_promo cvsp_aux
                     JOIN public.exc_promo_ticket ept_aux ON (((ept_aux.mlid = cvsp_aux.mlid) AND (cvsp_aux.mlid = cvsp.mlid) AND (cvsp.codigo = cvsp_aux.codigo) AND (ept_aux.transacao IS NOT NULL) AND (cvsp_aux.produto = cvsp.produto) AND (NOT cvsp_aux.aplicado) AND (cvsp_aux.codigo IS NOT NULL) AND (EXISTS ( SELECT true AS bool
                           FROM public.caixa_venda_sugestao_promo cvsp_aux1
                          WHERE ((cvsp_aux1.mlid = cvsp_aux.mlid) AND (cvsp_aux1.codigo = cvsp_aux.codigo) AND cvsp_aux1.aplicado)))))))))) venda_sugestao_promo ON (((venda_sugestao_promo.mlid = nf.mlid) AND (venda_sugestao_promo.produto = nfp.produto) AND (EXISTS ( SELECT 1
           FROM public.exc_promo_config epc
          WHERE ((epc.company_id = 'brmania'::text) AND (epc.empresa = nf.empresa)))) AND (EXISTS ( SELECT true AS bool
           FROM public.lancto_desconto ld
          WHERE ((ld.lancto = nfp.lancto) AND (COALESCE(ld.desconto_item_promo, (0)::double precision) <> (0)::double precision) AND ld.desconto_auto))))))
     LEFT JOIN ( SELECT ebp.setor,
            ebp.codigo,
            ebp.codigo_barra,
            pd.produto,
            pd.distribuidora,
            ebp.nome,
            ebp.nome_resumido,
            ebp.estrutura_merc,
            ebp.unid_med
           FROM (public.produto_distribuidora pd
             JOIN public.exc_br_produto ebp ON (((ebp.grid = pd.produto_dist) AND (ebp.codigo IS NOT NULL) AND (pd.distribuidora = 4))))) produto_br ON (((produto_br.produto = p.grid) AND (produto_br.codigo_barra =
        CASE
            WHEN ((nfp.codigo_barra = p.codigo) OR (nfp.codigo_barra = p.codigo_barra) OR ((EXISTS ( SELECT true AS bool
               FROM public.produto_codigo_barra x
              WHERE ((x.produto = p.grid) AND (x.codigo_barra = nfp.codigo_barra)))) AND (((EXISTS ( SELECT count(*) AS count
               FROM (public.produto_distribuidora pdx
                 JOIN public.exc_br_produto ebpx ON (((ebpx.grid = pdx.produto_dist) AND (ebpx.codigo IS NOT NULL) AND (pdx.produto = p.grid) AND (pdx.distribuidora = 4)))))))::integer > 0))) THEN ( SELECT ebpx.codigo_barra
               FROM (public.produto_distribuidora pdx
                 JOIN public.exc_br_produto ebpx ON (((ebpx.grid = pdx.produto_dist) AND (ebpx.codigo IS NOT NULL) AND (pdx.produto = p.grid) AND (pdx.distribuidora = 4) AND
                    CASE
                        WHEN (EXISTS ( SELECT true AS bool
                           FROM (public.caixa_venda_sugestao_promo cvsp
                             JOIN public.exc_promo_ticket ept ON (((ept.mlid = cvsp.mlid) AND (ept.transacao IS NOT NULL) AND (nf.mlid = cvsp.mlid) AND (cvsp.produto = p.grid) AND cvsp.aplicado AND (cvsp.codigo IS NOT NULL) AND (EXISTS ( SELECT 1
                                   FROM public.exc_promo_config epc
                                  WHERE ((epc.company_id = 'brmania'::text) AND (epc.empresa = nf.empresa))))))))) THEN (nfp.codigo_barra = ebpx.codigo_barra)
                        WHEN (EXISTS ( SELECT true AS bool
                           FROM (public.caixa_venda_sugestao_promo cvsp
                             JOIN public.exc_promo_ticket ept ON (((ept.mlid = cvsp.mlid) AND (ept.transacao IS NOT NULL) AND (nf.mlid = cvsp.mlid) AND (cvsp.produto = p.grid) AND (NOT cvsp.aplicado) AND (cvsp.codigo IS NOT NULL) AND (EXISTS ( SELECT true AS bool
                                   FROM public.caixa_venda_sugestao_promo cvsp_aux
                                  WHERE ((cvsp_aux.mlid = cvsp.mlid) AND (cvsp_aux.codigo = cvsp.codigo) AND cvsp_aux.aplicado))) AND (EXISTS ( SELECT 1
                                   FROM public.exc_promo_config epc
                                  WHERE ((epc.company_id = 'brmania'::text) AND (epc.empresa = nf.empresa))))))))) THEN (nfp.codigo_barra = ebpx.codigo_barra)
                        WHEN (EXISTS ( SELECT true AS bool
                           FROM (public.produto_distribuidora pdxx
                             JOIN public.exc_br_produto ebpxx ON (((ebpxx.grid = pdxx.produto_dist) AND (ebpxx.codigo IS NOT NULL) AND (pdxx.produto = p.grid) AND (pdxx.distribuidora = 4) AND (nfp.codigo_barra = ebpxx.codigo_barra)))))) THEN (nfp.codigo_barra = ebpx.codigo_barra)
                        ELSE true
                    END)))
             LIMIT 1)
            WHEN ((nfp.codigo = p.codigo) AND (length(nfp.codigo_barra) = 13) AND ("substring"(nfp.codigo_barra, 1, 1) = (2)::text) AND (((EXISTS ( SELECT count(*) AS count
               FROM (public.produto_distribuidora pdx
                 JOIN public.exc_br_produto ebpx ON (((ebpx.grid = pdx.produto_dist) AND (ebpx.codigo IS NOT NULL) AND (pdx.produto = p.grid) AND (pdx.distribuidora = 4)))))))::integer > 0)) THEN ( SELECT ebpx.codigo_barra
               FROM (public.produto_distribuidora pdx
                 JOIN public.exc_br_produto ebpx ON (((ebpx.grid = pdx.produto_dist) AND (ebpx.codigo IS NOT NULL) AND (pdx.produto = p.grid) AND (pdx.distribuidora = 4))))
             LIMIT 1)
            ELSE nfp.codigo_barra
        END))))
     LEFT JOIN ( SELECT ebpk.setor,
            ebpk.codigo,
            ebpk.codigo_barra,
            pdk.produto,
            pdk.distribuidora
           FROM (public.produto_distribuidora pdk
             JOIN public.exc_br_produto ebpk ON (((ebpk.grid = pdk.produto_dist) AND (ebpk.codigo IS NOT NULL) AND (pdk.distribuidora = 4))))) produto_br_kit ON ((produto_br_kit.produto = l.produto_kit)))
     LEFT JOIN public.exc_br_inclusao_cadastro ebic ON (((ebic.produto = p.grid) AND (ebic.empresa = nf.empresa))))
     LEFT JOIN public.unidade_federativa uf ON ((nf.estado = uf.sigla)))
     LEFT JOIN ( SELECT ebpr.numero,
            ebpr.codigo,
            ebpr.codigo_ftc,
            eba.uf_codigo,
            ''::text AS codigo_barra_kit_resgate
           FROM (public.exc_brpremmia_promocao ebpr
             JOIN public.exc_brpremmia_abrangencia eba ON ((ebpr.grid = eba.promocao)))) ebprom ON ((((ebprom.numero)::text = ( SELECT p1.codigo_barra
           FROM public.produto p1
          WHERE (p1.grid = l.produto_kit))) AND ((ebprom.uf_codigo = uf.codigo) OR (ebprom.uf_codigo IS NULL)))))
     LEFT JOIN ( SELECT ebpr.numero AS numero_premmia,
            ebpr.codigo AS codigo_premmia,
            ebpr.codigo_ftc AS codigo_ftc_premmia,
            eba.uf_codigo AS uf_codigo_premmia,
            ( SELECT ebpp.codigo_barra
                   FROM public.exc_brpremmia_produto ebpp
                  WHERE (ebpr.grid = ebpp.promocao)
                 LIMIT 1) AS codigo_barra_kit_resgate
           FROM (public.exc_brpremmia_promocao ebpr
             JOIN public.exc_brpremmia_abrangencia eba ON ((ebpr.grid = eba.promocao)))) ebpromresg ON (((ebpromresg.codigo_ftc_premmia = ( SELECT DISTINCT ebptransacao.codigo_produto
           FROM ((((public.produto_distribuidora pd
             JOIN public.exc_br_produto ebp ON (((pd.distribuidora = 4) AND (pd.produto_dist = ebp.grid) AND (nfp.produto = pd.produto))))
             JOIN public.exc_brpremmia_produto ebpp ON ((ebpp.codigo_barra = ebp.codigo_barra)))
             JOIN public.exc_brpremmia_promocao ebppromo ON ((ebppromo.grid = ebpp.promocao)))
             JOIN public.exc_brpremmia_transacao ebptransacao ON (((ebptransacao.codigo_produto = ebppromo.codigo_ftc) AND (ebptransacao.mlid = nf.mlid))))
        UNION ALL
         SELECT DISTINCT ebptransacao.codigo_produto
           FROM ((((((public.produto p_1
             JOIN public.produto_kit_map pkm_1 ON (((pkm_1.kit = (p_1.grid)::text) AND (p_1.tipo = 'K'::bpchar) AND (pkm_1.produto = nfp.produto))))
             JOIN public.produto_distribuidora pd ON ((pkm_1.kit = (pd.produto)::text)))
             JOIN public.exc_br_produto ebp ON (((pd.distribuidora = 4) AND (pd.produto_dist = ebp.grid))))
             JOIN public.exc_brpremmia_produto ebpp ON ((ebpp.codigo_barra = ebp.codigo_barra)))
             JOIN public.exc_brpremmia_promocao ebppromo ON ((ebppromo.grid = ebpp.promocao)))
             JOIN public.exc_brpremmia_transacao ebptransacao ON (((ebptransacao.codigo_produto = ebppromo.codigo_ftc) AND (nf.mlid = ebptransacao.mlid))))
 LIMIT 1)) AND (((ebpromresg.uf_codigo_premmia)::text = (uf.codigo)::text) OR (ebpromresg.uf_codigo_premmia IS NULL)))))
     LEFT JOIN LATERAL ( SELECT ebt.mlid,
            ebt.codigo_produto AS codigo_ftc_premmia,
            ebt.valor AS valor_ftc_premmia,
            ebpr.qtde_pontos AS qtde_pontos_premmia
           FROM (public.exc_brpremmia_transacao ebt
             LEFT JOIN public.exc_brpremmia_produto_resgate ebpr ON ((ebpr.codigo_ftc = ebt.codigo_produto)))
          WHERE ((ebt.operacao = 'efetivaResgateProduto'::text) AND (ebt.mlid = nf.mlid))) brpremmia_resgate ON ((brpremmia_resgate.mlid = nf.mlid)))
  WHERE (p.tipo = ANY (ARRAY['C'::bpchar, 'M'::bpchar, 'K'::bpchar]))
UNION
 SELECT p.grid,
    c.grid AS grid_venda,
    ct.mlid AS mlid_venda,
    NULL::bigint AS grid_nota_fiscal_produto,
    NULL::text AS codigo_ftc_premmia,
    NULL::double precision AS valor_ftc_premmia,
    NULL::numeric AS qtde_pontos_premmia,
    p.nome AS produto_nome,
    true AS is_ecf,
    'N'::text AS indicador_promo_linx,
    ''::text AS numero_transacao_promo_linx,
        CASE
            WHEN (p.tipo = 'C'::bpchar) THEN 'P'::text
            WHEN (COALESCE(produto_br.setor, ebic.setor) = 3) THEN 'P'::text
            WHEN (COALESCE(produto_br.setor, ebic.setor) = 4) THEN 'X'::text
            ELSE 'L'::text
        END AS setor,
    'N'::text AS situacao,
        CASE
            WHEN ((COALESCE(pe.custo_medio, (0)::double precision) <> (0)::double precision) AND (pe.empresa = c.empresa)) THEN pe.custo_medio
            WHEN (COALESCE(p.preco_prazo, (0)::double precision) <> (0)::double precision) THEN p.preco_prazo
            ELSE COALESCE(p.preco_custo, (0)::double precision)
        END AS preco_medio,
    '0'::text AS ordem_servico,
        CASE
            WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN '2'::text
            WHEN (ebpromresg.codigo_ftc_premmia IS NOT NULL) THEN '1'::text
            ELSE ''::text
        END AS tipo_promocao,
        CASE
            WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN ebprom.codigo
            WHEN (ebpromresg.codigo_ftc_premmia IS NOT NULL) THEN ebpromresg.codigo_premmia
            ELSE '0'::bigint
        END AS codigo_promocao,
    l.produto_kit_id,
    0.0 AS valor_iss,
    0.0 AS valor_icms,
    p.codigo_barra,
    p.codigo,
    COALESCE(cp.quantidade, (0.0)::double precision) AS quantidade,
    COALESCE(cp.preco_unit, (0.0)::double precision) AS preco_unit,
    c.data_emissao,
        CASE
            WHEN (cp.valor_desconto > (0)::double precision) THEN cp.valor_desconto
            ELSE (0.0)::double precision
        END AS valor_desconto,
        CASE
            WHEN (cp.valor_desconto < (0)::double precision) THEN COALESCE((cp.valor_desconto * ('-1'::integer)::double precision), (0.0)::double precision)
            ELSE (0.0)::double precision
        END AS valor_acrescimo,
    0.0 AS valor_ibs_uf,
    0.0 AS valor_ibs_mun,
    0.0 AS valor_cbs,
    ''::text AS codigo_ncm,
    ''::text AS codigo_anp,
    cp.descricao AS descricao_produto_venda,
    ''::text AS id_premmia,
    ''::text AS tipo_transacao,
    ''::text AS codigo_transacao,
    cp.nr_item AS seq,
        CASE
            WHEN (
            CASE
                WHEN ((ebprom.codigo IS NOT NULL) AND (ebprom.codigo_ftc IS NULL)) THEN '2'::text
                ELSE '1'::text
            END = '1'::text) THEN ''::text
            ELSE produto_br_kit.codigo_barra
        END AS kit_codigo,
    COALESCE(pkm.quantidade, (0.0)::double precision) AS quantidade_item,
    pkm.parent AS kit_etapa_ref,
    COALESCE(cp.preco_unit, (0.0)::double precision) AS preco_unit_produto,
    COALESCE((cp.preco_unit * cp.quantidade), (0.0)::double precision) AS valor_bruto,
    COALESCE(cp.valor, (0.0)::double precision) AS valor_liquido,
    public.produto_estoque_f(c.empresa, l.deposito, cp.produto, c.data_emissao) AS qtde_estoque,
        CASE
            WHEN (ebic.produto IS NOT NULL) THEN
            CASE
                WHEN (p.codigo <> ''::text) THEN (public.somente_numero_f(p.codigo))::bigint
                ELSE (0)::bigint
            END
            ELSE (produto_br.codigo)::bigint
        END AS codigo_distribuidora,
        CASE
            WHEN ((length(cp.codigo) > 0) AND (cp.codigo <> p.codigo)) THEN cp.codigo
            WHEN (length(produto_br.codigo_barra) > 0) THEN produto_br.codigo_barra
            WHEN ((length(p.codigo_barra) > 0) AND (ebic.produto IS NOT NULL)) THEN p.codigo_barra
            ELSE p.codigo
        END AS produto_codigo,
    produto_br.nome AS nome_distribuidora,
    produto_br.nome_resumido AS nome_resumido_distribuidora,
    produto_br.estrutura_merc AS estrutura_merc_distribuidora,
    produto_br.unid_med AS unid_med_distribuidora,
    ''::text AS codigo_promo,
    ''::text AS descricao_promo
   FROM (((((((((((((public.cupom_total ct
     JOIN public.cupom c ON ((c.grid = ct.cupom)))
     JOIN public.cupom_produto cp ON ((cp.cupom = c.grid)))
     JOIN public.produto p ON ((p.grid = cp.produto)))
     LEFT JOIN public.produto_empresa pe ON (((pe.produto = p.grid) AND (pe.empresa = c.empresa))))
     JOIN public.lancto l ON ((l.cupom_produto = cp.grid)))
     LEFT JOIN public.produto_kit_map pkm ON (((pkm.kit = (l.produto_kit)::text) AND (pkm.produto = l.produto))))
     LEFT JOIN ( SELECT ebp.setor,
            ebp.codigo,
            ebp.codigo_barra,
            pd.produto,
            pd.distribuidora,
            ebp.nome,
            ebp.nome_resumido,
            ebp.estrutura_merc,
            ebp.unid_med
           FROM (public.produto_distribuidora pd
             JOIN public.exc_br_produto ebp ON (((ebp.grid = pd.produto_dist) AND (ebp.codigo IS NOT NULL))))) produto_br ON (((produto_br.produto = p.grid) AND (produto_br.distribuidora = 4))))
     LEFT JOIN ( SELECT ebpk.setor,
            ebpk.codigo,
            ebpk.codigo_barra,
            pdk.produto,
            pdk.distribuidora
           FROM (public.produto_distribuidora pdk
             JOIN public.exc_br_produto ebpk ON (((ebpk.grid = pdk.produto_dist) AND (ebpk.codigo IS NOT NULL))))) produto_br_kit ON (((produto_br_kit.produto = l.produto_kit) AND (produto_br_kit.distribuidora = 4))))
     LEFT JOIN public.exc_br_inclusao_cadastro ebic ON (((ebic.produto = p.grid) AND (ebic.empresa = c.empresa))))
     LEFT JOIN public.pessoa e ON ((e.grid = c.empresa)))
     LEFT JOIN public.unidade_federativa uf ON ((e.uf = uf.sigla)))
     LEFT JOIN ( SELECT ebpr.numero,
            ebpr.codigo,
            ebpr.codigo_ftc,
            eba.uf_codigo
           FROM (public.exc_brpremmia_promocao ebpr
             JOIN public.exc_brpremmia_abrangencia eba ON ((ebpr.grid = eba.promocao)))) ebprom ON ((((ebprom.numero)::text = ( SELECT p1.codigo_barra
           FROM public.produto p1
          WHERE (p1.grid = l.produto_kit))) AND ((ebprom.uf_codigo = uf.codigo) OR (ebprom.uf_codigo IS NULL)))))
     LEFT JOIN ( SELECT ebpr.numero AS numero_premmia,
            ebpr.codigo AS codigo_premmia,
            ebpr.codigo_ftc AS codigo_ftc_premmia,
            eba.uf_codigo AS uf_codigo_premmia
           FROM (public.exc_brpremmia_promocao ebpr
             JOIN public.exc_brpremmia_abrangencia eba ON ((ebpr.grid = eba.promocao)))) ebpromresg ON (((ebpromresg.codigo_ftc_premmia = ( SELECT ebpt.codigo_produto
           FROM public.exc_brpremmia_transacao ebpt
          WHERE (ebpt.mlid = ct.mlid)
         LIMIT 1)) AND (((ebpromresg.uf_codigo_premmia)::text = (uf.codigo)::text) OR (ebpromresg.uf_codigo_premmia IS NULL)))))
  WHERE ((cp.situacao = 'E'::text) AND (cp.tipo_item = ANY (ARRAY['C'::text, 'M'::text])) AND (p.tipo = ANY (ARRAY['C'::bpchar, 'M'::bpchar, 'K'::bpchar])));


