--
-- Name: exc_br_send_venda_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.exc_br_send_venda_view AS
 SELECT tb.grid,
    tb.mlid,
    tb.movto,
    tb.nr_ecf,
    tb.empresa,
    tb.motivo,
    tb.modelo_doc,
    tb.versao_autosystem,
    tb.cpf_premmia,
    tb.chave_acesso,
    tb.data_emissao,
    tb.documento,
    tb.data_venda,
    tb.valor_liquido,
    tb.valor_bruto,
    tb.cpf,
    tb.cnpj,
    tb.valor_desconto,
    tb.valor_acrescimo,
    tb.tipo_doc,
    tb.valor_desconto_itens,
    tb.valor_acrescimo_itens,
    tb.canal_venda,
    tb.email_cliente,
    tb.celular_cliente,
    tb.is_resgate_premmia,
    tb.id_premmia
   FROM ( SELECT nf.grid,
            nf.mlid,
            m.grid AS movto,
            NULL::integer AS nr_ecf,
            nf.empresa,
            m.motivo,
            nf.modelo_doc,
            COALESCE(nf.versao_autosystem, ''::text) AS versao_autosystem,
            public.somente_numero_f(COALESCE(ebprt.cpf, ''::text)) AS cpf_premmia,
                CASE
                    WHEN (((nf.modelo)::character varying)::text = '65'::text) THEN (nfe.chave_acesso)::character varying
                    WHEN (((nf.modelo)::character varying)::text = '55'::text) THEN (nfe.chave_acesso)::character varying
                    WHEN (((nf.modelo)::character varying)::text = '59'::text) THEN (cfe.chave_acesso)::character varying
                    ELSE NULL::character varying
                END AS chave_acesso,
            nf.data_emissao,
            nf.numero_nota AS documento,
            nf.hora_saida AS data_venda,
            nf.valor_nota AS valor_liquido,
            nf.total_produto AS valor_bruto,
            public.somente_numero_f(nf.cpf) AS cpf,
            public.somente_numero_f(e.cpf) AS cnpj,
                CASE
                    WHEN ((COALESCE(trunc((nf.valor_desconto)::numeric, 2), 0.0) - ( SELECT COALESCE(sum(trunc((nfp.valor_desconto)::numeric, 2)), 0.0) AS "coalesce"
                       FROM public.nota_fiscal_produto nfp
                      WHERE (nfp.nota_fiscal = nf.grid))) < (0)::numeric) THEN (0)::numeric
                    ELSE (COALESCE(trunc((nf.valor_desconto)::numeric, 2), 0.0) - ( SELECT COALESCE(sum(round((nfp.valor_desconto)::numeric, 2)), 0.0) AS "coalesce"
                       FROM public.nota_fiscal_produto nfp
                      WHERE (nfp.nota_fiscal = nf.grid)))
                END AS valor_desconto,
                CASE
                    WHEN ((COALESCE(trunc((nf.valor_acrescimo)::numeric, 2), 0.0) - ( SELECT COALESCE(sum(trunc((nfp.valor_acrescimo)::numeric, 2)), 0.0) AS "coalesce"
                       FROM public.nota_fiscal_produto nfp
                      WHERE (nfp.nota_fiscal = nf.grid))) < (0)::numeric) THEN (0)::numeric
                    ELSE (COALESCE(trunc((nf.valor_acrescimo)::numeric, 2), 0.0) - ( SELECT COALESCE(sum(round((nfp.valor_acrescimo)::numeric, 2)), 0.0) AS "coalesce"
                       FROM public.nota_fiscal_produto nfp
                      WHERE (nfp.nota_fiscal = nf.grid)))
                END AS valor_acrescimo,
                CASE
                    WHEN (length(public.somente_numero_f(nf.cpf)) <= 11) THEN (0)::text
                    WHEN (length(public.somente_numero_f(nf.cpf)) > 11) THEN (1)::text
                    ELSE ''::text
                END AS tipo_doc,
            ( SELECT COALESCE(sum(trunc((nfp.valor_desconto)::numeric, 2)), 0.0) AS "coalesce"
                   FROM public.nota_fiscal_produto nfp
                  WHERE (nfp.nota_fiscal = nf.grid)) AS valor_desconto_itens,
            ( SELECT COALESCE(sum(trunc((nfp.valor_acrescimo)::numeric, 2)), 0.0) AS "coalesce"
                   FROM public.nota_fiscal_produto nfp
                  WHERE (nfp.nota_fiscal = nf.grid)) AS valor_acrescimo_itens,
                CASE
                    WHEN (cvt.tipo = 'cv_vendas'::text) THEN cvt.info
                    ELSE 'VL'::text
                END AS canal_venda,
            COALESCE(nfpe.email, ''::text) AS email_cliente,
            COALESCE(nfpe.fone, ''::text) AS celular_cliente,
                CASE
                    WHEN (mm.info_adic = 16) THEN true
                    ELSE false
                END AS is_resgate_premmia,
            COALESCE(ebprt.transaction_id, ''::text) AS id_premmia
           FROM (((((((((((public.nota_fiscal nf
             JOIN public.nota_fiscal_situacao nfs ON (((nfs.nota_fiscal = nf.grid) AND (nfs.situacao = 310))))
             JOIN public.movto m ON (((m.mlid = nf.mlid) AND (m.tipo_doc = ANY (ARRAY['NFC-e'::text, 'CF-e'::text, 'NF-e'::text])))))
             JOIN public.motivo_movto mm ON ((mm.grid = m.motivo)))
             JOIN public.pessoa e ON (((e.grid = nf.empresa) AND (e.tipo ~~ ('%%E%%'::bpchar)::text))))
             JOIN public.unidade_federativa uf ON ((e.uf = uf.sigla)))
             LEFT JOIN public.nota_fiscal_pessoa nfpe ON ((nfpe.grid = nf.destinatario)))
             LEFT JOIN public.nfe ON ((nfe.nota_fiscal = nf.grid)))
             LEFT JOIN public.cfe ON ((cfe.nota_fiscal = nf.grid)))
             LEFT JOIN public.orcamento orc ON ((orc.mlid = nf.mlid)))
             LEFT JOIN public.exc_canal_vendas_transacao cvt ON (((cvt.mlid = nf.mlid) AND (cvt.tipo = 'cv_vendas'::text))))
             LEFT JOIN public.exc_brpremmia_resgate_transacao ebprt ON ((ebprt.mlid = nf.mlid)))
          WHERE (true AND (nf.tipo = 'S'::bpchar) AND (nf.numero_nota <> '-1'::integer) AND (nf.modelo_doc = ANY (ARRAY['55'::text, '59'::text, '65'::text])) AND (NOT (EXISTS ( SELECT true AS bool
                   FROM public.nota_fiscal_referenciada nfr
                  WHERE (nfr.nota_fiscal = nf.grid)))) AND ((( SELECT count(nfp.grid) AS count
                   FROM ((((public.nota_fiscal_produto nfp
                     JOIN public.produto p ON (((p.grid = nfp.produto) AND (p.tipo = 'M'::bpchar))))
                     JOIN public.lancto l ON ((l.mlid = nf.mlid)))
                     JOIN public.produto_distribuidora pd ON ((pd.produto = p.grid)))
                     JOIN public.exc_br_produto ebp ON (((ebp.grid = pd.produto_dist) AND (pd.distribuidora = 4))))
                  WHERE (nf.grid = nfp.nota_fiscal)) >= 1) OR (( SELECT count(nfp.grid) AS count
                   FROM ((public.nota_fiscal_produto nfp
                     JOIN public.produto p ON (((p.grid = nfp.produto) AND (p.tipo = 'M'::bpchar))))
                     JOIN public.exc_br_inclusao_cadastro ebic ON ((ebic.produto = p.grid)))
                  WHERE (nfp.nota_fiscal = nf.grid)) >= 1) OR (( SELECT count(*) AS count
                   FROM ((public.exc_brpremmia_promocao ebpr
                     JOIN public.exc_brpremmia_abrangencia eba ON (((ebpr.grid = eba.promocao) AND (((eba.uf_codigo)::text = (uf.codigo)::text) OR (eba.uf_codigo IS NULL)))))
                     JOIN public.exc_brpremmia_transacao ebpt ON ((ebpr.codigo_ftc = ebpt.codigo_produto)))
                  WHERE (ebpt.mlid = nf.mlid)) >= 1) OR (( SELECT count(nfp.grid) AS count
                   FROM (public.nota_fiscal_produto nfp
                     JOIN public.produto p ON (((p.grid = nfp.produto) AND (p.tipo = 'C'::bpchar))))
                  WHERE (nfp.nota_fiscal = nf.grid)) >= 1)))
        UNION
         SELECT c.grid,
            ct.mlid,
            m.grid AS movto,
            c.nr_ecf,
            c.empresa,
            m.motivo,
            '2d'::character varying AS modelo_doc,
            ''::text AS versao_autosystem,
            public.somente_numero_f(COALESCE(ebprt.cpf, ''::text)) AS cpf_premmia,
            NULL::character varying AS chave_acesso,
            c.data_emissao,
            c.nr_cupom AS documento,
            c.hora_emissao AS data_venda,
            ((( SELECT sum(cupom_produto.valor) AS sum
                   FROM public.cupom_produto
                  WHERE (cupom_produto.cupom = c.grid)) -
                CASE
                    WHEN (ct.valor_desconto >= (0.0)::double precision) THEN ct.valor_desconto
                    ELSE (0.0)::double precision
                END) +
                CASE
                    WHEN (ct.valor_desconto < (0.0)::double precision) THEN (ct.valor_desconto * ('-1'::integer)::double precision)
                    ELSE (0.0)::double precision
                END) AS valor_liquido,
            ( SELECT sum(cupom_produto.preco_unit) AS sum
                   FROM public.cupom_produto
                  WHERE (cupom_produto.cupom = c.grid)) AS valor_bruto,
            public.somente_numero_f(c.pessoa_cpf) AS cpf,
            public.somente_numero_f(e.cpf) AS cnpj,
                CASE
                    WHEN (ct.valor_desconto >= (0.0)::double precision) THEN ct.valor_desconto
                    ELSE (0.0)::double precision
                END AS valor_desconto,
                CASE
                    WHEN (ct.valor_desconto < (0.0)::double precision) THEN (ct.valor_desconto * ('-1'::integer)::double precision)
                    ELSE (0.0)::double precision
                END AS valor_acrescimo,
                CASE
                    WHEN (length(public.somente_numero_f(c.pessoa_cpf)) <= 11) THEN (0)::text
                    WHEN (length(public.somente_numero_f(c.pessoa_cpf)) > 11) THEN (1)::text
                    ELSE ''::text
                END AS tipo_doc,
            ( SELECT COALESCE(sum(cupom_produto.valor_desconto), (0.0)::double precision) AS "coalesce"
                   FROM public.cupom_produto
                  WHERE ((cupom_produto.valor_desconto > (0)::double precision) AND (cupom_produto.cupom = c.grid))) AS valor_desconto_itens,
            ( SELECT COALESCE(sum((cupom_produto.valor_desconto * ('-1'::integer)::double precision)), (0.0)::double precision) AS "coalesce"
                   FROM public.cupom_produto
                  WHERE ((cupom_produto.valor_desconto < (0)::double precision) AND (cupom_produto.cupom = c.grid))) AS valor_acrescimo_itens,
                CASE
                    WHEN (cvt.tipo = 'cv_vendas'::text) THEN cvt.info
                    ELSE 'VL'::text
                END AS canal_venda,
            ''::text AS email_cliente,
            ''::text AS celular_cliente,
            false AS is_resgate_premmia,
            ''::text AS id_premmia
           FROM ((((((public.cupom c
             JOIN public.cupom_total ct ON ((ct.cupom = c.grid)))
             JOIN public.pessoa e ON (((e.grid = c.empresa) AND (e.tipo ~~ ('%%E%%'::bpchar)::text))))
             JOIN public.movto m ON ((m.mlid = ct.mlid)))
             LEFT JOIN public.orcamento orc ON ((orc.mlid = m.mlid)))
             LEFT JOIN public.exc_canal_vendas_transacao cvt ON (((cvt.mlid = m.mlid) AND (cvt.tipo = 'cv_vendas'::text))))
             LEFT JOIN public.exc_brpremmia_resgate_transacao ebprt ON ((ebprt.mlid = m.mlid)))
          WHERE (true AND (c.situacao = 'E'::text) AND (m.tipo_doc = ANY (ARRAY['ECF'::text, 'CUPOM'::text])) AND ((( SELECT count(cp.grid) AS count
                   FROM ((((public.cupom_produto cp
                     JOIN public.produto p ON ((p.grid = cp.produto)))
                     JOIN public.lancto l ON ((l.cupom_produto = cp.grid)))
                     JOIN public.produto_distribuidora pd ON ((pd.produto = p.grid)))
                     JOIN public.exc_br_produto ebp ON (((ebp.grid = pd.produto_dist) AND (pd.distribuidora = 4))))
                  WHERE (((p.tipo)::text = 'M'::text) AND (cp.situacao = 'E'::text) AND (cp.tipo_item = 'M'::text) AND (cp.cupom = c.grid))) >= 1) OR (( SELECT count(cp.grid) AS count
                   FROM ((public.cupom_produto cp
                     JOIN public.produto p ON ((p.grid = cp.produto)))
                     JOIN public.exc_br_inclusao_cadastro ebic ON ((ebic.produto = p.grid)))
                  WHERE (((p.tipo)::text = 'M'::text) AND (cp.situacao = 'E'::text) AND (cp.tipo_item = 'M'::text) AND (cp.cupom = c.grid))) >= 1) OR (( SELECT count(*) AS count
                   FROM (((public.exc_brpremmia_promocao ebpr
                     JOIN public.exc_brpremmia_abrangencia eba ON ((ebpr.grid = eba.promocao)))
                     JOIN public.exc_brpremmia_transacao ebpt ON ((ebpr.codigo_ftc = ebpt.codigo_produto)))
                     JOIN public.unidade_federativa uf ON ((e.uf = uf.sigla)))
                  WHERE (((ebpt.mlid = ct.mlid) AND ((eba.uf_codigo)::text = (uf.codigo)::text)) OR (eba.uf_codigo IS NULL))) >= 1) OR (( SELECT count(cp.grid) AS count
                   FROM (public.cupom_produto cp
                     JOIN public.produto p ON ((p.grid = cp.produto)))
                  WHERE (((p.tipo)::text = 'C'::text) AND (cp.situacao = 'E'::text) AND (cp.tipo_item = 'C'::text) AND (cp.cupom = c.grid))) >= 1)))) tb
  ORDER BY tb.data_venda, tb.nr_ecf, tb.documento;


ALTER TABLE public.exc_br_send_venda_view OWNER TO postgres;

