-- Name: exc_brpremmia_abrangencia_flow; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.exc_brpremmia_abrangencia_flow (
    pgd_gfid bigint,
    pgd_username text,
    pgd_host text,
    pgd_optype text,
    pgd_when timestamp(0) without time zone,
    pgd_rfid bigint,
    pgd_flow_flag text,
    pgd_module text,
    pgd_version text,
    grid bigint,
    promocao bigint,
    codigo_cpbr bigint,
