    retorno text,
    comunicar_monitoramento boolean DEFAULT false,
    nota_fiscal bigint
);


ALTER TABLE public.exchange_emsys_gestao_pendencia OWNER TO postgres;

--
-- Name: COLUMN exchange_emsys_gestao_pendencia.situacao; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.exchange_emsys_gestao_pendencia.situacao IS '1-pendente;2-enviado;3-erro;4-json pendente;5-json erro';


--
-- Name: exchange_emsys_gestao_pend_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.exchange_emsys_gestao_pend_view AS
 SELECT eegp.codigo,
    eegp.empresa,
    eegp.caixa,
    eegp.data,
    eegp.turno,
    eegp.mlid,
    eegp.requisicao,
    eegp.situacao,
    eegp.ts_geracao,
    eegp.ts_envio,
    eegp.argumento,
    eegp.conteudo,
    eegp.retorno,
    eegp.comunicar_monitoramento,
    eegp.nota_fiscal
   FROM public.exchange_emsys_gestao_pendencia eegp
  WHERE ((eegp.situacao = ANY (ARRAY[1, 4])) AND ((CURRENT_TIMESTAMP - (eegp.ts_geracao)::timestamp with time zone) >= ((COALESCE(( SELECT eegc.timer_pendencia
           FROM public.exchange_emsys_gestao_config eegc
          WHERE (COALESCE(eegc.timer_pendencia, 0) > 0)
         LIMIT 1), 15))::double precision * '00:00:01'::interval)) AND ((eegp.requisicao = 'turno_abre'::text) OR ((eegp.requisicao <> ALL (ARRAY['turno_abre'::text, 'turno_fecha'::text])) AND (NOT (EXISTS ( SELECT true AS bool
           FROM public.exchange_emsys_gestao_pendencia eegp2
          WHERE ((eegp2.empresa = eegp.empresa) AND (eegp2.caixa = eegp.caixa) AND (eegp2.data = eegp.data) AND (eegp2.turno = eegp.turno) AND (eegp2.situacao > 2) AND (eegp2.requisicao = 'turno_abre'::text)))))) OR ((eegp.requisicao = 'turno_fecha'::text) AND (NOT (EXISTS ( SELECT true AS bool
           FROM public.exchange_emsys_gestao_pendencia eegp3
          WHERE ((eegp3.empresa = eegp.empresa) AND (eegp3.caixa = eegp.caixa) AND (eegp3.data = eegp.data) AND (eegp3.turno = eegp.turno) AND (eegp3.situacao > 2) AND (eegp3.requisicao <> 'turno_fecha'::text))))))))
  ORDER BY
        CASE
            WHEN (eegp.requisicao = 'turno_abre'::text) THEN 1
            ELSE 2
        END, eegp.ts_geracao, eegp.codigo
 LIMIT 1;


ALTER TABLE public.exchange_emsys_gestao_pend_view OWNER TO postgres;

