--
-- Name: lancto_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.lancto_view AS
 SELECT lancto.data,
    lancto.turno,
    lancto.hora,
    lancto.seq,
    lancto.operacao,
    lancto.produto,
    lancto.bico,
    lancto.quantidade,
    lancto.deposito,
    lancto.pessoa,
    lancto.documento,
    lancto.tipo_doc,
    lancto.data_doc,
    lancto.tributacao,
    lancto.preco_unit,
    lancto.valor,
    lancto.vendedor,
    lancto.abastecimento,
    lancto.hora_abastec,
    lancto.usuario,
    lancto.estacao,
    lancto.empresa,
    lancto.mlid,
    lancto.grid,
    produto.nome AS produto_nome
   FROM public.lancto,
    public.produto
  WHERE ((lancto.produto)::text = produto.codigo);


ALTER TABLE public.lancto_view OWNER TO postgres;

