--
-- Name: movto_view_2; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.movto_view_2 AS
 SELECT movto.data,
    movto.hora,
    movto.turno,
    movto.seq,
    movto.motivo,
    movto.conta_debitar,
    movto.conta_creditar,
    movto.pessoa,
    movto.pessoa_id,
    movto.documento,
    movto.data_doc,
    movto.tipo_doc,
    movto.lote,
    movto.vencto,
    movto.valor,
    movto.parent,
    movto.child,
    movto.usuario,
    movto.estacao,
    movto.obs,
    movto.info,
    movto.empresa,
    movto.mlid,
    movto.grid,
    motivo_movto.nome AS motivo_nome,
    pessoa.nome AS pessoa_nome
   FROM public.movto,
    public.motivo_movto,
    public.pessoa
  WHERE ((movto.motivo = motivo_movto.codigo) AND (movto.pessoa = pessoa.codigo));


ALTER TABLE public.movto_view_2 OWNER TO postgres;

