--
-- Name: municipio_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.municipio_view AS
 SELECT m.codigo,
    m.nome AS municipio,
    uf.codigo AS uf_codigo,
    uf.sigla AS uf,
    uf.nome AS uf_nome,
    mi.codigo AS microregiao_codigo,
    mi.nome AS microregiao_nome,
    me.codigo AS mesoregiao_codigo,
    me.nome AS mesoregiao_nome,
    m.codigo_siafi
   FROM (((public.municipio m
     JOIN public.micro_regiao mi ON ((m.micro_regiao = mi.codigo)))
     JOIN public.meso_regiao me ON ((mi.meso_regiao = me.codigo)))
     JOIN public.unidade_federativa uf ON ((me.uf = uf.codigo)));


ALTER TABLE public.municipio_view OWNER TO postgres;

