--
-- Name: pessoa_id_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pessoa_id_view AS
 SELECT pessoa.grid,
    pessoa_id.id,
    pessoa.nome AS pessoa_nome,
    identificacao.nome AS id_nome
   FROM ((public.pessoa_id
     JOIN public.pessoa ON ((pessoa_id.pessoa = pessoa.grid)))
     JOIN public.identificacao ON ((pessoa_id.tipo_id = identificacao.grid)))
  WHERE (pessoa.flag = 'A'::bpchar);


ALTER TABLE public.pessoa_id_view OWNER TO postgres;

