--
-- Name: pessoa_principal_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.pessoa_principal_view AS
 SELECT p1.codigo,
    p1.nome,
    p1.nome_reduzido,
    p1.tipo,
    p1.grupo,
    p1.endereco,
    p1.bairro,
    p1.cidade,
    p1.cep,
    p1.estado,
    p1.fone,
    p1.fax,
    p1.celular,
    p1.cpf,
    p1.rg,
    p1.inscr_est,
    p1.email,
    p1.contato,
    p1.endereco_c,
    p1.bairro_c,
    p1.cidade_c,
    p1.cep_c,
    p1.estado_c,
    p1.fone_c,
    p1.fax_c,
    p1.bloqueado,
    p1.mot_bloq,
    p1.sexo,
    p1.visa,
    p1.mastercard,
    p1.amex,
    p1.credcard,
    p1.outro_cartao,
    p1.nome_cartao,
    p1.rg_orgao_exp,
    p1.rg_data_exp,
    p1.data_nasc,
    p1.data_cad,
    p1.www,
    p1.pessoa,
    p1.empresa,
    p1.obs,
    p1.tabela_preco,
    p1.forma_pgto,
    p1.flag,
    p1.grid,
    p1.inscr_municipal
   FROM (public.pessoa p1
     JOIN public.pessoa p2 ON ((p1.grid = p2.pessoa)))
  WHERE (p2.pessoa IS NOT NULL);


ALTER TABLE public.pessoa_principal_view OWNER TO postgres;

