--
-- Name: produto_deposito_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.produto_deposito_view AS
 SELECT d.grid AS deposito,
    d.nome AS deposito_nome,
    d.codigo AS deposito_codigo,
    d.empresa,
    p.grid AS produto,
    p.nome AS produto_nome,
    p.codigo AS produto_codigo,
    p.tipo,
    public.deposito_movimenta_produto_f(d.grid, p.grid) AS movto_deposito,
    p.flag,
    gp.grid AS grupo_produto,
    gp.codigo AS grupo_produto_codigo,
    gp.nome AS grupo_produto_nome,
    gp.flag AS grupo_produto_flag,
    p.tipo_combustivel
   FROM (((public.produto p
     JOIN public.grupo_produto gp ON ((gp.grid = p.grupo)))
     LEFT JOIN public.deposito_grupo_produto dgp ON ((dgp.grupo = gp.grid)))
     JOIN public.deposito d ON (((d.grid = dgp.deposito) OR (d.produto = p.grid))));


