--
-- Name: produto_movimenta_deposito_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.produto_movimenta_deposito_view AS
 SELECT p.grid AS produto,
    d.grid AS deposito,
    d.empresa
   FROM (((public.produto p
     JOIN public.deposito_grupo_produto dgp ON ((p.grupo = dgp.grupo)))
     JOIN public.deposito d ON ((dgp.deposito = d.grid)))
     LEFT JOIN public.produto_deposito pd ON (((pd.produto = p.grid) AND (pd.deposito = d.grid))))
  WHERE ((pd.movimenta IS NULL) OR (pd.movimenta = true))
UNION
 SELECT deposito.produto,
    deposito.grid AS deposito,
    deposito.empresa
   FROM public.deposito
  WHERE (NOT (deposito.produto IS NULL));


ALTER TABLE public.produto_movimenta_deposito_view OWNER TO postgres;

