--
-- Name: recarga_operadora_config_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.recarga_operadora_config_view AS
 SELECT rcc.fornecedor,
    rcoc.operadora,
    COALESCE(rcoc.comissao, rcc.comissao) AS comissao,
    COALESCE(rcoc.tipo_vencto, rcc.tipo_vencto) AS tipo_vencto,
    COALESCE(rcoc.inicio, rcc.inicio) AS inicio,
    COALESCE(rcoc.prazo, rcc.prazo) AS prazo,
    COALESCE(rcoc.motivo_venda, rcc.motivo_venda) AS motivo_venda,
    COALESCE(rcoc.motivo_pagar, rcc.motivo_pagar) AS motivo_pagar,
    COALESCE(rcoc.motivo_comissao, rcc.motivo_comissao) AS motivo_comissao,
    rcc.motivo_cheque
   FROM public.recarga_celular_config rcc,
    public.recarga_celular_operadora_config rcoc
  WHERE rcoc.ativo
UNION
 SELECT rcc.fornecedor,
    rcoc.operadora,
    rcc.comissao,
    rcc.tipo_vencto,
    rcc.inicio,
    rcc.prazo,
    rcc.motivo_venda,
    rcc.motivo_pagar,
    rcc.motivo_comissao,
    rcc.motivo_cheque
   FROM public.recarga_celular_config rcc,
    public.recarga_celular_operadora_config rcoc
  WHERE (NOT rcoc.ativo);


ALTER TABLE public.recarga_operadora_config_view OWNER TO postgres;

