--
-- Name: terminal_grupo_produto_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.terminal_grupo_produto_view AS
 SELECT terminal_grupo_produto.terminal,
    terminal_grupo_produto.grupo_produto
   FROM public.terminal_grupo_produto
UNION
 SELECT t.grid AS terminal,
    gp.grid AS grupo_produto
   FROM public.terminal t,
    public.grupo_produto gp
  WHERE (NOT (EXISTS ( SELECT 1
           FROM public.terminal_grupo_produto tgp
          WHERE (tgp.terminal = t.grid))));


ALTER TABLE public.terminal_grupo_produto_view OWNER TO postgres;

