--
-- Name: unidade_medida_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.unidade_medida_view AS
 SELECT NULL::bigint AS grid,
    um.codigo,
    um.descricao,
    um.fracao
   FROM public.unidade_medida um
UNION
 SELECT umc.grid,
    umc.codigo,
    umc.descricao,
    umc.fracao
   FROM public.unidade_medida_config umc
  WHERE (NOT (EXISTS ( SELECT true AS bool
           FROM public.unidade_medida um
          WHERE (um.codigo = umc.codigo))));


