--
-- Name: venda_pgto_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.venda_pgto_view AS
 SELECT t.empresa,
    t.data,
    t.mlid,
    t.usuario,
    t.pessoa,
    t.turno,
    t.forma_pgto,
    ((((t.valor_forma_pgto / t.total_forma_pgto) * (100)::double precision) * t.valor_venda) / (100)::double precision) AS valor_venda_rateio,
    t.valor_venda,
    t.valor_forma_pgto,
    t.total_forma_pgto,
    t.troco,
    t.pgto,
    t.conta_debitar,
    ( SELECT COALESCE(cf.data_emissao, nf.data_emissao) AS data_emissao
           FROM ((( SELECT 1 AS "?column?") tab_aux
             LEFT JOIN public.cupom cf ON ((cf.grid = ( SELECT ct.cupom
                   FROM public.cupom_total ct
                  WHERE (ct.mlid = t.mlid)
                 LIMIT 1))))
             LEFT JOIN public.nota_fiscal nf ON ((nf.mlid = t.mlid)))
         LIMIT 1) AS data_emissao
   FROM (( SELECT c.empresa,
            c.data,
            c.mlid,
            c.usuario,
            c.pessoa,
            c.turno,
            c.forma_pgto,
            c.valor_venda,
            c.valor_forma_pgto,
            (c.total_forma_pgto +
                CASE
                    WHEN ((c.valor_venda - c.total_forma_pgto) > (0)::double precision) THEN (c.valor_venda - c.total_forma_pgto)
                    ELSE (0)::double precision
                END) AS total_forma_pgto,
                CASE
                    WHEN ((c.valor_venda - c.total_forma_pgto) < (0)::double precision) THEN abs((c.valor_venda - c.total_forma_pgto))
                    ELSE (0)::double precision
                END AS troco,
                CASE
                    WHEN (c.forma_pgto = ( SELECT motivo_config.motivo
                       FROM public.motivo_config
                      WHERE (motivo_config.chave = 'DINHEIRO'::text))) THEN (1)::bigint
                    ELSE
                    CASE
                        WHEN (
                        CASE
                            WHEN ((c.valor_venda - c.total_forma_pgto) > (0)::double precision) THEN (c.valor_venda - c.total_forma_pgto)
                            ELSE (0)::double precision
                        END > (0)::double precision) THEN ( SELECT (count(t_1.tot) + 1)
                           FROM (( SELECT count(*) AS tot,
                                    x.motivo
                                   FROM public.movto x
                                  WHERE (x.mlid = c.mlid)
                                  GROUP BY x.motivo) t_1
                             JOIN public.motivo_movto xx ON (((t_1.motivo = xx.grid) AND xx.forma_pgto))))
                        ELSE ( SELECT count(t_1.tot) AS count
                           FROM (( SELECT count(*) AS tot,
                                    x.motivo
                                   FROM public.movto x
                                  WHERE (x.mlid = c.mlid)
                                  GROUP BY x.motivo) t_1
                             JOIN public.motivo_movto xx ON (((t_1.motivo = xx.grid) AND xx.forma_pgto))))
                    END
                END AS pgto,
            c.conta_debitar
           FROM ( SELECT m.empresa,
                    m.data,
                    m.mlid,
                    m.usuario,
                    m.pessoa,
                    m.turno,
                    COALESCE(mp.motivo, ( SELECT mc1.motivo
                           FROM public.motivo_config mc1
                          WHERE (mc1.chave = 'DINHEIRO'::text))) AS forma_pgto,
                    m.valor AS valor_venda,
                    sum(COALESCE(mp.valor, m.valor)) AS valor_forma_pgto,
                    COALESCE(( SELECT sum(m1.valor) AS sum
                           FROM ((public.movto m1
                             JOIN public.motivo_movto mm_1 ON (((mm_1.grid = m1.motivo) AND (mm_1.tipo_movto <> 14))))
                             LEFT JOIN public.tipo_vale tv ON (((tv.grid = mm_1.tipo_vale) AND (tv.tipo = 1))))
                          WHERE ((m1.mlid = m.mlid) AND (m1.conta_creditar = m.conta_debitar) AND
                                CASE
                                    WHEN (tv.grid IS NULL) THEN true
                                    ELSE false
                                END)), m.valor) AS total_forma_pgto,
                    m.conta_debitar
                   FROM ((public.movto m
                     LEFT JOIN public.movto mp ON (((m.mlid = mp.mlid) AND (mp.conta_creditar = m.conta_debitar))))
                     JOIN public.motivo_config mc ON (((m.motivo = mc.motivo) AND ((mc.chave = 'VENDA'::text) OR (mc.chave = 'VENDA_TRR'::text)))))
                  GROUP BY m.empresa, m.data, m.mlid, m.usuario, m.pessoa, m.turno, COALESCE(mp.motivo, ( SELECT mc1.motivo
                           FROM public.motivo_config mc1
                          WHERE (mc1.chave = 'DINHEIRO'::text))), m.valor, COALESCE(( SELECT sum(m1.valor) AS sum
                           FROM ((public.movto m1
                             JOIN public.motivo_movto mm_1 ON (((mm_1.grid = m1.motivo) AND (mm_1.tipo_movto <> 14))))
                             LEFT JOIN public.tipo_vale tv ON (((tv.grid = mm_1.tipo_vale) AND (tv.tipo = 1))))
                          WHERE ((m1.mlid = m.mlid) AND (m1.conta_creditar = m.conta_debitar) AND
                                CASE
                                    WHEN (tv.grid IS NULL) THEN true
                                    ELSE false
                                END)), m.valor), m.conta_debitar) c
        UNION
         SELECT c.empresa,
            c.data,
            c.mlid,
            c.usuario,
            c.pessoa,
            c.turno,
            ( SELECT motivo_config.motivo
                   FROM public.motivo_config
                  WHERE (motivo_config.chave = 'DINHEIRO'::text)) AS movto_dinheiro,
            c.valor_venda,
                CASE
                    WHEN ((c.valor_venda - c.total_forma_pgto) > (0)::double precision) THEN (c.valor_venda - c.total_forma_pgto)
                    ELSE (0)::double precision
                END AS valor_forma_pgto,
            (c.total_forma_pgto +
                CASE
                    WHEN ((c.valor_venda - c.total_forma_pgto) > (0)::double precision) THEN (c.valor_venda - c.total_forma_pgto)
                    ELSE (0)::double precision
                END) AS total_forma_pgto,
                CASE
                    WHEN ((c.valor_venda - c.total_forma_pgto) < (0)::double precision) THEN abs((c.valor_venda - c.total_forma_pgto))
                    ELSE (0)::double precision
                END AS troco,
                CASE
                    WHEN (c.forma_pgto = ( SELECT motivo_config.motivo
                       FROM public.motivo_config
                      WHERE (motivo_config.chave = 'DINHEIRO'::text))) THEN (1)::bigint
                    ELSE
                    CASE
                        WHEN (
                        CASE
                            WHEN ((c.valor_venda - c.total_forma_pgto) > (0)::double precision) THEN (c.valor_venda - c.total_forma_pgto)
                            ELSE (0)::double precision
                        END > (0)::double precision) THEN ( SELECT (count(t_1.tot) + 1)
                           FROM (( SELECT count(*) AS tot,
                                    x.motivo
                                   FROM public.movto x
                                  WHERE (x.mlid = c.mlid)
                                  GROUP BY x.motivo) t_1
                             JOIN public.motivo_movto xx ON (((t_1.motivo = xx.grid) AND xx.forma_pgto))))
                        ELSE ( SELECT count(t_1.tot) AS count
                           FROM (( SELECT count(*) AS tot,
                                    x.motivo
                                   FROM public.movto x
                                  WHERE (x.mlid = c.mlid)
                                  GROUP BY x.motivo) t_1
                             JOIN public.motivo_movto xx ON (((t_1.motivo = xx.grid) AND xx.forma_pgto))))
                    END
                END AS pgto,
            c.conta_debitar
           FROM ( SELECT m.empresa,
                    m.data,
                    m.mlid,
                    m.usuario,
                    m.pessoa,
                    m.turno,
                    COALESCE(mp.motivo, ( SELECT mc2.motivo
                           FROM public.motivo_config mc2
                          WHERE (mc2.chave = 'DINHEIRO'::text))) AS forma_pgto,
                    m.valor AS valor_venda,
                    sum(COALESCE(mp.valor, m.valor)) AS valor_forma_pgto,
                    COALESCE(( SELECT sum(m2.valor) AS sum
                           FROM public.movto m2
                          WHERE ((m2.mlid = m.mlid) AND (m2.conta_creditar = m.conta_debitar))), m.valor) AS total_forma_pgto,
                    m.conta_debitar
                   FROM ((public.movto m
                     LEFT JOIN public.movto mp ON (((m.mlid = mp.mlid) AND (mp.conta_creditar = m.conta_debitar))))
                     JOIN public.motivo_config mc ON (((m.motivo = mc.motivo) AND ((mc.chave = 'VENDA'::text) OR (mc.chave = 'VENDA_TRR'::text)))))
                  GROUP BY m.empresa, m.data, m.mlid, m.usuario, m.pessoa, m.turno, COALESCE(mp.motivo, ( SELECT mc2.motivo
                           FROM public.motivo_config mc2
                          WHERE (mc2.chave = 'DINHEIRO'::text))), m.valor, COALESCE(( SELECT sum(m2.valor) AS sum
                           FROM public.movto m2
                          WHERE ((m2.mlid = m.mlid) AND (m2.conta_creditar = m.conta_debitar))), m.valor), m.conta_debitar) c) t
     JOIN public.motivo_movto mm ON (((mm.grid = t.forma_pgto) AND mm.forma_pgto)))
  WHERE (t.valor_forma_pgto > (0.001)::double precision)
  ORDER BY t.data, t.mlid;


ALTER TABLE public.venda_pgto_view OWNER TO postgres;

